    check('surfacing: DXF key note states depth, geotextile and tonnage',
      sDxf.includes('CRUSHED ROCK SURFACING:') && sDxf.includes('GEOTEXTILE') &&
      sDxf.includes('4"') && /TONS/.test(sDxf));
    // A design without surfacing keeps the legend/key note out
    const noSurf = structuredClone(dBetween);
    noSurf.surfacing = null;
    const nDxf = buildDesignDxfString(noSurf, 'Hondo_NoSurf');
    check('surfacing: no-surfacing design omits legend entry + key note',
      !nDxf.includes('CRUSHED ROCK SURFACING'));

    // Compliance: golden design passes; gutted regions flag; overlap fails
    const now = new Date('2026-01-01T12:00:00');
    for (const [label, d2] of [['between-roads', dBetween], ['full-yard', dFull]] as const) {
      const rep = buildComplianceReport(d2, config, { hotClimate: true, now });
      const f = rep.findings.find(x => x.ruleId === 'surfacing-coverage')!;
      check(`surfacing: compliance coverage PASS on golden ${label} design`,
        f?.status === 'PASS', f?.measured);
    }
    const gutted = structuredClone(dBetween);
    gutted.surfacing = { ...gutted.surfacing!, regions: [], areaSqFt: 0, tons: 0 };
    const rGut = buildComplianceReport(gutted, config, { hotClimate: true, now });
    check('surfacing: emptied regions → coverage FAIL',
      rGut.findings.find(x => x.ruleId === 'surfacing-coverage')!.status === 'FAIL');
    const overlapped = structuredClone(dBetween);
    // Paint the whole fence interior as "surfacing" — includes road surface
    overlapped.surfacing = {
      ...overlapped.surfacing!,
      regions: [{ outer: overlapped.fence, holes: [] }],
    };
    const rOver = buildComplianceReport(overlapped, config, { hotClimate: true, now });
    check('surfacing: surfacing painted over roads → coverage FAIL',
      rOver.findings.find(x => x.ruleId === 'surfacing-coverage')!.status === 'FAIL');
    const missing = structuredClone(dBetween);
    missing.surfacing = null;
    const rMiss = buildComplianceReport(missing, config, { hotClimate: true, now });
    check('surfacing: missing surfacing on a populated yard → WARN',
      rMiss.findings.find(x => x.ruleId === 'surfacing-coverage')!.status === 'WARN');
    // Compact layouts (no road network) still surface + still get checked
    const compactS = generateSiteDesign(hondo, config, 100, 400, { hotClimate: true, roadMode: 'compact' });
    const rCompactS = buildComplianceReport(compactS, config, { hotClimate: true, now });
    check('surfacing: compact layout surfacing check never crashes',
      !!rCompactS.findings.find(x => x.ruleId === 'surfacing-coverage'));
