  // ---------------------------------------------------------------
  console.log('\n[27b] Augmentation area cross-hatch mesh (ANSI37) in DXF/display list');
  {
    const { ansi31Segments, ansi37Segments } = await import('../client/src/lib/nextera/hatchPatterns');
    // Pure segment generator: ANSI37 = both 45 and 135 deg families.
    const sq: number[][][] = [[[0, 0], [30, 0], [30, 30], [0, 30]]];
    const s31 = ansi31Segments(sq), s37 = ansi37Segments(sq);
    // Both diagonal families present (135-deg family alignment can differ by
    // one line from the 45-deg family depending on where c0 lands).
    check('aug-hatch: ANSI37 draws both diagonal families (~2x ANSI31 on a square)',
      s37.length >= 2 * s31.length - 2 && s37.length <= 2 * s31.length,
      `${s37.length} vs ${s31.length}`);

    // QTY3 island design carries island-aug futureAug zones -> mesh hatch.
    const meta = { projectName: 'HATCH', location: 'Hondo, TX', drafter: 'QA', revision: 'A', date: '01/01/2026' };
    const dA = generateSiteDesign(hondo, config, 100, 400,
      { hotClimate: true, roadMode: 'roads', containersPerPcs: 3, laydownPct: 2 });
    const nAug = dA.reservedZones.filter(z => z.kind === 'futureAug').length;
    const nLay = dA.reservedZones.filter(z => z.kind !== 'futureAug').length;
    check('aug-hatch: fixture design reserves futureAug zones', nAug > 0 && nLay > 0, `${nAug} aug / ${nLay} laydown`);
    const dxfA = buildDesignDxfString(dA, 'HATCH', config, meta);
    const hatchPats = [...dxfA.matchAll(/HATCH[\s\S]*?\n {2}2\n(\w+)\n/g)].map(m => m[1]);
    const n37 = hatchPats.filter(p => p === 'ANSI37').length;
    const n31 = hatchPats.filter(p => p === 'ANSI31').length;
    // [567] One ANSI37 ENVELOPE per aug island group (the entire augmentation
    // area, ghosts + gaps included) + the legend swatch; laydown zones and
    // the laydown legend swatch stay ANSI31.
    const nAugGroups = new Set(
      dA.reservedZones.filter(z => z.kind === 'futureAug')
        .map(z => z.label.match(/\(ISLAND (\d+)\)/)?.[1] ?? z.id)
    ).size;
    check('aug-hatch: one ANSI37 mesh hatch per aug island group + legend swatch',
      n37 === nAugGroups + 1, `${n37} ANSI37 vs ${nAugGroups} groups`);
    check('aug-hatch: laydown zones + swatch keep ANSI31',
      n31 === nLay + 1, `${n31} ANSI31 vs ${nLay} laydown zones`);
    // Pattern definition: two families at 45 and 135 deg (78 = 2).
    const def37 = dxfA.match(/\n {2}2\nANSI37\n[\s\S]*?\n 78\n(\d+)\n 53\n([\d.]+)[\s\S]*?\n 53\n([\d.]+)/);
    check('aug-hatch: ANSI37 pattern def embeds two families at 45/135 deg',
      def37 !== null && def37[1] === '2' && def37[2] === '45.0' && def37[3] === '135.0',
      def37 ? def37.slice(1).join(',') : 'no ANSI37 pattern def');
    // Display list (CAD view / PDF plot source): futureAug hatch ops carry
    // the ANSI37 pattern on the FUTURE_BESS layer.
    {
      const { DxfWriter, composeDesignDxf } = await import('../client/src/lib/nextera/dxfExport');
      const w = new DxfWriter();
      composeDesignDxf(w, dA, 'HATCH', config, meta);
      const hatch37 = w.ops.filter(o => o.kind === 'hatch' && (o as any).pattern === 'ANSI37');
      check('aug-hatch: display list mirrors the ANSI37 ops 1:1 with the DXF',
        hatch37.length === n37, `${hatch37.length} ops vs ${n37} entities`);
    }
    // Aug-free design: no ANSI37 anywhere (legend swatch keeps ANSI31) so
    // the golden byte-identity above holds by construction.
    // Islands each reserve DEFAULT_ISLAND_AUG_UNITS by default, so an
    // aug-FREE fixture must switch every island's reserve off explicitly.
    const dProbe = generateSiteDesign(hondo, config, 100, 400, { hotClimate: true, roadMode: 'roads' });
    const dNone = generateSiteDesign(hondo, config, 100, 400, {
      hotClimate: true, roadMode: 'roads',
      constraints: {
        islandAugUnits: Object.fromEntries((dProbe.islands ?? []).map(i => [i.n, 0])),
      },
    });
    check('aug-hatch: aug-free fixture really has no futureAug zones',
      !dNone.reservedZones.some(z => z.kind === 'futureAug'));
    const dxfNone = buildDesignDxfString(dNone, 'HATCH', config, meta);
    check('aug-hatch: aug-free DXF contains no ANSI37 (byte-identical legend)',
      !dxfNone.includes('ANSI37'));
  }

  // ---------------------------------------------------------------
  console.log('\n[28] Design worker path (parity + big-site performance budget)');
  {
    const { handleGenerate, handleDxf, handleOptimize } =
      await import('../client/src/lib/nextera/designWorkerCore');
    const { workerAvailable, generateDesignInWorker, buildDxfInWorker } =
      await import('../client/src/lib/nextera/designWorkerClient');
    const { optimizeLayout } = await import('../client/src/lib/nextera/optimizer');

    check('worker: Node has no Worker — client falls back to sync path', !workerAvailable());

    // --- Parity: worker request handlers produce byte-identical output ---
    // structuredClone simulates the postMessage round-trip in both directions.
    const opts = { hotClimate: true, roadMode: 'roads' as const };
    const direct = generateSiteDesign(hondo, config, 100, 400, opts);
    const meta = { projectName: 'WORKER', location: 'Hondo, TX', drafter: 'QA', revision: 'A', date: '01/01/2026' };
    const directDxf = buildDesignDxfString(direct, 'WORKER', config, meta);

    const workerDesign = structuredClone(handleGenerate(structuredClone({
      kind: 'generate' as const, boundary: hondo, configId: config.id,
      targetMW: 100, targetMWh: 400, options: opts,
    })));
    const workerDxf = handleDxf(structuredClone({
      kind: 'dxf' as const, design: workerDesign, projectName: 'WORKER',
      configId: config.id, meta,
    }));
    check('worker: generate + dxf through the worker handlers is byte-identical to the direct path',
      workerDxf === directDxf,
      workerDxf.length !== directDxf.length ? `length ${workerDxf.length} vs ${directDxf.length}` : 'same length, content differs');

    // Client fallback wrappers (async API, sync compute in Node)
    const viaClient = await generateDesignInWorker(hondo, config.id, 100, 400, opts);
    const viaClientDxf = await buildDxfInWorker(viaClient, 'WORKER', config.id, meta);
    check('worker: client fallback wrappers match the direct DXF bytes', viaClientDxf === directDxf);

    // Optimizer through the worker handler matches the direct search exactly
    const baseOpts = { hotClimate: true, roadMode: 'roads' as const, laydownPct: 0, augmentPct: 0 };
    const optDirect = optimizeLayout(hondo, config, 100, 400, baseOpts, 1);
    const optWorker = handleOptimize(structuredClone({
      kind: 'optimize' as const, boundary: hondo, configId: config.id,
      targetMW: 100, targetMWh: 400, baseOptions: baseOpts, seed: 1,
    }));
    check('worker: optimizer through the worker handler matches direct params + stats',
      JSON.stringify(optWorker.candidates.map(c => [c.params, c.stats])) ===
      JSON.stringify(optDirect.candidates.map(c => [c.params, c.stats])));
    check('worker: optimizer cancellation returns a cancelled result with no candidates', (() => {
      const r = handleOptimize({
        kind: 'optimize', boundary: hondo, configId: config.id,
        targetMW: 100, targetMWh: 400, baseOptions: baseOpts, seed: 1,
      }, undefined, () => true);
      return r.cancelled && r.candidates.length === 0;
    })());

    // --- 500+ MW performance budget: 150+ blocks must stay responsive ---
    // Budgets are ~10x the measured times on this class of machine (~120ms
    // generate / ~120ms DXF at 157 blocks) so the test only fails on real
    // regressions (accidental O(n^2) work), never on CI jitter.
    const bigPoly: Pt[] = [
      { x: -3500, y: -3500 }, { x: 3500, y: -3500 },
      { x: 3500, y: 3500 }, { x: -3500, y: 3500 },
    ];
    const bigBoundary: SiteBoundary = {
      name: 'perf-7000ft-square', polygon: bigPoly, origin: { lat: 0, lon: 0 },
      areaAcres: Math.abs(polygonArea(bigPoly)) / 43560,
    };
    const bigCfg = getConfiguration('ge-aux-400');
    const t0 = performance.now();
    const big = generateSiteDesign(bigBoundary, bigCfg, 600, 2400, { hotClimate: true, roadMode: 'roads' });
    const genMs = performance.now() - t0;
    check('perf: 600MW synthetic site places 150+ blocks', big.blocksPlaced >= 150, `${big.blocksPlaced} blocks`);
    check('perf: 150+ block generation under 2500ms budget', genMs < 2500, `${genMs.toFixed(0)}ms`);

    const t1 = performance.now();
    const bigDxf = buildDesignDxfString(big, 'PERF', bigCfg, meta);
    const dxfMs = performance.now() - t1;
    check('perf: 150+ block DXF build under 2500ms budget', dxfMs < 2500, `${dxfMs.toFixed(0)}ms (${(bigDxf.length / 1e6).toFixed(1)}MB)`);

    // clearSite must leave no design, no busy flag, and no pending compute
    // (it invalidates in-flight async regenerations; in Node the compute is
    // sync, so we assert the observable post-clear state).
    {
      const { useDesignStore } = await import('../client/src/lib/stores/useDesignStore');
      const saved = useDesignStore.getState();
      useDesignStore.setState({ boundary: hondo }, false);
      useDesignStore.getState().regenerate();
      useDesignStore.getState().clearSite();
      const s = useDesignStore.getState();
      check('worker: clearSite leaves design null and computing false',
        s.design === null && s.computing === false && s.boundary === null);
      // A regenerate call after clear is a no-op (no boundary), never a crash
      useDesignStore.getState().regenerate();
      check('worker: regenerate after clearSite is a safe no-op',
        useDesignStore.getState().design === null);
      useDesignStore.setState(saved, true);
    }

    const t2 = performance.now();
    const bigClone = structuredClone(big);
    const cloneMs = performance.now() - t2;
    check('perf: 150+ block design survives structuredClone byte-identically (postMessage safety)',
      buildDesignDxfString(bigClone, 'PERF', bigCfg, meta) === bigDxf, `clone ${cloneMs.toFixed(0)}ms`);
  }

