  // Ground texture sampling regression: cloned textures reset anisotropy
  // to 1, which brings back far-zoom shimmer. Guard both the helper's
  // behavior and DesignScene's discipline of always calling it after clone.
  {
    const MAX_ANISO = 16;
    const tex = new THREE.Texture();
    const clone = tex.clone(); // three resets sampling on clone
    check('ground texture: three.js clone really does reset anisotropy to 1',
      clone.anisotropy === 1, `${clone.anisotropy}`);

    configureGroundTexture(clone, MAX_ANISO);
    check('ground texture: helper applies RepeatWrapping on both axes',
      clone.wrapS === THREE.RepeatWrapping && clone.wrapT === THREE.RepeatWrapping);
    check('ground texture: helper applies trilinear mipmap filtering',
      clone.minFilter === THREE.LinearMipmapLinearFilter && clone.magFilter === THREE.LinearFilter);
    check('ground texture: helper enables mipmap generation',
      clone.generateMipmaps === true);
    check('ground texture: helper applies the passed max anisotropy',
      clone.anisotropy === MAX_ANISO, `${clone.anisotropy}`);
    check('ground texture: helper flags the texture for GPU re-upload',
      clone.needsUpdate === true || (clone as any).version > 0);

    // Source scan: every texture clone in DesignScene.tsx must be followed
    // by configureGroundTexture(<var>, ...) within the next few lines.
    // Texture clones are identified by the cloned variable later receiving
    // texture-sampling property writes (repeat/wrapS/anisotropy/...).
    const scenePath = path.resolve('client/src/components/DesignScene.tsx');
    const src = readFileSync(scenePath, 'utf8');
    const lines = src.split('\n');
    const violations: string[] = [];
    let textureClones = 0;
    for (let i = 0; i < lines.length; i++) {
      const m = lines[i].match(/(?:const|let|var)\s+(\w+)\s*=\s*\w+(?:\.\w+|\[[^\]]*\])*\.clone\(\)/);
      if (!m) continue;
      const v = m[1];
      const lookahead = lines.slice(i + 1, i + 11).join('\n');
      const isTexture =
        new RegExp(`\\b${v}\\.(repeat|wrapS|wrapT|anisotropy|minFilter|magFilter|generateMipmaps|needsUpdate)\\b`).test(lookahead) ||
        new RegExp(`configureGroundTexture\\(\\s*${v}\\b`).test(lookahead);
      if (!isTexture) continue;
      textureClones++;
      if (!new RegExp(`configureGroundTexture\\(\\s*${v}\\b`).test(lookahead)) {
        violations.push(`line ${i + 1}: ${lines[i].trim()}`);
      }
    }
    check('ground texture: DesignScene has texture clones to guard (scan is not vacuous)',
      textureClones >= 3, `${textureClones} texture clones found`);
    check('ground texture: every texture clone in DesignScene calls configureGroundTexture',
      violations.length === 0, violations.join('; '));
    check('ground texture: DesignScene imports the shared helper (no local reimplementation)',
      src.includes("from '../lib/groundTexture'") && !/function\s+configureGroundTexture/.test(src));
  }

  // ---------------------------------------------------------------
  // Trench clip-plane regression: the see-through trench band relies on
  // hand-derived plane constants (plan (x,y) -> scene (x, elev, -y)).
  // three.js clips a fragment when plane.distanceToPoint(p) < 0.
  //  - inside set (clipIntersection=false): fragment kept only when ALL
  //    planes have distance >= 0, i.e. only inside the band survives.
  //  - outside set (clipIntersection=true): fragment clipped only when
  //    ALL planes have distance < 0, i.e. only the band is cut away.
  {
    const trench: TrenchBand = { x: 100, yBottom: 40, yTop: 260, width: 6 };
    const { inside, outside } = trenchClipPlanes(trench);
    check('trench clip: returns 4 inside and 4 outside planes',
      inside.length === 4 && outside.length === 4);

    // Plane sets must be exact negations of each other (same boundary).
    const negated = outside.every(po =>
      inside.some(pi =>
        pi.normal.clone().negate().distanceTo(po.normal) < 1e-9 &&
        Math.abs(pi.constant + po.constant) < 1e-9));
    check('trench clip: outside planes are exact negations of inside planes', negated);

    // Scene mapping: plan (x, y) -> scene (x, elev, -y)
    const scenePt = (x: number, y: number, elev = 0) => new THREE.Vector3(x, elev, -y);
    const keptByInside = (p: THREE.Vector3) => inside.every(pl => pl.distanceToPoint(p) >= 0);
    const clippedByOutside = (p: THREE.Vector3) => outside.every(pl => pl.distanceToPoint(p) < 0);

    const insidePts: [string, THREE.Vector3][] = [
      ['band center', scenePt(100, 150)],
      ['near west wall', scenePt(97.5, 150)],
      ['near east wall', scenePt(102.5, 150)],
      ['near south end', scenePt(100, 40.5)],
      ['near north end', scenePt(100, 259.5)],
      ['below grade inside band', scenePt(100, 150, -2)],
    ];
    for (const [name, p] of insidePts) {
      check(`trench clip: ${name} is inside band (kept by inside set)`, keptByInside(p));
      check(`trench clip: ${name} is cut from ground (clipped by outside set)`, clippedByOutside(p));
    }

    const outsidePts: [string, THREE.Vector3][] = [
      ['west of band', scenePt(90, 150)],
      ['east of band', scenePt(110, 150)],
      ['south of band', scenePt(100, 30)],
      ['north of band', scenePt(100, 270)],
      ['just past west wall', scenePt(96.9, 150)],
      ['just past east wall', scenePt(103.1, 150)],
      ['just south of yBottom', scenePt(100, 39.9)],
      ['just north of yTop', scenePt(100, 260.1)],
      ['diagonal corner outside', scenePt(90, 30)],
    ];
    for (const [name, p] of outsidePts) {
      check(`trench clip: ${name} is outside band (rejected by inside set)`, !keptByInside(p));
      check(`trench clip: ${name} keeps ground intact (not clipped by outside set)`, !clippedByOutside(p));
    }

    // Sign-error trap: y (northing) maps to scene -z. A sign flip in the
    // z planes would classify the band's mirror image (-yTop..-yBottom in
    // plan y) as inside. Assert the mirror band is rejected.
    const mirror = scenePt(100, -150);
    check('trench clip: mirror band (plan y negated) is NOT treated as inside',
      !keptByInside(mirror) && !clippedByOutside(mirror));

    // Boundary points sit exactly on a plane (distance 0): kept by the
    // inside set, not clipped by the outside set (no double-clip seam).
    const edge = scenePt(97, 150); // exactly on west wall
    check('trench clip: point exactly on band edge is kept by both passes',
      keptByInside(edge) && !clippedByOutside(edge));
  }

  // ---------------------------------------------------------------
  // First-person walkthrough: spawn pose, gate opening, collision world
  console.log('\n[35] First-person walkthrough (spawn, gate opening, collisions)');
  {
    const {
      gateSpawn, fenceWalls, buildWalkWorld, resolveCollisions, stepWalk,
      SPAWN_BACKOFF_FT, PLAYER_RADIUS_FT, WALK_SPEED_FPS, SPRINT_SPEED_FPS,
    } = await import('../client/src/lib/walkthrough');
    const cfg = getConfiguration('ge-aux-400');
    const d = generateSiteDesign(hondo, cfg, 100, 400, { hotClimate: true });
    const gate = d.gate!;
    check('walk: design under test has a gate', !!d.gate);

    const spawn = gateSpawn(d)!;
    check('walk: spawn pose exists when the design has a gate', !!spawn);
    check('walk: spawn is the backoff distance from the gate',
      Math.abs(Math.hypot(spawn.x - gate.x, spawn.y - gate.y) - SPAWN_BACKOFF_FT) < 1e-6,
      `d=${Math.hypot(spawn.x - gate.x, spawn.y - gate.y)}`);
    check('walk: spawn is outside the fence', !pointInPolygon({ x: spawn.x, y: spawn.y }, d.fence));
    // Facing into the yard: a point well past the gate along the spawn
    // heading lands inside the fence.
    const ahead = {
      x: spawn.x + Math.cos(spawn.yaw) * (SPAWN_BACKOFF_FT + 25),
      y: spawn.y + Math.sin(spawn.yaw) * (SPAWN_BACKOFF_FT + 25),
    };
    check('walk: spawn faces into the yard', pointInPolygon(ahead, d.fence),
      `ahead=(${ahead.x.toFixed(1)},${ahead.y.toFixed(1)})`);

    // Fence walls leave a gap at the gate: closest wall point to the gate
    // center is at least the half opening (minus fp slack).
    const walls = fenceWalls(d);
    let minD = Infinity;
    for (const s of walls) {
      const dx = s.bx - s.ax, dy = s.by - s.ay;
      const l2 = dx * dx + dy * dy;
      const t = l2 < 1e-12 ? 0 : Math.max(0, Math.min(1, ((gate.x - s.ax) * dx + (gate.y - s.ay) * dy) / l2));
      minD = Math.min(minD, Math.hypot(gate.x - (s.ax + dx * t), gate.y - (s.ay + dy * t)));
    }
    check('walk: fence walls leave the gate opening clear',
      minD >= gate.width / 2 - 1e-6, `minD=${minD.toFixed(2)} vs ${gate.width / 2}`);

    const world = buildWalkWorld(d);
    check('walk: collision world covers all equipment', world.boxes.length === d.equipment.length);
    // Open field: resolver is a no-op at the spawn point.
    const free = resolveCollisions(spawn.x, spawn.y, world);
    check('walk: resolver is a no-op in the open', free.x === spawn.x && free.y === spawn.y);

    const simulate = (x: number, y: number, yaw: number, secs: number, sprint = false) => {
      let st = { x, y, vx: 0, vy: 0, yaw, bobPhase: 0 };
      const dt = 1 / 60;
      for (let i = 0; i < secs * 60; i++) {
        st = stepWalk(st, { forward: true, back: false, left: false, right: false, sprint }, dt, world);
      }
      return st;
    };

    // Walking forward from spawn passes through the open gate into the yard.
    const inYard = simulate(spawn.x, spawn.y, spawn.yaw, 6);
    check('walk: engineer can walk through the gate into the yard',
      pointInPolygon({ x: inYard.x, y: inYard.y }, d.fence),
      `end=(${inYard.x.toFixed(1)},${inYard.y.toFixed(1)})`);

    // The fence blocks everywhere else: start just inside a fence edge far
    // from the gate and walk straight out — the wall must hold the engineer
    // (never ends up meaningfully outside the fence line).
    {
      let seg: { mx: number; my: number; ox: number; oy: number } | null = null;
      for (let i = 0; i < d.fence.length; i++) {
        const a = d.fence[i], b = d.fence[(i + 1) % d.fence.length];
        const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
        if (Math.hypot(mx - gate.x, my - gate.y) < 150) continue;
        const len = Math.hypot(b.x - a.x, b.y - a.y);
        if (len < 40) continue;
        // outward normal: away from the inside
        let nx = -(b.y - a.y) / len, ny = (b.x - a.x) / len;
        if (pointInPolygon({ x: mx + nx * 3, y: my + ny * 3 }, d.fence)) { nx = -nx; ny = -ny; }
        seg = { mx, my, ox: nx, oy: ny };
        break;
      }
      check('walk: found a fence edge far from the gate to test against', !!seg);
      if (seg) {
        const start = resolveCollisions(seg.mx - seg.ox * 4, seg.my - seg.oy * 4, world);
        const rammed = simulate(start.x, start.y, Math.atan2(seg.oy, seg.ox), 3);
        const escaped = (rammed.x - seg.mx) * seg.ox + (rammed.y - seg.my) * seg.oy;
        check('walk: fence blocks the engineer away from the gate',
          escaped <= PLAYER_RADIUS_FT + 1e-6, `outward progress=${escaped.toFixed(2)} ft`);
      }
    }

    // Equipment blocks: ram the first BESS-sized box head-on; the engineer
    // must stay outside its footprint.
    {
      const e = d.equipment[0];
      const yawIn = Math.atan2(e.y - spawn.y, e.x - spawn.x);
      const startX = e.x - Math.cos(yawIn) * 40;
      const startY = e.y - Math.sin(yawIn) * 40;
      const ram = simulate(startX, startY, Math.atan2(e.y - startY, e.x - startX), 4);
      // to equipment-local frame
      const c = Math.cos(e.rotation), s = Math.sin(e.rotation);
      const lx = (ram.x - e.x) * c + (ram.y - e.y) * s;
      const ly = -(ram.x - e.x) * s + (ram.y - e.y) * c;
      const outside = Math.abs(lx) >= e.length / 2 + PLAYER_RADIUS_FT - 0.01 ||
        Math.abs(ly) >= e.width / 2 + PLAYER_RADIUS_FT - 0.01;
      check('walk: equipment footprint blocks the engineer',
        outside, `local=(${lx.toFixed(2)},${ly.toFixed(2)}) half=(${e.length / 2},${e.width / 2})`);
    }

    // Kinematics: sprint covers about double the walking distance in the open.
    {
      const far = { x: spawn.x - Math.cos(spawn.yaw) * 500, y: spawn.y - Math.sin(spawn.yaw) * 500 };
      const away = Math.atan2(-Math.sin(spawn.yaw), -Math.cos(spawn.yaw));
      const w = simulate(far.x, far.y, away, 2, false);
      const sp = simulate(far.x, far.y, away, 2, true);
      const dw = Math.hypot(w.x - far.x, w.y - far.y);
      const dsp = Math.hypot(sp.x - far.x, sp.y - far.y);
      check('walk: walking speed settles near the walk cap',
        dw > WALK_SPEED_FPS * 2 * 0.85 && dw <= WALK_SPEED_FPS * 2 + 1, `d=${dw.toFixed(1)}`);
      check('walk: sprint is meaningfully faster than walking',
        dsp > dw * 1.6 && dsp <= SPRINT_SPEED_FPS * 2 + 1, `walk=${dw.toFixed(1)} sprint=${dsp.toFixed(1)}`);
    }

    // No gate -> no spawn (button is disabled, but the lib must be safe too).
    check('walk: gateSpawn is null without a gate', gateSpawn({ ...d, gate: null }) === null);

    // UI invariant scans: walk mode must never survive a switch to 2D, and
    // input flags must clear when focus/pointer lock is lost (sticky keys).
    {
      const sceneSrc = readFileSync('client/src/components/DesignScene.tsx', 'utf8');
      const fpSrc = readFileSync('client/src/components/FirstPersonMode.tsx', 'utf8');
      check('walk ui: 2D button exits walk mode before switching views',
        /if \(walkMode\) setWalkMode\(false\); setViewMode\('2d'\)/.test(sceneSrc));
      check('walk ui: input clears on window blur',
        /addEventListener\('blur', clearInput\)/.test(fpSrc));
      check('walk ui: input clears when the tab is hidden',
        /visibilitychange/.test(fpSrc) && /document\.hidden/.test(fpSrc));
      check('walk ui: input clears when pointer lock is lost',
        /pointerlockchange/.test(fpSrc) && /!document\.pointerLockElement\) clearInput\(\)/.test(fpSrc));
    }
  }

  // ---------------------------------------------------------------
  // Trench clip-plane RENDER wiring: the math above is locked, but the
  // renderer can still regress if a ground material forgets to wire
  // clippingPlanes/clipIntersection, localClipping gets disabled on the
  // Canvas, or the translucent trench fill pass drifts. Source-scan
  // DesignScene.tsx (same style as the configureGroundTexture scan).
  {
    const scenePath = path.resolve('client/src/components/DesignScene.tsx');
    const src = readFileSync(scenePath, 'utf8');
    const lines = src.split('\n');

    // Renderer-level switch: without localClippingEnabled all material
    // clipping planes are silently ignored.
    check('trench render: Canvas enables localClippingEnabled',
      /localClippingEnabled:\s*true/.test(src));

    // The whole-scene ground clip must come from the shared trenchClipPlanes
    // helper's OUTSIDE set (cut the band out of the ground plane).
    check('trench render: groundClip derives from trenchClipPlanes(...).outside',
      /trenchClipPlanes\(design\.trench\)\.outside/.test(src));

    // Scan every clippingPlanes JSX attribute and validate its pairing
    // within the surrounding material attribute block (±6 lines).
    let outsideUses = 0;
    let insideUses = 0;
    let forwardedUses = 0;
    const violations: string[] = [];
    for (let i = 0; i < lines.length; i++) {
      const m = lines[i].match(/clippingPlanes=\{([^}]+)\}/);
      if (!m) continue;
      const expr = m[1].trim();
      const ctx = lines.slice(Math.max(0, i - 6), i + 7).join('\n');
      const hasClipIntersection = /clipIntersection=\{(!!clip|!!clippingPlanes|true)\}/.test(ctx);
      // Find the JSX element this attribute belongs to (nearest opening tag
      // above/on this line). Custom components (Capitalized) forward the
      // planes and pair clipIntersection internally — validated separately.
      let tag = '';
      for (let j = i; j >= 0 && j > i - 12; j--) {
        const tm = lines[j].match(/<([A-Za-z][\w.]*)\b[^<]*$/);
        if (tm) { tag = tm[1]; break; }
      }
      const isCustomComponent = /^[A-Z]/.test(tag);
      if (isCustomComponent) { forwardedUses++; continue; }
      if (/\.outside\b/.test(expr)) {
        // Opaque cut-out pass: must clip ONLY the band (clipIntersection).
        outsideUses++;
        if (!hasClipIntersection) {
          violations.push(`line ${i + 1}: outside set without clipIntersection`);
        }
      } else if (/\.inside\b/.test(expr)) {
        // Translucent fill pass: keep ONLY the band -> default AND-clipping
        // (no clipIntersection), and must render as a see-through overlay.
        insideUses++;
        if (/clipIntersection/.test(ctx)) {
          violations.push(`line ${i + 1}: inside set must not use clipIntersection`);
        }
        if (!/\btransparent\b/.test(ctx) || !/depthWrite=\{false\}/.test(ctx)) {
          violations.push(`line ${i + 1}: inside fill pass missing transparent/depthWrite={false}`);
        }
      } else if (/\bclippingPlanes\b/.test(expr) || /\bgroundClip\b/.test(expr)) {
        // Prop-forwarded planes (GroundMaterial/DirtMaterial/SatelliteDrape):
        // these receive the outside set, so clipIntersection is required.
        forwardedUses++;
        if (!hasClipIntersection) {
          violations.push(`line ${i + 1}: forwarded planes without clipIntersection`);
        }
      } else {
        violations.push(`line ${i + 1}: unrecognized clippingPlanes source '${expr}'`);
      }
    }
    // Not vacuous: surfacing, road network (+fill), entrance road (+fill),
    // ground materials, satellite drape all participate.
    check('trench render: scan found outside-set cut-out materials (not vacuous)',
      outsideUses >= 3, `${outsideUses} outside uses`);
    check('trench render: scan found translucent inside-set fill passes (not vacuous)',
      insideUses >= 2, `${insideUses} inside uses`);
    check('trench render: scan found prop-forwarded ground/satellite materials (not vacuous)',
      forwardedUses >= 3, `${forwardedUses} forwarded uses`);
    check('trench render: every clippingPlanes material is wired correctly',
      violations.length === 0, violations.join('; '));

    // Custom components that receive the planes as a prop must actually
    // wire them onto their internal material(s) with clipIntersection —
    // a component that silently drops the prop reopens the trench gap.
    const componentBody = (name: string): string => {
      const start = src.indexOf(`function ${name}(`);
      if (start < 0) return '';
      const next = src.indexOf('\nfunction ', start + 1);
      return src.slice(start, next < 0 ? src.length : next);
    };
    for (const name of ['GroundMaterial', 'DirtMaterial', 'SatelliteDrape']) {
      const body = componentBody(name);
      check(`trench render: ${name} accepts a clippingPlanes prop`,
        /clippingPlanes\??:/.test(body) || /\bclippingPlanes\b/.test(body.split('\n')[0] || ''));
      // `?? null` is REQUIRED, not just tolerated: an undefined prop skips
      // three's WebGLClipping no-clip check and crashed the 3D view.
      const wiresDirectly =
        /clippingPlanes=\{clippingPlanes( \?\? null)?\}/.test(body) &&
        /clipIntersection=\{!!clippingPlanes\}/.test(body);
      // GroundMaterial may delegate its textured branch to DirtMaterial —
      // then it must forward the prop on that call site.
      const delegates = /<DirtMaterial\b[^>]*clippingPlanes=\{clippingPlanes( \?\? null)?\}/.test(body);
      check(`trench render: ${name} wires clippingPlanes + clipIntersection onto its material`,
        wiresDirectly, wiresDirectly ? '' : 'material wiring missing in component body');
      if (name === 'GroundMaterial') {
        check('trench render: GroundMaterial forwards planes to DirtMaterial branch',
          delegates);
      }
    }
    // ...and the scene-level call sites must pass the ground clip in.
    check('trench render: GroundMaterial call site receives groundClip',
      /<GroundMaterial\b[^>]*clippingPlanes=\{groundClip\}/.test(src));
    check('trench render: SatelliteDrape call site receives groundClip',
      /<SatelliteDrape\b[\s\S]{0,200}?clippingPlanes=\{groundClip\}/.test(src));

    // Trench-consuming mesh components each derive their clip from the
    // shared helper — no hand-rolled plane math in the scene.
    const clipDerivations = (src.match(/trenchClipPlanes\(trench\)/g) || []).length;
    check('trench render: mesh components derive clips via trenchClipPlanes(trench)',
      clipDerivations >= 3, `${clipDerivations} derivations`);
    check('trench render: DesignScene imports trenchClipPlanes from YardExtras (no local copy)',
      /import\s*\{[^}]*\btrenchClipPlanes\b[^}]*\}\s*from '\.\/YardExtras'/.test(src) &&
      !/function\s+trenchClipPlanes/.test(src));
  }

  // ---------------------------------------------------------------
  // Gate 3D model alignment: the gate's width axis must follow the fence
  // segment direction. Plan (x, y) -> scene (x, elev, -y), and a scene
  // rotation.y = th maps local +X to plan (cos th, sin th) — so the yaw must
  // be +gate.rotation. A negated yaw mirrors the direction and skews the
  // gate across every non-axis-aligned fence segment (regressed repeatedly).
  {
    console.log('\n[36] Gate model alignment with fence line');
    const src = readFileSync('client/src/components/YardExtras.tsx', 'utf8');
    check('gate: GateModel group yaw is +gate.rotation (not negated)',
      /position=\{\[gate\.x, scale\.y \/ 2, -gate\.y\]\} rotation=\{\[0, gate\.rotation, 0\]\}/.test(src) &&
      !/rotation=\{\[0, -gate\.rotation, 0\]\}/.test(src));

    // Math-level: applying the scene transform to the gate's local width axis
    // must land exactly on the fence segment direction in plan space, for a
    // rotated (non-axis-aligned) fence segment.
    const r = Math.atan2(3, 7); // arbitrary rotated fence direction
    const g = new THREE.Group();
    g.rotation.set(0, r, 0);
    g.updateMatrixWorld(true);
    const v = new THREE.Vector3(1, 0, 0).applyMatrix4(g.matrixWorld);
    const planDir = { x: v.x, y: -v.z }; // scene -> plan
    check('gate: yaw = +rotation maps local +X onto the fence direction',
      Math.abs(planDir.x - Math.cos(r)) < 1e-9 && Math.abs(planDir.y - Math.sin(r)) < 1e-9,
      `planDir=(${planDir.x.toFixed(6)},${planDir.y.toFixed(6)}) vs (${Math.cos(r).toFixed(6)},${Math.sin(r).toFixed(6)})`);

    // Placed on the fence line: the Hondo gate midpoint must lie on its
    // fence segment (distance-to-fence ~ 0) so the yaw fix is the only
    // remaining degree of freedom for alignment.
    check('gate: Hondo gate center lies on the fence line',
      design.gate !== null && distanceToPolygonEdge({ x: design.gate!.x, y: design.gate!.y }, design.fence) < 0.01);

    // The 2D yellow bar and 3D model must agree on the rotation source (both
    // driven by the same +gate.rotation, no divergent sign conventions).
    const sceneSrc = readFileSync('client/src/components/DesignScene.tsx', 'utf8');
    check('gate: 2D bar uses [-PI/2, 0, +gate.rotation] (shared sign convention)',
      /rotation=\{\[-Math\.PI \/ 2, 0, design\.gate\.rotation\]\}/.test(sceneSrc));

    // The fallback 3D gate bar (shown when the GLB model option is off) must
    // use the same non-negated yaw as GateModel.
    check('gate: fallback 3D bar yaw is +g.rotation (not negated)',
      /position=\{\[g\.x, 3, -g\.y\]\} rotation=\{\[0, g\.rotation, 0\]\}/.test(sceneSrc) &&
      !/rotation=\{\[0, -g\.rotation, 0\]\}/.test(sceneSrc));
  }

  // ---------------------------------------------------------------
  // Satellite imagery drape defaults ON (opt-out persisted) and auto-fetches
  // when a design with coordinates loads, with visible loading/error state.
  {
    console.log('\n[37] Satellite imagery on by default');
    const storeSrc = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
    check('satellite: showSatellite defaults ON (localStorage opt-out only)',
      /localStorage\.getItem\('nextera-show-satellite'\)\s*!==\s*'false'/.test(storeSrc) &&
      !/localStorage\.getItem\('nextera-show-satellite'\)\s*===\s*'true'/.test(storeSrc));
    check('satellite: catch branch of the default also returns true',
      /nextera-show-satellite'\)\s*!==\s*'false';\s*\}\s*catch\s*\{\s*return true;/.test(storeSrc));
    // KMZ upload and sample loads funnel through the shared applyBoundary
    // path (boundary picker refactor), so the auto-fetch line appears there
    // once, plus on the project-open and session-restore paths.
    check('satellite: auto-fetch wired on all design-load paths (KMZ/sample, project open, session restore)',
      (storeSrc.match(/if \(get\(\)\.showSatellite\) void get\(\)\.loadSatellite\(\);/g) ?? []).length >= 3 &&
      /get\(\)\.regenerate\([^)]*\);\s*\/\/[^\n]*\n[^\n]*\n\s*if \(get\(\)\.showSatellite\) void get\(\)\.loadSatellite\(\);\s*(?:void get\(\)\.loadTerrain\(\);\s*)?\},\s*\n\s*dismissSavedSession/.test(storeSrc) &&
      /applyBoundary: \(boundary: SiteBoundary\)/.test(storeSrc) &&
      /loadKmlWithPicker\(kmlText, sourceName\)/.test(storeSrc) &&
      /loadKmlWithPicker\(kmlText, name, boundaryNames\)/.test(storeSrc));

    const sceneSrc2 = readFileSync('client/src/components/DesignScene.tsx', 'utf8');
    // North-up lock: a top-down ortho camera with the default up=(0,1,0) is
    // degenerate (up parallel to the view direction) and OrbitControls'
    // tie-break can flip the plan 180° (south-up). Scene -Z is plan north, so
    // the 2D camera must pin up to -Z and rotation must stay 3D-only.
    check('satellite: 2D ortho camera pins up=[0,0,-1] (deterministic north-up)',
      /<OrthographicCamera[^>]*up=\{\[0, 0, -1\]\}/.test(sceneSrc2));
    check('satellite: rotation disabled in 2D so north-up cannot drift',
      /enableRotate=\{viewMode !== '2d'\}/.test(sceneSrc2));
    // WebGL failure recovery: context-creation throws must be caught by an
    // error boundary around the Canvas (not escape to the dev overlay), a
    // lost live context must surface the same recovery UI, and Retry must
    // remount a fresh canvas without touching the design store.
    check('webgl recovery: pre-mount probe keeps the no-WebGL path exception-free (no dev overlay)',
      /probe\.getContext\('webgl2'\)/.test(sceneSrc2) && !/probe\.getContext\('webgl'\)/.test(sceneSrc2) &&
      /WEBGL_lose_context/.test(sceneSrc2));
    check('webgl recovery: error boundary catches canvas mount failures into silent recovery',
      /class CanvasErrorBoundary extends Component/.test(sceneSrc2) &&
      /static getDerivedStateFromError/.test(sceneSrc2) &&
      /<CanvasErrorBoundary key=\{glRetry\} onError=\{attemptRecovery\}>/.test(sceneSrc2));
    // Context loss is recovered SILENTLY: preventDefault (required for the
    // browser to attempt restoration), wait briefly for contextrestored
    // (three re-inits in place → repaint), else rebuild the canvas with
    // backoff. setGlFailure (the panel) fires only from attemptRecovery
    // once the auto-retry budget is exhausted.
    check('webgl recovery: context loss recovers silently (restored → repaint, else timed rebuild)',
      /webglcontextlost/.test(sceneSrc2) &&
      /e\.preventDefault\(\)/.test(sceneSrc2) &&
      /webglcontextrestored/.test(sceneSrc2) &&
      /attemptRecovery\('The browser lost its WebGL graphics context\.'\)/.test(sceneSrc2) &&
      !/setGlFailure\('The browser lost/.test(sceneSrc2));
    check('webgl recovery: panel is a last resort after the auto-retry budget, Retry resets it',
      /r\.attempts >= GL_MAX_AUTO_RETRIES/.test(sceneSrc2) &&
      /setGlFailure\(reason\)/.test(sceneSrc2) &&
      /glFailure !== null \?/.test(sceneSrc2) &&
      /<SceneRecoveryPanel/.test(sceneSrc2) &&
      /recovery\.current\.attempts = 0;[\s\S]{0,120}setGlRetry\(r => r \+ 1\);/.test(sceneSrc2));
    // View-mode switches must preserve one live Canvas so an in-flight/cached
    // GLB texture load cannot be destroyed between 3D and CAD. Detached guards
    // still protect intentional recovery remounts and component unmounts.
    check('webgl recovery: view switches preserve the canvas; real remounts keep detached guards',
      !/key=\{viewMode\}/.test(sceneSrc2) &&
      (sceneSrc2.match(/if \(!gl\.domElement\.isConnected\) \{\s*\n\s*clearTimeout\(lostTimer\);\s*\n\s*return;/)?.length ?? 0) === 1 &&
      /lostTimer = setTimeout\(\(\) => \{\s*\n(?:\s*\/\/[^\n]*\n)*\s*if \(!gl\.domElement\.isConnected\) return;/.test(sceneSrc2) &&
      /clearTimeout\(lostTimer\);\s*\n\s*if \(!gl\.domElement\.isConnected\) return; \/\/ detached canvas: ignore/.test(sceneSrc2));
    // The "3D view recovered" toast must be tied to an explicit "this mount
    // was triggered by a recovery attempt" flag, never the raw attempt
    // counter: attempts stays > 0 for ~10s after a genuine recovery, so an
    // unrelated render in that window would otherwise re-toast. The flag is
    // set exactly when the scheduled recovery remount fires and consumed
    // (cleared) by the next onCreated before toasting.
    check('webgl recovery: mount toast keys off the recoveredMount flag, not the attempt counter',
      /r\.recoveredMount = true;[\s\S]{0,200}setGlRetry\(x => x \+ 1\);/.test(sceneSrc2) &&
      /if \(r\.recoveredMount\) \{[\s\S]{0,400}r\.recoveredMount = false;\s*\n\s*toast\.success\('3D view recovered'\);/.test(sceneSrc2) &&
      !/if \(r\.attempts > 0\) \{[\s\S]{0,300}toast\.success\('3D view recovered'\)/.test(sceneSrc2));
    check('webgl recovery: remount restores the saved camera pose and revives hidden tabs',
      /<PosePersistence savedPose=\{savedPose\} restorePending=\{poseRestorePending\}/.test(sceneSrc2) &&
      /<VisibilityRevive onDeadContext=/.test(sceneSrc2) &&
      /visibilitychange/.test(sceneSrc2));
    // CAD view: the drawing must come from the exporter's own display list
    // (composeDesignDxf into DxfWriter.ops) — never re-derived geometry — so
    // the on-screen CAD view can never drift from the exported DXF/PDF.
    {
      const cadSrc = readFileSync('client/src/components/CadLinework.tsx', 'utf8');
      // [717] The CAD view now composes through composeSiteDxf, which draws
      // EVERY area of a multi-area site and delegates verbatim to
      // composeDesignDxf for a single-area project. The WYSIWYG rule is
      // unchanged: the view still renders exporter-composed ops, never
      // re-derived geometry.
      check('CAD view: linework built via composeSiteDxf on a DxfWriter (WYSIWYG with exports)',
        /new DxfWriter\(drawingVisibility\)/.test(cadSrc) &&
        /composeSiteDxf\(dxf, \{/.test(cadSrc) &&
        /areas: siteAreas/.test(cadSrc) && /activeAreaId,/.test(cadSrc));
      // The 2D fallback must share ONE composition helper with the WebGL CAD
      // view, or the two renderings of "the drawing" drift apart.
      {
        const planSrc = readFileSync('client/src/components/PlanFallback2D.tsx', 'utf8');
        check('2D plan fallback: composes through the SAME composeSiteDxf helper as the CAD view',
          /composeSiteDxf\(w, \{/.test(planSrc) && /areas: siteAreas/.test(planSrc));
      }
      // Single-area byte-identity: the shared helper must delegate to the
      // legacy call unchanged, so single-boundary CAD/2D output is untouched.
      {
        const composeSrc = readFileSync('client/src/lib/nextera/siteCompose.ts', 'utf8');
        check('site compose: single-area projects delegate to the legacy composeDesignDxf call',
          /areas\.length < 2/.test(composeSrc) && /composeDesignDxf\(dxf, design, projectName, config, meta, feeders, substation,/.test(composeSrc));
      }
      check('CAD view: display-only (no dxf.toString / no export writes)',
        !/toString\(\)/.test(cadSrc) && !/saveAs|downloadDxf/.test(cadSrc));
      check('CAD view: demand frameloop repaint + disposal on rebuild',
        /invalidate\(\)/.test(cadSrc) && /geometry\.dispose\(\)/.test(cadSrc));
      check('CAD view mode persisted and wired into the scene',
        /nextera-view-mode/.test(sceneSrc2) && /cad=\{viewMode === 'cad'\}/.test(sceneSrc2));
    }
    check('satellite: viewport shows a loading indicator while tiles fetch',
      /showSatellite && satelliteStatus === 'loading'/.test(sceneSrc2) &&
      /Loading satellite imagery/.test(sceneSrc2));
    check('satellite: viewport shows an unavailable message on fetch failure',
      /showSatellite && satelliteStatus === 'error'/.test(sceneSrc2) &&
      /Satellite imagery unavailable/.test(sceneSrc2));

    // Full-ground coverage: the fetch must request the WGS84 bbox of the 3D
    // ground plane (max |coord| * 2.6 + 200 ft, centered on origin), and the
    // server must honor a bbox by mosaicking a tile grid that covers it at
    // the highest zoom within its tile budget.
    const { satelliteCoverageBbox, satelliteLocalRect } = await import('../client/src/lib/nextera/satellite');
    const bbox = satelliteCoverageBbox(design.boundary.polygon, design.boundary.origin);
    const groundSize = Math.max(...design.boundary.polygon.map(p => Math.max(Math.abs(p.x), Math.abs(p.y)))) * 2.6 + 200;
    const ftPerDegLon = 364000 * Math.cos((design.boundary.origin.lat * Math.PI) / 180);
    check('satellite: coverage bbox spans the full ground plane (E-W)',
      Math.abs((bbox.east - bbox.west) * ftPerDegLon - groundSize) < 0.01);
    check('satellite: coverage bbox spans the full ground plane (N-S)',
      Math.abs((bbox.north - bbox.south) * 364000 - groundSize) < 0.01);
    check('satellite: coverage bbox is centered on the site origin',
      Math.abs((bbox.east + bbox.west) / 2 - design.boundary.origin.lon) < 1e-9 &&
      Math.abs((bbox.north + bbox.south) / 2 - design.boundary.origin.lat) < 1e-9);
    // The drape rect derived from any mosaic covering that bbox must contain
    // every boundary vertex (the parcel never pokes out of the imagery).
    const rect = satelliteLocalRect(
      { dataUrl: '', widthPx: 1, heightPx: 1, zoom: 19, bounds: bbox },
      design.boundary.origin
    );
    check('satellite: coverage rect contains the whole parcel',
      design.boundary.polygon.every(p =>
        p.x >= rect.minX && p.x <= rect.maxX && p.y >= rect.minY && p.y <= rect.maxY));

    check('satellite: loadSatellite requests ground-plane coverage bbox',
      /fetchSatelliteImage\(\s*boundary\.origin\.lat,\s*boundary\.origin\.lon,\s*satelliteCoverageBboxFor\(polygons, boundary\.origin\)\s*\)/.test(storeSrc));

    // Multi-area imagery. Two failure modes are guarded here, both of which
    // left the viewport on a permanent "Loading satellite imagery…" spinner
    // over bare ground for a multi-footprint import:
    //
    // 1. Completion was matched on the boundary OBJECT's identity. A
    //    multi-area import swaps that object mid-flight (applyBoundary takes
    //    a renamed copy, regenerateAreas then re-seats the original), so the
    //    arriving image was discarded and the status never left 'loading'.
    //    The guard must be a site epoch, never an identity compare.
    // 2. Coverage was derived from the ACTIVE area's distance from the shared
    //    origin, so far-flung areas sat off the imagery entirely.
    const { satelliteCoverageBboxFor, siteGroundExtentFt } = await import('../client/src/lib/nextera/satellite');
    {
      // Scope the scan to loadSatellite: loadTerrain legitimately keeps the
      // boundary-identity guard (it is not affected by the area re-seat).
      const satFn = storeSrc.slice(
        storeSrc.indexOf('  loadSatellite: async ()'),
        storeSrc.indexOf('  loadTerrain: async ()')
      );
      check('satellite: completion is guarded by a site epoch, not boundary identity',
        satFn.length > 0 &&
        /satelliteEpoch/.test(satFn) &&
        /if \(satelliteEpoch !== epoch\) return null;/.test(satFn) &&
        !/get\(\)\.boundary !== boundary/.test(satFn));
    }
    check('satellite: the site epoch is bumped whenever the site changes',
      (storeSrc.match(/bumpSatelliteEpoch\(\)/g) ?? []).length >= 3);
    check('satellite: multi-area load requests coverage for every area polygon',
      /siteAreas/.test(storeSrc) &&
      /areas\.length >= 2\s*\n?\s*\?\s*areas\.map\(a => a\.boundary\.polygon\)/.test(storeSrc));
    {
      // Two footprints offset from a shared origin: the envelope must contain
      // BOTH, which the single-polygon formula on either one alone does not.
      const near = [{ x: -100, y: -100 }, { x: 100, y: -100 }, { x: 100, y: 100 }, { x: -100, y: 100 }];
      const far = [{ x: 4000, y: 3000 }, { x: 4400, y: 3000 }, { x: 4400, y: 3400 }, { x: 4000, y: 3400 }];
      const multi = satelliteCoverageBboxFor([near, far], design.boundary.origin);
      const mRect = satelliteLocalRect(
        { dataUrl: '', widthPx: 1, heightPx: 1, zoom: 19, bounds: multi },
        design.boundary.origin
      );
      check('satellite: multi-area coverage contains every area vertex',
        [...near, ...far].every(p =>
          p.x >= mRect.minX && p.x <= mRect.maxX && p.y >= mRect.minY && p.y <= mRect.maxY));

      // Framing is the ENVELOPE of the areas, not a square centered on the
      // shared projection origin. With one origin across many footprints, no
      // area sits at the origin, so an origin-centered square has to grow all
      // the way back across the origin and out the far side to reach a distant
      // area — mostly empty land, and a mosaic big enough to force the server
      // to back the zoom down (coarse imagery) or blow its tile budget.
      const { siteGroundExtent } = await import('../client/src/lib/nextera/satellite');
      const ext = siteGroundExtent([near, far]);
      const envMinX = Math.min(...[...near, ...far].map(p => p.x));
      const envMaxX = Math.max(...[...near, ...far].map(p => p.x));
      const envMinY = Math.min(...[...near, ...far].map(p => p.y));
      const envMaxY = Math.max(...[...near, ...far].map(p => p.y));
      check('satellite: multi-area square is centered on the area envelope',
        Math.abs(ext.cx - (envMinX + envMaxX) / 2) < 1e-9 &&
        Math.abs(ext.cy - (envMinY + envMaxY) / 2) < 1e-9,
        `center (${ext.cx.toFixed(0)}, ${ext.cy.toFixed(0)})`);
      // Sized off the envelope SPAN, so it never pays for the origin offset.
      const span = Math.max(envMaxX - envMinX, envMaxY - envMinY);
      check('satellite: multi-area extent is sized from the envelope span',
        Math.abs(ext.size - (span * 1.15 + 200)) < 1e-9,
        `${ext.size.toFixed(0)} ft for a ${span.toFixed(0)} ft span`);
      // The regression this replaces: the old origin-centered square was
      // materially larger for the same site, and unboundedly so as areas move
      // away from the origin.
      const maxAbs = Math.max(...[...near, ...far].map(p => Math.max(Math.abs(p.x), Math.abs(p.y))));
      check('satellite: envelope framing beats the old origin-centered square',
        ext.size < maxAbs * 2,
        `${ext.size.toFixed(0)} ft vs ${(maxAbs * 2).toFixed(0)} ft origin-centered`);
      // Single-polygon framing is unchanged (byte-identical single-area path).
      check('satellite: single-area extent keeps the legacy 2.6x framing',
        Math.abs(siteGroundExtentFt([design.boundary.polygon]) - groundSize) < 1e-9);
      const singleExt = siteGroundExtent([design.boundary.polygon]);
      check('satellite: single-area square stays centered on the origin',
        singleExt.cx === 0 && singleExt.cy === 0);
      // The imagery drape must land exactly on the ground plane it covers:
      // same center, same side length, derived from the same helper.
      check('satellite: multi-area coverage rect matches the ground plane square',
        Math.abs((mRect.maxX - mRect.minX) - ext.size) < 0.01 &&
        Math.abs((mRect.maxY - mRect.minY) - ext.size) < 0.01 &&
        Math.abs((mRect.minX + mRect.maxX) / 2 - ext.cx) < 0.01 &&
        Math.abs((mRect.minY + mRect.maxY) / 2 - ext.cy) < 0.01);
      // The scene's ground plane must use the SAME helper AND be re-centered
      // on the envelope; sizing alone would leave the plane at the origin
      // while the imagery sits over the site.
      check('satellite: scene ground plane sizes from the shared extent helper',
        /siteGroundExtent\(/.test(sceneSrc2) &&
        /groundAreaPolys\.length >= 2/.test(sceneSrc2));
      check('satellite: scene ground plane is positioned at the extent center',
        /position=\{\[groundExtent\.cx, -0\.25, -groundExtent\.cy\]\}/.test(sceneSrc2));
    }

    const routesSrc = readFileSync('server/routes.ts', 'utf8');
    check('satellite: server accepts a coverage bbox (west/east/north/south)',
      /req\.query\.west/.test(routesSrc) && /req\.query\.south/.test(routesSrc) &&
      /hasBbox/.test(routesSrc));
    check('satellite: server backs off zoom until the grid fits the tile budget',
      /MAX_TILES/.test(routesSrc) && /cols \* rows > MAX_TILES\) continue/.test(routesSrc));
  }

  // ---------------------------------------------------------------
  {
    console.log('\n[38] PDF cover: layout overlaid on aerial imagery');
    const { buildPdfPlotString } = await import('../client/src/lib/nextera/pdfPlot');
    const { satelliteCoverageBbox, satelliteLocalRect } = await import('../client/src/lib/nextera/satellite');
    const { buildDxfPackage } = await import('../client/src/lib/nextera/dxfSheets');

    const meta = { projectName: 'GOLDEN', location: 'Hondo, TX', drafter: 'QA', revision: 'A', date: '01/01/2026' };
    const d = generateSiteDesign(hondo, config, 100, 400, { hotClimate: true, roadMode: 'roads' });

    // Deterministic stand-in mosaic: a fixed embedded JPEG spanning the same
    // local-feet rect the real satellite fetch would produce.
    const bbox = satelliteCoverageBbox(d.boundary.polygon, d.boundary.origin);
    const localRect = satelliteLocalRect(
      { dataUrl: '', widthPx: 1, heightPx: 1, zoom: 19, bounds: bbox },
      d.boundary.origin
    );
    // Distinct 1x1 white JPEG (jsPDF dedupes identical embedded images, so
    // reusing a mech plate here would hide the cover mosaic in the counts).
    const TINY_JPEG =
      '';
    const coverImage = {
      dataUrl: `data:image/jpeg;base64,${TINY_JPEG}`,
      widthPx: 1,
      heightPx: 1,
      caption: 'SITE VICINITY — AERIAL IMAGERY (TEST)',
      localRect,
    };
    const ctx = { design: d, projectName: 'GOLDEN', config, meta, coverImage };

    const pdf = buildPdfPlotString(ctx);
    check('cover: PDF with imagery builds and stays a valid PDF', pdf.startsWith('%PDF'));
    check('cover: imagery caption rendered on the cover page',
      pdf.includes('SITE VICINITY'));
    check('cover: build with imagery is deterministic (two builds byte-identical)',
      buildPdfPlotString(ctx) === pdf);
    // The overlay adds one JPEG (the mosaic) beyond the mech appendix plates
    // and a large batch of vector strokes over the plain build.
    const plain = buildPdfPlotString({ design: d, projectName: 'GOLDEN', config, meta });
    check('cover: exactly one extra embedded JPEG vs the imagery-free build',
      (pdf.match(/\/Filter \/DCTDecode/g) || []).length ===
      (plain.match(/\/Filter \/DCTDecode/g) || []).length + 1);
    check('cover: overlay adds vector line work over the imagery-free build',
      (pdf.match(/ l\n/g) || []).length > (plain.match(/ l\n/g) || []).length + 500,
      `${(pdf.match(/ l\n/g) || []).length} vs ${(plain.match(/ l\n/g) || []).length} line ops`);
    check('cover: imagery-free build unchanged (byte-deterministic default path)',
      buildPdfPlotString({ design: d, projectName: 'GOLDEN', config, meta }) === plain);

    // Overlay source contract: the cover renderer reuses the site-plan
    // drawing routines (never hand-rolled geometry) and stays PDF-only.
    const pdfSrc = readFileSync('client/src/lib/nextera/pdfPlot.ts', 'utf8');
    check('cover: overlay reuses drawBoundaryAndFence/drawRoads/drawEquipment/drawGate',
      /drawBoundaryAndFence\(ov, ctx\.design\)/.test(pdfSrc) &&
      /drawRoads\(ov, ctx\.design, false\)/.test(pdfSrc) &&
      /drawEquipment\(ov, ctx\.design, ctx\.config\)/.test(pdfSrc) &&
      /drawGate\(ov, ctx\.design\)/.test(pdfSrc));
    check('cover: export path passes the mosaic local rect for georegistration',
      /localRect: satelliteLocalRect\(satImg, boundary\.origin\)/.test(
        readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8')));

    // Boundary-crossing overlay work is clipped at the mosaic rect edge,
    // never dropped whole. Exercise the clipper directly with a rect smaller
    // than the layout extents, and check the render path uses it.
    const { clipSegmentToRect } = await import('../client/src/lib/nextera/pdfPlot');
    const smallRect = { minX: 0, minY: 0, maxX: 100, maxY: 100 };
    const crossing = clipSegmentToRect([-50, 50], [150, 50], smallRect);
    check('cover: segment crossing the mosaic rect is clipped to its edges',
      !!crossing &&
      crossing[0][0] === 0 && crossing[0][1] === 50 &&
      crossing[1][0] === 100 && crossing[1][1] === 50);
    const partial = clipSegmentToRect([50, 50], [50, 250], smallRect);
    check('cover: segment leaving the rect is trimmed at the boundary',
      !!partial &&
      partial[0][1] === 50 && partial[1][1] === 100 && partial[1][0] === 50);
    check('cover: fully-outside segment yields nothing',
      clipSegmentToRect([200, 200], [300, 300], smallRect) === null);
    const inside = clipSegmentToRect([10, 10], [90, 90], smallRect);
    check('cover: fully-inside segment is unchanged',
      !!inside && inside[0][0] === 10 && inside[1][0] === 90);
    check('cover: overlay pass clips segments instead of skipping them',
      /clipSegmentToRect\(seg\.pts\[i\], seg\.pts\[i \+ 1\], lr\)/.test(pdfSrc) &&
      !/seg\.pts\.every\(inRect\)/.test(pdfSrc));

    // A mosaic rect smaller than the layout extents still yields overlay
    // strokes (clipped, not dropped): shrink the rect to the middle of the
    // parcel and confirm the build gains line ops over the plain build.
    const midX = (localRect.minX + localRect.maxX) / 2;
    const midY = (localRect.minY + localRect.maxY) / 2;
    const spanX = (localRect.maxX - localRect.minX) / 4;
    const spanY = (localRect.maxY - localRect.minY) / 4;
    const smallCover = {
      ...coverImage,
      localRect: { minX: midX - spanX, maxX: midX + spanX, minY: midY - spanY, maxY: midY + spanY },
    };
    const pdfSmall = buildPdfPlotString({ design: d, projectName: 'GOLDEN', config, meta, coverImage: smallCover });
    check('cover: rect smaller than layout still draws clipped overlay line work',
      (pdfSmall.match(/ l\n/g) || []).length > (plain.match(/ l\n/g) || []).length + 100,
      `${(pdfSmall.match(/ l\n/g) || []).length} vs ${(plain.match(/ l\n/g) || []).length} line ops`);

    // -----------------------------------------------------------
    // Golden-value pinning of the overlay georegistration math. All inputs
    // are fixed (no network): if satelliteLocalRect, computeCoverPlacement,
    // or coverOverlayMapper drift numerically, these fail before a
    // misregistered cover ever ships.
    {
      const { computeCoverPlacement, coverOverlayMapper } = await import('../client/src/lib/nextera/pdfPlot');
      const near = (a: number, b: number, tol = 1e-9) => Math.abs(a - b) <= tol;

      // (1) satelliteLocalRect: fixed WGS84 mosaic bounds + origin -> local feet.
      // ft = deg * 364000; x scaled by cos(origin lat). At lat 30:
      // ftPerDegLon = 364000 * cos(30 deg) = 315233.24697753568.
      const goldenRect = satelliteLocalRect(
        {
          dataUrl: '', widthPx: 2000, heightPx: 1000, zoom: 19,
          bounds: { west: -96.001, east: -95.999, south: 29.999, north: 30.001 },
        },
        { lat: 30, lon: -96 }
      );
      check('cover golden: satelliteLocalRect east-west extent (±315.2332470 ft)',
        near(goldenRect.minX, -315.23324697753573, 1e-6) &&
        near(goldenRect.maxX, 315.23324697753573, 1e-6),
        `minX=${goldenRect.minX} maxX=${goldenRect.maxX}`);
      check('cover golden: satelliteLocalRect north-south extent (±364 ft)',
        near(goldenRect.minY, -364, 1e-9) && near(goldenRect.maxY, 364, 1e-9),
        `minY=${goldenRect.minY} maxY=${goldenRect.maxY}`);

      // (2) computeCoverPlacement: fixed boundary bbox + fixed page transform.
      // span=1000 -> k=5/6 -> 30k=25 ft pad; area 0.25..10.75 in x, 13.25..21.75
      // in y; capH=0.3 -> maxW=10.5, maxH=8.2; 2000x1000 px -> s=0.00525 ->
      // w=10.5, h=5.25, x=0.25, y=13.25+(8.2-5.25)/2=14.725.
      const fixedT = { scale: 100, toX: (ft: number) => 0.5 + ft * 0.01, toY: (ft: number) => 21.5 - ft * 0.01 };
      const p = computeCoverPlacement(
        { minX: 0, maxX: 1000, minY: 0, maxY: 800 },
        { widthPx: 2000, heightPx: 1000 },
        fixedT
      );
      check('cover golden: placement position matches (x=0.25, y=14.725 in)',
        !!p && near(p.x, 0.25) && near(p.y, 14.725), p ? `x=${p.x} y=${p.y}` : 'null');
      check('cover golden: placement size matches (w=10.5, h=5.25 in)',
        !!p && near(p.w, 10.5) && near(p.h, 5.25), p ? `w=${p.w} h=${p.h}` : 'null');
      check('cover golden: degenerate plan area yields null (skip, not garbage)',
        computeCoverPlacement({ minX: 0, maxX: 1, minY: 0, maxY: 1 },
          { widthPx: 2000, heightPx: 1000 },
          { scale: 100, toX: () => 5, toY: () => 5 }) === null);

      // (3) coverOverlayMapper: local feet -> page inches through the placed
      // photo using the golden mosaic rect. Origin (0,0) lands at photo
      // center; rect corners land at photo edges; a quarter-point vertex
      // lands at the expected interior position.
      if (p) {
        const { fx, fy } = coverOverlayMapper(goldenRect, p);
        check('cover golden: site origin maps to photo center (5.5, 17.35 in)',
          near(fx(0), 5.5) && near(fy(0), 17.35), `fx=${fx(0)} fy=${fy(0)}`);
        check('cover golden: mosaic rect corners map to photo edges',
          near(fx(goldenRect.minX), 0.25) && near(fx(goldenRect.maxX), 10.75) &&
          near(fy(goldenRect.maxY), 14.725) && near(fy(goldenRect.minY), 19.975));
        check('cover golden: quarter-point vertex maps to (8.125, 16.0375 in)',
          near(fx(goldenRect.maxX / 2), 8.125) && near(fy(182), 16.0375),
          `fx=${fx(goldenRect.maxX / 2)} fy=${fy(182)}`);
      }

      // The render path must actually use these pinned helpers — a rewrite
      // back to inline math would silently un-pin the goldens.
      check('cover golden: renderCoverImage uses computeCoverPlacement + coverOverlayMapper',
        /computeCoverPlacement\(bbox, img, t\)/.test(pdfSrc) &&
        /coverOverlayMapper\(lr, placement\)/.test(pdfSrc));
    }

    // DXF stays raster- and overlay-free: the cover sheet golden is untouched.
    const sheets = buildDxfPackage({ design: d, projectName: 'GOLDEN', config, meta });
    const goldenCover = readFileSync(path.resolve('scripts/golden/hondo-100mw-sheet-01.dxf'), 'utf8');
    check('cover: DXF cover sheet still byte-identical to golden (no raster/overlay in DXF)',
      sheets[0].content === goldenCover);
  }

  // ---------------------------------------------------------------
  // Feeder-trench stencil RENDER wiring: the feeder cut-outs use stencil
  // masks (feederCutStencil spread onto ground-level opaque materials +
  // FeederTrenchChannels mask meshes), not clipping planes. A material
  // that drops the {...feederCutStencil} spread — or a Canvas that loses
  // gl stencil: true — silently closes the feeder openings. Source-scan
  // both files, same style as the trench render section above.
  {
    const src = readFileSync('client/src/components/DesignScene.tsx', 'utf8');
    const yardSrc = readFileSync('client/src/components/YardExtras.tsx', 'utf8');
    const lines = src.split('\n');

    // Renderer-level switch: without a stencil buffer every stencilFunc
    // test is ignored and the mask does nothing.
    check('feeder stencil: Canvas gl requests stencil: true',
      /<Canvas\b[^>]*gl=\{\{[^}]*\bstencil:\s*true/.test(src));

    // The spread must come from the shared YardExtras definition, never a
    // local copy that could drift from the mask's stencilRef.
    check('feeder stencil: DesignScene imports feederCutStencil from YardExtras (no local copy)',
      /import\s*\{[^}]*\bfeederCutStencil\b[^}]*\}\s*from '\.\/YardExtras'/.test(src) &&
      !/const feederCutStencil/.test(src));

    // Every opaque ground-level cut-out material (the same materials the
    // trench scan classifies as outside-set or prop-forwarded planes) must
    // also spread feederCutStencil. Translucent inside-set fill passes are
    // exempt: they overlay the trench band and must not be stencil-cut.
    let opaqueCutouts = 0;
    let stenciled = 0;
    const missing: string[] = [];
    for (let i = 0; i < lines.length; i++) {
      const m = lines[i].match(/clippingPlanes=\{([^}]+)\}/);
      if (!m) continue;
      const expr = m[1].trim();
      if (/\.inside\b/.test(expr)) continue; // translucent fill pass
      // Custom component call sites forward planes; their internal
      // materials are scanned separately below.
      let tag = '';
      for (let j = i; j >= 0 && j > i - 12; j--) {
        const tm = lines[j].match(/<([A-Za-z][\w.]*)\b[^<]*$/);
        if (tm) { tag = tm[1]; break; }
      }
      if (/^[A-Z]/.test(tag)) continue;
      opaqueCutouts++;
      const ctx = lines.slice(Math.max(0, i - 6), i + 7).join('\n');
      if (/\{\.\.\.feederCutStencil\}/.test(ctx)) stenciled++;
      else missing.push(`line ${i + 1} (${expr})`);
    }
    check('feeder stencil: scan found opaque cut-out materials (not vacuous)',
      opaqueCutouts >= 3, `${opaqueCutouts} opaque cut-out materials`);
    check('feeder stencil: every opaque cut-out material spreads feederCutStencil',
      missing.length === 0, missing.join('; '));
    check('feeder stencil: stenciled count matches opaque cut-out count',
      stenciled === opaqueCutouts, `${stenciled}/${opaqueCutouts}`);

    // Components that own ground-level materials internally must spread the
    // stencil inside their bodies (GroundMaterial both branches via
    // DirtMaterial delegation, SatelliteDrape).
    const componentBody = (name: string): string => {
      const start = src.indexOf(`function ${name}(`);
      if (start < 0) return '';
      const next = src.indexOf('\nfunction ', start + 1);
      return src.slice(start, next < 0 ? src.length : next);
    };
    for (const name of ['GroundMaterial', 'DirtMaterial', 'SatelliteDrape']) {
      check(`feeder stencil: ${name} spreads feederCutStencil onto its material`,
        /\{\.\.\.feederCutStencil\}/.test(componentBody(name)));
    }

    // The scene must actually mount the feeder channels (which draw the
    // stencil masks) — otherwise the spreads are inert.
    check('feeder stencil: DesignScene renders FeederTrenchChannels',
      /<FeederTrenchChannels\b/.test(src));

    // YardExtras side: the shared spread must be a NotEqual test against
    // FEEDER_STENCIL_REF that never writes (mask-consumer semantics)...
    const spreadDef = (() => {
      const start = yardSrc.indexOf('export const feederCutStencil');
      return start < 0 ? '' : yardSrc.slice(start, yardSrc.indexOf('} as const', start));
    })();
    check('feeder stencil: feederCutStencil uses NotEqualStencilFunc against FEEDER_STENCIL_REF',
      /stencilFunc:\s*THREE\.NotEqualStencilFunc/.test(spreadDef) &&
      /stencilRef:\s*FEEDER_STENCIL_REF/.test(spreadDef));
    check('feeder stencil: feederCutStencil never writes to the stencil buffer',
      /stencilWriteMask:\s*0\b/.test(spreadDef));

    // ...and the mask mesh must write FEEDER_STENCIL_REF unconditionally,
    // invisibly, before the ground materials render (negative renderOrder).
    const maskStart = yardSrc.indexOf('function FeederTrenchChannels');
    const maskSrc = maskStart < 0 ? '' : yardSrc.slice(maskStart);
    check('feeder stencil: mask mesh writes FEEDER_STENCIL_REF via Always/Replace',
      /stencilFunc=\{THREE\.AlwaysStencilFunc\}/.test(maskSrc) &&
      /stencilZPass=\{THREE\.ReplaceStencilOp\}/.test(maskSrc) &&
      /stencilRef=\{FEEDER_STENCIL_REF\}/.test(maskSrc));
    check('feeder stencil: mask mesh is invisible and renders before ground materials',
      /colorWrite=\{false\}/.test(maskSrc) && /renderOrder=\{-\d+\}/.test(maskSrc));
  }

  // ---------------------------------------------------------------
  // Feeder-color leak scan: every scene-side use of the feeder palette
  // (feederColor / feederTintByInverterId) must be gated by the
  // showFeederColors toggle, or the monochrome plan view silently shows
  // stray colors. Exporters are the opposite: DXF/PDF always keep feeder
  // colors and must never read the flag. Source-scan every component that
  // imports the palette, same style as the stencil scan above.
  console.log('\n[feeder-colors] showFeederColors gating scan');
  {
    const { readdirSync } = await import('fs');
    const compDir = 'client/src/components';
    const paletteCall = /\b(feederColor|feederTintByInverterId)\s*\(/;
    let usageCount = 0;
    const ungated: string[] = [];
    const paletteImporters: string[] = [];
    for (const file of readdirSync(compDir).filter(f => /\.tsx?$/.test(f))) {
      const path = `${compDir}/${file}`;
      const src = readFileSync(path, 'utf8');
      if (!/from '.*\/feederColors'/.test(src) && !paletteCall.test(src)) continue;
      paletteImporters.push(file);
      const lines = src.split('\n');
      for (let i = 0; i < lines.length; i++) {
        if (/^\s*import\b/.test(lines[i])) continue;
        if (!paletteCall.test(lines[i])) continue;
        usageCount++;
        // Gate must appear on the call line itself (ternary) or within the
        // preceding few lines (early return / assignment guard).
        const ctx = lines.slice(Math.max(0, i - 6), i + 1).join('\n');
        if (!/\bshowFeederColors\b/.test(ctx)) ungated.push(`${file}:${i + 1}`);
      }
      // Any component touching the palette must actually subscribe to the
      // toggle — a nearby mention that isn't wired to the store is not a gate.
      if (paletteCall.test(src.split('\n').filter(l => !/^\s*import\b/.test(l)).join('\n'))) {
        check(`feeder colors: ${file} subscribes to showFeederColors from the design store`,
          /useDesignStore\(\s*(?:\(?\s*)?s\s*=>\s*s\.showFeederColors/.test(src) ||
          /\bshowFeederColors\b/.test(src.match(/useDesignStore[\s\S]{0,600}/)?.[0] ?? ''));
      }
    }
    check('feeder colors: scan found palette call sites in scene components (not vacuous)',
      usageCount >= 4, `${usageCount} call sites in [${paletteImporters.join(', ')}]`);
    check('feeder colors: every scene palette use is gated by showFeederColors',
      ungated.length === 0, ungated.join('; '));
    // Known gated call sites must still exist so the scan keeps covering them.
    for (const [file, fn] of [
      ['DesignScene.tsx', 'feederTintByInverterId'],
      ['DesignScene.tsx', 'feederColor'],
      ['YardExtras.tsx', 'feederColor'],
      ['RealisticEquipment.tsx', 'feederTintByInverterId'],
    ] as const) {
      const src = readFileSync(`${compDir}/${file}`, 'utf8');
      check(`feeder colors: ${file} still uses ${fn} (coverage anchor)`,
        new RegExp(`\\b${fn}\\s*\\(`).test(src.split('\n').filter(l => !/^\s*import\b/.test(l)).join('\n')));
    }
    // Exporters keep colors unconditionally: they must never read the flag.
    for (const exp of ['client/src/lib/nextera/dxfExport.ts', 'client/src/lib/nextera/pdfPlot.ts']) {
      const src = readFileSync(exp, 'utf8');
      check(`feeder colors: ${exp.split('/').pop()} never reads showFeederColors (exports keep colors)`,
        !/\bshowFeederColors\b/.test(src));
    }
  }

  // ---------------------------------------------------------------
  // Legend feeder visibility toggles (display-only). Store behavior: toggle
  // one feeder, hide/show all, and the hidden set MUST reset whenever
  // feeders recompute (regenerate/import/regroup can renumber circuits).
  // Exporters must never read the hidden set — DXF/PDF always keep every
  // feeder. Scene consumers must all subscribe to it.
  console.log('\n[feeder-visibility] legend hide/show toggles');
  {
    const { useDesignStore } = await import('../client/src/lib/stores/useDesignStore');
    const saved = useDesignStore.getState();
    const st = () => useDesignStore.getState();

    const fakeFeeders = [1, 2, 3].map(idx => ({ idx, inverterIds: [], segments: [] })) as any;
    useDesignStore.setState({ feeders: fakeFeeders, hiddenFeeders: new Set<number>() }, false);

    st().toggleFeederHidden(2);
    check('feeder visibility: toggling a feeder adds it to the hidden set',
      st().hiddenFeeders.size === 1 && st().hiddenFeeders.has(2));
    st().toggleFeederHidden(2);
    check('feeder visibility: toggling again removes it',
      st().hiddenFeeders.size === 0);

    st().setAllFeedersHidden(true);
    check('feeder visibility: hide-all hides every feeder idx',
      st().hiddenFeeders.size === 3 && [1, 2, 3].every(i => st().hiddenFeeders.has(i)));
    st().setAllFeedersHidden(false);
    check('feeder visibility: show-all clears the hidden set',
      st().hiddenFeeders.size === 0);

    // Any feeder recompute clears the hidden set (stale idx must never
    // silently hide a different circuit after renumbering).
    st().toggleFeederHidden(1);
    useDesignStore.setState({ design: null, substation: null }, false);
    st().recomputeFeeders();
    check('feeder visibility: recomputeFeeders clears the hidden set',
      st().hiddenFeeders.size === 0);

    // clearSite also resets
    st().toggleFeederHidden(1);
    st().clearSite();
    check('feeder visibility: clearSite clears the hidden set',
      st().hiddenFeeders.size === 0);

    useDesignStore.setState(saved, true);

    // Exports are WYSIWYG for feeders regardless of preview visibility:
    // neither exporter may ever consult the hidden set.
    for (const exp of ['client/src/lib/nextera/dxfExport.ts', 'client/src/lib/nextera/pdfPlot.ts']) {
      const src = readFileSync(exp, 'utf8');
      check(`feeder visibility: ${exp.split('/').pop()} never reads hiddenFeeders (exports keep all feeders)`,
        !/\bhiddenFeeders\b/.test(src));
    }
    // The hidden set is session-ephemeral: never in the project file /
    // session snapshot (projectFromState) or the undo snapshot (snapOf).
    const storeSrc = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
    check('feeder visibility: hiddenFeeders is never persisted (no snapshot/localStorage write)',
      !/hiddenFeeders\s*:\s*(s|snap|prev|p)\./.test(storeSrc) &&
      !/localStorage\.setItem\([^)]*hidden/i.test(storeSrc));
    // Every scene consumer of feeder rendering subscribes to the hidden set.
    for (const file of ['DesignScene.tsx', 'RealisticEquipment.tsx', 'FeederLegend.tsx']) {
      const src = readFileSync(`client/src/components/${file}`, 'utf8');
      check(`feeder visibility: ${file} subscribes to hiddenFeeders`,
        /useDesignStore\(\s*s\s*=>\s*s\.hiddenFeeders\s*\)/.test(src));
    }
    // Legend rows are actual toggle buttons wired to the store actions.
    const legendSrc = readFileSync('client/src/components/FeederLegend.tsx', 'utf8');
    check('feeder visibility: legend rows call toggleFeederHidden',
      /toggleFeederHidden\s*\(/.test(legendSrc) && /<button/.test(legendSrc));
    check('feeder visibility: legend header has a hide/show-all control',
      /setAllFeedersHidden\s*\(/.test(legendSrc));
    // The legend must stay available with feeder colors off (hide/show
    // toggles are independent of coloring); swatches fall back to the
    // scene's single uncolored feeder color instead of the palette.
    check('feeder visibility: legend renders even when showFeederColors is off',
      !/!showFeederColors\s*\|\|/.test(legendSrc) && /rows\.length\s*===\s*0\s*\)\s*return null/.test(legendSrc));
    check('feeder visibility: legend swatch falls back to uncolored feeder color',
      /showFeederColors\s*\?\s*r\.color\.hex\s*:\s*UNCOLORED_FEEDER_HEX/.test(legendSrc) &&
      /UNCOLORED_FEEDER_HEX\s*=\s*'#e91e63'/.test(legendSrc));

    // With colors off every feeder polyline is the same pink, so the scene
    // must draw an "F n" text tag at each home-run midpoint (matching the
    // legend labels). Labels are preview-only (never in DXF/PDF), gated by
    // !showFeederColors, and skip hidden feeders.
    const sceneSrc = readFileSync('client/src/components/DesignScene.tsx', 'utf8');
    check('feeder id labels: DesignScene renders F-labels when colors are off',
      /!showFeederColors\s*&&[\s\S]{0,200}FeederIdLabel/.test(sceneSrc));
    check('feeder id labels: labels skip hidden feeders',
      /!showFeederColors\s*&&[\s\S]{0,120}hiddenFeeders\.has\(f\.idx\)[\s\S]{0,120}FeederIdLabel/.test(sceneSrc));
    check('feeder id labels: label text matches the legend breaker-position naming',
      sceneSrc.includes('#${feederDisplayName(f)}'));
    check('feeder id labels: label anchored at the home-run midpoint',
      /FeederIdLabel[\s\S]{0,600}f\.segments\[f\.segments\.length - 1\]/.test(sceneSrc));
  }

  // ---------------------------------------------------------------
  // Feeder-trench channel GEOMETRY: the stencil scan above locks the render
  // wiring, but not the visible result. Verify the pure sub-segment
  // decomposition (centers, lengths, angles) matches the routed feeder
  // polylines exactly, and that the channel/mask meshes in YardExtras are
  // built from the shared constants so the recessed channel (walls, bottom,
  // conductor) always sits inside the stenciled opening.
  console.log('\n[feeder-trench] channel geometry vs feeder polylines');
  {
    const { feederTrenchSubSegments, FEEDER_TRENCH_W_FT, FEEDER_SUB_MIN_LEN_FT, FEEDER_SUB_OVERHANG_FT } =
      await import('../client/src/lib/nextera/feederTrenchGeom');

    // Real routed feeders on the Hondo design
    const cfg = getConfiguration('ge-aux-400');
    const d = generateSiteDesign(hondo, cfg, 100, 400, { hotClimate: true });
    const xs = d.boundary.polygon.map(p => p.x);
    const sub: Pt = { x: Math.max(...xs) + 300, y: 0 };
    const feeders = generateFeeders(d, sub, cfg.blockMW);
    const subs = feederTrenchSubSegments(feeders);
    check('trench geom: decomposition is non-empty', subs.length > 0, `${subs.length} subs`);

    // Rebuild the expected sub-segments straight from the polylines and
    // compare 1:1 (same keys, centers, lengths, angles in the scene frame).
    let expected = 0;
    let mismatches = 0;
    const byKey = new Map(subs.map(s => [s.key, s]));
    feeders.forEach((f, fi) =>
      f.segments.forEach((seg, si) => {
        for (let i = 0; i < seg.pts.length - 1; i++) {
          const a = seg.pts[i];
          const b = seg.pts[i + 1];
          const len = Math.hypot(b.x - a.x, b.y - a.y);
          if (len < FEEDER_SUB_MIN_LEN_FT) continue;
          expected++;
          const s = byKey.get(`${fi}-${si}-${i}`);
          if (!s ||
            Math.abs(s.cx - (a.x + b.x) / 2) > 1e-9 ||
            Math.abs(s.cz - -(a.y + b.y) / 2) > 1e-9 ||
            Math.abs(s.len - len) > 1e-9 ||
            Math.abs(s.ang - Math.atan2(-(b.y - a.y), b.x - a.x)) > 1e-9) mismatches++;
        }
      })
    );
    check('trench geom: one sub-segment per drawable polyline edge',
      subs.length === expected, `${subs.length}/${expected}`);
    check('trench geom: centers/lengths/angles match polylines exactly',
      mismatches === 0, `${mismatches} mismatches`);
    // Sub-segment lengths must reconstruct the routed feeder total (nothing
    // longer than the min-length filter is dropped or double-counted).
    const totalRouted = feeders.reduce((s, f) => s + f.totalLengthFt, 0);
    const totalSubs = subs.reduce((s, x) => s + x.len, 0);
    check('trench geom: sub-segment lengths sum to routed feeder total',
      Math.abs(totalRouted - totalSubs) < FEEDER_SUB_MIN_LEN_FT * subs.length,
      `${totalSubs.toFixed(1)} vs ${totalRouted.toFixed(1)} ft`);
    // Every sub-segment center must lie on its parent polyline edge midpoint
    // in the PLAN frame too (scene z = -plan y round-trips).
    check('trench geom: scene z is negated plan y for all subs',
      subs.every(s => Number.isFinite(s.cz)) && subs.every(s => {
        const [fi, si, i] = s.key.split('-').map(Number);
        const a = feeders[fi].segments[si].pts[i];
        const b = feeders[fi].segments[si].pts[i + 1];
        return Math.abs(-s.cz - (a.y + b.y) / 2) < 1e-9;
      }));

    // A FINITE substation far outside the parcel (the task-213 repro wording)
    // must always yield fully finite routing + trench geometry.
    {
      const far: Pt = { x: Math.min(...xs) - 200, y: 0 };
      const farFeeders = generateFeeders(d, far, cfg.blockMW);
      const farSubs = feederTrenchSubSegments(farFeeders);
      check('NaN guard: finite far-outside substation routes with all-finite feeder points',
        farFeeders.length > 0 && farFeeders.every(f =>
          f.segments.every(seg => seg.pts.every(p =>
            Number.isFinite(p.x) && Number.isFinite(p.y)))));
      check('NaN guard: finite far-outside substation yields all-finite trench subs',
        farSubs.length > 0 && farSubs.every(s2 =>
          Number.isFinite(s2.cx) && Number.isFinite(s2.cz) &&
          Number.isFinite(s2.len) && Number.isFinite(s2.ang)));
    }

    // NaN guards (regression: substation placed via the store API with a
    // non-finite coordinate produced NaN feeder geometry — duplicate "eNaN"
    // React keys and NaN bounding spheres in the 3D view).
    {
      const badSubs: Pt[] = [
        { x: Number.NaN, y: 0 },
        { x: Math.min(...xs) - 200, y: Number.NaN },
        { x: Number.POSITIVE_INFINITY, y: 0 },
      ];
      check('NaN guard: generateFeeders refuses non-finite substation points',
        badSubs.every(s2 => generateFeeders(d, s2, cfg.blockMW).length === 0));
      const { feederCorridorInfo } = await import('../client/src/lib/nextera/feeders');
      check('NaN guard: feederCorridorInfo returns null for non-finite substation',
        badSubs.every(s2 => feederCorridorInfo(d, s2) === null));
      // Even if a poisoned polyline reaches the decomposition, no sub-segment
      // may carry non-finite geometry (NaN length passes a plain < filter).
      const poisoned = [{
        idx: 1,
        segments: [
          { pts: [{ x: 0, y: 0 }, { x: Number.NaN, y: 5 }, { x: 20, y: 5 }] },
          { pts: [{ x: 0, y: 0 }, { x: 10, y: 0 }] },
        ],
      }];
      const poisonedSubs = feederTrenchSubSegments(poisoned);
      check('NaN guard: feederTrenchSubSegments drops non-finite edges, keeps finite ones',
        poisonedSubs.length === 1 &&
        poisonedSubs.every(s2 =>
          Number.isFinite(s2.cx) && Number.isFinite(s2.cz) &&
          Number.isFinite(s2.len) && Number.isFinite(s2.ang)));
      // Store guard: placeSubstation must reject non-finite points outright.
      const storeSrc = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
      check('NaN guard: placeSubstation validates coordinates before storing',
        /placeSubstation: \(pt: Pt\) => \{[\s\S]{0,600}?Number\.isFinite\(pt\.x\)[\s\S]{0,80}?Number\.isFinite\(pt\.y\)/.test(storeSrc));
      check('NaN guard: restored/imported substation points are sanitized',
        /substation: sanitizeSubstation\(s\.substation\)/.test(storeSrc) &&
        /substation: sanitizeSubstation\(p\.substation\)/.test(storeSrc));

      // Task-218 follow-up: EVERY numeric drafter input path is guarded, not
      // just the substation.
      check('NaN guard: restored/imported layoutEdits are deep-sanitized',
        /layoutEdits: sanitizeLayoutEdits\(s\.layoutEdits\)/.test(storeSrc) &&
        /layoutEdits: sanitizeLayoutEdits\(p\.layoutEdits\)/.test(storeSrc));
      check('NaN guard: restored/imported latticeShift falls back to null when non-finite',
        /latticeShift: finitePt\(s\.latticeShift\) \? s\.latticeShift : null/.test(storeSrc) &&
        /latticeShift: finitePt\(p\.latticeShift\) \? p\.latticeShift : null/.test(storeSrc));
      check('NaN guard: history snap layoutEdits are sanitized on session restore',
        /layoutEdits: sanitizeLayoutEdits\(e2\.layoutEdits\)/.test(storeSrc));
      check('NaN guard: applyOptimizedLayout validates latticeShift and trenchX',
        /applyOptimizedLayout: \(params: OptimizeParams\) => \{[\s\S]{0,400}?finitePt\(params\.latticeShift\)[\s\S]{0,300}?Number\.isFinite\(params\.trenchX\)/.test(storeSrc));

      const { sanitizeLayoutEdits, useDesignStore: nanStore } =
        await import('../client/src/lib/stores/useDesignStore');
      const nan = Number.NaN;
      const inf = Number.POSITIVE_INFINITY;
      const dirty = sanitizeLayoutEdits({
        rowMoves: { 1: { dx: 5, dy: 0 }, 2: { dx: nan, dy: 0 }, x: { dx: 1, dy: 1 } },
        blockMoves: { 3: { dx: 0, dy: -2 }, 4: { dx: 0, dy: inf } },
        equipMoves: { 'inv-1': { dx: 1, dy: 1 }, 'inv-2': { dx: '3', dy: 1 } },
        trenchX: nan,
        laydownPin: { x: 10, y: nan },
        laydownSize: { length: -5, width: 20 },
        augPins: { 'future-blk-1': { x: 1, y: 2 }, 'island-aug-2-1': { x: 3, y: 4 }, 'future-blk-2': { x: inf, y: 2 }, 'island-aug-1-1': { x: nan, y: 4 }, evil: { x: 1, y: 1 } },
        gatePin: { x: inf, y: 0 },
        aisleMoves: { 1: 4, 2: nan },
        feederCorridor: inf,
        customRoads: [
          { id: 'r1', pts: [{ x: 0, y: 0 }, { x: nan, y: 5 }, { x: 20, y: 5 }] },
          { id: 'r2', pts: [{ x: 0, y: 0 }, { x: nan, y: 5 }] },
          { id: '', pts: [{ x: 0, y: 0 }, { x: 9, y: 9 }] },
        ],
        forcedEdits: ['row-1', 7, ''],
      });
      check('NaN guard: sanitizeLayoutEdits drops non-finite entries, keeps finite ones',
        Object.keys(dirty.rowMoves ?? {}).join(',') === '1' &&
        Object.keys(dirty.blockMoves ?? {}).join(',') === '3' &&
        Object.keys(dirty.equipMoves ?? {}).join(',') === 'inv-1' &&
        dirty.trenchX === undefined &&
        dirty.laydownPin === undefined &&
        dirty.laydownSize === undefined &&
        Object.keys(dirty.augPins ?? {}).join(',') === 'future-blk-1,island-aug-2-1' &&
        dirty.gatePin === undefined &&
        Object.keys(dirty.aisleMoves ?? {}).join(',') === '1' &&
        dirty.feederCorridor === undefined &&
        (dirty.customRoads ?? []).map(r => r.id).join(',') === 'r1' &&
        (dirty.customRoads ?? [])[0]?.pts.length === 2 &&
        (dirty.forcedEdits ?? []).join(',') === 'row-1',
        JSON.stringify(dirty));
      check('NaN guard: sanitizeLayoutEdits keeps a fully clean edit set intact',
        (() => {
          const clean = {
            rowMoves: { 1: { dx: 5, dy: 0 } },
            trenchX: 120,
            laydownPin: { x: 10, y: 20 },
            laydownSize: { length: 100, width: 50 },
            gatePin: { x: 3, y: 4 },
            aisleMoves: { 1: 4 },
            feederCorridor: -40,
            customRoads: [{ id: 'r1', pts: [{ x: 0, y: 0 }, { x: 20, y: 5 }] }],
            forcedEdits: ['row-1'],
          };
          return JSON.stringify(sanitizeLayoutEdits(clean)) === JSON.stringify(clean);
        })());
      check('NaN guard: sanitizeLayoutEdits returns {} for junk input',
        JSON.stringify(sanitizeLayoutEdits(null)) === '{}' &&
        JSON.stringify(sanitizeLayoutEdits([1, 2])) === '{}' &&
        JSON.stringify(sanitizeLayoutEdits('x')) === '{}');
      // Store guards: non-finite MW/MWh targets are ignored outright.
      {
        const st0 = nanStore.getState();
        const prevMW = st0.targetMW;
        const prevMWh = st0.targetMWh;
        const prevUndo = st0.undoStack.length;
        st0.setTargetMW(Number.NaN);
        st0.setTargetMWh(Number.POSITIVE_INFINITY);
        const st1 = nanStore.getState();
        check('NaN guard: setTargetMW/setTargetMWh ignore non-finite values (no state or history change)',
          st1.targetMW === prevMW && st1.targetMWh === prevMWh &&
          st1.undoStack.length === prevUndo);
      }

      // UI surfacing: every placeSubstation / removeSubstation call site in
      // the UI must capture the returned notice and show it (toast), so a
      // rejected placement or a corridor-pin reset never looks like a silent
      // no-op to the drafter.
      const sceneSrc2 = readFileSync('client/src/components/DesignScene.tsx', 'utf8');
      const panelSrc2 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
      check('notice surfacing: DesignScene toasts the placeSubstation return value',
        /const notice = placeSubstation\([\s\S]{0,120}?\);\s*\n\s*if \(notice\) toast\.warning\(notice\)/.test(sceneSrc2) &&
        !/(?<!const notice = )placeSubstation\(\{/.test(sceneSrc2.replace(/const notice = placeSubstation\(\{/g, '')));
      check('notice surfacing: DesignControlPanel toasts the removeSubstation return value',
        /const notice = removeSubstation\(\);\s*\n\s*if \(notice\) toast\.warning\(notice\)/.test(panelSrc2));
      check('notice surfacing: no UI call site discards the placeSubstation return',
        ['client/src/components/DesignScene.tsx', 'client/src/components/DesignControlPanel.tsx'].every(f => {
          const src = readFileSync(f, 'utf8');
          // Every invocation (not the store subscription) must assign the result.
          const calls = src.match(/(?:^|[^.\w])placeSubstation\(\{/g) ?? [];
          const captured = src.match(/(?:const|let) notice = placeSubstation\(\{/g) ?? [];
          return calls.length === captured.length;
        }));

      // Feeder maps from untrusted files: only integer feeder indices and
      // known conductor sizes survive load; junk entries are dropped.
      {
        const { sanitizeFeederAssignments, sanitizeFeederSizes } =
          await import('../client/src/lib/stores/useDesignStore');
        const assign = sanitizeFeederAssignments({
          'inv-1': 1, 'inv-2': 2, 'inv-3': Number.NaN, 'inv-4': 1.5,
          'inv-5': Number.POSITIVE_INFINITY, 'inv-6': '2', 'inv-7': null, 'inv-8': -3,
        });
        check('NaN guard: sanitizeFeederAssignments keeps only finite integer values',
          JSON.stringify(assign) === JSON.stringify({ 'inv-1': 1, 'inv-2': 2, 'inv-8': -3 }),
          JSON.stringify(assign));
        check('NaN guard: sanitizeFeederAssignments returns {} for junk input',
          JSON.stringify(sanitizeFeederAssignments(null)) === '{}' &&
          JSON.stringify(sanitizeFeederAssignments([1])) === '{}' &&
          JSON.stringify(sanitizeFeederAssignments('x')) === '{}');
        const sizes = sanitizeFeederSizes({
          1: '500', 2: '750', 3: '1000', 4: '9999', 5: 750,
          'x': '500', '2.5': '750', 6: null,
        });
        check('NaN guard: sanitizeFeederSizes keeps integer keys with APPROVED feeder sizes only (500/750 migrate out per [691])',
          JSON.stringify(sizes) === JSON.stringify({ 3: '1000' }),
          JSON.stringify(sizes));
        check('NaN guard: sanitizeFeederSizes returns {} for junk input',
          JSON.stringify(sanitizeFeederSizes(null)) === '{}' &&
          JSON.stringify(sanitizeFeederSizes(['500'])) === '{}' &&
          JSON.stringify(sanitizeFeederSizes('x')) === '{}');
        check('NaN guard: restored/imported feeder maps are sanitized',
          /feederAssignments: sanitizeFeederAssignments\(s\.feederAssignments\)/.test(storeSrc) &&
          /feederAssignments: sanitizeFeederAssignments\(p\.feederAssignments\)/.test(storeSrc) &&
          /feederSizes: sanitizeFeederSizes\(s\.feederSizes\)/.test(storeSrc) &&
          /feederSizes: sanitizeFeederSizes\(p\.feederSizes\)/.test(storeSrc));
      }
    }

    // YardExtras must consume the SAME decomposition + constants (no local
    // copy that could drift from what the test verifies), and the mask /
    // channel meshes must be sized from them: mask plane = (len+w, w),
    // bottom plane = (len+w, w) at -TRENCH_DEPTH_FT, walls at ±w/2 spanning
    // depth d, conductor inside the channel (radius < w/2, above -d).
    const yardSrc = readFileSync('client/src/components/YardExtras.tsx', 'utf8');
    check('trench geom: YardExtras imports feederTrenchSubSegments (no local copy)',
      /feederTrenchSubSegments/.test(yardSrc) &&
      /from '\.\.\/lib\/nextera\/feederTrenchGeom'/.test(yardSrc) &&
      !/const feederTrenchSubSegments/.test(yardSrc));
    check('trench geom: YardExtras re-exports FEEDER_TRENCH_W_FT from the shared module',
      /export \{ FEEDER_TRENCH_W_FT \} from '\.\.\/lib\/nextera\/feederTrenchGeom'/.test(yardSrc));
    const chanStart = yardSrc.indexOf('export function FeederTrenchChannels');
    const chanSrc = chanStart < 0 ? '' : yardSrc.slice(chanStart, yardSrc.indexOf('\n}\n', chanStart));
    check('trench geom: channels call the shared decomposition in a memo',
      /useMemo\(\(\) => feederTrenchSubSegments\(feeders, patchBounds\)/.test(chanSrc));
    // The geometry now lives in the shared instanced renderer: unit planes /
    // cylinders scaled per instance, so the checks below assert the SAME
    // footprints and positions via the instance matrix scales instead of
    // per-mesh planeGeometry args.
    const instStart = yardSrc.indexOf('function InstancedTrenchChannels');
    const instSrc = instStart < 0 ? '' : yardSrc.slice(instStart, yardSrc.indexOf('\n}\n', instStart));
    check('trench geom: channel depth/width come from shared constants',
      /w=\{FEEDER_TRENCH_W_FT\}/.test(chanSrc) && /const d = TRENCH_DEPTH_FT;/.test(instSrc));
    // Stencil mask and excavation bottom use the identical (len+w, w)
    // footprint — the recessed channel exactly fills the opening.
    check('trench geom: mask and bottom planes share the (len+w, w) footprint',
      /const L = s\.len \+ w;/.test(instSrc) &&
      /push\(stencil, 0, 0\.45, 0, QUAT_XNEG90, L, w, 1\)/.test(instSrc) &&
      /push\(bottom, 0, -d, 0, QUAT_XNEG90, L, w, 1\)/.test(instSrc));
    check('trench geom: mask overhang equals FEEDER_SUB_OVERHANG_FT (= w)',
      FEEDER_SUB_OVERHANG_FT === FEEDER_TRENCH_W_FT);
    check('trench geom: side walls sit at ±w/2 and span the full depth',
      /push\(walls, 0, -d \/ 2, -w \/ 2, QUAT_IDENT, L, d, 1\)/.test(instSrc) &&
      /push\(walls, 0, -d \/ 2, w \/ 2, QUAT_IDENT, L, d, 1\)/.test(instSrc) &&
      /push\(walls, -L \/ 2, -d \/ 2, 0, QUAT_Y90, w, d, 1\)/.test(instSrc) &&
      /push\(walls, L \/ 2, -d \/ 2, 0, QUAT_Y90, w, d, 1\)/.test(instSrc));
    check('trench geom: excavation bottom sits at -TRENCH_DEPTH_FT',
      /push\(bottom, 0, -d, 0, QUAT_XNEG90, L, w, 1\)/.test(instSrc));
    // Conductor: radius 0.3 < w/2 and center -(d-0.55) strictly between
    // -d (bottom) and 0 (grade) so the cable stays visible in the opening.
    // Depth comes from YardExtras' exported TRENCH_DEPTH_FT constant.
    const depthMatch = yardSrc.match(/export const TRENCH_DEPTH_FT = ([\d.]+);/);
    const trenchDepth = depthMatch ? Number(depthMatch[1]) : NaN;
    check('trench geom: TRENCH_DEPTH_FT constant found in YardExtras',
      Number.isFinite(trenchDepth) && trenchDepth > 0, String(trenchDepth));
    const condR = 0.3, condY = -(trenchDepth - 0.55);
    check('trench geom: conductor mesh uses radius 0.3 at -(d - 0.55)',
      /condRadius=\{0\.3\}/.test(chanSrc) && /condDrop=\{0\.55\}/.test(chanSrc) && /condSegs=\{10\}/.test(chanSrc) &&
      /p\.set\(0, -\(d - condDrop\), 0\), QUAT_Z90, sc\.set\(condRadius, Math\.max\(L - 0\.4, 0\.5\), condRadius\)/.test(instSrc));
    check('trench geom: conductor fits inside the channel cross-section',
      condR < FEEDER_TRENCH_W_FT / 2 && condY + condR < 0 && condY - condR > -trenchDepth);
  }

  // ---------------------------------------------------------------
  {
    console.log('\n[39] Multi-boundary KMZ: Great Prairie sample + boundary picker');
    const { listKmlBoundaryOptions } = await import('../client/src/lib/nextera/kmz');
    const gpBuf = readFileSync('client/public/samples/great-prairie-1-2.kmz');
    const gpZip = await JSZip.loadAsync(gpBuf);
    const gpEntry = Object.values(gpZip.files).find(f => f.name.toLowerCase().endsWith('.kml'))!;
    const gpKml = await gpEntry.async('text');

    const opts = listKmlBoundaryOptions(gpKml);
    check('gp: KMZ exposes multiple parcel-scale boundary options', opts.length > 1, `${opts.length}`);
    const findOpt = (nm: string) => opts.find(o => o.name === nm);
    const sub = findOpt('GREAT PRAIRIE WIND LLC substation boundary');
    const gp1 = findOpt('GP1 phase 1 - 200MW');
    const ess = findOpt('GP Energy Storage Boundary');
    check('gp: substation boundary listed (~14.8 ac)', !!sub && Math.abs(sub.areaAcres - 14.8) < 0.5, sub && sub.areaAcres.toFixed(1));
    check('gp: GP1 phase 1 listed (~17.2 ac)', !!gp1 && Math.abs(gp1.areaAcres - 17.2) < 0.5, gp1 && gp1.areaAcres.toFixed(1));
    check('gp: energy storage boundary listed (~39.7 ac)', !!ess && Math.abs(ess.areaAcres - 39.7) < 0.5, ess && ess.areaAcres.toFixed(1));

    // Each option parses into a boundary whose acreage matches the listing
    // and whose kmlName reflects the CHOSEN placemark, not polygon[0].
    for (const o of [sub!, gp1!, ess!]) {
      const b = parseKmlText(gpKml, 'Great Prairie 1 & 2', o.index);
      check(`gp: option "${o.name}" parses at its listed acreage`,
        Math.abs(b.areaAcres - o.areaAcres) < 0.2, `${b.areaAcres.toFixed(1)} vs ${o.areaAcres.toFixed(1)}`);
      check(`gp: option "${o.name}" carries its own placemark name`, b.kmlName === o.name, b.kmlName);
    }
    // Out-of-range index fails loudly, never silently falls back to polygon 0.
    let threw = false;
    try { parseKmlText(gpKml, 'x', 999); } catch { threw = true; }
    check('gp: out-of-range polygon index throws', threw);

    // Laydown sample is a separate single-boundary site (~9.5 ac).
    const ldBuf = readFileSync('client/public/samples/laydown.kmz');
    const ldZip = await JSZip.loadAsync(ldBuf);
    const ldEntry = Object.values(ldZip.files).find(f => f.name.toLowerCase().endsWith('.kml'))!;
    const ldKml = await ldEntry.async('text');
    const ldOpts = listKmlBoundaryOptions(ldKml);
    check('laydown: exactly one boundary option (no picker)', ldOpts.length === 1, `${ldOpts.length}`);
    const ld = parseKmlText(ldKml, 'Great Prairie Laydown', ldOpts[0].index);
    check('laydown: parses at ~9.5 ac', Math.abs(ld.areaAcres - 9.5) < 0.5, ld.areaAcres.toFixed(1));

    // Wiring contracts: store opens the picker for multi-boundary files and
    // the panel defaults to Great Prairie with the three approved boundaries.
    const storeSrc2 = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
    check('store: multi-option KML opens the boundary picker',
      /options\.length > 1/.test(storeSrc2) && /boundaryPicker: \{ sourceName, kmlText, options \}/.test(storeSrc2));
    check('store: chooseBoundary parses the picked polygon index',
      /parseKmlText\(picker\.kmlText, picker\.sourceName, index\)/.test(storeSrc2));
    const panelSrc = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
    check('panel: Great Prairie 1 & 2 is the first (default) sample',
      /SAMPLE_SITES[^=]*=\s*\[\s*\{\s*name: 'Great Prairie 1 & 2'/.test(panelSrc));
    check('panel: Great Prairie sample restricts choices to the three approved boundaries',
      panelSrc.includes("'GREAT PRAIRIE WIND LLC substation boundary'") &&
      panelSrc.includes("'GP1 phase 1 - 200MW'") &&
      panelSrc.includes("'GP Energy Storage Boundary'"));
    check('panel: laydown ships as its own sample site',
      /name: 'Great Prairie Laydown', url: assetUrl\('\/samples\/laydown\.kmz'\)/.test(panelSrc));
    check('panel: fresh start auto-loads the default sample (never over a saved session)',
      /if \(st\.boundary \|\| st\.savedSession\) return;/.test(panelSrc) &&
      /handleSample\(SAMPLE_SITES\[0\]\)/.test(panelSrc));
  }

  // ---------------------------------------------------------------
  // [39b] Great Prairie 400 MW / 1600 MWh (QTY3 mirrored islands): every
  // ~6-PCS chunk must route INDIVIDUALLY through its FJB to the substation
  // in a parallel bundle — never a combined/collinear trunk. Regression for
  // the bug where west-end FJB sharers seeded run lines AT the box, the
  // ideal fan failed the obstacle check, and grid-reroute collapsed several
  // circuits onto ONE collinear trench (wrong trench counts on the bottom
  // islands). Also covers climb-step compression (shallow strip) and
  // same-FJB approach-hop lane separation in the island corridor.
  console.log('\n[39b] GP 400 MW: no collinear cross-feeder trench trunks');
  {
    const { feederTrenchSubSegments } =
      await import('../client/src/lib/nextera/feederTrenchGeom');
    const gpBuf = readFileSync('client/public/samples/great-prairie-1-2.kmz');
    const gpZip = await JSZip.loadAsync(gpBuf);
    const gpEntry = Object.values(gpZip.files).find(f => f.name.toLowerCase().endsWith('.kml'))!;
    const gpKml = await gpEntry.async('text');
    const { listKmlBoundaryOptions } = await import('../client/src/lib/nextera/kmz');
    const ess = listKmlBoundaryOptions(gpKml).find(o => o.name === 'GP Energy Storage Boundary')!;
    const boundary = parseKmlText(gpKml, 'Great Prairie 1 & 2', ess.index);
    const cfg = getConfiguration('ge-aux-400')!;
    const d = generateSiteDesign(boundary, cfg, 400, 1600, { hotClimate: true, containersPerPcs: 3 });
    const ys = d.equipment.map(e => e.y), xs = d.equipment.map(e => e.x);
    const substation = { x: (Math.min(...xs) + Math.max(...xs)) / 2, y: Math.min(...ys) - 400 };
    const fjbs = d.equipment.filter(e => e.kind === 'feederJunctionBox');
    // The feeder cap is fixed at 7 in the app (legacy 5/6 dropdown removed);
    // only the reachable cap is exercised here.
    for (const maxPer of [7]) {
      const feeders = generateFeeders(d, substation, cfg.blockMW, { maxPerFeeder: maxPer });
      const subs = feederTrenchSubSegments(feeders as any);
      // Collinear trunk = two DIFFERENT feeders' trench pieces on the same
      // line (lateral gap < 1 ft) sharing a long stretch (> 60 ft), outside
      // the two legitimate convergence zones: within 70 ft of a shared FJB
      // and the substation entry row.
      const bad: string[] = [];
      for (let i = 0; i < subs.length; i++) for (let j = i + 1; j < subs.length; j++) {
        const a = subs[i], b = subs[j];
        if (a.idx === b.idx) continue;
        const angDiff = Math.abs(((a.ang - b.ang) + Math.PI) % Math.PI);
        if (!(angDiff < 0.02 || angDiff > Math.PI - 0.02)) continue;
        const dx = b.cx - a.cx, dz = b.cz - a.cz;
        const ux = Math.cos(a.ang), uz = Math.sin(a.ang);
        const lon = dx * ux + dz * uz;
        const lat = Math.abs(-dx * uz + dz * ux);
        if (lat >= 1) continue;
        const lo = Math.max(-a.len / 2, lon - b.len / 2);
        const hi = Math.min(a.len / 2, lon + b.len / 2);
        if (hi - lo <= 60) continue;
        const mid = (lo + hi) / 2;
        const mx = a.cx + ux * mid, my = -(a.cz + uz * mid);
        if (fjbs.some(f => Math.hypot(mx - f.x, my - f.y) < 70)) continue;
        if (Math.hypot(mx - substation.x, my - substation.y) < 200 && Math.abs(my - substation.y) < 5) continue;
        bad.push(`F${a.idx}~F${b.idx} lat=${lat.toFixed(2)} at (${mx.toFixed(0)},${my.toFixed(0)}) ovl=${(hi - lo).toFixed(0)}`);
      }
      check(`gp400 maxPer=${maxPer}: feeder count matches chunking (no dropped circuits)`,
        feeders.length >= Math.ceil(105 / maxPer), `${feeders.length}`);
      check(`gp400 maxPer=${maxPer}: no long collinear cross-feeder trench pieces`,
        bad.length === 0, bad.slice(0, 5).join('; ') || 'clean');
      // The collinear-separation post-pass mutates home-run geometry AFTER
      // the electrical outputs were first computed — every returned circuit
      // must stay self-consistent with its FINAL segments.
      const { CONDUCTOR_R_PER_KFT, MV_VOLTAGE } =
        await import('../client/src/lib/nextera/feeders');
      const inconsistent = feeders.filter(f => {
        const segLen = f.segments.reduce((s, sg) => s + sg.lengthFt, 0);
        if (Math.abs(segLen - f.totalLengthFt) > 0.01) return true;
        const rPerFt = CONDUCTOR_R_PER_KFT[f.material][f.size] / 1000 / Math.max(1, f.parallelSets || 1);
        const eolScale = f.amps > 0 ? f.eolAmps / f.amps : 1;
        const vd = f.segments.reduce((s, sg) => s + Math.sqrt(3) * sg.amps * eolScale * rPerFt * sg.lengthFt, 0);
        return Math.abs(vd - f.vdVolts) > 0.01 ||
          Math.abs(f.vdPct - (vd / MV_VOLTAGE) * 100) > 1e-6;
      });
      check(`gp400 maxPer=${maxPer}: circuit lengths + voltage drop match final geometry`,
        inconsistent.length === 0, inconsistent.map(f => `F${f.idx}`).join(','));
    }
  }

  // ---------------------------------------------------------------
  // Feeder-trench JOINT geometry: each channel piece (and its stencil-mask
  // opening) is an overlong rectangle (len + FEEDER_SUB_OVERHANG_FT by
  // FEEDER_TRENCH_W_FT). Consecutive pieces must overlap around their shared
  // polyline vertex so no sliver of un-cut ground hides the cable at an
  // elbow — including shallow/obtuse turn angles from non-orthogonal
  // detours, not just right angles.
  console.log('\n[feeder-trench] overlong rectangles overlap at every joint');
  {
    const { feederTrenchSubSegments, FEEDER_TRENCH_W_FT, FEEDER_SUB_MIN_LEN_FT, FEEDER_SUB_OVERHANG_FT } =
      await import('../client/src/lib/nextera/feederTrenchGeom');
    const w = FEEDER_TRENCH_W_FT;
    const oh = FEEDER_SUB_OVERHANG_FT;

    // Point-in-overlong-rect test in the PLAN frame. The rect for edge a->b
    // is centered on the edge midpoint, (len + oh) long by w wide.
    type P = { x: number; y: number };
    const insideRect = (p: P, a: P, b: P, eps = 1e-9): boolean => {
      const len = Math.hypot(b.x - a.x, b.y - a.y);
      if (len === 0) return false;
      const ux = (b.x - a.x) / len;
      const uy = (b.y - a.y) / len;
      const dx = p.x - a.x;
      const dy = p.y - a.y;
      const along = dx * ux + dy * uy;
      const perp = Math.abs(dx * uy - dy * ux);
      return along >= -oh / 2 - eps && along <= len + oh / 2 + eps && perp <= w / 2 + eps;
    };

    // A joint is "clean" when the union of the two overlong rects covers the
    // entire visible elbow of the nominal trench footprint: (1) the full
    // closed disk of radius w/2 around the shared vertex V (the trench
    // opening at the elbow), and (2) the outer miter corner region of the
    // exact width-w strips. Sample both densely.
    const jointCovered = (a: P, v: P, b: P): { ok: boolean; why: string } => {
      const inEither = (p: P) => insideRect(p, a, v) || insideRect(p, v, b);
      // (1) elbow disk
      for (let i = 0; i < 64; i++) {
        for (const r of [w * 0.25, w * 0.4999]) {
          const t = (i / 64) * Math.PI * 2;
          const p = { x: v.x + r * Math.cos(t), y: v.y + r * Math.sin(t) };
          if (!inEither(p)) return { ok: false, why: `elbow disk gap at r=${r.toFixed(2)}` };
        }
      }
      if (!inEither(v)) return { ok: false, why: 'vertex uncovered' };
      // (2) nominal footprint near the joint: sample points of BOTH exact
      // (non-overlong) strips within w of V across the full width — every
      // one must be cut by at least one overlong rect (no sliver).
      const strips: [P, P][] = [[a, v], [v, b]];
      for (const [s0, s1] of strips) {
        const len = Math.hypot(s1.x - s0.x, s1.y - s0.y);
        const ux = (s1.x - s0.x) / len;
        const uy = (s1.y - s0.y) / len;
        const vAlong = (v.x - s0.x) * ux + (v.y - s0.y) * uy; // 0 or len
        for (let ai = 0; ai <= 20; ai++) {
          const along = Math.min(Math.max(vAlong - w + (ai / 20) * 2 * w, 0), len);
          for (let pi = -10; pi <= 10; pi++) {
            const perp = (pi / 10) * (w / 2) * 0.9999;
            const p = { x: s0.x + along * ux - perp * uy, y: s0.y + along * uy + perp * ux };
            if (!inEither(p)) return { ok: false, why: `strip gap at along=${along.toFixed(2)} perp=${perp.toFixed(2)}` };
          }
        }
      }
      // The two overlong rects must genuinely OVERLAP (shared area), not
      // merely abut: the vertex plus small offsets along both directions
      // must be inside BOTH rects.
      const inBoth = (p: P) => insideRect(p, a, v) && insideRect(p, v, b);
      const dirs: P[] = [
        { x: (v.x - a.x), y: (v.y - a.y) },
        { x: (b.x - v.x), y: (b.y - v.y) },
      ].map(d => {
        const l = Math.hypot(d.x, d.y);
        return { x: d.x / l, y: d.y / l };
      });
      const probes = [v,
        { x: v.x - dirs[0].x * w * 0.2, y: v.y - dirs[0].y * w * 0.2 },
        { x: v.x + dirs[1].x * w * 0.2, y: v.y + dirs[1].y * w * 0.2 }];
      if (!probes.every(inBoth)) return { ok: false, why: 'rects abut but do not overlap' };
      return { ok: true, why: '' };
    };

    // (a) Real routed feeders on the Hondo design: walk every consecutive
    // drawable sub-segment pair sharing a vertex and verify the joint.
    const cfg = getConfiguration('ge-aux-400');
    const d = generateSiteDesign(hondo, cfg, 100, 400, { hotClimate: true });
    const xs = d.boundary.polygon.map(p => p.x);
    const sub: Pt = { x: Math.max(...xs) + 300, y: 0 };
    const feeders = generateFeeders(d, sub, cfg.blockMW);
    const subsReal = feederTrenchSubSegments(feeders);
    const drawn = new Set(subsReal.map(s => s.key));
    let joints = 0;
    let nonOrtho = 0;
    let skippedShort = 0;
    let badJoints = 0;
    let firstBad = '';
    feeders.forEach((f, fi) =>
      f.segments.forEach((seg, si) => {
        for (let i = 0; i < seg.pts.length - 2; i++) {
          const k1 = `${fi}-${si}-${i}`;
          const k2 = `${fi}-${si}-${i + 1}`;
          if (!drawn.has(k1)) continue;
          if (!drawn.has(k2)) {
            // A sub-min-length middle edge was dropped: the two drawn
            // neighbors around it must still overlap thanks to the
            // overhang exceeding the dropped gap. Verify directly.
            const k3 = `${fi}-${si}-${i + 2}`;
            if (drawn.has(k3)) {
              skippedShort++;
              // Geometric check: sample the dropped middle edge across the
              // full trench width — every point must still be cut by one of
              // the two neighboring overlong rects.
              const m0 = seg.pts[i + 1];
              const m1 = seg.pts[i + 2];
              const gap = Math.hypot(m1.x - m0.x, m1.y - m0.y);
              const ux = gap > 0 ? (m1.x - m0.x) / gap : 0;
              const uy = gap > 0 ? (m1.y - m0.y) / gap : 0;
              const inNbr = (p: P) =>
                insideRect(p, seg.pts[i], seg.pts[i + 1]) ||
                insideRect(p, seg.pts[i + 2], seg.pts[i + 3]);
              let covered = true;
              for (let ai = 0; ai <= 10 && covered; ai++) {
                const along = (ai / 10) * gap;
                for (let pi = -10; pi <= 10; pi++) {
                  const perp = (pi / 10) * (w / 2) * 0.9999;
                  const p = { x: m0.x + along * ux - perp * uy, y: m0.y + along * uy + perp * ux };
                  if (!inNbr(p)) { covered = false; break; }
                }
              }
              if (!covered) {
                badJoints++;
                if (!firstBad) firstBad = `${k1}/${k3}: dropped ${gap.toFixed(2)} ft edge left a gap`;
              }
            }
            continue;
          }
          joints++;
          const a = seg.pts[i];
          const v = seg.pts[i + 1];
          const b = seg.pts[i + 2];
          const angA = Math.atan2(v.y - a.y, v.x - a.x);
          const angB = Math.atan2(b.y - v.y, b.x - v.x);
          let dev = Math.abs(angB - angA);
          if (dev > Math.PI) dev = 2 * Math.PI - dev;
          if (dev > 1e-6 && Math.abs(dev - Math.PI / 2) > 1e-6) nonOrtho++;
          const res = jointCovered(a, v, b);
          if (!res.ok) {
            badJoints++;
            if (!firstBad) firstBad = `${k1}/${k2}: ${res.why} (dev=${(dev * 180 / Math.PI).toFixed(1)}°)`;
          }
        }
      })
    );
    check('trench joints: real routed feeders produce joints to verify', joints > 0, `${joints} joints (${nonOrtho} non-orthogonal, ${skippedShort} short-edge skips)`);
    check('trench joints: every real feeder joint is fully covered with overlap', badJoints === 0, firstBad || `${badJoints} bad`);

    // (b) Synthetic joint-angle fan: joints up to 90° must be covered by the
    // fixed overhang directly. Sharper (hairpin) deviations get an extra
    // angle-scaled miter patch piece, so the fan now extends to
    // 179° and verifies, from the ACTUAL decomposition (edge rects + the
    // angle-scaled miter patch emitted for joints sharper than 90°):
    // (1) both exact strips near the vertex are fully cut, (2) the elbow
    // disk is cut, and (3) the outer miter wedge of the elbow is cut out to
    // min(miter tip, FEEDER_JOINT_PATCH_MAX_FT) — the sliver a fixed
    // overhang leaves un-cut past 90°.
    const { sharpJointPatches, FEEDER_JOINT_PATCH_MAX_FT } =
      await import('../client/src/lib/nextera/feederTrenchGeom');
    // Reconstruct plan-frame rect endpoints from a decomposed sub.
    type Rect = { a: P; b: P };
    const subRects = (feeders: Parameters<typeof feederTrenchSubSegments>[0]): Rect[] =>
      feederTrenchSubSegments(feeders).map(s => {
        const dir = { x: Math.cos(s.ang), y: -Math.sin(s.ang) }; // ang is in the (x, -y) frame
        const c = { x: s.cx, y: -s.cz };
        return {
          a: { x: c.x - dir.x * s.len / 2, y: c.y - dir.y * s.len / 2 },
          b: { x: c.x + dir.x * s.len / 2, y: c.y + dir.y * s.len / 2 },
        };
      });
    const insideAny = (p: P, rects: Rect[]): boolean =>
      rects.some(r => insideRect(p, r.a, r.b));
    const stripCoveredByAny = (s0: P, s1: P, near: P, rects: Rect[]): string => {
      const len = Math.hypot(s1.x - s0.x, s1.y - s0.y);
      const ux = (s1.x - s0.x) / len;
      const uy = (s1.y - s0.y) / len;
      const nAlong = (near.x - s0.x) * ux + (near.y - s0.y) * uy;
      for (let ai = 0; ai <= 20; ai++) {
        const along = Math.min(Math.max(nAlong - w + (ai / 20) * 2 * w, 0), len);
        for (let pi = -10; pi <= 10; pi++) {
          const perp = (pi / 10) * (w / 2) * 0.9999;
          const p = { x: s0.x + along * ux - perp * uy, y: s0.y + along * uy + perp * ux };
          if (!insideAny(p, rects)) return `strip gap at along=${along.toFixed(2)} perp=${perp.toFixed(2)}`;
        }
      }
      return '';
    };
    // Coverage audit for one elbow a->v->b against the full decomposition.
    const elbowCovered = (a: P, v: P, b: P): string => {
      const rects = subRects([{ segments: [{ pts: [a, v, b] }] }]);
      let why = stripCoveredByAny(a, v, v, rects);
      if (why) return `incoming ${why}`;
      why = stripCoveredByAny(v, b, v, rects);
      if (why) return `outgoing ${why}`;
      // Elbow disk around the vertex.
      for (let i = 0; i < 64; i++) {
        for (const r of [0, w * 0.25, w * 0.4999]) {
          const t = (i / 64) * Math.PI * 2;
          const p = { x: v.x + r * Math.cos(t), y: v.y + r * Math.sin(t) };
          if (!insideAny(p, rects)) return `elbow disk gap at r=${r.toFixed(2)} t=${((t * 180) / Math.PI).toFixed(0)}°`;
        }
      }
      // Outer miter wedge: the region between the outer edges of the two
      // exact strips, sampled radially from the vertex out to the (capped)
      // miter tip. This is exactly the sliver a fixed overhang misses for
      // deviations past 90°.
      const l1 = Math.hypot(v.x - a.x, v.y - a.y);
      const l2 = Math.hypot(b.x - v.x, b.y - v.y);
      const d1 = { x: (v.x - a.x) / l1, y: (v.y - a.y) / l1 };
      const d2 = { x: (b.x - v.x) / l2, y: (b.y - v.y) / l2 };
      const dot = Math.max(-1, Math.min(1, d1.x * d2.x + d1.y * d2.y));
      const dev = Math.acos(dot);
      if (dev > 1e-6 && Math.PI - dev > 1e-6) {
        const ml = Math.hypot(d1.x - d2.x, d1.y - d2.y);
        const m = { x: (d1.x - d2.x) / ml, y: (d1.y - d2.y) / ml };
        const tip = (w / 2) / Math.cos(dev / 2);
        const reach = Math.min(tip, FEEDER_JOINT_PATCH_MAX_FT) * 0.999;
        const halfWedge = (Math.PI - dev) / 2;
        const mAng = Math.atan2(m.y, m.x);
        // Outer normals of the two strips (pointing away from the turn's
        // inner side): the miter footprint is bounded by both outer edge
        // lines, so only points inside BOTH are part of the trench outline.
        const turn = Math.sign(d1.x * d2.y - d1.y * d2.x) || 1;
        const o1 = { x: turn * d1.y, y: -turn * d1.x };
        const o2 = { x: turn * d2.y, y: -turn * d2.x };
        for (let ri = 1; ri <= 12; ri++) {
          const rho = (ri / 12) * reach;
          for (let ti = -8; ti <= 8; ti++) {
            const t = mAng + (ti / 8) * halfWedge * 0.999;
            const p = { x: v.x + rho * Math.cos(t), y: v.y + rho * Math.sin(t) };
            // Skip samples outside the mitered trench outline (beyond an
            // outer edge line) — nothing needs cutting there.
            const s1 = (p.x - v.x) * o1.x + (p.y - v.y) * o1.y;
            const s2 = (p.x - v.x) * o2.x + (p.y - v.y) * o2.y;
            if (s1 > w / 2 - 1e-6 || s2 > w / 2 - 1e-6) continue;
            if (!insideAny(p, rects)) return `miter wedge gap at rho=${rho.toFixed(2)} theta=${((t * 180) / Math.PI).toFixed(1)}°`;
          }
        }
      }
      return '';
    };
    let fanBad = 0;
    let fanFirst = '';
    for (let deg = 1; deg <= 179; deg++) {
      const dev = (deg * Math.PI) / 180;
      const a = { x: -20, y: 0 };
      const v = { x: 0, y: 0 };
      const b = { x: 20 * Math.cos(dev), y: 20 * Math.sin(dev) };
      let why = elbowCovered(a, v, b);
      // A sharp joint must emit exactly one patch; a gentle one must not.
      const patches = sharpJointPatches([a, v, b]);
      if (!why && deg <= 90 && patches.length !== 0) why = `≤90° joint emitted a patch`;
      if (!why && deg > 90 && patches.length !== 1) why = `hairpin joint emitted ${patches.length} patches`;
      if (why) {
        fanBad++;
        if (!fanFirst) fanFirst = `${deg}°: ${why}`;
      }
    }
    check('trench joints: synthetic fan 1°–179° deviations all join cleanly', fanBad === 0, fanFirst || '');
    // 180° full reversal: the strips coincide, so plain edge rects cover
    // everything; the degenerate patch (if any) must not blow up.
    {
      const revWhy = elbowCovered({ x: -20, y: 0 }, { x: 0, y: 0 }, { x: -20, y: 0 });
      const revSubs = feederTrenchSubSegments([{ segments: [{ pts: [{ x: -20, y: 0 }, { x: 0, y: 0 }, { x: -20, y: 0 }] }] }]);
      const finite = revSubs.every(s =>
        Number.isFinite(s.cx) && Number.isFinite(s.cz) && Number.isFinite(s.len) && Number.isFinite(s.ang) &&
        (!s.key.includes('-p') || s.len <= FEEDER_JOINT_PATCH_MAX_FT + 1e-9));
      check('trench joints: 180° reversal stays covered with finite, capped subs', revWhy === '' && finite, revWhy || `${revSubs.length} subs`);
    }
    // Decomposition shape: a two-edge polyline with a ≤90° elbow yields
    // exactly two subs (no patch) with the rect-model lengths.
    const fanSubs = feederTrenchSubSegments([{ segments: [{ pts: [{ x: -20, y: 0 }, { x: 0, y: 0 }, { x: 14, y: 14 }] }] }]);
    check('trench joints: fan polyline decomposes into two sub-segments', fanSubs.length === 2 && Math.abs(fanSubs[0].len - 20) < 1e-9 && Math.abs(fanSubs[1].len - Math.hypot(14, 14)) < 1e-9);
    // ...and a hairpin polyline gains exactly one patch sub keyed p<i>.
    const hairSubs = feederTrenchSubSegments([{ segments: [{ pts: [{ x: -20, y: 0 }, { x: 0, y: 0 }, { x: -18, y: 6 }] }] }]);
    check('trench joints: hairpin polyline gains one miter patch sub',
      hairSubs.length === 3 && hairSubs.filter(s => s.key.includes('-p')).length === 1);

    // (c) Patch clipping: a hairpin right at the fence line must never emit
    // a patch rect that pokes outside the fence, and a patch aimed at an
    // equipment footprint must stop short of it.
    {
      const w = FEEDER_TRENCH_W_FT;
      // 100x100 fence; hairpin vertex sits on x=100-w/2 so the outer miter
      // (pointing +x) would reach past the fence line.
      const fence = [
        { x: 0, y: 0 }, { x: 100, y: 0 }, { x: 100, y: 100 }, { x: 0, y: 100 },
      ];
      const vx = 100 - w / 2;
      const hairpin = [{ segments: [{ pts: [
        { x: vx - 30, y: 48 }, { x: vx, y: 50 }, { x: vx - 30, y: 52 },
      ] }] }];
      // Every sub rect (edge pieces AND patch) sampled across its overlong
      // footprint must stay inside the fence when bounds are provided.
      const rectSamplesInside = (subs: ReturnType<typeof feederTrenchSubSegments>, poly: P[]): string => {
        for (const s of subs) {
          if (!s.key.includes('-p')) continue; // patches are the derived geometry under test
          const dir = { x: Math.cos(s.ang), y: -Math.sin(s.ang) };
          const c = { x: s.cx, y: -s.cz };
          const half = (s.len + w) / 2; // rendered rect is len + overhang long
          for (let ai = -8; ai <= 8; ai++) {
            for (const perp of [-0.499 * w, 0, 0.499 * w]) {
              const p = {
                x: c.x + dir.x * (ai / 8) * half - dir.y * perp,
                y: c.y + dir.y * (ai / 8) * half + dir.x * perp,
              };
              if (!pointInPolygon(p, poly)) return `${s.key} pokes out at (${p.x.toFixed(1)}, ${p.y.toFixed(1)})`;
            }
          }
        }
        return '';
      };
      const unclipped = feederTrenchSubSegments(hairpin);
      const clippedSubs = feederTrenchSubSegments(hairpin, { fence });
      check('trench patch clip: unclipped fence-edge hairpin patch DOES poke outside (sanity)',
        rectSamplesInside(unclipped, fence) !== '');
      check('trench patch clip: fence bounds keep every patch rect inside the fence',
        rectSamplesInside(clippedSubs, fence) === '', rectSamplesInside(clippedSubs, fence));
      // Edge (non-patch) subs are untouched by bounds.
      const edgeKeys = (subs: ReturnType<typeof feederTrenchSubSegments>) =>
        subs.filter(s => !s.key.includes('-p')).map(s => `${s.key}:${s.len.toFixed(3)}`).join('|');
      check('trench patch clip: edge sub-segments are unchanged by bounds',
        edgeKeys(unclipped) === edgeKeys(clippedSubs));
      // A hairpin whose vertex is OUTSIDE the fence (home run to an outside
      // substation) is not fence-clipped.
      const outHairpin = [{ segments: [{ pts: [
        { x: 120, y: 48 }, { x: 150, y: 50 }, { x: 120, y: 52 },
      ] }] }];
      const outSubs = feederTrenchSubSegments(outHairpin, { fence });
      const outPlain = feederTrenchSubSegments(outHairpin);
      check('trench patch clip: joints outside the fence keep their full patch',
        outSubs.length === outPlain.length &&
        outSubs.every((s, i) => Math.abs(s.len - outPlain[i].len) < 1e-9));
      // Obstacle clipping: same hairpin mid-yard, with an equipment rect
      // squarely in the patch path — the patch must stop before entering it.
      const obstacle = [
        { x: 52, y: 40 }, { x: 70, y: 40 }, { x: 70, y: 60 }, { x: 52, y: 60 },
      ];
      const midHairpin = [{ segments: [{ pts: [
        { x: 20, y: 48 }, { x: 50, y: 50 }, { x: 20, y: 52 },
      ] }] }];
      const obSubs = feederTrenchSubSegments(midHairpin, { fence, obstacles: [obstacle] });
      const obBad = obSubs.filter(s => s.key.includes('-p')).some(s => {
        const dir = { x: Math.cos(s.ang), y: -Math.sin(s.ang) };
        const c = { x: s.cx, y: -s.cz };
        const half = (s.len + w) / 2;
        for (let ai = -8; ai <= 8; ai++) {
          for (const perp of [-0.499 * w, 0, 0.499 * w]) {
            const p = {
              x: c.x + dir.x * (ai / 8) * half - dir.y * perp,
              y: c.y + dir.y * (ai / 8) * half + dir.x * perp,
            };
            if (pointInPolygon(p, obstacle)) return true;
          }
        }
        return false;
      });
      check('trench patch clip: patch rects never enter equipment footprints', !obBad);
      // Clipped joints are flagged for callers that want to warn.
      const flagged = sharpJointPatches(
        [{ x: vx - 30, y: 48 }, { x: vx, y: 50 }, { x: vx - 30, y: 52 }], { fence });
      check('trench patch clip: fence-clipped joint is flagged clipped',
        flagged.length === 1 && flagged[0].clipped === true);
      const unflagged = sharpJointPatches(
        [{ x: 20, y: 48 }, { x: 50, y: 50 }, { x: 20, y: 52 }], { fence });
      check('trench patch clip: mid-yard joint with room is not flagged',
        unflagged.length === 1 && unflagged[0].clipped === false);
      // Joints EXACTLY on the fence line (right and top edges, where the
      // even-odd point test classifies boundary points as outside) must
      // still be fence-enforced: no patch rect may poke outside.
      for (const [label, hp] of [
        ['right edge', [{ x: 70, y: 48 }, { x: 100, y: 50 }, { x: 70, y: 52 }]],
        ['top edge', [{ x: 48, y: 70 }, { x: 50, y: 100 }, { x: 52, y: 70 }]],
      ] as const) {
        const subs = feederTrenchSubSegments([{ segments: [{ pts: [...hp] }] }], { fence });
        const why = rectSamplesInside(subs, fence);
        const flag = sharpJointPatches([...hp], { fence });
        check(`trench patch clip: joint exactly on fence ${label} stays clipped inside`,
          why === '' && flag.length === 1 && flag[0].clipped === true, why);
      }
    }
  }

  // ---------------------------------------------------------------
  console.log('\n[40] Mirrored-pair 3-container islands (Puma reference)');
  {
    const cfg40 = getConfiguration('ge-aux-400');
    const d40 = generateSiteDesign(hondo, cfg40, 100, 300, { hotClimate: true, containersPerPcs: 3 });
    const isl40 = d40.islands ?? [];
    check('QTY3: islands present on the design', isl40.length > 0, `${isl40.length}`);

    const cont40 = d40.equipment.filter(e => e.kind === 'bess');
    const inv40 = d40.equipment.filter(e => e.kind === 'inverter');

    // Uniform rotations: A-1/A-2 long axis y, A-3 long axis x, PCS rot 0
    let rotBad = '';
    for (const c of cont40) {
      const suffix = c.id.split('-').pop();
      const wantRot = suffix === '3' ? 0 : Math.PI / 2;
      if (Math.abs(c.rotation - wantRot) > 1e-6) { rotBad = `${c.id} rot ${c.rotation}`; break; }
    }
    check('QTY3: container rotations uniform (A-1/A-2 along y, A-3 along x)', rotBad === '', rotBad);
    // [606] North-row PCS keeps rotation 0 (sheet-3); south-row PCS is a TRUE
    // 180° rotation (π) so its DC/MV compartments mirror end-for-end.
    {
      let pcsRotBad = '';
      for (const isl of isl40) {
        for (const id of isl.northIds) {
          const i = inv40.find(v => v.id === id)!;
          if (Math.abs(i.rotation) > 1e-6) { pcsRotBad = `${id} north rot ${i.rotation}`; break; }
        }
        for (const id of isl.southIds) {
          const i = inv40.find(v => v.id === id)!;
          if (Math.abs(i.rotation - Math.PI) > 1e-6) { pcsRotBad = `${id} south rot ${i.rotation}`; break; }
        }
        if (pcsRotBad) break;
      }
      check('QTY3: north PCS rotation 0, south PCS rotation π (true 180° unit)', pcsRotBad === '', pcsRotBad);
    }

    // Per-block dimension chain: A-1/A-2 separated by 3 ft clear (pair sits
    // tight; the wide gap is BETWEEN blocks), A-3 at 3 ft from the pair,
    // PCS gap = 14 ft (hot).
    let geoBad = '';
    for (const inv of inv40) {
      const n = inv.id.replace('inv-', '');
      const a1 = cont40.find(c => c.id === `bess-${n}-1`);
      const a2 = cont40.find(c => c.id === `bess-${n}-2`);
      const a3 = cont40.find(c => c.id === `bess-${n}-3`);
      if (!a1 || !a2 || !a3) { geoBad = `block ${n} missing containers`; break; }
      const clearX = Math.abs(a2.x - a1.x) - a1.width;
      if (Math.abs(clearX - 3) > 0.05) { geoBad = `block ${n} pair gap ${clearX.toFixed(2)}`; break; }
      const sgn = Math.sign(a1.y - inv.y) || 1;
      const pairNear = a1.y - sgn * a1.length / 2;
      const invFace = inv.y + sgn * inv.width / 2;
      const pcsGap = Math.abs(pairNear - invFace);
      if (Math.abs(pcsGap - 14) > 0.05) { geoBad = `block ${n} PCS gap ${pcsGap.toFixed(2)}`; break; }
      const a3Near = a3.y - sgn * a3.width / 2;
      const pairFar = a1.y + sgn * a1.length / 2;
      const gap3 = Math.abs(a3Near - pairFar);
      if (Math.abs(gap3 - 3) > 0.05) { geoBad = `block ${n} A-3 gap ${gap3.toFixed(2)}`; break; }
    }
    check('QTY3: pair dimension chain 3\' pair gap / 3\' A-3 / 14\' hot PCS gap', geoBad === '', geoBad);

    // Mirrored pair bias (per reference plan): the A-1/A-2 pair is NOT
    // centered under the A-3 — the C (A-1) container sits flush with one END
    // of the A-3, and the north block is a 180-degree rotation of the south
    // block, so the flush end (and the C/A order) flips while the centered
    // PCS units stay aligned across the corridor.
    {
      let mirBad = '';
      for (const inv of inv40) {
        const n = inv.id.replace('inv-', '');
        const a1 = cont40.find(c => c.id === `bess-${n}-1`)!;
        const a3 = cont40.find(c => c.id === `bess-${n}-3`)!;
        const south = a1.y < a3.y; // pair south of A-3 => south block
        // Flush end: south block C flush with A-3 west end, north with east.
        const a3End = a3.x + (south ? -1 : 1) * a3.length / 2;
        const cEdge = a1.x + (south ? -1 : 1) * a1.width / 2;
        if (Math.abs(cEdge - a3End) > 0.05) { mirBad = `block ${n} C edge ${cEdge.toFixed(2)} vs A-3 end ${a3End.toFixed(2)}`; break; }
        // PCS stays centered on the block/A-3 centerline.
        if (Math.abs(inv.x - a3.x) > 0.05) { mirBad = `block ${n} PCS off-center`; break; }
      }
      check('QTY3: mirrored pair bias — C flush with A-3 end, flipped between blocks; PCS centered', mirBad === '', mirBad);
    }

    // Block-to-block spacing: adjacent block footprints (A-3 governs the
    // width) sit 14 ft clear per the reference.
    {
      let gapBad = '';
      const a3s = cont40.filter(c => c.id.endsWith('-3')).sort((a, b) => a.y - b.y || a.x - b.x);
      const rows = new Map<number, typeof a3s>();
      for (const c of a3s) {
        const key = Math.round(c.y);
        const near = Array.from(rows.keys()).find(k => Math.abs(k - key) < 2);
        if (near !== undefined) rows.get(near)!.push(c); else rows.set(key, [c]);
      }
      for (const row of rows.values()) {
        const sorted = row.sort((a, b) => a.x - b.x);
        for (let i2 = 1; i2 < sorted.length; i2++) {
          const clear = (sorted[i2].x - sorted[i2 - 1].x) - sorted[i2 - 1].length;
          if (clear > 100) continue; // inter-island gap (standard 7-pair islands)
          // Widened island MIDDLE gap (CAR-D-B005-1): 10' clear each side of
          // the widest cluster piece (aux xfmr width 7.333 rot 90) = 27.33'.
          if (Math.abs(clear - 27.333) < 0.1) continue;
          if (Math.abs(clear - 14) > 0.1) { gapBad = `A-3 gap ${clear.toFixed(2)} between ${sorted[i2 - 1].id} and ${sorted[i2].id}`; break; }
        }
        if (gapBad) break;
      }
      check('QTY3: adjacent blocks sit at 14 ft clear (A-3 to A-3)', gapBad === '', gapBad);
    }

    // Aux corridor: opposing A-3 units across each island corridor are 10 ft
    // apart, centered on island.y.
    let corBad = '';
    for (const isl of isl40) {
      const a3s = cont40.filter(c => c.id.endsWith('-3') &&
        Math.abs(Math.abs(c.y - isl.y) - (5 + c.width / 2)) < 0.05);
      const south = a3s.filter(c => c.y < isl.y);
      const north = a3s.filter(c => c.y > isl.y);
      if (!south.length && !north.length) { corBad = `island ${isl.n}: no A-3 at corridor`; break; }
      if (isl.southIds.length && isl.northIds.length && (!south.length || !north.length)) {
        corBad = `island ${isl.n}: A-3 missing on one side`; break;
      }
    }
    check('QTY3: 10 ft aux corridor centered on island.y with A-3 at edges', corBad === '', corBad);

    // FJB(s) + comms cabinet per island, inside fence with clearance
    let gearBad = '';
    for (const isl of isl40) {
      const fjbs = d40.equipment.filter(e => e.kind === 'feederJunctionBox' && new RegExp(`^fjb-${isl.n}(?:-\\d+)?$`).test(e.id));
      const comms = d40.equipment.find(e => e.id === `comms-${isl.n}`);
      if (!fjbs.length || !comms) {
        if (!d40.warnings.some(w => w.toLowerCase().includes('junction box') || w.toLowerCase().includes('feeder'))) {
          gearBad = `island ${isl.n}: gear missing without warning`; break;
        }
        continue;
      }
      for (const g of [...fjbs, comms]) {
        const rot = Math.abs(Math.sin(g.rotation)) > 0.5;
        if (!rectInsidePolygon(g.x, g.y, (rot ? g.width : g.length) / 2, (rot ? g.length : g.width) / 2, d40.fence, 2.9)) {
          gearBad = `${g.id} fails fence clearance`; break;
        }
      }
      if (gearBad) break;
    }
    check('QTY3: FJB(s) + comms cabinet per island placed with clearance (or warned)', gearBad === '', gearBad);

    // Per-island aux cluster (reference PMA-D-B001-2B island detail): aux
    // transformer + aux distribution center + comms cabinet at the island
    // midpoint on the corridor centerline, in the inter-pair gaps. Named
    // warning when a piece cannot fit (reject -> warn, never silent).
    {
      let cluBad = '';
      const clusterWarn = (n: number) =>
        d40.warnings.some(w => w.includes(`Island ${n} aux cluster`));
      for (const isl of isl40) {
        for (const id of [`island-aux-xfmr-${isl.n}`, `island-aux-dist-${isl.n}`, `comms-${isl.n}`]) {
          const e = d40.equipment.find(q => q.id === id);
          if (!e) {
            if (!clusterWarn(isl.n)) { cluBad = `island ${isl.n}: ${id} missing without aux-cluster warning`; }
            continue;
          }
          // Cluster gear stacks down the mid-island gap column just OUTSIDE
          // the 10 ft corridor band (the corridor centerline is the feeder
          // approach highway and must stay clear), within the island body.
          const rot = Math.abs(Math.sin(e.rotation)) > 0.5;
          const ehy = (rot ? e.length : e.width) / 2;
          const inSpan = e.x > isl.minX - 1 && e.x < isl.maxX + 1;
          if (inSpan && Math.abs(e.y - isl.y) - ehy < 5 - 0.01) {
            cluBad = `${id} intrudes into the aux corridor band (edge ${(Math.abs(e.y - isl.y) - ehy).toFixed(2)} ft from centerline)`;
          }
          if (inSpan && Math.abs(e.y - isl.y) > 60) {
            cluBad = `${id} too far from the corridor (dy=${(e.y - isl.y).toFixed(1)})`;
          }
          if (!id.startsWith('comms-') && !inSpan) { cluBad = `${id} outside island span`; }
          if (id.startsWith('comms-') && !inSpan && !clusterWarn(isl.n)) {
            cluBad = `${id} at strip end without fallback warning`;
          }
          if (cluBad) break;
        }
        if (cluBad) break;
      }
      check('QTY3: per-island aux cluster (xfmr + dist + comms) mid-island on centerline (or warned)', cluBad === '', cluBad);

      // Reference island-middle spacing (90% package CAR-D-B005-1 + the
      // dimensioned island detail): the middle inter-pair gap is widened so
      // every cluster piece keeps >= 10'-0" clear each side to the adjacent
      // pair columns, with the widest piece (aux xfmr, rot 90) at exactly 10'.
      {
        let midBad = '';
        const halfW = d40.rowEditGeom?.halfW ?? 0;
        const clusterWarned = (n: number) =>
          d40.warnings.some(w => w.includes(`Island ${n} aux cluster`));
        for (const isl of isl40) {
          if (clusterWarned(isl.n)) continue;
          for (const id of [`island-aux-xfmr-${isl.n}`, `island-aux-dist-${isl.n}`, `comms-${isl.n}`]) {
            const e = d40.equipment.find(q => q.id === id);
            if (!e) continue;
            const rot = Math.abs(Math.sin(e.rotation)) > 0.5;
            const ehx = (rot ? e.width : e.length) / 2;
            // Nearest pair columns each side (block centers on this island row)
            const bcs = (d40.blockRows ?? [])
              .flatMap(r => r.blocks)
              .filter(b => Math.abs(b.y - isl.y) < 1);
            const west = bcs.filter(b => b.x < e.x).map(b => b.x);
            const east = bcs.filter(b => b.x > e.x).map(b => b.x);
            if (!west.length || !east.length) continue;
            const clrW = e.x - Math.max(...west) - halfW - ehx;
            const clrE = Math.min(...east) - e.x - halfW - ehx;
            if (clrW < 10 - 0.05 || clrE < 10 - 0.05) {
              midBad = `island ${isl.n}: ${id} middle clearance ${clrW.toFixed(2)}/${clrE.toFixed(2)} ft < 10`;
              break;
            }
            if (id.startsWith('island-aux-xfmr-') &&
                (Math.abs(clrW - 10) > 0.05 || Math.abs(clrE - 10) > 0.05)) {
              midBad = `island ${isl.n}: aux xfmr not exactly 10 ft each side (${clrW.toFixed(2)}/${clrE.toFixed(2)})`;
              break;
            }
          }
          if (midBad) break;
        }
        check('QTY3: island middle cluster keeps 10 ft clear each side to pair columns (CAR-D-B005-1)', midBad === '', midBad);

        // Package sides: aux distribution NORTH of the corridor, transformer
        // SOUTH (CAR-D-B005-1 AUXSWB/AUXTX), unless the mirrored-fallback
        // warning was raised.
        let sideBad = '';
        for (const isl of isl40) {
          const mirrored40 = d40.warnings.some(w =>
            w.includes(`Island ${isl.n} aux cluster`) && w.includes('mirrored across the corridor'));
          if (mirrored40 || clusterWarned(isl.n)) continue;
          const dist = d40.equipment.find(e => e.id === `island-aux-dist-${isl.n}`);
          const xfmr = d40.equipment.find(e => e.id === `island-aux-xfmr-${isl.n}`);
          if (dist && dist.y <= isl.y) { sideBad = `island ${isl.n}: aux dist south of corridor`; break; }
          if (xfmr && xfmr.y >= isl.y) { sideBad = `island ${isl.n}: aux xfmr north of corridor`; break; }
        }
        check('QTY3: aux dist north / aux xfmr south of corridor per CAR-D-B005-1 (or mirrored w/ warning)', sideBad === '', sideBad);

        // Reverse-scan arrangement ('ne'): the middle-gap widening shifts in
        // the scan direction, so the 10 ft clearances (or the explicit
        // narrow-gap warning) must hold there too — never silent violation.
        const dNe = generateSiteDesign(hondo, cfg40, 100, 300, { hotClimate: true, containersPerPcs: 3, arrangement: 'ne' });
        let neBad = '';
        for (const isl of dNe.islands ?? []) {
          if (dNe.warnings.some(w => w.includes(`Island ${isl.n} aux cluster`))) continue;
          for (const id of [`island-aux-xfmr-${isl.n}`, `island-aux-dist-${isl.n}`, `comms-${isl.n}`]) {
            const e = dNe.equipment.find(q => q.id === id);
            if (!e) continue;
            const rot = Math.abs(Math.sin(e.rotation)) > 0.5;
            const ehx = (rot ? e.width : e.length) / 2;
            const bcs = (dNe.blockRows ?? []).flatMap(r => r.blocks).filter(b => Math.abs(b.y - isl.y) < 1);
            const west = bcs.filter(b => b.x < e.x).map(b => b.x);
            const east = bcs.filter(b => b.x > e.x).map(b => b.x);
            if (!west.length || !east.length) continue;
            const hw = dNe.rowEditGeom?.halfW ?? 0;
            const clrW = e.x - Math.max(...west) - hw - ehx;
            const clrE = Math.min(...east) - e.x - hw - ehx;
            if (clrW < 10 - 0.05 || clrE < 10 - 0.05) {
              neBad = `island ${isl.n}: ${id} ne-arrangement middle clearance ${clrW.toFixed(2)}/${clrE.toFixed(2)} ft < 10 without warning`;
              break;
            }
          }
          if (neBad) break;
        }
        check("QTY3: 'ne' arrangement keeps the 10 ft middle clearances (or warns)", neBad === '', neBad);
      }

      // Cluster gear never overlaps other equipment or leaves the fence.
      let ovBad = '';
      const cluster = d40.equipment.filter(e => /^island-aux-(xfmr|dist)-\d+$/.test(e.id));
      for (const g of cluster) {
        const grot = Math.abs(Math.sin(g.rotation)) > 0.5;
        const ghx = (grot ? g.width : g.length) / 2;
        const ghy = (grot ? g.length : g.width) / 2;
        if (!rectInsidePolygon(g.x, g.y, ghx, ghy, d40.fence, 2.9)) {
          ovBad = `${g.id} fails fence clearance`; break;
        }
        for (const e of d40.equipment) {
          if (e.id === g.id) continue;
          const rot = Math.abs(Math.sin(e.rotation)) > 0.5;
          const ehx = (rot ? e.width : e.length) / 2;
          const ehy = (rot ? e.length : e.width) / 2;
          if (Math.abs(g.x - e.x) < ghx + ehx - 0.01 &&
              Math.abs(g.y - e.y) < ghy + ehy - 0.01) {
            ovBad = `${g.id} overlaps ${e.id}`; break;
          }
        }
        if (ovBad) break;
      }
      check('QTY3: island aux cluster gear inside fence and overlap-free', ovBad === '', ovBad);

      // Yard-level gate-side aux pad is suppressed when island clusters exist.
      const anyCluster = cluster.some(e => e.kind === 'auxTransformer');
      check('QTY3: yard-level aux pad suppressed when island clusters placed',
        !anyCluster || !d40.equipment.some(e => e.id === 'aux-xfmr' || e.id === 'aux-swgr'));

      // 480V aux & fiber corridor trench per island: spans the island's
      // collector (drops + its own aux transformer) on the centerline.
      let trBad = '';
      for (const isl of isl40) {
        const coll = d40.cables.find(c => c.id === `lvac-corridor-${isl.n}`);
        const tr = (d40.corridorTrenches ?? []).find(t => t.islandN === isl.n);
        if (!coll) continue; // no drops -> no collector/trench
        if (!tr) { trBad = `island ${isl.n}: collector without corridor trench`; break; }
        if (Math.abs(tr.y - isl.y) > 0.5) { trBad = `island ${isl.n}: trench off centerline`; break; }
        const xs = coll.pts.map(p => p.x);
        if (tr.minX > Math.min(...xs) + 0.1 || tr.maxX < Math.max(...xs) - 0.1) {
          trBad = `island ${isl.n}: trench does not span collector`; break;
        }
        const xfmr = d40.equipment.find(e => e.id === `island-aux-xfmr-${isl.n}`);
        if (xfmr && (xfmr.x < tr.minX - 0.1 || xfmr.x > tr.maxX + 0.1)) {
          trBad = `island ${isl.n}: trench misses its aux transformer`; break;
        }
        if (xfmr && (xfmr.x < Math.min(...xs) - 0.1 || xfmr.x > Math.max(...xs) + 0.1)) {
          trBad = `island ${isl.n}: collector does not reach its aux transformer`; break;
        }
      }
      check('QTY3: per-island 480V corridor trench spans collector + aux cluster', trBad === '', trBad);

      // Self-fed islands need no trench-spine tie warning.
      const allClustered = isl40.every(isl =>
        d40.equipment.some(e => e.id === `island-aux-xfmr-${isl.n}`) ||
        !d40.cables.some(c => c.id === `lvac-corridor-${isl.n}`));
      check('QTY3: no corridor-to-spine tie warning when islands feed from own clusters',
        !allClustered || !d40.warnings.some(w => w.includes('corridor collectors could not be tied')));

      // DXF carries the corridor trench rects + label (WYSIWYG rectangles).
      if ((d40.corridorTrenches ?? []).length) {
        const dxf40b = buildDesignDxfString(d40, 'Hondo_QTY3_Aux');
        check('QTY3: DXF labels the island corridor trench',
          dxf40b.includes('480V AUX AND FIBER TRENCH'));
      }
    }

    // FJB capacity convention (reference detail PMA-D-B001: 2 feeders per
    // box). Islands whose sides split under the 6-PCS cap need > 2 feeders,
    // so they get a SECOND FJB at the opposite strip end — and after feeder
    // generation no box may terminate more than 2 feeders.
    {
      const splitIslands = isl40.filter(isl =>
        Math.ceil(isl.southIds.length / MAX_INVERTERS_PER_FEEDER) +
        Math.ceil(isl.northIds.length / MAX_INVERTERS_PER_FEEDER) > 2);
      // Standard islands cap each side at 7 PCS, so real layouts never need
      // more than the two strip-end boxes — the split path below is legacy
      // safety for hand-edited saves.
      check('QTY3: standard islands never need more than 2 feeders (no split-side islands)',
        splitIslands.length === 0,
        isl40.map(i => `${i.southIds.length}/${i.northIds.length}`).join(', '));
      let splitBad = '';
      for (const isl of splitIslands) {
        const a = d40.equipment.find(e => e.id === `fjb-${isl.n}`);
        const b = d40.equipment.find(e => e.id === `fjb-${isl.n}-2`);
        if (!a || !b) { splitBad = `island ${isl.n}: expected two FJBs, got ${[a, b].filter(Boolean).length}`; break; }
        if (a.label !== `FJB-${String(isl.n).padStart(2, '0')}A` || b.label !== `FJB-${String(isl.n).padStart(2, '0')}B`) {
          splitBad = `island ${isl.n}: labels ${a.label}/${b.label}`; break;
        }
        // Boxes sit at OPPOSITE strip ends
        if ((a.x - (isl.minX + isl.maxX) / 2) * (b.x - (isl.minX + isl.maxX) / 2) >= 0) {
          splitBad = `island ${isl.n}: both FJBs on the same strip end`; break;
        }
      }
      check('QTY3: split-side islands carry a second FJB (A/B labels, opposite strip ends)', splitBad === '', splitBad);

      // FJBs carry fiber only (CAR-D-B005-0): every 34.5 kV feeder routes
      // chain-end -> substation directly and must never touch a box.
      const fxs40 = d40.fence.map(p => p.x);
      const fys40 = d40.fence.map(p => p.y);
      const sub40: Pt = { x: Math.max(...fxs40) + 300, y: (Math.min(...fys40) + Math.max(...fys40)) / 2 };
      const warns40: string[] = [];
      const feeds40 = generateFeeders(d40, sub40, cfg40.blockMW, { onWarning: m => warns40.push(m) });
      const nonTrunk40 = feeds40.filter(f => !f.trunk);
      check('QTY3: no feeder carries an FJB id (boxes are fiber-only)',
        nonTrunk40.every(f => f.fjbId === null),
        nonTrunk40.filter(f => f.fjbId).map(f => `F${f.idx}=${f.fjbId}`).join(', '));
      const fjbAll40 = d40.equipment.filter(e => e.kind === 'feederJunctionBox');
      const touching40 = nonTrunk40.filter(f => f.segments.some(sg =>
        sg.pts.some(p => fjbAll40.some(b => Math.hypot(p.x - b.x, p.y - b.y) < 5))));
      check('QTY3: no feeder route point lands on any FJB',
        touching40.length === 0, touching40.map(f => `F${f.idx}`).join(', '));
      check('QTY3: no FJB termination warnings fire (concept retired)',
        !warns40.some(w => w.includes('junction box terminations')), warns40.join(' | '));
    }

    // DC runs: every run exits the PCS's single green DC compartment
    // (bundled at one end of the container-facing face) and lands at the
    // container's cable-entry box.
    let dcBad = '';
    for (const inv of inv40) {
      const comp = pcsCompartments(inv).find(cc => cc.kind === 'dc')!;
      const n = inv.id.replace('inv-', '');
      const conts = cont40.filter(c => c.id.startsWith(`bess-${n}-`));
      const midY = conts.reduce((s, c) => s + c.y, 0) / conts.length;
      const sgn = Math.sign(midY - inv.y) || 1;
      const invFace = inv.y + sgn * inv.width / 2;
      if (Math.abs(comp.y - invFace) > 2.1) { dcBad = `${inv.id}: DC compartment on the wrong face`; break; }
      for (const c of conts) {
        const run = d40.cables.find(r => r.id === `dc-${c.id}-pos`);
        if (!run) { dcBad = `${c.id}: no DC run`; break; }
        const p0 = run.pts[0];
        if (Math.abs(p0.x - comp.x) > comp.length / 2 + 0.1 || Math.abs(p0.y - invFace) > 1e-6) {
          dcBad = `${c.id}: DC does not exit the PCS DC compartment`; break;
        }
        const pe = run.pts[run.pts.length - 1];
        const rot = Math.abs(Math.sin(c.rotation)) > 0.5;
        if (rot) {
          const s2 = c.epanel === 'left' ? -1 : 1;
          const wantX = c.x + s2 * (c.width / 2 - 1.0);
          const wantY = c.y - sgn * (c.length / 2);
          // [624] the (+) conductor lands exactly at the entry box; the (−)
          // conductor lands 0.6 ft inboard on its own trench line.
          if (Math.abs(pe.x - wantX) > 0.05 || Math.abs(pe.y - wantY) > 0.05) {
            dcBad = `${c.id}: DC does not land at the entry box`; break;
          }
          for (let k = 1; k < run.pts.length; k++) {
            const a = run.pts[k - 1], b2 = run.pts[k];
            if (Math.abs(a.x - b2.x) > 1e-6 && Math.abs(a.y - b2.y) > 1e-6) {
              dcBad = `${c.id}: DC run has a diagonal segment`; break;
            }
          }
          if (dcBad) break;
        } else {
          // A-3: lands 1 ft inside the open-lane end (epanel-flipped) on the
          // corridor side, via an orthogonal route down the lane the pair
          // bias opens — the run must NEVER trench under the A-1/A-2 pair.
          const endSgn = c.epanel === 'left' ? -1 : 1;
          const wantX = c.x + endSgn * (c.length / 2 - 1.0);
          const wantY = c.y + sgn * (c.width / 2 - 1.0);
          // [624] the (+) conductor lands exactly at the A-3 entry corner
          if (Math.abs(pe.x - wantX) > 0.05 || Math.abs(pe.y - wantY) > 0.05) {
            dcBad = `${c.id}: DC does not land at the A-3 entry corner`; break;
          }
          for (let k = 1; k < run.pts.length; k++) {
            const a = run.pts[k - 1], b2 = run.pts[k];
            if (Math.abs(a.x - b2.x) > 1e-6 && Math.abs(a.y - b2.y) > 1e-6) {
              dcBad = `${c.id}: A-3 DC run has a diagonal segment`; break;
            }
            for (const pc of conts.filter(cc => Math.abs(Math.sin(cc.rotation)) > 0.5)) {
              const x0 = pc.x - pc.width / 2, x1 = pc.x + pc.width / 2;
              const y0 = pc.y - pc.length / 2, y1 = pc.y + pc.length / 2;
              const sx0 = Math.min(a.x, b2.x), sx1 = Math.max(a.x, b2.x);
              const sy0 = Math.min(a.y, b2.y), sy1 = Math.max(a.y, b2.y);
              if (sx1 > x0 + 1e-6 && sx0 < x1 - 1e-6 && sy1 > y0 + 1e-6 && sy0 < y1 - 1e-6) {
                dcBad = `${c.id}: A-3 DC run trenches under ${pc.id}`; break;
              }
            }
            if (dcBad) break;
          }
          if (dcBad) break;
        }
      }
      if (dcBad) break;
    }
    check('QTY3: DC runs exit the PCS DC compartment to each entry box', dcBad === '', dcBad);

    // No block's DC runs may cross each other (reference drawing: cables
    // peel off in destination order and fan out on nested corridors).
    let dcCross = '';
    {
      const segsCross = (a1: {x:number;y:number}, a2: {x:number;y:number},
                         b1: {x:number;y:number}, b2: {x:number;y:number}) => {
        const d = (p: {x:number;y:number}, q: {x:number;y:number}, r: {x:number;y:number}) =>
          (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x);
        const d1 = d(b1, b2, a1), d2 = d(b1, b2, a2), d3 = d(a1, a2, b1), d4 = d(a1, a2, b2);
        return ((d1 > 1e-9 && d2 < -1e-9) || (d1 < -1e-9 && d2 > 1e-9)) &&
               ((d3 > 1e-9 && d4 < -1e-9) || (d3 < -1e-9 && d4 > 1e-9));
      };
      outer40:
      for (const inv of inv40) {
        const n = inv.id.replace('inv-', '');
        const runs = cont40.filter(c => c.id.startsWith(`bess-${n}-`))
          .map(c => d40.cables.find(r => r.id === `dc-${c.id}-pos`)!)
          .filter(Boolean);
        for (let i = 0; i < runs.length; i++) {
          for (let j = i + 1; j < runs.length; j++) {
            for (let k = 1; k < runs[i].pts.length; k++) {
              for (let l = 1; l < runs[j].pts.length; l++) {
                if (segsCross(runs[i].pts[k - 1], runs[i].pts[k],
                              runs[j].pts[l - 1], runs[j].pts[l])) {
                  dcCross = `${inv.id}: ${runs[i].id} crosses ${runs[j].id}`;
                  break outer40;
                }
              }
            }
          }
        }
      }
    }
    check('QTY3: no DC run crosses another DC run within its block', dcCross === '', dcCross);

    // Aux drops end on the corridor centerline; collector present per island;
    // no sheet-3 LVAC row buses in mirrored mode.
    let lvBad = '';
    for (const c of cont40) {
      const run = d40.cables.find(r => r.id === `lvac-${c.id}`);
      if (!run) { lvBad = `${c.id}: no aux drop`; break; }
      const end = run.pts[run.pts.length - 1];
      if (!isl40.some(i => Math.abs(end.y - i.y) < 1e-6)) {
        lvBad = `${c.id}: drop ends off-corridor y=${end.y.toFixed(2)}`; break;
      }
      // Shared entry: the aux run starts at the same green cable-entry box
      // where the DC run lands (within the 2'x2' corner box).
      const dc = d40.cables.find(r => r.id === `dc-${c.id}-pos`)!;
      const dcEnd = dc.pts[dc.pts.length - 1];
      const p0 = run.pts[0];
      if (Math.hypot(p0.x - dcEnd.x, p0.y - dcEnd.y) > 2.1) {
        lvBad = `${c.id}: aux entry ${p0.x.toFixed(1)},${p0.y.toFixed(1)} not at the DC entry box ${dcEnd.x.toFixed(1)},${dcEnd.y.toFixed(1)}`; break;
      }
    }
    check('QTY3: every container aux drop lands on its corridor centerline', lvBad === '', lvBad);
    let colBad = '';
    for (const isl of isl40) {
      const col = d40.cables.find(r => r.id === `lvac-corridor-${isl.n}`);
      if (!col) { colBad = `island ${isl.n}: no collector`; break; }
      if (col.pts.some(p => Math.abs(p.y - isl.y) > 1e-6)) { colBad = `island ${isl.n}: collector off centerline`; break; }
      const drops = d40.cables.filter(r => r.class === 'LVAC' && r.id.startsWith('lvac-bess-') &&
        cont40.some(c => r.id === `lvac-${c.id}` && Math.abs((r.pts[r.pts.length - 1].y) - isl.y) < 1e-6));
      const minX = Math.min(...col.pts.map(p => p.x)), maxX = Math.max(...col.pts.map(p => p.x));
      const uncovered = drops.filter(r => {
        const x = r.pts[r.pts.length - 1].x;
        return x < minX - 1e-6 || x > maxX + 1e-6;
      });
      if (uncovered.length) { colBad = `island ${isl.n}: ${uncovered.length} drops outside collector span`; break; }
    }
    check('QTY3: corridor collector spans all drops per island', colBad === '', colBad);
    check('QTY3: no sheet-3 LVAC row buses in mirrored mode',
      !d40.cables.some(r => /^lvac-bus-/.test(r.id) || /^lvac-drop-inv/.test(r.id)));

    // Labels: FF = island group index; unit numbering down one side, back up
    // the other (serpentine). Apply the reference labels the way the store does.
    const { applyReferenceLabels } = await import('../client/src/lib/nextera/labels');
    applyReferenceLabels(d40.equipment, null, isl40);
    let lblBad = '';
    isl40.forEach((isl, gi) => {
      if (lblBad) return;
      const ff = String(gi + 1).padStart(2, '0');
      for (let k = 0; k < isl.inverterIds.length; k++) {
        const invE = d40.equipment.find(e => e.id === isl.inverterIds[k]);
        if (!invE) { lblBad = `island ${isl.n}: missing ${isl.inverterIds[k]}`; break; }
        const want = `PCS${ff}-${String(k + 1).padStart(2, '0')}`;
        if (invE.label !== want) { lblBad = `${invE.id}: label ${invE.label} != ${want}`; break; }
      }
      // serpentine: southIds ordered W->E, northIds continue E->W
      const sX = isl.southIds.map(id => d40.equipment.find(e => e.id === id)!.x);
      const nX = isl.northIds.map(id => d40.equipment.find(e => e.id === id)!.x);
      if (sX.some((x, i2) => i2 > 0 && x < sX[i2 - 1])) lblBad = `island ${isl.n}: south not W->E`;
      if (nX.some((x, i2) => i2 > 0 && x > nX[i2 - 1])) lblBad = `island ${isl.n}: north not E->W`;
      if (JSON.stringify(isl.inverterIds) !== JSON.stringify([...isl.southIds, ...isl.northIds]))
        lblBad = `island ${isl.n}: inverterIds not south-then-north`;
    });
    check('QTY3: PCS<FF>-<UU> labels follow island serpentine order', lblBad === '', lblBad);

    // FJB-terminated feeder topology: each island side feeder chains
    // through its own PCS units and ends at the island FJB — no
    // substation corridor home run for island feeders.
    {
      const fxs = d40.fence.map(p => p.x);
      const fys = d40.fence.map(p => p.y);
      const sub40 = { x: Math.max(...fxs) + 150, y: (Math.min(...fys) + Math.max(...fys)) / 2 };
      const f40 = generateFeeders(d40, sub40, cfg40.blockMW);
      // One feeder per island side, EXCEPT sides larger than the 6-PCS
      // feeder cap (MAX_INVERTERS_PER_FEEDER) must split into balanced,
      // order-preserving chunks — Hondo's middle island has 10 PCS per
      // side, so each of those sides legally carries two feeders. Every
      // chunk still terminates at its own island's FJB.
      const chunkSide = (ids: string[]): string[][] => {
        const n = ids.length;
        if (!n) return [];
        const k = Math.ceil(n / MAX_INVERTERS_PER_FEEDER);
        const base = Math.floor(n / k);
        let extra = n % k;
        const out: string[][] = [];
        let i2 = 0;
        for (let g = 0; g < k; g++) {
          const take = base + (extra-- > 0 ? 1 : 0);
          out.push(ids.slice(i2, i2 + take));
          i2 += take;
        }
        return out;
      };
      const sideGroups = isl40.flatMap(isl =>
        [...chunkSide(isl.southIds), ...chunkSide(isl.northIds)].map(ids => ({ n: isl.n, ids })));
      const f40Sides = f40;
      check('QTY3 FJB: feeder count = island side chunks (6-PCS cap)', f40Sides.length === sideGroups.length,
        `${f40Sides.length} vs ${sideGroups.length}`);
      check('QTY3 FJB: standard islands keep every side at or below the 7-PCS cap',
        isl40.every(isl => isl.southIds.length <= MAX_INVERTERS_PER_FEEDER &&
          isl.northIds.length <= MAX_INVERTERS_PER_FEEDER),
        isl40.map(i => `${i.southIds.length}/${i.northIds.length}`).join(', '));

      const invById40 = new Map(d40.equipment.filter(e => e.kind === 'inverter').map(e => [e.id, e]));
      let fjbBad = '';
      for (const fd of f40Sides) {
        const grp = sideGroups.find(g =>
          JSON.stringify([...g.ids].sort()) === JSON.stringify([...fd.inverterIds].sort()));
        if (!grp) { fjbBad = `feeder ${fd.idx}: members are not one island side chunk`; break; }
        // Reference route maps (CAR-D-B005-0): every daisy chain is its OWN
        // feeder routed individually chain-end -> substation. FJBs carry
        // fiber only, so the run must never touch a box.
        if (fd.fjbId !== null) { fjbBad = `feeder ${fd.idx}: carries fjbId ${fd.fjbId} (boxes are fiber-only)`; break; }
        const boxes = d40.equipment.filter(e =>
          e.kind === 'feederJunctionBox' && new RegExp(`^fjb-${grp.n}(?:-\\d+)?$`).test(e.id));
        const touchesBox = fd.segments.some(s => s.pts.some(p =>
          boxes.some(b => Math.hypot(p.x - b.x, p.y - b.y) < 5)));
        if (touchesBox) { fjbBad = `feeder ${fd.idx}: run touches an island FJB`; break; }
        const lastSeg = fd.segments[fd.segments.length - 1];
        const end = lastSeg.pts[lastSeg.pts.length - 1];
        if (Math.hypot(end.x - sub40.x, end.y - sub40.y) > 0.01) {
          fjbBad = `feeder ${fd.idx}: does not end at the substation`; break;
        }
        // hops (N-1) + home run = N segments for an N-PCS chain
        if (fd.segments.length !== fd.inverterIds.length) {
          fjbBad = `feeder ${fd.idx}: ${fd.segments.length} segments for ${fd.inverterIds.length} PCS`; break;
        }
        // chain is anchored at the substation: it ends at the PCS from
        // which the home run launches, and no other member is meaningfully
        // closer to the substation than that launch PCS.
        const lastId = fd.inverterIds[fd.inverterIds.length - 1];
        const lastInv = invById40.get(lastId)!;
        const dLast = Math.hypot(lastInv.x - sub40.x, lastInv.y - sub40.y);
        const nearer = fd.inverterIds.filter(id => {
          const e = invById40.get(id)!;
          return Math.hypot(e.x - sub40.x, e.y - sub40.y) < dLast - 60;
        });
        if (nearer.length) { fjbBad = `feeder ${fd.idx}: chain does not end near the substation side`; break; }
      }
      check('QTY3: each feeder home-runs chain-end -> substation, bypassing every FJB', fjbBad === '', fjbBad);

      // Same-island feeders must separate immediately after their launch
      // points — no collinear shared stretch (that would read as a combined
      // trunk trench). Grouped by island via the inverter ids.
      let dropBad = '';
      const byIsland = new Map<number, typeof f40>();
      for (const fd of f40Sides) {
        const grp = sideGroups.find(g =>
          JSON.stringify([...g.ids].sort()) === JSON.stringify([...fd.inverterIds].sort()));
        if (!grp) continue;
        byIsland.set(grp.n, [...(byIsland.get(grp.n) ?? []), fd]);
      }
      for (const [islN, group] of Array.from(byIsland.entries())) {
        if (group.length < 2) continue;
        // First point of each home run past its launch, ~5 ft out
        const probes = group.map(fd => {
          const home = fd.segments[fd.segments.length - 1];
          // walk 5 ft along the polyline from the FJB
          let rem = 5;
          for (let j = 0; j < home.pts.length - 1; j++) {
            const a = home.pts[j], b = home.pts[j + 1];
            const len = Math.hypot(b.x - a.x, b.y - a.y);
            if (len >= rem) {
              const t = rem / len;
              return { idx: fd.idx, x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
            }
            rem -= len;
          }
          const end = home.pts[home.pts.length - 1];
          return { idx: fd.idx, x: end.x, y: end.y };
        });
        for (let i = 0; i < probes.length && !dropBad; i++) {
          for (let j = i + 1; j < probes.length; j++) {
            if (Math.hypot(probes[i].x - probes[j].x, probes[i].y - probes[j].y) < 0.5) {
              dropBad = `island ${islN}: feeders ${probes[i].idx} and ${probes[j].idx} still coincident 5 ft past launch`;
              break;
            }
          }
        }
      }
      check('QTY3: same-island home runs separate immediately past the launch point', dropBad === '', dropBad);

      // One MV circuit per trench (Puma reference): any two DIFFERENT
      // feeders' parallel axis-aligned segments that overlap for more than
      // a joint-crossing length must sit in separate trenches — at least
      // the hop stagger apart everywhere, and at full trench spacing on
      // the shared-corridor portions. Perpendicular crossings are legal
      // (trenches may cross, never share a cut). A ~15 ft zone around a
      // shared FJB is exempt: both circuits legitimately enter one box.
      {
        const S_FULL = FEEDER_TRENCH_SPACING_FT;
        const S_MIN = 3;   // HOP_STAGGER_FT
        const fjbPts = d40.equipment
          .filter(e => e.kind === 'feederJunctionBox')
          .map(e => ({ x: e.x, y: e.y }));
        type Seg = { x0: number; y0: number; x1: number; y1: number; horiz: boolean };
        const axisSegs = (fd: (typeof f40)[number]): Seg[] => {
          const out: Seg[] = [];
          for (const s of fd.segments) {
            for (let k = 1; k < s.pts.length; k++) {
              const a = s.pts[k - 1], b = s.pts[k];
              if (Math.abs(a.x - b.x) < 1e-6 && Math.abs(a.y - b.y) < 1e-6) continue;
              if (Math.abs(a.y - b.y) < 1e-6) out.push({ x0: Math.min(a.x, b.x), x1: Math.max(a.x, b.x), y0: a.y, y1: a.y, horiz: true });
              else if (Math.abs(a.x - b.x) < 1e-6) out.push({ x0: a.x, x1: a.x, y0: Math.min(a.y, b.y), y1: Math.max(a.y, b.y), horiz: false });
            }
          }
          return out;
        };
        // Substation terminal zone: every circuit legitimately converges on
        // the one substation termination point, so the final jogs from each
        // lane into it are exempt (zone spans half the lane bundle width).
        const subZone = (f40Sides.length * S_FULL) / 2 + 15;
        const nearFjb = (x: number, y: number) =>
          fjbPts.some(p => Math.hypot(p.x - x, p.y - y) < 15) ||
          Math.hypot(sub40.x - x, sub40.y - y) < subZone;
        let trenchBad = '';
        outerTrench:
        for (let i = 0; i < f40Sides.length; i++) {
          for (let j = i + 1; j < f40Sides.length; j++) {
            for (const sa of axisSegs(f40Sides[i])) {
              for (const sb of axisSegs(f40Sides[j])) {
                if (sa.horiz !== sb.horiz) continue; // perpendicular: allowed
                const sep = sa.horiz ? Math.abs(sa.y0 - sb.y0) : Math.abs(sa.x0 - sb.x0);
                const lo = sa.horiz ? Math.max(sa.x0, sb.x0) : Math.max(sa.y0, sb.y0);
                const hi = sa.horiz ? Math.min(sa.x1, sb.x1) : Math.min(sa.y1, sb.y1);
                const overlap = hi - lo;
                if (overlap <= 5) continue; // joint / crossing-length overlap
                // midpoint of the shared stretch; exempt the FJB entry zone
                const mid = (lo + hi) / 2;
                const ma = sa.horiz ? { x: mid, y: sa.y0 } : { x: sa.x0, y: mid };
                if (nearFjb(ma.x, ma.y)) continue;
                if (sep < S_MIN - 0.01) {
                  trenchBad = `feeders ${f40Sides[i].idx}/${f40Sides[j].idx}: parallel segments ${sep.toFixed(2)} ft apart over ${overlap.toFixed(0)} ft`;
                  break outerTrench;
                }
                // Long shared stretches (corridor rides / home runs) demand
                // full trench spacing, not just the hop stagger.
                if (overlap > 60 && sep < S_FULL - 0.01) {
                  trenchBad = `feeders ${f40Sides[i].idx}/${f40Sides[j].idx}: corridor segments only ${sep.toFixed(2)} ft apart over ${overlap.toFixed(0)} ft`;
                  break outerTrench;
                }
              }
            }
          }
        }
        check('QTY3 trench exclusivity: no two feeders share a trench (parallel overlap >= spacing)',
          trenchBad === '', trenchBad);
      }

      // Direct home runs: no feeder's FJB->substation run may wander far
      // beyond the Manhattan distance — a bounded allowance covers the
      // corridor spread (one lane per feeder), drop jogs, and the climb
      // outside the fence. Catches "trench crossing the yard to nothing".
      {
        const allowance = 6 * f40Sides.length * 10 + 200;
        let homeBad = '';
        for (const fd of f40Sides) {
          if (!fd.fjbId) continue;
          const fjb = d40.equipment.find(e => e.id === fd.fjbId)!;
          const home = fd.segments[fd.segments.length - 1];
          const manhattan = Math.abs(sub40.x - fjb.x) + Math.abs(sub40.y - fjb.y);
          if (home.lengthFt > manhattan + allowance) {
            homeBad = `feeder ${fd.idx}: home run ${home.lengthFt.toFixed(0)} ft vs Manhattan ${manhattan.toFixed(0)} + ${allowance}`;
            break;
          }
        }
        check('QTY3 direct home runs: length bounded by Manhattan + corridor allowance', homeBad === '', homeBad);
      }

      // No island wrap-around detours: each chain hop connects neighbors,
      // so no single hop should be longer than the island's full strip
      // width (a hop that long means the chain doubled back around rows).
      {
        let hopBad = '';
        for (const fd of f40Sides) {
          const hops = fd.segments.slice(0, fd.inverterIds.length);
          const isl = isl40.find(z => z.inverterIds.includes(fd.inverterIds[0]))!;
          const stripW = (isl.maxX - isl.minX) + 60;
          for (const h of hops.slice(0, -1)) { // last hop enters the FJB
            if (h.lengthFt > stripW) {
              hopBad = `feeder ${fd.idx}: chain hop ${h.lengthFt.toFixed(0)} ft exceeds strip width ${stripW.toFixed(0)}`;
              break;
            }
          }
          if (hopBad) break;
        }
        check('QTY3 chain order: no wrap-around island detours (hop length bounded)', hopBad === '', hopBad);
      }
      check('QTY3 FJB: lengths follow the new routing (sum of segments)',
        f40.every(fd => Math.abs(fd.totalLengthFt - fd.segments.reduce((s, x) => s + x.lengthFt, 0)) < 0.1));
      check('QTY3 FJB: deterministic',
        JSON.stringify(generateFeeders(d40, sub40, cfg40.blockMW)) === JSON.stringify(f40));

      // Fallback: with FJBs removed (placement failure), feeders home-run
      // to the substation corridor as before (fjbId null, ends at sub).
      const dNoFjb = { ...d40, equipment: d40.equipment.filter(e => e.kind !== 'feederJunctionBox') };
      const fNo = generateFeeders(dNoFjb, sub40, cfg40.blockMW);
      check('QTY3 FJB fallback: missing FJB -> generic substation home run',
        fNo.length === f40Sides.length && fNo.every(fd => {
          const lastSeg = fd.segments[fd.segments.length - 1];
          const end = lastSeg.pts[lastSeg.pts.length - 1];
          return fd.fjbId === null && Math.hypot(end.x - sub40.x, end.y - sub40.y) < 0.01;
        }));

      // Drafter-overridden feeder cap (opts.maxPerFeeder): island sides
      // still split into balanced, order-preserving chunks under the new
      // cap, and every chunk still routes through its own island FJB to
      // the substation — determinism included.
      {
        const cap = 4; // non-default (< 6) drafter pick
        // Entry-end-first chunking: full cap-4 groups fill from the
        // substation-entry end of each side, remainder at the FAR end. The
        // generator derives the entry from the substation approach, so the
        // expected membership set accepts any hint orientation (the chunk
        // COUNT is orientation-invariant).
        const fCap = generateFeeders(d40, sub40, cfg40.blockMW, { maxPerFeeder: cap });
        const capGroupSet = new Set<string>();
        for (const h of [undefined,
          { horiz: true, dir: 1 }, { horiz: true, dir: -1 },
          { horiz: false, dir: 1 }, { horiz: false, dir: -1 }] as any[]) {
          for (const g of islandGroups(d40, cap, h) ?? []) {
            capGroupSet.add(JSON.stringify([...g].sort()));
          }
        }
        const capCount = (islandGroups(d40, cap) ?? []).length;
        check(`QTY3 cap override: layout has a side that splits differently under cap ${cap}`,
          capCount > sideGroups.length,
          `${capCount} vs ${sideGroups.length}`);
        check(`QTY3 cap override: feeder count = island side chunks at cap ${cap}`,
          fCap.length === capCount, `${fCap.length} vs ${capCount}`);
        check(`QTY3 cap override: no feeder exceeds ${cap} PCS`,
          fCap.every(fd => fd.inverterIds.length <= cap),
          fCap.map(fd => fd.inverterIds.length).join(','));
        check('QTY3 cap override: each feeder is one entry-end-first side chunk',
          fCap.every(fd => capGroupSet.has(JSON.stringify([...fd.inverterIds].sort()))));
        check('QTY3 cap override: every PCS appears in exactly one feeder',
          JSON.stringify(fCap.flatMap(fd => fd.inverterIds).sort()) ===
          JSON.stringify(isl40.flatMap(isl => isl.inverterIds).sort()));
        let capBad = '';
        for (const fd of fCap) {
          if (!capGroupSet.has(JSON.stringify([...fd.inverterIds].sort()))) {
            capBad = `feeder ${fd.idx}: members are not one cap-${cap} side chunk`; break;
          }
          if (fd.fjbId !== null) { capBad = `feeder ${fd.idx}: carries fjbId ${fd.fjbId} (boxes are fiber-only)`; break; }
          const islOf = isl40.find(i => fd.inverterIds.every(id => i.inverterIds.includes(id)));
          const boxes = d40.equipment.filter(e =>
            e.kind === 'feederJunctionBox' && islOf && new RegExp(`^fjb-${islOf.n}(?:-\\d+)?$`).test(e.id));
          const touchesBox = fd.segments.some(s => s.pts.some(p =>
            boxes.some(b => Math.hypot(p.x - b.x, p.y - b.y) < 5)));
          if (touchesBox) { capBad = `feeder ${fd.idx}: run touches an island FJB`; break; }
          const lastSeg = fd.segments[fd.segments.length - 1];
          const end = lastSeg.pts[lastSeg.pts.length - 1];
          if (Math.hypot(end.x - sub40.x, end.y - sub40.y) > 0.01) {
            capBad = `feeder ${fd.idx}: does not end at the substation`; break;
          }
          if (fd.segments.length !== fd.inverterIds.length) {
            capBad = `feeder ${fd.idx}: ${fd.segments.length} segments for ${fd.inverterIds.length} PCS`; break;
          }
        }
        check('QTY3 cap override: each chunk feeder home-runs to the substation, bypassing the FJBs',
          capBad === '', capBad);
        check('QTY3 cap override: deterministic',
          JSON.stringify(generateFeeders(d40, sub40, cfg40.blockMW, { maxPerFeeder: cap })) ===
          JSON.stringify(fCap));
        // Over-cap requests are clamped to the hard 6-PCS limit.
        check('QTY3 cap override: cap above 6 clamps to the default grouping',
          JSON.stringify(generateFeeders(d40, sub40, cfg40.blockMW, { maxPerFeeder: 9 })) ===
          JSON.stringify(f40));
      }
    }

    // 4-container path unchanged: no islands, no corridor collectors
    const d44 = generateSiteDesign(hondo, cfg40, 100, 400, { hotClimate: true, containersPerPcs: 4 });
    check('QTY4: no islands and no corridor collectors',
      (!d44.islands || d44.islands.length === 0) && !d44.cables.some(r => r.id.startsWith('lvac-corridor-')));
  }

  // ---------------------------------------------------------------
  console.log('\n[40b] Oversized synthetic island still routes every feeder directly (FJBs fiber-only)');
  {
    // Standard islands cap every side at 7 PCS, so a real layout can no
    // longer produce an island needing more than the two strip-end boxes —
    // a very wide strip now splits into multiple 7-pair islands instead.
    // The exceed path in the FEEDER GENERATOR is legacy safety for
    // hand-edited saves, so it is exercised with a SYNTHETIC merged island
    // (all of the wide strip's PCS forced onto island 1 and its lone box).
    const mega: SiteBoundary = {
      name: 'mega-strip',
      polygon: [{ x: 0, y: 0 }, { x: 3600, y: 0 }, { x: 3600, y: 420 }, { x: 0, y: 420 }],
      origin: { lat: 0, lon: 0 },
      areaAcres: (3600 * 420) / 43560,
    };
    const cfgB = getConfiguration('ge-aux-400');
    const dBReal = generateSiteDesign(mega, cfgB, 160, 640, { hotClimate: true, containersPerPcs: 3 });
    const islReal = dBReal.islands ?? [];
    check('oversized: standard islands keep the wide strip split (no island needs > 2 FJBs)',
      islReal.length > 1 && islReal.every(isl =>
        Math.ceil(isl.southIds.length / MAX_INVERTERS_PER_FEEDER) +
        Math.ceil(isl.northIds.length / MAX_INVERTERS_PER_FEEDER) <= 4),
      islReal.map(i => `${i.n}:${i.southIds.length}/${i.northIds.length}`).join(', '));
    check('oversized: layout never needs the manual-boxes warning under standard islands',
      !dBReal.warnings.some(w => w.includes('locate the remaining boxes manually')),
      dBReal.warnings.join(' | '));

    // Synthetic merged island (legacy hand-edited save shape): every PCS of
    // the row on one island, only island 1's strip-end box(es) available.
    const invsB = dBReal.equipment.filter(e => e.kind === 'inverter');
    const rowY = islReal[0].y;
    const southAll = invsB.filter(e => e.y < rowY).sort((a, b) => a.x - b.x || a.id.localeCompare(b.id));
    const northAll = invsB.filter(e => e.y >= rowY).sort((a, b) => b.x - a.x || a.id.localeCompare(b.id));
    const mergedIsl = {
      n: 1,
      y: rowY,
      minX: Math.min(...islReal.map(i => i.minX)),
      maxX: Math.max(...islReal.map(i => i.maxX)),
      inverterIds: [...southAll.map(e => e.id), ...northAll.map(e => e.id)],
      southIds: southAll.map(e => e.id),
      northIds: northAll.map(e => e.id),
    };
    const dB = {
      ...dBReal,
      islands: [mergedIsl],
      equipment: dBReal.equipment.filter(e =>
        e.kind !== 'feederJunctionBox' || /^fjb-1(?:-\d+)?$/.test(e.id)),
    };
    const islB = dB.islands;
    const bigIslands = islB.filter(isl =>
      Math.ceil(isl.southIds.length / MAX_INVERTERS_PER_FEEDER) +
      Math.ceil(isl.northIds.length / MAX_INVERTERS_PER_FEEDER) > 4);
    check('oversized: synthetic fixture yields an island needing more than 2 FJBs (>4 feeders)',
      bigIslands.length > 0,
      islB.map(i => `${i.n}:${i.southIds.length}/${i.northIds.length}`).join(', '));

    // Never more than the two strip-end boxes are auto-placed per island.
    let boxBad = '';
    for (const isl of islB) {
      const boxes = dB.equipment.filter(e =>
        e.kind === 'feederJunctionBox' && new RegExp(`^fjb-${isl.n}(?:-\\d+)?$`).test(e.id));
      if (boxes.length > 2) { boxBad = `island ${isl.n}: ${boxes.length} FJBs auto-placed`; break; }
    }
    check('oversized: at most 2 strip-end FJBs are auto-placed per island', boxBad === '', boxBad);

    // Feeder generation: full feeder set, every chain routes directly to
    // the substation (FJBs are fiber-only — no termination caps, no
    // exceed-warnings; an island with any number of side chunks is fine).
    const subB: Pt = { x: 3900, y: 210 };
    const warnsB: string[] = [];
    const feedsB = generateFeeders(dB, subB, cfgB.blockMW, { onWarning: m => warnsB.push(m) });
    const nonTrunkB = feedsB.filter(f => !f.trunk);
    const expectFeeders = islB.reduce((s, isl) =>
      s + Math.ceil(isl.southIds.length / MAX_INVERTERS_PER_FEEDER) +
      Math.ceil(isl.northIds.length / MAX_INVERTERS_PER_FEEDER), 0);
    check('oversized: feeder count matches the 6-PCS side chunking', nonTrunkB.length === expectFeeders,
      `${nonTrunkB.length} vs ${expectFeeders}`);
    check('oversized: no feeder carries an FJB id (boxes are fiber-only)',
      nonTrunkB.every(f => f.fjbId === null),
      nonTrunkB.filter(f => f.fjbId).map(f => `F${f.idx}=${f.fjbId}`).join(', '));
    check('oversized: every feeder ends at the substation',
      nonTrunkB.every(f => {
        const home = f.segments[f.segments.length - 1];
        const e = home.pts[home.pts.length - 1];
        return Math.hypot(e.x - subB.x, e.y - subB.y) < 0.01;
      }));
    check('oversized: feeder lengths stay consistent (sum of segments)',
      nonTrunkB.every(fd => Math.abs(fd.totalLengthFt - fd.segments.reduce((s, x) => s + x.lengthFt, 0)) < 0.1));
    check('oversized: no FJB termination warnings fire (concept retired)',
      !warnsB.some(w => w.includes('junction box terminations')), warnsB.join(' | '));
    check('oversized: deterministic',
      JSON.stringify(generateFeeders(dB, subB, cfgB.blockMW)) === JSON.stringify(feedsB));
  }

  // ---------------------------------------------------------------
  console.log('\n[41] Single-sided (half island) edge strip: labels, gear, cabling');
  {
    // Parcel sized to fit exactly ONE mirrored-pair column (fence width fits a
    // single 28 ft pair pitch) and two pair rows. Requesting 3 blocks fills
    // row 1 with a full pair (south + north) and leaves ONE block for row 2 —
    // the fence-adjacent single-sided strip (placeMirroredPair count=1).
    const halfBoundary: SiteBoundary = {
      name: 'half-island-strip',
      // Sized for the zero fence setback (fence == parcel): 130 x 410 is the
      // fenced area the original 180 x 460 parcel produced at the retired
      // 25 ft inset, keeping this a one-pair-column, two-pair-row yard.
      polygon: [{ x: 0, y: 0 }, { x: 130, y: 0 }, { x: 130, y: 410 }, { x: 0, y: 410 }],
      origin: { lat: 0, lon: 0 },
      areaAcres: (130 * 410) / 43560,
    };
    const cfg41 = getConfiguration('ge-aux-400');
    // 3 blocks: energy governs (3 x 15.3 MWh covers 45 MWh)
    const d41 = generateSiteDesign(halfBoundary, cfg41, 10, 45, { hotClimate: true, containersPerPcs: 3 });
    const isl41 = d41.islands ?? [];
    check('half-island: 3 blocks requested and placed', d41.blocksRequired === 3 && d41.blocksPlaced === 3,
      `required ${d41.blocksRequired}, placed ${d41.blocksPlaced}`);
    check('half-island: two islands on the design', isl41.length === 2, `${isl41.length}`);

    const single = isl41.find(i => i.northIds.length === 0 && i.southIds.length > 0);
    const full = isl41.find(i => i.northIds.length > 0 && i.southIds.length > 0);
    check('half-island: one island is single-sided (south only), one is a full pair',
      !!single && !!full,
      isl41.map(i => `isl ${i.n}: S${i.southIds.length}/N${i.northIds.length}`).join(', '));

    if (single && full) {
      const cont41 = d41.equipment.filter(e => e.kind === 'bess');
      // inverterIds of the single-sided island = its southIds only
      check('half-island: single-sided inverterIds == southIds (no phantom north units)',
        JSON.stringify(single.inverterIds) === JSON.stringify(single.southIds));

      // All equipment of the single-sided block sits SOUTH of its corridor
      // centerline (the corridor stays adjacent on the empty north side).
      const singleBlockNs = single.southIds.map(id => id.replace('inv-', ''));
      let sideBad = '';
      for (const n of singleBlockNs) {
        const members = d41.equipment.filter(e => e.id === `inv-${n}` || e.id.startsWith(`bess-${n}-`));
        if (members.length !== 4) { sideBad = `block ${n}: ${members.length} members`; break; }
        const north = members.find(e => e.y >= single.y);
        if (north) { sideBad = `${north.id} at y=${north.y.toFixed(1)} >= corridor ${single.y.toFixed(1)}`; break; }
      }
      check('half-island: single-sided block equipment entirely south of corridor', sideBad === '', sideBad);

      // A-3 present at the south corridor edge only
      const a3s = cont41.filter(c => c.id.endsWith('-3') &&
        singleBlockNs.some(n => c.id === `bess-${n}-3`));
      check('half-island: A-3 at the south corridor edge (10 ft corridor half-gap)',
        a3s.length === singleBlockNs.length &&
        a3s.every(c => c.y < single.y && Math.abs((single.y - c.y) - (5 + c.width / 2)) < 0.05),
        a3s.map(c => `${c.id} y=${c.y.toFixed(2)}`).join(', '));

      // FJB + comms cabinet for the single-sided island too (or a warning)
      let gearBad = '';
      for (const isl of isl41) {
        const fjb = d41.equipment.find(e => e.id === `fjb-${isl.n}`);
        const comms = d41.equipment.find(e => e.id === `comms-${isl.n}`);
        if (!fjb || !comms) {
          if (!d41.warnings.some(w => w.toLowerCase().includes('junction box') || w.toLowerCase().includes('feeder'))) {
            gearBad = `island ${isl.n}: gear missing without warning`; break;
          }
          continue;
        }
        for (const g of [fjb, comms]) {
          const rot = Math.abs(Math.sin(g.rotation)) > 0.5;
          if (!rectInsidePolygon(g.x, g.y, (rot ? g.width : g.length) / 2, (rot ? g.length : g.width) / 2, d41.fence, 2.9)) {
            gearBad = `${g.id} fails fence clearance`; break;
          }
        }
        if (gearBad) break;
      }
      check('half-island: FJB + comms per island placed with clearance (or warned)', gearBad === '', gearBad);

      // Labels stay serpentine-consistent: FF = island index, UU walks south
      // W->E then north E->W (empty north side is a no-op, not a renumber).
      const { applyReferenceLabels } = await import('../client/src/lib/nextera/labels');
      applyReferenceLabels(d41.equipment, null, isl41);
      let lblBad = '';
      isl41.forEach((isl, gi) => {
        if (lblBad) return;
        const ff = String(gi + 1).padStart(2, '0');
        isl.inverterIds.forEach((id, k) => {
          const invE = d41.equipment.find(e => e.id === id);
          const want = `PCS${ff}-${String(k + 1).padStart(2, '0')}`;
          if (!invE || invE.label !== want) lblBad = `${id}: label ${invE?.label} != ${want}`;
        });
        if (JSON.stringify(isl.inverterIds) !== JSON.stringify([...isl.southIds, ...isl.northIds]))
          lblBad = `island ${isl.n}: inverterIds not south-then-north`;
      });
      check('half-island: PCS<FF>-<UU> labels serpentine-consistent across both islands', lblBad === '', lblBad);
      // Container labels follow their PCS position
      let conBad = '';
      for (const c of cont41) {
        const m = c.id.match(/^bess-(\d+)-(\d+)$/)!;
        const invE = d41.equipment.find(e => e.id === `inv-${m[1]}`);
        const pcsM = invE?.label?.match(/^PCS(\d{2})-(\d{2})$/);
        if (!pcsM) { conBad = `${c.id}: owner ${invE?.label} not PCS-labeled`; break; }
        const want = `CON${pcsM[1]}${pcsM[2]}-A-${m[2]}`;
        if (c.label !== want) { conBad = `${c.id}: ${c.label} != ${want}`; break; }
      }
      check('half-island: CON<FFUU>-A-<n> container labels match their PCS', conBad === '', conBad);

      // DC: entry-box routing convention (same as section [40], per the
      // Puma reference): each run is an orthogonal (no diagonals) finite
      // polyline that leaves the PCS DC compartment face and lands at the
      // container's cable entry box — NOT a bare 2-point vertical segment
      // (that older convention predates entry-box DC routing).
      let dcBad = '';
      for (const c of cont41) {
        const run = d41.cables.find(r => r.id === `dc-${c.id}-pos`);
        if (!run) { dcBad = `${c.id}: no DC run`; break; }
        if (run.pts.length < 2 || run.pts.some(p => !Number.isFinite(p.x) || !Number.isFinite(p.y))) {
          dcBad = `${c.id}: DC run degenerate or non-finite`; break;
        }
        for (let k = 1; k < run.pts.length; k++) {
          const a = run.pts[k - 1], b2 = run.pts[k];
          if (Math.abs(a.x - b2.x) > 1e-6 && Math.abs(a.y - b2.y) > 1e-6) {
            dcBad = `${c.id}: DC run has a diagonal segment`; break;
          }
        }
        if (dcBad) break;
        // terminal point lands on the container footprint (entry box)
        const pe = run.pts[run.pts.length - 1];
        const rot = Math.abs(Math.sin(c.rotation)) > 0.5;
        const hx = (rot ? c.width : c.length) / 2;
        const hy = (rot ? c.length : c.width) / 2;
        if (Math.abs(pe.x - c.x) > hx + 0.1 || Math.abs(pe.y - c.y) > hy + 0.1) {
          dcBad = `${c.id}: DC run does not land at the container entry box`; break;
        }
      }
      check('half-island: orthogonal entry-box DC run PCS -> each container', dcBad === '', dcBad);

      // Aux drops land on the corridor centerline; the single-sided island
      // still gets a collector spanning its drops (or a corridor tie warning).
      let lvBad = '';
      for (const c of cont41) {
        const run = d41.cables.find(r => r.id === `lvac-${c.id}`);
        if (!run) { lvBad = `${c.id}: no aux drop`; break; }
        const end = run.pts[run.pts.length - 1];
        if (!isl41.some(i => Math.abs(end.y - i.y) < 1e-6)) {
          lvBad = `${c.id}: drop ends off-corridor y=${end.y.toFixed(2)}`; break;
        }
      }
      check('half-island: every aux drop (incl. single-sided strip) lands on its corridor', lvBad === '', lvBad);
      let colBad = '';
      for (const isl of isl41) {
        const col = d41.cables.find(r => r.id === `lvac-corridor-${isl.n}`);
        if (!col) { colBad = `island ${isl.n}: no collector`; break; }
        if (col.pts.some(p => Math.abs(p.y - isl.y) > 1e-6)) { colBad = `island ${isl.n}: collector off centerline`; break; }
        const drops = d41.cables.filter(r => r.class === 'LVAC' && r.id.startsWith('lvac-bess-') &&
          cont41.some(c => r.id === `lvac-${c.id}` && Math.abs((r.pts[r.pts.length - 1].y) - isl.y) < 1e-6));
        const minX = Math.min(...col.pts.map(p => p.x)), maxX = Math.max(...col.pts.map(p => p.x));
        if (drops.some(r => {
          const x = r.pts[r.pts.length - 1].x;
          return x < minX - 1e-6 || x > maxX + 1e-6;
        })) { colBad = `island ${isl.n}: drops outside collector span`; break; }
      }
      const corridorTieWarned = d41.warnings.some(w => w.includes('aux corridor collectors'));
      check('half-island: single-sided island still gets a spanning collector (or tie warning)',
        colBad === '' || corridorTieWarned, colBad);
      check('half-island: no sheet-3 LVAC row buses in mirrored mode',
        !d41.cables.some(r => /^lvac-bus-/.test(r.id) || /^lvac-drop-inv/.test(r.id)));

      // Every cable vertex finite (no NaN geometry on the odd strip)
      check('half-island: all cable vertices finite',
        d41.cables.every(r => r.pts.every(p => Number.isFinite(p.x) && Number.isFinite(p.y))));
    }
  }

  // ---------------------------------------------------------------
  // [42] One-click row alignment: computeRowAlignOffsets() + rowMoves pipeline
  console.log('\n[42] Row alignment (left / center / right) via validated rowMoves');
  {
    const cfg = getConfiguration(CONFIGURATIONS[0].id)!;
    const base = generateSiteDesign(hondo, cfg, 100, 400, { hotClimate: true, roadMode: 'roads' });
    check('[42] baseline design has rows and rowEditGeom', base.blockRows.length > 0 && !!base.rowEditGeom);

    for (const mode of ['left', 'center', 'right'] as const) {
      const offsets = computeRowAlignOffsets(base, mode);
      // Offsets are horizontal-only, 0.5 ft grid, and never larger than the yard.
      const xsF = base.fence.map(p => p.x);
      const span = Math.max(...xsF) - Math.min(...xsF);
      check(`[42:${mode}] offsets are horizontal, on 0.5 ft grid, within yard span`,
        Object.values(offsets).every(o =>
          o.dy === 0 && Math.abs(o.dx) <= span &&
          Math.abs(o.dx / 0.5 - Math.round(o.dx / 0.5)) < 1e-9));

      // Applying through the normal rowMoves pipeline: engine accepts every
      // offset (no "move rejected" warnings) — the helper only proposes
      // shifts validateRowShift already approved.
      const rowMoves: Record<number, { dx: number; dy: number }> = {};
      for (const [k, o] of Object.entries(offsets)) rowMoves[Number(k)] = { dx: o.dx, dy: o.dy };
      const aligned = generateSiteDesign(hondo, cfg, 100, 400, {
        hotClimate: true, roadMode: 'roads', constraints: { rowMoves },
      });
      check(`[42:${mode}] engine accepts every proposed alignment offset`,
        !aligned.warnings.some(w => /Row \d+ move rejected/.test(w)),
        aligned.warnings.filter(w => /move rejected/.test(w)).join('; '));
      check(`[42:${mode}] aligned design keeps all blocks placed`,
        aligned.blocksPlaced === base.blocksPlaced);

      // Row block positions actually shifted by the requested offset.
      let shiftBad = '';
      for (const row of aligned.blockRows) {
        const want = rowMoves[row.index]?.dx ?? 0;
        const baseRow = base.blockRows.find(r => r.index === row.index)!;
        for (const b of row.blocks) {
          const b0 = baseRow.blocks.find(q => q.n === b.n)!;
          if (Math.abs((b.x - b0.x) - want) > 1e-6) {
            shiftBad = `row ${row.index} block ${b.n}: moved ${(b.x - b0.x).toFixed(2)} want ${want}`;
            break;
          }
        }
        if (shiftBad) break;
      }
      check(`[42:${mode}] every row shifted by exactly its proposed offset`, shiftBad === '', shiftBad);

      // Idempotence: re-running alignment on the aligned design proposes
      // (near) nothing — each row is already at its aligned position.
      const again = computeRowAlignOffsets(aligned, mode);
      check(`[42:${mode}] alignment is idempotent (second pass ~no-op)`,
        Object.values(again).every(o => Math.abs(o.dx) <= 0.5),
        JSON.stringify(again));
    }

    // Left vs right actually differ (rows have slack in the Hondo yard) and
    // center lands between them for each aligned row.
    const L = computeRowAlignOffsets(base, 'left');
    const R = computeRowAlignOffsets(base, 'right');
    const C = computeRowAlignOffsets(base, 'center');
    const anySlack = base.blockRows.some(r => (L[r.index]?.dx ?? 0) !== (R[r.index]?.dx ?? 0));
    check('[42] left and right alignment differ (rows have horizontal slack)', anySlack);
    let cBad = '';
    for (const r of base.blockRows) {
      const lo = L[r.index]?.dx ?? 0, hi = R[r.index]?.dx ?? 0, c = C[r.index]?.dx ?? 0;
      if (c < lo - 0.51 || c > hi + 0.51) { cBad = `row ${r.index}: center ${c} outside [${lo}, ${hi}]`; break; }
    }
    check('[42] center offset lies between left and right extremes per row', cBad === '', cBad);

    // Degradation: an absurd manual row move is still rejected with a warning
    // and the automatic position kept (alignment path never bypasses this).
    const idx0 = base.blockRows[0].index;
    const xsAll = base.fence.map(p => p.x);
    const hugeDx = (Math.max(...xsAll) - Math.min(...xsAll)) + 500;
    const bad = generateSiteDesign(hondo, cfg, 100, 400, {
      hotClimate: true, roadMode: 'roads',
      constraints: { rowMoves: { [idx0]: { dx: hugeDx, dy: 0 } } },
    });
    check('[42] out-of-yard row move degrades to warning + auto position kept',
      bad.warnings.some(w => w.includes(`Row ${idx0} move rejected`)) &&
      Math.abs(bad.blockRows.find(r => r.index === idx0)!.blocks[0].x -
               base.blockRows.find(r => r.index === idx0)!.blocks[0].x) < 1e-6);

    // Composition with an existing manual row edit: pre-shift one row, then
    // align on top. The alignment offset is from CURRENT positions, so the
    // composed rowMove (manual + align) must still land the row at its
    // aligned position and preserve the manual dy.
    {
      const preDx = -10, preDy = 0;
      const pre = generateSiteDesign(hondo, cfg, 100, 400, {
        hotClimate: true, roadMode: 'roads',
        constraints: { rowMoves: { [idx0]: { dx: preDx, dy: preDy } } },
      });
      check('[42:compose] manual pre-shift accepted (fixture sanity)',
        !pre.warnings.some(w => w.includes(`Row ${idx0} move rejected`)));
      const alignOff = computeRowAlignOffsets(pre, 'right');
      const composed: Record<number, { dx: number; dy: number }> = {
        [idx0]: { dx: preDx + (alignOff[idx0]?.dx ?? 0), dy: preDy },
      };
      for (const [k, o] of Object.entries(alignOff)) {
        if (Number(k) !== idx0) composed[Number(k)] = { dx: o.dx, dy: o.dy };
      }
      const post = generateSiteDesign(hondo, cfg, 100, 400, {
        hotClimate: true, roadMode: 'roads', constraints: { rowMoves: composed },
      });
      check('[42:compose] composed manual + alignment offsets all accepted',
        !post.warnings.some(w => /Row \d+ move rejected/.test(w)),
        post.warnings.filter(w => /move rejected/.test(w)).join('; '));
      const b0pre = pre.blockRows.find(r => r.index === idx0)!.blocks[0];
      const b0post = post.blockRows.find(r => r.index === idx0)!.blocks[0];
      check('[42:compose] pre-shifted row lands at its aligned position',
        Math.abs((b0post.x - b0pre.x) - (alignOff[idx0]?.dx ?? 0)) < 1e-6,
        `moved ${(b0post.x - b0pre.x).toFixed(2)} want ${alignOff[idx0]?.dx ?? 0}`);
      check('[42:compose] alignment on aligned+manual design is ~idempotent',
        Object.values(computeRowAlignOffsets(post, 'right')).every(o => Math.abs(o.dx) <= 0.5));
    }

    // Mirrored-pair (QTY3 island) layouts: alignment offsets stay valid
    // through the rowMoves pipeline there too.
    {
      const cfg3 = getConfiguration(CONFIGURATIONS[0].id)!;
      const b3 = generateSiteDesign(hondo, cfg3, 100, 400, { hotClimate: true, containersPerPcs: 3 });
      check('[42:qty3] mirrored fixture has islands and rows',
        (b3.islands?.length ?? 0) > 0 && b3.blockRows.length > 0);
      for (const mode of ['left', 'right'] as const) {
        const off3 = computeRowAlignOffsets(b3, mode);
        const rm3: Record<number, { dx: number; dy: number }> = {};
        for (const [k, o] of Object.entries(off3)) rm3[Number(k)] = o;
        const a3 = generateSiteDesign(hondo, cfg3, 100, 400, {
          hotClimate: true, containersPerPcs: 3, constraints: { rowMoves: rm3 },
        });
        check(`[42:qty3:${mode}] engine accepts every mirrored-pair alignment offset`,
          !a3.warnings.some(w => /Row \d+ move rejected/.test(w)),
          a3.warnings.filter(w => /move rejected/.test(w)).join('; '));
        check(`[42:qty3:${mode}] mirrored design keeps all blocks placed`,
          a3.blocksPlaced === b3.blocksPlaced);
      }
    }

    // Non-monotone validity guard: on a yard fragmented by a reserved area
    // the valid-shift range has a gap — bisection alone would stop at the
    // near side of the obstacle. The coarse-scan fallback must still find
    // the furthest valid aligned position beyond the gap.
    {
      // Synthetic fixture: one 20x20 ft block at x=0 inside a rectangular
      // fence x∈[-20,200], with a reserved strip centered at x=60 blocking
      // the middle of the eastward range. equipmentMargin 5 ft ⇒ the block
      // center may reach x=185 at the east fence. Reserved overlap test
      // (halfW 10 + length/2 10 + MIN_EQUIP_SEP 2) forbids |x-60|<22, so the
      // eastward valid ddx range is [0,38] ∪ [82,185] — non-monotone.
      const geomS = {
        halfW: 10, halfD: 10, equipmentMargin: 5, nfpa: null, augGrid: null,
      };
      const fenceS = [
        { x: -20, y: -20 }, { x: 200, y: -20 }, { x: 200, y: 20 }, { x: -20, y: 20 },
      ];
      const dsyn: any = {
        blockRows: [{
          index: 1, y: 0, autoY: 0, blockCount: 1, moved: false,
          blocks: [{ n: 1, x: 0, y: 0 }],
        }],
        rowEditGeom: geomS,
        fence: fenceS,
        boundary: { polygon: fenceS },
        aisles: [],
        reservedZones: [{ id: 'rz1', x: 60, y: 0, length: 20, width: 100 }],
      };
      // Sanity: the gap really is invalid and the far pocket really is valid.
      const vs = (ddx: number) => validateRowShift(
        dsyn.blockRows[0].blocks, [], geomS as any, fenceS, fenceS, ddx, 0, [], dsyn.reservedZones) === null;
      check('[42:gap] fixture sanity: near side valid, gap invalid, far pocket valid',
        vs(38) && !vs(60) && vs(82) && vs(185) && !vs(185.5));
      const offR = computeRowAlignOffsets(dsyn, 'right');
      check('[42:gap] right-align crosses the invalid gap to the true east limit (185)',
        Math.abs((offR[1]?.dx ?? 0) - 185) < 1e-9, JSON.stringify(offR));
      // Left alignment on the same fixture: west range is continuous, the
      // guard must not change the plain bisection answer (center to x=-5,
      // i.e. ddx = -5 with the 5 ft margin at the west fence).
      const offL = computeRowAlignOffsets(dsyn, 'left');
      check('[42:gap] left-align (continuous range) still lands at the west limit (-5)',
        Math.abs((offL[1]?.dx ?? 0) + 5) < 1e-9, JSON.stringify(offL));
      // Even when there is NO valid step adjacent to the row (0.5 ft invalid)
      // but a valid pocket exists farther out, the guard finds it: start the
      // block just west of the reserved strip so every small eastward shift
      // collides, then expect the jump into the far pocket.
      const dsyn2: any = {
        ...dsyn,
        blockRows: [{
          index: 1, y: 0, autoY: 0, blockCount: 1, moved: false,
          blocks: [{ n: 1, x: 38, y: 0 }],
        }],
      };
      const offR2 = computeRowAlignOffsets(dsyn2, 'right');
      check('[42:gap] row pinned against the obstacle still jumps to the far pocket',
        Math.abs((offR2[1]?.dx ?? 0) - (185 - 38)) < 1e-9, JSON.stringify(offR2));

      // Narrow-pocket guard: a valid pocket NARROWER than the 4 ft coarse
      // stride, sitting strictly between two invalid stretches, must still be
      // found via obstacle-edge candidate seeding. Two reserved strips leave
      // only x∈[182,183] valid east of the near range: strip A (x=160,
      // exclusion |x-160|<22) blocks (138,182) and strip B (x=205) blocks
      // (183,227) — together with the 185 fence limit the far pocket is a
      // 1 ft sliver every 4 ft coarse sample steps over.
      const dsyn3: any = {
        ...dsyn,
        reservedZones: [
          { id: 'rzA', x: 160, y: 0, length: 20, width: 100 },
          { id: 'rzB', x: 205, y: 0, length: 20, width: 100 },
        ],
      };
      const vs3 = (ddx: number) => validateRowShift(
        dsyn3.blockRows[0].blocks, [], geomS as any, fenceS, fenceS, ddx, 0, [], dsyn3.reservedZones) === null;
      check('[42:gap] narrow-pocket fixture sanity: sliver valid, both sides invalid',
        vs3(138) && !vs3(140) && !vs3(181.5) && vs3(182) && vs3(183) && !vs3(183.5) && !vs3(184));
      const offR3 = computeRowAlignOffsets(dsyn3, 'right');
      check('[42:gap] right-align lands in a <4 ft pocket at its exact limit (183)',
        Math.abs((offR3[1]?.dx ?? 0) - 183) < 1e-9, JSON.stringify(offR3));
    }

    // Wide-site performance guard: on a several-thousand-foot span with many
    // rows the coarse-stride guard scan must keep an alignment click visually
    // instant. Rows sit pinned against a reserved strip so the eastward 0.5 ft
    // probe fails immediately and every row exercises the full guard scan —
    // the worst case for the old full-grid walk (~10k validate calls/row).
    {
      const geomW = { halfW: 10, halfD: 10, equipmentMargin: 5, nfpa: null, augGrid: null };
      const spanW = 6000;
      const fenceW = [
        { x: -20, y: -20 }, { x: spanW, y: -20 },
        { x: spanW, y: 2000 }, { x: -20, y: 2000 },
      ];
      const rowsW = Array.from({ length: 12 }, (_, i) => ({
        index: i + 1, y: i * 60, autoY: i * 60, blockCount: 1, moved: false,
        blocks: [{ n: i + 1, x: 38, y: i * 60 }],
      }));
      const dWide: any = {
        blockRows: rowsW,
        rowEditGeom: geomW,
        fence: fenceW,
        boundary: { polygon: fenceW },
        aisles: [],
        reservedZones: rowsW.map((r, i) => ({
          id: `rzw${i}`, x: 60, y: r.y, length: 20, width: 30,
        })),
      };
      const t0 = performance.now();
      const offW = computeRowAlignOffsets(dWide, 'right');
      const ms = performance.now() - t0;
      const eastLimit = spanW - 5 - 10 - 38; // fence margin 5, halfW 10, start 38
      check('[42:wide] all rows still cross their gaps to the true east limit',
        rowsW.every(r => Math.abs((offW[r.index]?.dx ?? 0) - eastLimit) < 1e-9),
        JSON.stringify(offW));
      check('[42:wide] 12-row alignment on a 6000 ft span stays snappy (<250 ms)',
        ms < 250, `${ms.toFixed(1)} ms`);
    }
  }

  // ---------------------------------------------------------------
  // Permit packet: report model derives every number from the compliance /
  // validation / BOM modules (single source of truth), deterministic output,
  // and the PDF's text content (pure section layer) carries the key numbers.
  console.log('\n[43] Permitting & compliance packet');
  {
    const { buildPermitPacketModel, fenceToLotLineFt } = await import('../client/src/lib/nextera/permitReport');
    const { permitPacketSections, buildPermitPdf } = await import('../client/src/lib/nextera/permitPdf');
    const { buildComplianceReport } = await import('../client/src/lib/nextera/complianceReport');
    const { validateDesign } = await import('../client/src/lib/nextera/validateDesign');
    const { buildBomRows } = await import('../client/src/lib/nextera/bom');

    const d = generateSiteDesign(hondo, config, 100, 400, { hotClimate: true, roadMode: 'roads' });
    const now = new Date('2026-01-01T12:00:00');
    const titleBlock = { projectName: 'GOLDEN', location: 'Hondo, TX', drafter: 'QA', revision: 'A', date: '01/01/2026' };
    const opts = { hotClimate: true, titleBlock, now };
    const model = buildPermitPacketModel(d, config, opts);
    const compliance = buildComplianceReport(d, config, opts);
    const byId = (id: string) => compliance.findings.find(f => f.ruleId === id)!;

    // Single source of truth: setback + fire-access rows carry the compliance
    // findings' required/measured text VERBATIM.
    const pairs: Array<[string, string]> = [
      ['kn6-nfpa855', 'BESS container to lot line'],
      ['front-fence', 'Container front wall to fence'],
      ['side-fence', 'Container side wall to fence'],
      ['front-front', 'Container front-to-front separation'],
      ['rear-rear', 'Container rear-to-rear separation'],
      ['side-side', 'Container side-to-side separation'],
      ['pcs-clearance', 'Container to PCS clearance'],
    ];
    for (const [ruleId, item] of pairs) {
      const row = model.nfpaSetbacks.find(r => r.item === item);
      const f = byId(ruleId);
      check(`permit: setback row "${item}" matches compliance ${ruleId} verbatim`,
        !!row && row.requirement === f.required && row.measured === f.measured && row.status === f.status,
        row ? `${row.measured} vs ${f.measured}` : 'row missing');
    }
    const firePairs: Array<[string, string]> = [
      ['kn3-road-width', 'Access road width'],
      ['kn2-inner-radius', 'Inner turning radius'],
      ['kn4-outer-radius', 'Outer turning radius'],
      ['kn5-road-edge', 'Equipment distance to road edge'],
      ['connected-network', 'Connected road network'],
    ];
    for (const [ruleId, item] of firePairs) {
      const row = model.fireAccess.find(r => r.item === item);
      const f = byId(ruleId);
      check(`permit: fire-access row "${item}" matches compliance ${ruleId} verbatim`,
        !!row && row.requirement === f.required && row.measured === f.measured && row.status === f.status,
        row ? `${row.measured} vs ${f.measured}` : 'row missing');
    }

    // Fence-to-lot-line: only measurement unique to the packet — sanity check
    // it directly against the geometry helpers.
    const ftl = fenceToLotLineFt(d.fence, d.boundary.polygon);
    check('permit: fence-to-lot-line measured, positive, >= 25 ft on golden Hondo',
      ftl !== null && ftl >= CLEARANCES.fenceToLotLine - 0.05, `${ftl}`);
    const ftlRow = model.nfpaSetbacks.find(r => r.item === 'Security fence to lot line')!;
    check('permit: fence-to-lot-line row PASS and carries the measured number',
      ftlRow.status === 'PASS' && ftlRow.measured.includes(ftl!.toFixed(2)));

    // Equipment schedule identical to the BOM module output
    check('permit: equipment schedule equals buildBomRows output',
      JSON.stringify(model.equipmentSchedule) === JSON.stringify(buildBomRows(d, config)));

    // Warnings appendix: every engine warning appears verbatim; validation
    // non-pass checks and compliance non-PASS findings are included.
    check('permit: every layout-engine warning appears verbatim in the appendix',
      d.warnings.every(w => model.exceptions.some(e => e.source === 'Layout engine' && e.text === w)),
      `${d.warnings.length} warnings`);
    const val = validateDesign(d, { titleBlock });
    const nonPass = val.checks.filter(c => c.status !== 'pass');
    check('permit: every non-pass validation check appears in the appendix',
      nonPass.every(c => model.exceptions.some(e => e.source === 'Design validation' && e.text.startsWith(c.label))));
    const nonPassFindings = compliance.findings.filter(f => f.status !== 'PASS');
    check('permit: every non-PASS compliance finding appears in the appendix',
      nonPassFindings.every(f => model.exceptions.some(e => e.source === 'Compliance checklist' && e.text.includes(f.checklistItem))));
    check('permit: compliance summary counts match the compliance report',
      model.compliance.passCount === compliance.passCount &&
      model.compliance.warnCount === compliance.warnCount &&
      model.compliance.failCount === compliance.failCount &&
      model.compliance.total === compliance.findings.length);

    // Site data straight from the design
    check('permit: site data matches the design (acreage, counts, rating)',
      Math.abs(model.site.parcelAreaAcres - hondo.areaAcres) < 1e-9 &&
      model.site.containerCount === d.equipment.filter(e => e.kind === 'bess').length &&
      model.site.inverterCount === d.equipment.filter(e => e.kind === 'inverter').length &&
      model.project.achievedMW === d.achievedMW);

    // Determinism: same design + fixed now → byte-identical model
    const model2 = buildPermitPacketModel(
      generateSiteDesign(hondo, config, 100, 400, { hotClimate: true, roadMode: 'roads' }),
      config, opts);
    check('permit: model is deterministic (built twice, identical JSON)',
      JSON.stringify(model) === JSON.stringify(model2));

    // PDF content layer: the exact text the PDF renders
    const sections = permitPacketSections(model);
    check('permit: packet has the 7 required sections in order',
      sections.map(s => s.id).join(',') ===
      'site-data,nfpa-setbacks,fire-access,reserved-areas,equipment-schedule,trench-sections,exceptions');
    const allText = sections.map(s => [s.title, s.intro, ...s.rows.flat()].join('\n')).join('\n');
    check('permit: PDF text carries the NFPA 855 measured distance verbatim',
      allText.includes(byId('kn6-nfpa855').measured));
    check('permit: PDF text carries the achieved rating',
      allText.includes(`${d.achievedMW.toFixed(1)} MW / ${d.achievedMWh.toFixed(0)} MWh`));
    check('permit: PDF text carries road width + PCS clearance requirements',
      allText.includes(byId('kn3-road-width').required) && allText.includes(byId('pcs-clearance').required));
    check('permit: PDF text carries the BOM container line',
      allText.includes('LG JF2 DCLINK 5.1 CONTAINER (LG P/N EPNLTF_1200A/C, 5.1 MWH EA)'));
    check('permit: section text is deterministic',
      JSON.stringify(sections) === JSON.stringify(permitPacketSections(model2)));

    // Tampered design: NFPA violation must surface in the packet rows AND the
    // exceptions appendix (numbers can never silently drift from the drawing).
    const tamper = structuredClone(d);
    const c0 = tamper.equipment.find(e => e.kind === 'bess')!;
    const bp0 = tamper.boundary.polygon[0];
    c0.x = bp0.x; c0.y = bp0.y;
    tamper.warnings = tamper.warnings.filter(w => !w.includes('NFPA 855'));
    const tamperModel = buildPermitPacketModel(tamper, config, opts);
    const tamperRow = tamperModel.nfpaSetbacks.find(r => r.item === 'BESS container to lot line')!;
    check('permit: NFPA violation flips the setback row to FAIL',
      tamperRow.status === 'FAIL', tamperRow.measured);
    check('permit: NFPA violation appears in the exceptions appendix',
      tamperModel.exceptions.some(e => e.source === 'Compliance checklist' && e.severity === 'FAIL' && e.text.includes('Key note 6')));

    // Full PDF builds headlessly and has cover + TOC + one page per section
    const pdf = buildPermitPdf(model, d);
    check('permit: PDF builds with cover + TOC + 6 section pages (>= 8 pages)',
      pdf.getNumberOfPages() >= 8, `${pdf.getNumberOfPages()} pages`);

    // ---- Rough-grading (earthwork) section: optional, screening-labeled ----
    {
      const T = await import('../client/src/lib/nextera/terrain');
      // Synthetic 2% ramp covering the fence bbox + margin (deterministic).
      const fxs = d.fence.map(p => p.x), fys = d.fence.map(p => p.y);
      const rect = {
        minX: Math.min(...fxs) - 500, maxX: Math.max(...fxs) + 500,
        minY: Math.min(...fys) - 500, maxY: Math.max(...fys) + 500,
      };
      const size = 96;
      const valuesFt: number[] = [];
      for (let r = 0; r < size; r++) {
        for (let c = 0; c < size; c++) {
          const x = rect.minX + ((c + 0.5) / size) * (rect.maxX - rect.minX);
          valuesFt.push(1200 + 0.02 * (x - rect.minX));
        }
      }
      const grid = {
        width: size, height: size,
        bounds: { west: 0, east: 1, south: 0, north: 1 },
        valuesFt, source: 'USGS 3DEP (1/3 arc-second)', resolutionM: 10, noDataCount: 3,
      };
      const cutFill = T.computeCutFill(grid, rect, d.fence)!;
      const slope = T.computeSlopeGrid(grid, rect);
      const steep = T.findSteepZones(slope, rect,
        { equipment: d.equipment, roads: d.roads, aisles: d.aisles }, 1); // 1% threshold → 2% ramp flags items
      const gtTie = T.computeGradingTieIn(grid, rect, d.fence, cutFill.padElevationFt)!;
      const earthwork = {
        cutFill, steep,
        source: grid.source, resolutionM: grid.resolutionM, noDataCount: grid.noDataCount,
        tieIn: { maxCutFt: gtTie.maxCutFt, maxFillFt: gtTie.maxFillFt, slopeRatio: gtTie.slopeRatio },
      };
      const ewModel = buildPermitPacketModel(d, config, { ...opts, earthwork });

      // Absent: model carries null and the section list is unchanged (checked above)
      check('permit: earthwork is null when no elevation data is provided',
        model.earthwork === null);

      const ewSections = permitPacketSections(ewModel);
      check('permit: earthwork section inserted before the exceptions appendix',
        ewSections.map(s => s.id).join(',') ===
        'site-data,nfpa-setbacks,fire-access,reserved-areas,equipment-schedule,trench-sections,earthwork,exceptions');
      const ew = ewSections.find(s => s.id === 'earthwork')!;
      check('permit: earthwork section renumbers to 7 and appendix to 8',
        ew.title === '7. Rough Grading & Earthwork — Screening Only' &&
        ewSections[7].title.startsWith('8. Warnings & Exceptions'));
      check('permit: earthwork intro carries the screening-only disclaimer',
        ew.intro.includes('SCREENING ONLY — NOT FOR CONSTRUCTION'));
      const ewText = [ew.intro, ...ew.rows.flat()].join('\n');
      check('permit: earthwork text carries pad elevation + cut/fill/net CY',
        ewText.includes(`${cutFill.padElevationFt.toFixed(1)} ft`) &&
        ewText.includes(`${Math.round(cutFill.cutCY).toLocaleString('en-US')} CY`) &&
        ewText.includes(`${Math.round(cutFill.fillCY).toLocaleString('en-US')} CY`) &&
        ewText.includes(`${Math.round(Math.abs(cutFill.netCY)).toLocaleString('en-US')} CY`));
      check('permit: earthwork text carries max cut/fill at the pad edge + tie-in slope',
        gtTie.maxCutFt > 0 && gtTie.maxFillFt > 0 &&
        ewText.includes(`${gtTie.maxCutFt.toFixed(1)} ft below existing ground at the fence line`) &&
        ewText.includes(`${gtTie.maxFillFt.toFixed(1)} ft above existing ground at the fence line`) &&
        ewText.includes('3:1 (H:V) daylight slopes'),
        `cut ${gtTie.maxCutFt.toFixed(1)} fill ${gtTie.maxFillFt.toFixed(1)}`);
      check('permit: earthwork text carries the data source + no-data disclosure',
        ewText.includes('USGS 3DEP (1/3 arc-second)') && ewText.includes('3 no-data cell(s) filled'));
      check('permit: earthwork text carries the steep-zone findings vs threshold',
        steep.items.length > 0 &&
        ewText.includes('1% existing grade') &&
        steep.items.every(i => ewText.includes(`${i.label} — ${i.slopePct.toFixed(1)}% grade`)));
      check('permit: earthwork section text is deterministic',
        JSON.stringify(ewSections) ===
        JSON.stringify(permitPacketSections(buildPermitPacketModel(d, config, { ...opts, earthwork }))));

      // Flat-ground / no-steep phrasing + no-data-free disclosure
      const flatSteep = { thresholdPct: 8, maxSlopePct: 0.4, items: [] };
      const ewFlat = permitPacketSections(buildPermitPacketModel(d, config, {
        ...opts, earthwork: { ...earthwork, steep: flatSteep, noDataCount: 0 },
      })).find(s => s.id === 'earthwork')!;
      const flatText = ewFlat.rows.flat().join('\n');
      check('permit: earthwork no-steep + full-coverage phrasing',
        flatText.includes('None — all checked equipment and roads sit on existing grades at or below 8%') &&
        flatText.includes('Full elevation coverage — no no-data cells'));

      // PDF builds with the extra section page
      const ewPdf = buildPermitPdf(ewModel, d);
      check('permit: earthwork PDF gains at least one page over the base packet',
        ewPdf.getNumberOfPages() > pdf.getNumberOfPages(),
        `${ewPdf.getNumberOfPages()} vs ${pdf.getNumberOfPages()}`);

      // --- Contour figure in the earthwork section -----------------------
      const contours = T.contoursForDxf(grid, d.boundary.origin, 0);
      check('permit: test grid yields contours with minor + major lines',
        !!contours && contours.lines.length > 0 &&
        contours.lines.some(l => l.major) && contours.lines.some(l => !l.major));
      const ewCModel = buildPermitPacketModel(d, config, {
        ...opts, earthwork: { ...earthwork, contours },
      });
      check('permit: earthwork model carries the contour set verbatim',
        ewCModel.earthwork?.contours === contours);
      check('permit: contour figure never changes the packet section text',
        JSON.stringify(permitPacketSections(ewCModel)) === JSON.stringify(ewSections));
      // Structural twin ([69] pattern): deep-compare so any section field the
      // contour opt-in leaks is named structurally, not just a byte mismatch.
      check('permit: contour-figure sections deep-equal the no-contour sections',
        (await import('node:util')).isDeepStrictEqual(permitPacketSections(ewCModel), ewSections));
      const ewCPdf = buildPermitPdf(ewCModel, d);
      check('permit: earthwork PDF with contour figure builds',
        ewCPdf.getNumberOfPages() >= ewPdf.getNumberOfPages(),
        `${ewCPdf.getNumberOfPages()} vs ${ewPdf.getNumberOfPages()}`);
      // Deterministic output: identical inputs → byte-identical PDF
      const bytesA = buildPermitPdf(ewCModel, d).output();
      const bytesB = buildPermitPdf(ewCModel, d).output();
      check('permit: contour-figure PDF is deterministic (byte-identical rebuild)',
        bytesA === bytesB);
      // The figure is drawn (PDF grows vs the same packet without contours)
      check('permit: contour figure adds vector content to the PDF',
        bytesA.length > buildPermitPdf(ewModel, d).output().length,
        `${bytesA.length} vs ${buildPermitPdf(ewModel, d).output().length}`);
      // Cover key map: contour underlay drawn behind the site line work when
      // terrain is loaded (isolated via drawSitePlanThumbnail itself)
      {
        const { drawSitePlanThumbnail } = await import('../client/src/lib/nextera/permitPdf');
        const { jsPDF } = await import('jspdf');
        const mkDoc = () => {
          const doc = new jsPDF({ orientation: 'portrait', unit: 'pt', format: 'letter' });
          doc.setCreationDate(new Date('2026-01-01T00:00:00Z'));
          (doc as any).setFileId('00000000000000000000000000000000');
          return doc;
        };
        const box = { x: 54, y: 268, w: 504, h: 330 };
        const plain = mkDoc(); drawSitePlanThumbnail(plain, d, box);
        const withC = mkDoc(); drawSitePlanThumbnail(withC, d, box, contours);
        const nullC = mkDoc(); drawSitePlanThumbnail(nullC, d, box, null);
        check('permit: cover key map gains contour underlay when contours provided',
          withC.output().length > plain.output().length,
          `${withC.output().length} vs ${plain.output().length}`);
        check('permit: cover key map without contours is byte-identical to pre-contour output',
          nullC.output() === plain.output());
        check('permit: cover key map contour overlay is deterministic',
          withC.output() === (() => { const r = mkDoc(); drawSitePlanThumbnail(r, d, box, contours); return r.output(); })());
      }

      // No-contours earthwork (flat site / no data): packet unchanged vs
      // pre-contour behavior — same page count as the plain earthwork PDF
      const ewNullC = buildPermitPdf(buildPermitPacketModel(d, config, {
        ...opts, earthwork: { ...earthwork, contours: null },
      }), d);
      check('permit: null contours leaves the earthwork packet unchanged',
        ewNullC.getNumberOfPages() === ewPdf.getNumberOfPages() &&
        ewNullC.output().length === buildPermitPdf(ewModel, d).output().length);

      // WYSIWYG guarantee: DXF byte-identical with/without earthwork in play
      const dxfA = buildDesignDxfString(d, 'PERMIT-EW', config);
      buildPermitPdf(ewModel, d);
      const dxfB = buildDesignDxfString(d, 'PERMIT-EW', config);
      check('permit: DXF is byte-identical with the earthwork section in play', dxfA === dxfB);
    }

    // ---- Grounding screening section: opt-in, quantities verbatim ----
    {
      const gplan = buildGroundingPlan(d)!;
      check('permit: grounding plan builds for the packet test design', !!gplan);

      // Off by default: model carries null, sections + PDF bytes unchanged
      check('permit: grounding is null when not opted in', model.grounding === null);
      const baseBytes = buildPermitPdf(model, d).output();
      const nullGBytes = buildPermitPdf(
        buildPermitPacketModel(d, config, { ...opts, grounding: null }), d).output();
      check('permit: explicit null grounding keeps the packet byte-identical',
        baseBytes === nullGBytes);
      // Structural twin ([69] pattern): deep-compare the models so a leaked
      // field is named structurally, not just flagged as a PDF byte mismatch.
      check('permit: explicit-null grounding model deep-equals the base model',
        (await import('node:util')).isDeepStrictEqual(
          buildPermitPacketModel(d, config, { ...opts, grounding: null }), model));
      const sectionsNoG = permitPacketSections(model);
      check('permit: no grounding section without opt-in',
        !sectionsNoG.some(s => s.id === 'grounding'));

      // Opt-in: section appears before the exceptions appendix, renumbered
      const gModel = buildPermitPacketModel(d, config, { ...opts, grounding: gplan });
      check('permit: grounding model carries the plan verbatim', gModel.grounding === gplan);
      const gSections = permitPacketSections(gModel);
      check('permit: grounding section inserted before the exceptions appendix',
        gSections.map(s => s.id).join(',') ===
        'site-data,nfpa-setbacks,fire-access,reserved-areas,equipment-schedule,trench-sections,grounding,exceptions');
      const gSec = gSections.find(s => s.id === 'grounding')!;
      check('permit: grounding section renumbers to 7 and appendix to 8',
        gSec.title === '7. Grounding System — Screening Takeoff' &&
        gSections[7].title.startsWith('8. Warnings & Exceptions'));
      check('permit: grounding intro carries the screening-only disclaimer',
        gSec.intro.includes('SCREENING ONLY — NOT FOR CONSTRUCTION') &&
        gSec.intro.includes('IEEE 80'));
      const gText = gSec.rows.flat().join('\n');
      const gs = gplan.summary;
      check('permit: grounding text carries loop LF, rod count/spacing, taps and total conductor',
        gText.includes(`${Math.round(gs.loopLengthFt).toLocaleString('en-US')} LF`) &&
        gText.includes(`${gs.rodCount} rods`) &&
        gText.includes(`max ${gs.rodSpacingFt} ft spacing`) &&
        gText.includes(`${gs.tapCount} taps`) &&
        gText.includes(`${Math.round(gs.totalConductorFt).toLocaleString('en-US')} LF`) &&
        gText.includes(`${(gs.gridAreaSqFt / 43560).toFixed(2)} acres`));
      check('permit: grounding section text is deterministic',
        JSON.stringify(gSections) ===
        JSON.stringify(permitPacketSections(buildPermitPacketModel(d, config, { ...opts, grounding: buildGroundingPlan(d)! }))));

      // PDF: extra section page + figure, deterministic bytes
      const gPdf = buildPermitPdf(gModel, d);
      check('permit: grounding PDF gains at least one page over the base packet',
        gPdf.getNumberOfPages() > pdf.getNumberOfPages(),
        `${gPdf.getNumberOfPages()} vs ${pdf.getNumberOfPages()}`);
      const gBytesA = buildPermitPdf(gModel, d).output();
      const gBytesB = buildPermitPdf(gModel, d).output();
      check('permit: grounding PDF is deterministic (byte-identical rebuild)',
        gBytesA === gBytesB);
      check('permit: grounding figure adds vector content beyond the table page',
        gBytesA.length > baseBytes.length,
        `${gBytesA.length} vs ${baseBytes.length}`);

      // Figure draws directly (isolated) and is deterministic
      {
        const { drawGroundingFigure } = await import('../client/src/lib/nextera/permitPdf');
        const { jsPDF } = await import('jspdf');
        const mkDoc = () => {
          const doc = new jsPDF({ orientation: 'portrait', unit: 'pt', format: 'letter' });
          doc.setCreationDate(new Date('2026-01-01T00:00:00Z'));
          (doc as any).setFileId('00000000000000000000000000000000');
          return doc;
        };
        const box = { x: 54, y: 100, w: 504, h: 500 };
        const blank = mkDoc().output();
        const fA = mkDoc(); drawGroundingFigure(fA, gplan, d, box);
        const fB = mkDoc(); drawGroundingFigure(fB, gplan, d, box);
        check('permit: drawGroundingFigure emits vector content',
          fA.output().length > blank.length);
        check('permit: drawGroundingFigure is deterministic',
          fA.output() === fB.output());
      }

      // WYSIWYG guarantee: DXF byte-identical with the grounding section in play
      const dxfA2 = buildDesignDxfString(d, 'PERMIT-GND', config);
      buildPermitPdf(gModel, d);
      const dxfB2 = buildDesignDxfString(d, 'PERMIT-GND', config);
      check('permit: DXF is byte-identical with the grounding section in play', dxfA2 === dxfB2);
    }
  }

  // ---------------------------------------------------------------
  // Multi-scenario comparison: deterministic per-objective picks from the
  // seeded optimizer pool, scorecards consistent with the design geometry,
  // and applying a scenario round-trips through the engine + DXF export.
  console.log('\n[44] Multi-scenario layout comparison');
  {
    const { compareScenarios, pickScenarios, scorecardOf, SCENARIO_DEFS, roadRegionAreaSqFt, fencePerimeterFt } =
      await import('../client/src/lib/nextera/scenarios');
    const { optimizeLayout } = await import('../client/src/lib/nextera/optimizer');
    const { handleScenarios } = await import('../client/src/lib/nextera/designWorkerCore');

    const baseOpts = { hotClimate: true, roadMode: 'roads' as const };
    const r1 = compareScenarios(hondo, config, 100, 400, baseOpts, 1);
    const r2 = compareScenarios(hondo, config, 100, 400, baseOpts, 1);

    check('[44] produces one scenario per objective (4)',
      r1.scenarios.length === SCENARIO_DEFS.length &&
      r1.scenarios.map(s => s.objective).join(',') === 'capacity,cabling,civil,balanced');
    check('[44] deterministic: same inputs + seed → identical candidate ids and scorecards',
      JSON.stringify(r1.scenarios.map(s => [s.objective, s.candidate.id, s.scorecard])) ===
      JSON.stringify(r2.scenarios.map(s => [s.objective, s.candidate.id, s.scorecard])));

    const opt = optimizeLayout(hondo, config, 100, 400, baseOpts, 1);
    check('[44] optimizer exposes the full accepted pool (>= top candidates)',
      opt.allCandidates.length >= opt.candidates.length && opt.allCandidates.length > 0,
      `${opt.allCandidates.length} accepted`);
    const allCards = opt.allCandidates.map(c => scorecardOf(c.design));
    const byObj = (o: string) => r1.scenarios.find(s => s.objective === o)!;

    check('[44] capacity pick has the max MWh across the accepted pool',
      byObj('capacity').scorecard.achievedMWh === Math.max(...allCards.map(c => c.achievedMWh)));
    check('[44] cabling pick has the min cable+trench across the accepted pool',
      byObj('cabling').scorecard.cableFt + byObj('cabling').scorecard.trenchFt ===
      Math.min(...allCards.map(c => c.cableFt + c.trenchFt)));
    check('[44] civil pick has the min road area across the accepted pool',
      byObj('civil').scorecard.roadAreaSqFt === Math.min(...allCards.map(c => c.roadAreaSqFt)));
    check('[44] every scenario keeps at least the pristine baseline block count',
      r1.scenarios.every(s => s.scorecard.blockCount >= r1.baselineBlocks), `baseline ${r1.baselineBlocks}`);
    check('[44] sameAs flags only ever point at an earlier objective\'s identical pick',
      r1.scenarios.every(s => s.sameAs === null ||
        r1.scenarios.find(x => x.objective === s.sameAs)!.candidate.id === s.candidate.id));
    check('[44] pickScenarios is pure/deterministic on the same pool',
      JSON.stringify(pickScenarios(opt.allCandidates).map(s => s.candidate.id)) ===
      JSON.stringify(r1.scenarios.map(s => s.candidate.id)));

    // Scorecard consistency against the design geometry
    for (const s of r1.scenarios) {
      const d = s.candidate.design;
      const sc = s.scorecard;
      const cableFt = d.cables.reduce((sum, c) => {
        let l = 0;
        for (let i = 1; i < c.pts.length; i++) l += Math.hypot(c.pts[i].x - c.pts[i - 1].x, c.pts[i].y - c.pts[i - 1].y);
        return sum + l;
      }, 0);
      check(`[44] ${s.objective}: scorecard matches design (MW/MWh/blocks/cable/warnings)`,
        sc.achievedMW === d.achievedMW && sc.achievedMWh === d.achievedMWh &&
        sc.blockCount === d.blocksPlaced && Math.abs(sc.cableFt - cableFt) < 1e-6 &&
        sc.warningCount === d.warnings.length &&
        sc.trenchFt === (d.trench ? d.trench.yTop - d.trench.yBottom : 0) &&
        sc.roadAreaSqFt === roadRegionAreaSqFt(d) &&
        sc.fencePerimeterFt === fencePerimeterFt(d));
      check(`[44] ${s.objective}: road area positive and plausible (< fence area)`,
        sc.roadAreaSqFt > 0 && sc.roadAreaSqFt < sc.fenceAcres * 43560,
        `${sc.roadAreaSqFt.toFixed(0)} sqft vs fence ${(sc.fenceAcres * 43560).toFixed(0)}`);
    }

    // Apply round-trip: regenerating from a scenario's params reproduces the
    // scenario design (the store apply path calls generateSiteDesign with
    // exactly these knobs) and the result exports to DXF cleanly.
    const cap = byObj('capacity');
    const p = cap.candidate.params;
    const regen = generateSiteDesign(hondo, config, 100, 400, {
      ...baseOpts,
      arrangement: p.arrangement,
      latticeShift: p.latticeShift,
      gateEdge: p.gateEdge,
      constraints: p.trenchX !== null ? { trenchX: p.trenchX } : undefined,
    });
    check('[44] applying scenario params reproduces the scenario design',
      regen.blocksPlaced === cap.scorecard.blockCount &&
      regen.achievedMWh === cap.scorecard.achievedMWh &&
      JSON.stringify(regen.fence) === JSON.stringify(cap.candidate.design.fence));
    const dxf = buildDesignDxfString(regen, 'SCENARIO-RT', config);
    check('[44] applied scenario design exports to DXF (AC1015, has entities)',
      dxf.includes('AC1015') && dxf.includes('ENTITIES') && dxf.length > 10000, `${dxf.length} bytes`);

    // Worker core path: same request → same scenarios (worker == main thread),
    // and cancellation returns a well-formed empty result.
    const req = { kind: 'scenarios' as const, boundary: hondo, configId: config.id, targetMW: 100, targetMWh: 400, baseOptions: baseOpts, seed: 1 };
    const viaWorkerCore = handleScenarios(req);
    check('[44] worker-core path is byte-identical to the direct path',
      JSON.stringify(viaWorkerCore.scenarios.map(s => [s.objective, s.candidate.id, s.scorecard])) ===
      JSON.stringify(r1.scenarios.map(s => [s.objective, s.candidate.id, s.scorecard])));
    const cancelledRes = handleScenarios(req, undefined, () => true);
    check('[44] cancellation yields a well-formed empty result',
      cancelledRes.cancelled && cancelledRes.scenarios.length === 0);

    // Empty pool edge case
    check('[44] pickScenarios([]) returns no scenarios', pickScenarios([]).length === 0);
  }

  // ---------------------------------------------------------------
  // Terrain awareness: elevation grid math, slope, cut/fill screening and
  // steep-zone validation — all on synthetic grids (deterministic, offline).
  // Also proves the WYSIWYG guarantee: DXF output is byte-identical with and
  // without terrain analysis in play.
  console.log('\n[45] Terrain awareness (elevation, slope, cut/fill)');
  {
    const T = await import('../client/src/lib/nextera/terrain');
    const { validateDesign } = await import('../client/src/lib/nextera/validateDesign');

    const d45 = generateSiteDesign(hondo, config, 50, 200, { hotClimate: true, roadMode: 'roads' as const });
    const origin = hondo.origin;
    const ftPerLon = 364000 * Math.cos((origin.lat * Math.PI) / 180);

    // Coverage bbox: contains the parcel bbox plus a positive margin
    const bbox = T.terrainCoverageBbox(hondo.polygon, origin);
    const pxs = hondo.polygon.map(p => p.x), pys = hondo.polygon.map(p => p.y);
    check('[45] coverage bbox strictly contains the parcel bbox',
      (bbox.west - origin.lon) * ftPerLon < Math.min(...pxs) &&
      (bbox.east - origin.lon) * ftPerLon > Math.max(...pxs) &&
      (bbox.south - origin.lat) * 364000 < Math.min(...pys) &&
      (bbox.north - origin.lat) * 364000 > Math.max(...pys));

    // Synthetic grid builder: rect in local feet -> WGS84 bounds via the
    // inverse of terrainLocalRect, values from z(x, y) at cell centers.
    const makeGrid = (rect: { minX: number; maxX: number; minY: number; maxY: number }, n: number, z: (x: number, y: number) => number) => {
      const bounds = {
        west: origin.lon + rect.minX / ftPerLon,
        east: origin.lon + rect.maxX / ftPerLon,
        south: origin.lat + rect.minY / 364000,
        north: origin.lat + rect.maxY / 364000,
      };
      const cellX = (rect.maxX - rect.minX) / n, cellY = (rect.maxY - rect.minY) / n;
      const valuesFt: number[] = [];
      for (let r = 0; r < n; r++) {
        const y = rect.maxY - (r + 0.5) * cellY; // row 0 = north
        for (let c = 0; c < n; c++) valuesFt.push(z(rect.minX + (c + 0.5) * cellX, y));
      }
      return {
        grid: { width: n, height: n, bounds, valuesFt, source: 'synthetic', resolutionM: 10, noDataCount: 0 },
        rect,
      };
    };

    // Round-trip: terrainLocalRect inverts the bounds construction
    const rt = makeGrid({ minX: -500, maxX: 1500, minY: -400, maxY: 1600, }, 32, () => 100);
    const rtRect = T.terrainLocalRect(rt.grid, origin);
    check('[45] terrainLocalRect round-trips the local rect (<0.01 ft error)',
      Math.abs(rtRect.minX - -500) < 0.01 && Math.abs(rtRect.maxX - 1500) < 0.01 &&
      Math.abs(rtRect.minY - -400) < 0.01 && Math.abs(rtRect.maxY - 1600) < 0.01);

    // gridFromApi: null -> NaN with count; all-null throws
    const api = { width: 2, height: 2, bounds: rt.grid.bounds, valuesFt: [100, null, 102, 103] as (number | null)[], source: 's', resolutionM: 10 };
    const g0 = T.gridFromApi(api);
    check('[45] gridFromApi maps nulls to NaN and counts them',
      g0.noDataCount === 1 && Number.isNaN(g0.valuesFt[1]) && g0.valuesFt[0] === 100);
    let threw = false;
    try { T.gridFromApi({ ...api, valuesFt: [null, null, null, null] }); } catch { threw = true; }
    check('[45] gridFromApi throws on all-no-data (never fakes elevation)', threw);

    // fillNoData: fills every NaN with a nearby finite value, keeps finite
    const filled = T.fillNoData(g0);
    check('[45] fillNoData removes all NaN, preserves finite cells + count',
      filled.valuesFt.every(v => Number.isFinite(v)) && filled.valuesFt[0] === 100 &&
      filled.valuesFt[1] === 100 && filled.noDataCount === 1 && Number.isNaN(g0.valuesFt[1]));

    // Bilinear sampling is exact on a planar surface (interior points)
    const plane = makeGrid({ minX: 0, maxX: 1000, minY: 0, maxY: 1000 }, 64, (x, y) => 50 + 0.02 * x + 0.01 * y);
    const sErr = Math.abs(T.sampleElevationFt(plane.grid, plane.rect, 437.3, 612.9) - (50 + 0.02 * 437.3 + 0.01 * 612.9));
    check('[45] bilinear sample exact on a planar grid', sErr < 1e-9, `err ${sErr}`);
    check('[45] sampling clamps outside the rect (no NaN)',
      Number.isFinite(T.sampleElevationFt(plane.grid, plane.rect, -5000, 9000)));

    // Slope grid: 2%/1% plane -> hypot = sqrt(5)% everywhere (interior)
    const slope = T.computeSlopeGrid(plane.grid, plane.rect);
    const mid = slope.slopePct[32 * 64 + 32];
    check('[45] slope of a 2%+1% plane is sqrt(5)% in the interior',
      Math.abs(mid - 100 * Math.hypot(0.02, 0.01)) < 0.01, `${mid.toFixed(3)}%`);
    const flat = T.computeSlopeGrid(makeGrid(plane.rect, 64, () => 123).grid, plane.rect);
    check('[45] flat grid has zero slope everywhere', flat.maxSlopePct === 0);

    // Cut/fill: ramp over a square fence -> pad = mid elevation, cut == fill
    const ramp = makeGrid({ minX: 0, maxX: 1000, minY: 0, maxY: 1000 }, 64, x => 0.04 * x);
    const fence45 = [{ x: 200, y: 200 }, { x: 800, y: 200 }, { x: 800, y: 800 }, { x: 200, y: 800 }];
    const cf = T.computeCutFill(ramp.grid, ramp.rect, fence45)!;
    check('[45] cut/fill pad sits at the ramp midpoint elevation (±0.5 ft)',
      Math.abs(cf.padElevationFt - 0.04 * 500) < 0.5, `pad ${cf.padElevationFt.toFixed(2)}`);
    check('[45] symmetric ramp balances: cut ≈ fill, |net| < 2% of moved',
      cf.cutCY > 0 && cf.fillCY > 0 && Math.abs(cf.netCY) < 0.02 * (cf.cutCY + cf.fillCY),
      `cut ${cf.cutCY.toFixed(0)} fill ${cf.fillCY.toFixed(0)} net ${cf.netCY.toFixed(0)}`);
    check('[45] cut/fill area ≈ fence area (±5%)',
      Math.abs(cf.areaSqFt - 600 * 600) < 0.05 * 600 * 600, `${cf.areaSqFt.toFixed(0)} sqft`);
    const cfFlat = T.computeCutFill(makeGrid(ramp.rect, 64, () => 77).grid, ramp.rect, fence45)!;
    check('[45] flat ground needs zero earthwork', cfFlat.cutCY === 0 && cfFlat.fillCY === 0);
    check('[45] computeCutFill is deterministic',
      JSON.stringify(T.computeCutFill(ramp.grid, ramp.rect, fence45)) === JSON.stringify(cf));
    check('[45] degenerate fence returns null', T.computeCutFill(ramp.grid, ramp.rect, [{ x: 0, y: 0 }]) === null);

    // Steep zones over the real Hondo design on a synthetic 10% ramp:
    // every checked block is flagged at a 5% threshold, none on flat ground.
    const fxs = d45.fence.map(p => p.x), fys = d45.fence.map(p => p.y);
    const dRect = {
      minX: Math.min(...fxs) - 500, maxX: Math.max(...fxs) + 500,
      minY: Math.min(...fys) - 500, maxY: Math.max(...fys) + 500,
    };
    const steepG = makeGrid(dRect, 96, x => 0.10 * x);
    const steepSlope = T.computeSlopeGrid(steepG.grid, dRect);
    const designShape = { equipment: d45.equipment, roads: d45.roads, aisles: d45.aisles };
    const rep = T.findSteepZones(steepSlope, dRect, designShape, 5);
    const nChecked = d45.equipment.filter(e => e.kind === 'bess' || e.kind === 'inverter').length + d45.roads.length + d45.aisles.length;
    check('[45] 10% ramp flags every checked block/road at 5% threshold',
      rep.items.length === nChecked && rep.maxSlopePct > 5, `${rep.items.length}/${nChecked}`);
    const repFlat = T.findSteepZones(T.computeSlopeGrid(makeGrid(dRect, 96, () => 42).grid, dRect), dRect, designShape, 5);
    check('[45] flat ground flags nothing', repFlat.items.length === 0 && repFlat.maxSlopePct === 0);

    // Validation wiring: warn when steep items exist, pass when none, and
    // the terrain check is absent when no elevation data is provided.
    const vWarn = validateDesign(d45, { terrain: rep });
    const vPass = validateDesign(d45, { terrain: repFlat });
    const vNone = validateDesign(d45, {});
    const tc = (r: typeof vWarn) => r.checks.find(c => c.id === 'terrain');
    check('[45] validateDesign: steep zones -> terrain warn with labels',
      tc(vWarn)?.status === 'warn' && (tc(vWarn)?.detail.includes('%') ?? false));
    check('[45] validateDesign: no steep zones -> terrain pass', tc(vPass)?.status === 'pass');
    check('[45] validateDesign: no terrain data -> no terrain check', tc(vNone) === undefined);

    // Color ramp endpoints: green at 0, red at/after max
    const c0 = T.slopeRampColor(0, 10), c1 = T.slopeRampColor(10, 10), cOver = T.slopeRampColor(25, 10);
    check('[45] slope ramp: green at 0 -> red at max (clamped beyond)',
      c0[1] > c0[0] && c1[0] > c1[1] && JSON.stringify(c1) === JSON.stringify(cOver));

    // WYSIWYG guarantee: DXF built before and after terrain analysis is
    // byte-identical — terrain never touches export geometry.
    const dxfA = buildDesignDxfString(d45, 'TERRAIN-RT', config);
    T.computeCutFill(steepG.grid, dRect, d45.fence);
    T.findSteepZones(steepSlope, dRect, designShape, 5);
    const dxfB = buildDesignDxfString(d45, 'TERRAIN-RT', config);
    check('[45] DXF is byte-identical with terrain analysis in play', dxfA === dxfB, `${dxfA.length} bytes`);

    // -----------------------------------------------------------------
    console.log('\n[46] Elevation contour lines (marching squares, preview only)');

    // Auto interval: 1/2/5 ladder aiming for <= 16 contours
    check('[46] auto interval: 6 ft relief -> 0.5 ft', T.pickContourInterval(100, 106) === 0.5);
    check('[46] auto interval: 30 ft relief -> 2 ft', T.pickContourInterval(100, 130) === 2);
    check('[46] auto interval: 120 ft relief -> 10 ft', T.pickContourInterval(0, 120) === 10);
    check('[46] auto interval: zero relief -> smallest step', T.pickContourInterval(50, 50) === 0.5);

    // Planar ramp east-west: contours are straight north-south lines at
    // evenly spaced x positions; z = 0.04x on [0,1000] -> 40 ft relief.
    const ramp46 = makeGrid({ minX: 0, maxX: 1000, minY: 0, maxY: 1000 }, 64, x => 0.04 * x);
    const cs = T.computeContours(ramp46.grid, ramp46.rect, 5);
    check('[46] ramp: one polyline per 5 ft level', cs.lines.length === 7 && cs.intervalFt === 5,
      `${cs.lines.length} lines`);
    const lvl20 = cs.lines.find(l => l.elevFt === 20)!;
    const xs20 = lvl20.pts.map(p => p.x);
    check('[46] ramp: the 20 ft contour sits at x = 500 (±1 ft), spanning north-south',
      Math.max(...xs20) - Math.min(...xs20) < 2 && Math.abs(xs20[0] - 500) < 1 &&
      Math.max(...lvl20.pts.map(p => p.y)) - Math.min(...lvl20.pts.map(p => p.y)) > 900);
    check('[46] ramp: every contour is a single joined open polyline',
      cs.lines.every(l => !l.closed && l.pts.length > 10));
    check('[46] major flags every 5th level (multiples of 25 ft)',
      cs.lines.every(l => l.major === (Math.round(l.elevFt / 5) % 5 === 0)) &&
      cs.majorEveryFt === 25);

    // Cone hill: contours are closed rings, shorter at higher elevation
    const cone = makeGrid({ minX: 0, maxX: 1000, minY: 0, maxY: 1000 }, 96,
      (x, y) => Math.max(0, 60 - 0.2 * Math.hypot(x - 500, y - 500)));
    const csCone = T.computeContours(cone.grid, cone.rect, 10);
    const rings = csCone.lines.filter(l => l.elevFt >= 10 && l.elevFt <= 50);
    const ringLen = (l: (typeof rings)[0]) => {
      let s = 0;
      for (let i = 1; i < l.pts.length; i++) s += Math.hypot(l.pts[i].x - l.pts[i - 1].x, l.pts[i].y - l.pts[i - 1].y);
      return s;
    };
    check('[46] cone: contours at 10..50 ft are closed rings',
      rings.length === 5 && rings.every(l => l.closed), `${rings.length} rings`);
    check('[46] cone: rings shrink with elevation (roughly 2*pi*r)',
      ringLen(rings.find(l => l.elevFt === 10)!) > ringLen(rings.find(l => l.elevFt === 50)!) * 3);

    // Determinism + degenerate inputs
    check('[46] computeContours is deterministic',
      JSON.stringify(T.computeContours(cone.grid, cone.rect, 10)) === JSON.stringify(csCone));
    check('[46] flat grid or bad interval -> no contours',
      T.computeContours(makeGrid(ramp46.rect, 16, () => 77).grid, ramp46.rect, 5).lines.length === 0 &&
      T.computeContours(ramp46.grid, ramp46.rect, 0).lines.length === 0);

    // NaN cells: quads touching no-data are skipped, no NaN coordinates leak
    const holey = { ...ramp46.grid, valuesFt: ramp46.grid.valuesFt.slice() };
    for (let i = 0; i < holey.valuesFt.length; i += 97) holey.valuesFt[i] = NaN;
    const csHole = T.computeContours(holey, ramp46.rect, 5);
    check('[46] no-data cells never produce NaN contour points',
      csHole.lines.length > 0 &&
      csHole.lines.every(l => l.pts.every(p => Number.isFinite(p.x) && Number.isFinite(p.y))));

    // WYSIWYG guarantee: computing contours never changes the DXF
    const dxfC1 = buildDesignDxfString(d45, 'CONTOUR-RT', config);
    T.computeContours(steepG.grid, dRect, 2);
    const dxfC2 = buildDesignDxfString(d45, 'CONTOUR-RT', config);
    check('[46] DXF is byte-identical with contours in play', dxfC1 === dxfC2);

    // -----------------------------------------------------------------
    console.log('\n[47] Grading tie-in / daylight limits at the pad edge (preview only)');

    // Ramp z = 0.04x, square fence [200,800]^2, pad at the midpoint (~20 ft):
    // east side is CUT (ground above pad), west side FILL, run split expected.
    const gtRamp = makeGrid({ minX: 0, maxX: 1000, minY: 0, maxY: 1000 }, 64, x => 0.04 * x);
    const gtFence = [{ x: 200, y: 200 }, { x: 800, y: 200 }, { x: 800, y: 800 }, { x: 200, y: 800 }];
    const gtPad = T.computeCutFill(gtRamp.grid, gtRamp.rect, gtFence)!.padElevationFt;
    const gt = T.computeGradingTieIn(gtRamp.grid, gtRamp.rect, gtFence, gtPad)!;
    check('[47] ramp yields both cut and fill runs',
      gt.runs.some(r => r.kind === 'cut') && gt.runs.some(r => r.kind === 'fill'),
      gt.runs.map(r => r.kind).join(','));
    const cutPts = gt.runs.filter(r => r.kind === 'cut').flatMap(r => r.pts);
    const fillPts = gt.runs.filter(r => r.kind === 'fill').flatMap(r => r.pts);
    check('[47] cut side is uphill (east), fill side downhill (west)',
      cutPts.length > 0 && fillPts.length > 0 &&
      Math.min(...cutPts.map(p => p.x)) > Math.max(...fillPts.map(p => p.x)) - 1);
    check('[47] max cut/fill at the fence ≈ 12 ft (ramp edge minus mid, ±1)',
      Math.abs(gt.maxCutFt - 12) < 1 && Math.abs(gt.maxFillFt - 12) < 1,
      `cut ${gt.maxCutFt.toFixed(1)} fill ${gt.maxFillFt.toFixed(1)}`);
    // Daylight points sit OUTSIDE the fence, offset ~3x depth (clamped 80)
    const allRuns = gt.runs;
    check('[47] daylight points land outside the fence polygon',
      allRuns.every(r => r.daylightPts.every(p =>
        !(p.x > 200 && p.x < 800 && p.y > 200 && p.y < 800))));
    check('[47] daylight offset = min(3*|dz|, 80 ft) at every sample',
      allRuns.every(r => r.pts.every((p, i) => {
        const d = Math.hypot(r.daylightPts[i].x - p.x, r.daylightPts[i].y - p.y);
        return Math.abs(d - Math.min(3 * Math.abs(r.dzFt[i]), 80)) < 0.01;
      })));
    // Clockwise fence (reversed winding) must offset outward too
    const gtCw = T.computeGradingTieIn(gtRamp.grid, gtRamp.rect, gtFence.slice().reverse(), gtPad)!;
    check('[47] clockwise fence winding still daylights outward',
      gtCw.runs.every(r => r.daylightPts.every(p =>
        !(p.x > 200 && p.x < 800 && p.y > 200 && p.y < 800))));
    // Flat ground at pad elevation: no grading needed, no runs
    const gtFlat = T.computeGradingTieIn(
      makeGrid(gtRamp.rect, 64, () => gtPad).grid, gtRamp.rect, gtFence, gtPad)!;
    check('[47] flat ground at pad elevation -> no cut/fill runs',
      gtFlat.runs.length === 0 && gtFlat.maxCutFt === 0 && gtFlat.maxFillFt === 0);
    // Determinism + degenerate fence
    check('[47] computeGradingTieIn is deterministic',
      JSON.stringify(T.computeGradingTieIn(gtRamp.grid, gtRamp.rect, gtFence, gtPad)) === JSON.stringify(gt));
    check('[47] degenerate fence returns null',
      T.computeGradingTieIn(gtRamp.grid, gtRamp.rect, [{ x: 0, y: 0 }], gtPad) === null);

    // WYSIWYG guarantee: grading limits never change the DXF
    const dxfG1 = buildDesignDxfString(d45, 'GRADE-RT', config);
    T.computeGradingTieIn(steepG.grid, dRect, d45.fence, 0);
    const dxfG2 = buildDesignDxfString(d45, 'GRADE-RT', config);
    check('[47] DXF is byte-identical with grading limits in play', dxfG1 === dxfG2);

    // -----------------------------------------------------------------
    console.log('\n[48] Opt-in contour reference layer in the DXF export');
    const { LAYERS: L47 } = await import('../client/src/lib/nextera/dxfExport');

    // contoursForDxf: local-feet frame, auto interval, null on flat ground
    const exp47 = T.contoursForDxf(ramp46.grid as any, origin, 0);
    check('[48] contoursForDxf: auto interval from relief (40 ft -> 5 ft)',
      exp47 !== null && exp47.intervalFt === 5 && exp47.lines.length === 7,
      exp47 ? `${exp47.intervalFt} ft, ${exp47.lines.length} lines` : 'null');
    check('[48] contoursForDxf: explicit interval respected',
      T.contoursForDxf(ramp46.grid as any, origin, 10)?.intervalFt === 10);
    check('[48] contoursForDxf: flat grid -> null (nothing to export)',
      T.contoursForDxf(makeGrid(ramp46.rect, 16, () => 77).grid as any, origin, 5) === null);

    // The permit packet and its in-panel preview must honor the drafter's
    // contour-interval pick (0 = auto) with the SAME contoursForDxf call, so
    // the preview never lies about what the packet embeds. Source-scan both
    // call sites: any drift back to auto-only fails here.
    {
      const panelSrc48 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
      const previewSrc48 = readFileSync('client/src/components/ContourFigurePreview.tsx', 'utf8');
      check('[48] permit packet contours honor the drafter interval pick',
        /contours:\s*contoursForDxf\(terrainYard,\s*design\.boundary\.origin,\s*contourIntervalFt\)/.test(panelSrc48));
      check('[48] contour figure preview honors the same interval pick',
        /contoursForDxf\(terrain,\s*design\.boundary\.origin,\s*intervalFt\)/.test(previewSrc48) &&
        /<ContourFigurePreview[^>]*intervalFt=\{contourIntervalFt\}/.test(panelSrc48));
    }

    // OFF (default): passing nothing, null, or an empty set is byte-identical.
    const dxfOff = buildDesignDxfString(d45, 'CONTOUR-EXP', config);
    check('[48] default export (no contours arg) has no contour layers',
      !dxfOff.includes(L47.CONTOUR) && !dxfOff.includes(L47.CONTOUR_MAJOR));
    check('[48] contours: null is byte-identical to default',
      buildDesignDxfString(d45, 'CONTOUR-EXP', config, undefined, undefined, undefined, null) === dxfOff);
    check('[48] contours: empty set is byte-identical to default',
      buildDesignDxfString(d45, 'CONTOUR-EXP', config, undefined, undefined, undefined,
        { intervalFt: 5, majorEveryFt: 25, lines: [] }) === dxfOff);

    // ON: LWPOLYLINEs land on the dashed reference layers with major/minor
    // split and elevation labels on the index contours only.
    const dxfOn = buildDesignDxfString(d45, 'CONTOUR-EXP', config, undefined, undefined, undefined, exp47);
    check('[48] contours on: both reference layers declared',
      dxfOn.includes(`  2\n${L47.CONTOUR}\n`) && dxfOn.includes(`  2\n${L47.CONTOUR_MAJOR}\n`));
    check('[48] contour layers are DASHED',
      new RegExp(`${L47.CONTOUR}\\n 70\\n0\\n 62\\n\\d+\\n  6\\nDASHED`).test(dxfOn) &&
      new RegExp(`${L47.CONTOUR_MAJOR}\\n 70\\n0\\n 62\\n\\d+\\n  6\\nDASHED`).test(dxfOn));
    const nMinor = exp47!.lines.filter(l => !l.major && l.pts.length >= 2).length;
    const nMajor = exp47!.lines.filter(l => l.major && l.pts.length >= 2).length;
    check('[48] one LWPOLYLINE per minor contour on the minor layer',
      dxfOn.split(`  8\n${L47.CONTOUR}\n`).length - 1 === nMinor, `${nMinor} minor`);
    // Major layer carries the polyline + one TEXT label per major contour
    check('[48] major layer carries polyline + elevation label per index contour',
      dxfOn.split(`  8\n${L47.CONTOUR_MAJOR}\n`).length - 1 === nMajor * 2, `${nMajor} major`);
    for (const l of exp47!.lines.filter(l => l.major)) {
      const label = Number.isInteger(l.elevFt) ? l.elevFt.toFixed(0) : l.elevFt.toFixed(1);
      check(`[48] elevation label "${label}" present`, dxfOn.includes(`\n  1\n${label}\n`));
    }
    check('[48] contour export leaves the rest of the drawing untouched (prefix match)',
      dxfOn !== dxfOff && dxfOn.length > dxfOff.length);

    // Label placement avoids the equipment yard: for every index contour,
    // the chosen label vertex is outside the fence whenever the contour has
    // any vertex outside the fence, and never lands inside an equipment
    // rectangle when a clear vertex exists. Placement is deterministic.
    const { contourLabelVertex } = await import('../client/src/lib/nextera/dxfExport');
    const { pointInPolygon: pip48 } = await import('../client/src/lib/nextera/kmz');
    let allClear = true, allDet = true;
    for (const l of exp47!.lines.filter(l => l.major && l.pts.length >= 2)) {
      const i1 = contourLabelVertex(l.pts, d45);
      const i2 = contourLabelVertex(l.pts.map(p => ({ ...p })), d45);
      if (i1 !== i2) allDet = false;
      const hasOutside = l.pts.some(p => !pip48(p, d45.fence));
      if (hasOutside && pip48(l.pts[i1], d45.fence)) allClear = false;
    }
    check('[48] index-contour labels land outside the fence when possible', allClear);
    check('[48] contour label vertex choice is deterministic', allDet);
    check('[48] contours-on export is byte-identical across runs',
      buildDesignDxfString(d45, 'CONTOUR-EXP', config, undefined, undefined, undefined, exp47) === dxfOn);
    // Without a design, drawContours keeps the legacy middle-vertex pick.
    const legacyPts = [{ x: 0, y: 0 }, { x: 10, y: 0 }, { x: 20, y: 0 }, { x: 30, y: 0 }, { x: 40, y: 0 }];
    check('[48] no design -> legacy middle vertex',
      contourLabelVertex(legacyPts) === 2 && contourLabelVertex(legacyPts, undefined) === 2);
    // Synthetic yard: a square fence with one container; a contour crossing
    // the yard must label at an outside vertex, and a fully-inside contour
    // labels at the vertex farthest from the equipment.
    const synthFence = [{ x: 0, y: 0 }, { x: 100, y: 0 }, { x: 100, y: 100 }, { x: 0, y: 100 }];
    const synthDesign = {
      ...d45, fence: synthFence,
      equipment: [{ id: 'c1', kind: 'bess' as const, label: 'BATT', x: 50, y: 50, rotation: 0, length: 40, width: 10, height: 10 }],
    } as typeof d45;
    const crossPts = [{ x: -30, y: 50 }, { x: 20, y: 50 }, { x: 50, y: 50 }, { x: 80, y: 50 }, { x: 150, y: 50 }];
    const ci = contourLabelVertex(crossPts, synthDesign);
    check('[48] crossing contour labels outside the fence (farthest vertex)',
      !pip48(crossPts[ci], synthFence) && ci === 4, `picked ${ci}`);
    const insidePts = [{ x: 50, y: 48 }, { x: 50, y: 50 }, { x: 50, y: 90 }];
    const ii = contourLabelVertex(insidePts, synthDesign);
    check('[48] fully-inside contour labels farthest from equipment', ii === 2, `picked ${ii}`);

    // Worker-path parity: the DxfRequest carries contours as plain data.
    const { handleDxf: handleDxf47 } = await import('../client/src/lib/nextera/designWorkerCore');
    const { getEffectiveConfiguration } = await import('../client/src/lib/nextera/catalog');
    const viaWorker = handleDxf47(structuredClone({
      kind: 'dxf' as const, design: d45, projectName: 'CONTOUR-EXP',
      configId: config.id, contours: exp47,
    }));
    check('[48] worker path with contours is byte-identical to direct call',
      viaWorker === buildDesignDxfString(d45, 'CONTOUR-EXP', getEffectiveConfiguration(config.id), undefined, undefined, undefined, exp47));

    // Interval lock: the panel's contour-interval pick drives BOTH the DXF
    // reference layer and the permit packet figure through the same
    // contoursForDxf call. Byte-level regression at a NON-auto interval:
    // build both exports at 2 ft and confirm each carries contours at
    // exactly that interval with identical line data — any future call site
    // that forgets to pass the setting (drifting back to auto = 5 ft on
    // this grid) fails here.
    {
      const cDxf48 = T.contoursForDxf(ramp46.grid as any, origin, 2);
      const cPkt48 = T.contoursForDxf(ramp46.grid as any, origin, 2);
      check('[48] interval lock: DXF contour set honors the 2 ft pick (not auto 5 ft)',
        cDxf48 !== null && cDxf48.intervalFt === 2,
        cDxf48 ? `${cDxf48.intervalFt} ft` : 'null');
      const dxf2 = buildDesignDxfString(d45, 'CONTOUR-EXP', config, undefined, undefined, undefined, cDxf48);
      check('[48] interval lock: 2 ft DXF differs from the auto-interval DXF',
        dxf2 !== dxfOn && dxf2.includes(`  2\n${L47.CONTOUR}\n`));

      const { buildPermitPacketModel: buildPkt48 } = await import('../client/src/lib/nextera/permitReport');
      const model2 = buildPkt48(d45, config, {
        now: new Date('2026-01-01T12:00:00'),
        earthwork: {
          cutFill: {
            padElevationFt: 60, cutCY: 100, fillCY: 100, netCY: 0,
            areaSqFt: 10000, sampleSpacingFt: 10, minElevFt: 40, maxElevFt: 80,
          },
          steep: null, source: 'test grid', resolutionM: 10, noDataCount: 0,
          contours: cPkt48,
        },
      });
      const pktC = model2.earthwork?.contours;
      check('[48] interval lock: permit packet contour set carries intervalFt === 2',
        !!pktC && pktC.intervalFt === 2, pktC ? `${pktC.intervalFt} ft` : 'missing');
      check('[48] interval lock: DXF and permit packet contour line data are identical',
        !!pktC && JSON.stringify(pktC) === JSON.stringify(cDxf48));
      // Every major-contour elevation in the packet set appears as a DXF label
      const majors2 = cDxf48!.lines.filter(l => l.major && l.pts.length >= 2);
      check('[48] interval lock: 2 ft DXF labels every index contour of the shared set',
        majors2.length > 0 && majors2.every(l => {
          const label = Number.isInteger(l.elevFt) ? l.elevFt.toFixed(0) : l.elevFt.toFixed(1);
          return dxf2.includes(`\n  1\n${label}\n`);
        }), `${majors2.length} majors`);
    }

    // -----------------------------------------------------------------
    console.log('\n[49] Contours in the DXF package and PDF plots');
    const { buildDxfPackage: buildPkg49 } = await import('../client/src/lib/nextera/dxfSheets');
    const { buildPdfPlotString: pdfPlot49, buildDesignPdfString: designPdf49 } =
      await import('../client/src/lib/nextera/pdfPlot');
    const { handleDxfPackage: handlePkg49 } = await import('../client/src/lib/nextera/designWorkerCore');
    const ctx49 = { design: d45, projectName: 'CONTOUR-PKG', config };

    // Default (unchecked) output stays byte-identical for every export path:
    // absent, null, and empty contours all produce the same bytes.
    const pkgOff = buildPkg49(ctx49);
    check('[49] package: null contours is byte-identical to default',
      JSON.stringify(buildPkg49({ ...ctx49, contours: null })) === JSON.stringify(pkgOff));
    check('[49] package: empty contour set is byte-identical to default',
      JSON.stringify(buildPkg49({ ...ctx49, contours: { intervalFt: 5, majorEveryFt: 25, lines: [] } }))
        === JSON.stringify(pkgOff));
    check('[49] package default has no contour layers on any sheet',
      pkgOff.every(s => !s.content.includes(L47.CONTOUR) && !s.content.includes(L47.CONTOUR_MAJOR)));

    // ON: contours land on the site-plan sheet only (reference layers), the
    // other discipline sheets stay byte-identical.
    const pkgOn = buildPkg49({ ...ctx49, contours: exp47 });
    const sitePlanIdx = pkgOn.findIndex(s => s.filename.includes('Overall_Site_Plan'));
    check('[49] package on: site-plan sheet carries both contour layers',
      sitePlanIdx >= 0 &&
      pkgOn[sitePlanIdx].content.includes(`  2\n${L47.CONTOUR}\n`) &&
      pkgOn[sitePlanIdx].content.includes(`  2\n${L47.CONTOUR_MAJOR}\n`));
    check('[49] package on: site-plan sheet has one LWPOLYLINE per minor contour',
      pkgOn[sitePlanIdx].content.split(`  8\n${L47.CONTOUR}\n`).length - 1 === nMinor);
    check('[49] package on: all other sheets are byte-identical to default',
      pkgOn.every((s, i) => i === sitePlanIdx || s.content === pkgOff[i].content));
    check('[49] package on: site-plan is a strict superset of the default sheet',
      pkgOn[sitePlanIdx].content !== pkgOff[sitePlanIdx].content &&
      pkgOn[sitePlanIdx].content.length > pkgOff[sitePlanIdx].content.length);

    // Worker-path parity for the package request.
    const pkgViaWorker = handlePkg49(structuredClone({
      kind: 'dxfPackage' as const, design: d45, projectName: 'CONTOUR-PKG',
      configId: config.id, contours: exp47,
    }));
    check('[49] package worker path with contours matches direct call',
      JSON.stringify(pkgViaWorker) ===
      JSON.stringify(buildPkg49({ design: d45, projectName: 'CONTOUR-PKG', config: getEffectiveConfiguration(config.id), contours: exp47 })));

    // PDF plot set (multi-sheet): default stays byte-identical; with contours
    // on, the PDF changes (contour line work + labels on the site-plan page).
    const plotOff = pdfPlot49(ctx49);
    check('[49] plot set: null contours is byte-identical to default',
      pdfPlot49({ ...ctx49, contours: null }) === plotOff);
    const plotOn = pdfPlot49({ ...ctx49, contours: exp47 });
    check('[49] plot set: contours change the PDF output', plotOn !== plotOff);
    check('[49] plot set with contours is deterministic',
      pdfPlot49({ ...ctx49, contours: exp47 }) === plotOn);

    // Single-page design PDF plot: same guarantees.
    const dPdfOff = designPdf49(ctx49);
    check('[49] design PDF: null contours is byte-identical to default',
      designPdf49({ ...ctx49, contours: null }) === dPdfOff);
    const dPdfOn = designPdf49({ ...ctx49, contours: exp47 });
    check('[49] design PDF: contours change the PDF output', dPdfOn !== dPdfOff);
    check('[49] design PDF with contours is deterministic',
      designPdf49({ ...ctx49, contours: exp47 }) === dPdfOn);
  }

  // ---------------------------------------------------------------
  // Source-scan (same pattern as the configureGroundTexture scan): the
  // in-panel ContourFigurePreview manually mirrors drawContourFigure in
  // permitPdf.ts and the packet's contoursForDxf call. If either side
  // changes (interval argument, origin, major/minor/label structure, or
  // styling) without the other, drafters would approve a preview that no
  // longer matches the exported packet. Expected values are extracted from
  // permitPdf.ts so a PDF-side change fails here until the preview follows.
  {
    console.log('\n[50] Earthwork figure preview mirrors the permit packet figure');
    const prevSrc = readFileSync('client/src/components/ContourFigurePreview.tsx', 'utf8');
    const pdfSrc = readFileSync('client/src/lib/nextera/permitPdf.ts', 'utf8');
    const panelSrc = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');

    // The preview is actually mounted in the panel (the scan is moot otherwise).
    check('[50] panel mounts ContourFigurePreview',
      panelSrc.includes('<ContourFigurePreview') &&
      panelSrc.includes("from './ContourFigurePreview'"));

    // Contour data call parity: the packet path (PermitEarthwork.contours in
    // the panel) and the preview must call contoursForDxf with the SAME
    // argument list — same terrain source, same origin expression, and the
    // same interval expression. This is a true parity comparison, not a
    // pinned signature: if both sides change together (e.g. both switch
    // interval handling) the test stays green; if only one side changes, it
    // fails. The preview receives its interval as a prop, so resolve the
    // panel's <ContourFigurePreview intervalFt={...}> binding and substitute
    // it for the prop name before comparing; also normalize whitespace and
    // the design/d local alias.
    const packetCall = panelSrc.match(/contours:\s*contoursForDxf\(([^)]*)\)/);
    const previewCall = prevSrc.match(/contoursForDxf\(([^)]*)\)/);
    check('[50] panel packet path calls contoursForDxf', !!packetCall, packetCall?.[1] ?? 'missing');
    check('[50] preview calls contoursForDxf', !!previewCall, previewCall?.[1] ?? 'missing');
    const mount = panelSrc.match(/<ContourFigurePreview\b([\s\S]*?)\/>/);
    const propBindings: Record<string, string> = {};
    for (const m of (mount?.[1] ?? '').matchAll(/(\w+)=\{([^}]*)\}/g)) {
      propBindings[m[1]] = m[2].replace(/\s+/g, '').replace(/!/g, '');
    }
    const normArgs = (s: string, bindings?: Record<string, string>) =>
      s.replace(/\s+/g, '')
        .replace(/!/g, '')
        .replace(/\bd\.boundary\.origin\b/, 'design.boundary.origin')
        .split(',')
        .map(a => (bindings && bindings[a] !== undefined ? bindings[a] : a))
        .join(',');
    const packetArgs = packetCall ? normArgs(packetCall[1]) : '';
    const previewArgs = previewCall ? normArgs(previewCall[1], propBindings) : '';
    check('[50] preview passes the SAME contoursForDxf arguments as the packet path (props resolved)',
      !!packetCall && !!previewCall && packetArgs === previewArgs,
      `packet(${packetArgs}) vs preview(${previewArgs})`);
    check('[50] preview and packet agree on interval handling (same argument count)',
      packetArgs.split(',').length === previewArgs.split(',').length,
      `packet has ${packetArgs.split(',').length} args, preview ${previewArgs.split(',').length}`);
    // The drafter's DXF interval preference must reach the preview's data
    // call if and only if the packet path uses it (parity, not a pinned rule).
    check('[50] preview uses the DXF interval preference exactly when the packet does',
      previewArgs.includes('contourIntervalFt') === packetArgs.includes('contourIntervalFt'));

    // Isolate the PDF figure function body.
    const figStart = pdfSrc.indexOf('export function drawContourFigure');
    const figTail = pdfSrc.slice(figStart);
    const figEnd = figTail.indexOf('\nexport function', 10);
    const figSrc = figStart >= 0 ? (figEnd > 0 ? figTail.slice(0, figEnd) : figTail) : '';
    check('[50] drawContourFigure found in permitPdf.ts', figSrc.length > 0);

    // Extract the figure's styling from the PDF source: sequential
    // setDrawColor/setLineWidth pairs are minor, major, boundary (fence
    // reuses the boundary width); label font size, color, and y offset.
    // The boundary stroke is the shared property-line constant (spread
    // form, per [898]); resolve it to its RGB value in source order.
    const { PROPERTY_LINE_FIGURE_RGB: plRgb50 } =
      await import('../client/src/lib/nextera/propertyLineColor');
    const colors = [...figSrc.matchAll(/setDrawColor\((?:(\d+),\s*(\d+),\s*(\d+)|\.\.\.PROPERTY_LINE_FIGURE_RGB)\)/g)]
      .map(m => m[1] !== undefined ? `${m[1]},${m[2]},${m[3]}` : plRgb50.join(','));
    const widths = [...figSrc.matchAll(/setLineWidth\(([\d.]+)\)/g)].map(m => m[1]);
    const textColor = figSrc.match(/setTextColor\((\d+),\s*(\d+),\s*(\d+)\)/);
    const fontSize = figSrc.match(/setFontSize\((\d+)\)/);
    const labelOffset = figSrc.match(/fy\(m\.y\)\s*-\s*([\d.]+)/);
    check('[50] extracted 4 stroke colors + 3 widths + label style from the PDF figure',
      colors.length === 4 && widths.length >= 3 && !!textColor && !!fontSize && !!labelOffset,
      `colors=${colors.length} widths=${widths.length}`);

    // The preview strokes the boundary via the same shared constant
    // (stroke={BOUNDARY_STROKE}); accept that form only when it is truly
    // derived from PROPERTY_LINE_FIGURE_RGB — parity by shared source.
    const sharedStroke50 = prevSrc.includes("PROPERTY_LINE_FIGURE_RGB.join(',')");
    const hasStroke = (color: string, width: string) =>
      new RegExp(`stroke="rgb\\(${color.replace(/,/g, ',\\s*')}\\)"\\s+strokeWidth=\\{${width}\\}`).test(prevSrc) ||
      (color === plRgb50.join(',') && sharedStroke50 &&
        new RegExp(`stroke=\\{BOUNDARY_STROKE\\}\\s+strokeWidth=\\{${width}\\}`).test(prevSrc));
    check('[50] preview minor contour stroke matches the PDF figure', hasStroke(colors[0], widths[0]),
      `expect rgb(${colors[0]}) @ ${widths[0]}`);
    check('[50] preview index (major) contour stroke matches the PDF figure', hasStroke(colors[1], widths[1]),
      `expect rgb(${colors[1]}) @ ${widths[1]}`);
    check('[50] preview boundary stroke matches the PDF figure', hasStroke(colors[2], widths[2]),
      `expect rgb(${colors[2]}) @ ${widths[2]}`);
    check('[50] preview fence stroke matches the PDF figure (same width as boundary)',
      hasStroke(colors[3], widths[2]), `expect rgb(${colors[3]}) @ ${widths[2]}`);
    check('[50] preview label font size + color match the PDF figure',
      !!fontSize && !!textColor &&
      new RegExp(`fontSize=\\{${fontSize[1]}\\}`).test(prevSrc) &&
      prevSrc.includes(`fill="rgb(${textColor[1]},${textColor[2]},${textColor[3]})"`));
    check('[50] preview label y-offset matches the PDF figure',
      !!labelOffset && prevSrc.includes(`fy(m.y) - ${labelOffset[1]}`));

    // Structural parity: labels only on index contours, placed at the middle
    // vertex, formatted with the identical fmtElev rule; both sides bail on
    // an empty contour set the same way.
    const fmtElevRule = /Number\.isInteger\(e\)\s*\?\s*e\.toFixed\(0\)\s*:\s*e\.toFixed\(1\)/;
    check('[50] fmtElev rule identical in preview and PDF figure',
      fmtElevRule.test(prevSrc) && fmtElevRule.test(figSrc));
    check('[50] both label the middle vertex of index contours',
      prevSrc.includes('Math.floor(line.pts.length / 2)') &&
      figSrc.includes('Math.floor(line.pts.length / 2)'));
    const majorBranch = prevSrc.match(/if\s*\(line\.major\)\s*\{([\s\S]*?)\}\s*else\s*\{([\s\S]*?)\}/);
    check('[50] preview labels index contours only (label push in the major branch)',
      !!majorBranch && majorBranch[1].includes('labels.push') && majorBranch[2].includes('minor.push') &&
      !majorBranch[2].includes('labels.push'));
    check('[50] both bail identically on an empty contour set',
      prevSrc.includes('!contours.lines.length') && figSrc.includes('!contours.lines.length'));
    // The PDF figure skips degenerate (<2 pt) lines; the preview must too.
    check('[50] both skip degenerate contour lines (< 2 points)',
      prevSrc.includes('line.pts.length < 2') && figSrc.includes('line.pts.length < 2'));
  }

  // ---------------------------------------------------------------
  // [51] Voltage drop & losses report (screening) + validation wiring
  {
    console.log('\n[51] Voltage drop & losses report');
    const { buildFeederElectricalReport, lossFactor, HOURS_PER_YEAR, DEFAULT_CAPACITY_FACTOR_PCT } =
      await import('../client/src/lib/nextera/electrical');
    const { validateDesign } = await import('../client/src/lib/nextera/validateDesign');

    // Hand-checkable synthetic feeder: one 1000 ft segment @ 200 A, 500 Al.
    // R = 0.0424 Ω/kft → ΔV = √3·200·0.0424 = 14.6877 V (0.0426% of 34.5 kV)
    // Loss = 3·200²·0.0424e-3·1000 = 5088 W = 5.088 kW
    // LsF(35%) = 0.3·0.35 + 0.7·0.35² = 0.19075
    // Annual = 5.088·8760·0.19075/1000 = 8.5019 MWh
    const mkFeeder = (amps: number, lengthFt: number, idx = 1) => ({
      idx,
      inverterIds: ['PCS-1'],
      loadMW: 0,
      amps,
      segments: [{ pts: [{ x: 0, y: 0 }, { x: lengthFt, y: 0 }], lengthFt, amps }],
      totalLengthFt: lengthFt,
      size: '500' as const,
      material: 'Al' as const,
      vdVolts: 0, vdPct: 0, overLimit: false, recommendedSize: null,
      ampacity: 400, fjbId: null, overAmpacity: false,
      ampacityRecommendedSize: null, parallelRunsNeeded: 1,
      futurePcs: 0, eolAmps: amps, parallelSets: 1, effectiveAmpacity: 400,
      adjacentCircuits: 1, derateFactor: 1, governing: 'ampacity' as const,
    });
    const rep = buildFeederElectricalReport([mkFeeder(200, 1000)]);
    const row = rep.rows[0];
    check('[51] hand-check: ΔV = √3·I·R·L', Math.abs(row.vdVolts - Math.sqrt(3) * 200 * 0.0424) < 1e-9,
      `${row.vdVolts}`);
    check('[51] hand-check: vdPct vs 34.5 kV', Math.abs(row.vdPct - (row.vdVolts / 34500) * 100) < 1e-12);
    check('[51] hand-check: peak loss = 3·I²·R·L = 5.088 kW', Math.abs(row.peakLossKW - 5.088) < 1e-9,
      `${row.peakLossKW}`);
    check('[51] hand-check: loss factor at default 35% CF = 0.19075',
      Math.abs(rep.lossFactorUsed - 0.19075) < 1e-12 && rep.capacityFactorPct === DEFAULT_CAPACITY_FACTOR_PCT);
    check('[51] hand-check: annual loss = P·8760·LsF',
      Math.abs(row.annualLossMWh - (5.088 * HOURS_PER_YEAR * 0.19075) / 1000) < 1e-9,
      `${row.annualLossMWh}`);
    check('[51] defaults: limit is the 3% engineering default and row passes',
      rep.limitPct === 3 && !row.overLimit && rep.overCount === 0 && Math.abs(rep.worstVdPct - row.vdPct) < 1e-12);
    check('[51] summary totals equal row sums',
      Math.abs(rep.totalPeakLossKW - row.peakLossKW) < 1e-12 &&
      Math.abs(rep.totalAnnualLossMWh - row.annualLossMWh) < 1e-12);

    // EOL basis (task 631): the report must surface EOL current + the
    // derated parallel capacity that sized the conductor — not BOL/base —
    // and evaluate drop/loss at EOL.
    {
      const eolF = {
        ...mkFeeder(200, 1000),
        eolAmps: 300, parallelSets: 2, effectiveAmpacity: 320,
        overAmpacity: false,
      };
      const rEol = buildFeederElectricalReport([eolF]).rows[0];
      check('[631] report row carries BOL + EOL amps',
        rEol.amps === 200 && rEol.eolAmps === 300);
      check('[631] report capacity = sets x derated rating (not base ampacity)',
        rEol.eolCapacityAmps === 2 * 320 && rEol.eolCapacityAmps !== rEol.ampacity);
      // VD/loss at EOL current with parallel-set resistance: scale 1.5, /2
      const expEolVd = Math.sqrt(3) * 300 * (0.0424 / 1000 / 2) * 1000;
      check('[631] report drop evaluated at EOL current over set resistance',
        Math.abs(rEol.vdVolts - expEolVd) < 1e-9, `${rEol.vdVolts} vs ${expEolVd}`);
      check('[631] overAmpacity flag passes through', rEol.overAmpacity === false &&
        buildFeederElectricalReport([{ ...eolF, overAmpacity: true }]).rows[0].overAmpacity === true);
      // UI surfaces the EOL fields, not the old BOL/base pair
      const panelSrc631 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
      check('[631] report table renders eolAmps + eolCapacityAmps',
        panelSrc631.includes('r.eolAmps.toFixed(0)') &&
        panelSrc631.includes('r.eolCapacityAmps.toFixed(0)') &&
        !panelSrc631.includes('{r.amps.toFixed(0)}/{r.ampacity}'));
      check('[631] report narrative states the EOL basis',
        panelSrc631.includes('EOL basis: currents include reserved augmentation PCS'));
    }

    // Per-segment currents: chain hop at 100 A + home run at 200 A must NOT
    // equal a single 200 A run of the combined length.
    const chained = {
      ...mkFeeder(200, 0),
      segments: [
        { pts: [{ x: 0, y: 0 }, { x: 500, y: 0 }], lengthFt: 500, amps: 100 },
        { pts: [{ x: 500, y: 0 }, { x: 1500, y: 0 }], lengthFt: 1000, amps: 200 },
      ],
      totalLengthFt: 1500,
    };
    const repChain = buildFeederElectricalReport([chained]);
    const rPerFt = 0.0424 / 1000;
    const expVd = Math.sqrt(3) * rPerFt * (100 * 500 + 200 * 1000);
    const expLossKW = (3 * rPerFt * (100 * 100 * 500 + 200 * 200 * 1000)) / 1000;
    check('[51] chain segments use per-segment amps (drop)',
      Math.abs(repChain.rows[0].vdVolts - expVd) < 1e-9);
    check('[51] chain segments use per-segment amps (loss)',
      Math.abs(repChain.rows[0].peakLossKW - expLossKW) < 1e-9);

    // Options: tighter limit flags the row; capacity factor changes losses.
    const long = mkFeeder(400, 30000); // big drop
    const tight = buildFeederElectricalReport([long], { maxVdPct: 1 });
    check('[51] custom limit flags rows and counts them',
      tight.limitPct === 1 && tight.rows[0].overLimit === (tight.rows[0].vdPct > 1) &&
      tight.overCount === (tight.rows[0].overLimit ? 1 : 0));
    const cf100 = buildFeederElectricalReport([long], { capacityFactorPct: 100 });
    check('[51] 100% capacity factor → loss factor 1 (continuous)',
      Math.abs(cf100.lossFactorUsed - 1) < 1e-12 &&
      Math.abs(cf100.rows[0].annualLossMWh - (cf100.rows[0].peakLossKW * HOURS_PER_YEAR) / 1000) < 1e-9);
    check('[51] invalid options fall back to defaults',
      buildFeederElectricalReport([long], { maxVdPct: NaN, capacityFactorPct: -5 }).limitPct === 3 &&
      buildFeederElectricalReport([long], { maxVdPct: 0 }).capacityFactorPct === DEFAULT_CAPACITY_FACTOR_PCT);
    check('[51] lossFactor edges: 0→0, 1→1, clamps out-of-range',
      lossFactor(0) === 0 && Math.abs(lossFactor(1) - 1) < 1e-12 &&
      lossFactor(-1) === 0 && Math.abs(lossFactor(2) - 1) < 1e-12);

    // Determinism: same inputs → identical serialized report.
    check('[51] report is deterministic',
      JSON.stringify(buildFeederElectricalReport([chained, long], { maxVdPct: 2, capacityFactorPct: 40 })) ===
      JSON.stringify(buildFeederElectricalReport([chained, long], { maxVdPct: 2, capacityFactorPct: 40 })));

    // Validation wiring: warn when over, pass when within, absent when the
    // report isn't provided (and the legacy 'feeders' check is untouched).
    const emptyDesign: any = {
      boundary: { polygon: [{ x: 0, y: 0 }, { x: 100, y: 0 }, { x: 100, y: 100 }, { x: 0, y: 100 }], origin: { lat: 0, lon: 0 } },
      fence: [], blockRows: [], equipment: [], reservedZones: [], roads: [], aisles: [],
      trenches: [], cables: [], gate: null, gates: [],
      blocksPlaced: 0, blocksRequired: 0, achievedMW: 0, achievedMWh: 0,
      targetMW: 0, targetMWh: 0, warnings: [],
    };
    const vd = (r: ReturnType<typeof validateDesign>) => r.checks.find(c => c.id === 'vdrop');
    const vWarn = validateDesign(emptyDesign, { electrical: buildFeederElectricalReport([long], { maxVdPct: 0.5 }) });
    const vPass = validateDesign(emptyDesign, { electrical: rep });
    const vNone = validateDesign(emptyDesign, {});
    check('[51] validateDesign: over-limit feeders → vdrop warn naming the feeder',
      vd(vWarn)?.status === 'warn' && (vd(vWarn)?.detail ?? '').includes('#F1'),
      vd(vWarn)?.detail);
    check('[51] validateDesign: all within limit → vdrop pass with losses in detail',
      vd(vPass)?.status === 'pass' && (vd(vPass)?.detail ?? '').includes('MWh/yr'));
    check('[51] validateDesign: no report → no vdrop check', vd(vNone) === undefined);
    check('[51] validateDesign: empty report rows → no vdrop check',
      vd(validateDesign(emptyDesign, { electrical: buildFeederElectricalReport([]) })) === undefined);

    // Export purity: the electrical module must not leak into the DXF path
    // (default exports stay byte-identical; report is UI/checklist only).
    const dxfSrc = readFileSync('client/src/lib/nextera/dxfExport.ts', 'utf8');
    check('[51] dxfExport does not import the electrical module', !dxfSrc.includes("electrical"));
  }

  // ---------------------------------------------------------------
  // [52] Single-line diagram (standalone DXF + PDF sheet)
  {
    console.log('\n[52] Single-line diagram sheet');
    const { buildSldModel, buildSldDxfString, sldSchematicWidth, drawSldInto, sldPlanRect } =
      await import('../client/src/lib/nextera/sld');
    const { generateFeeders } = await import('../client/src/lib/nextera/feeders');
    const { specForKind, LG_JF2_SPEC, HITACHI_AUX_XFMR_SPEC } = await import('../client/src/lib/nextera/catalog');
    const { DxfWriter, nexteraLabel } = await import('../client/src/lib/nextera/dxfExport');

    // Real Hondo design + routed feeders (east substation).
    const sub = { x: 2500, y: 0 };
    const sldFeeders = generateFeeders(design, sub, config.blockMW);
    check('[52] fixture: Hondo routes at least 2 feeders', sldFeeders.length >= 2, `${sldFeeders.length}`);

    const model = buildSldModel(design, sldFeeders, config);

    // Topology counts match the routed circuits exactly.
    check('[52] model has one branch per feeder', model.feeders.length === sldFeeders.length);
    check('[52] PCS count per feeder matches inverterIds',
      model.feeders.every((mf, i) => mf.pcs.length === sldFeeders[i].inverterIds.length));
    const totalPcs = model.feeders.reduce((s, f) => s + f.pcs.length, 0);
    const totalInv = design.equipment.filter(e => e.kind === 'inverter').length;
    check('[52] every inverter appears exactly once in the SLD', totalPcs === totalInv,
      `${totalPcs} vs ${totalInv}`);
    const allLabels = model.feeders.flatMap(f => f.pcs.map(p => p.label));
    check('[52] no duplicate PCS labels', new Set(allLabels).size === allLabels.length);

    // Labels match the yard-plan tags (same nexteraLabel source).
    const invById = new Map(design.equipment.map(e => [e.id, e]));
    check('[52] PCS labels match yard-plan nexteraLabel tags',
      model.feeders.every((mf, i) =>
        mf.pcs.every((p, j) => p.label === nexteraLabel(invById.get(sldFeeders[i].inverterIds[j])!))));

    // Container counts: each PCS block carries all its bess containers.
    const totalCont = model.feeders.reduce((s, f) => s + f.pcs.reduce((t, p) => t + p.containerCount, 0), 0);
    const totalBess = design.equipment.filter(e => e.kind === 'bess').length;
    check('[52] container counts sum to placed BESS containers', totalCont === totalBess,
      `${totalCont} vs ${totalBess}`);

    // Ratings verbatim from the catalog (never derived/recomputed).
    const invSpec = specForKind('inverter', config)!;
    check('[52] PCS rating text is the catalog rating verbatim',
      model.feeders.every(f => f.pcs.every(p => p.rating === invSpec.rating && p.model === invSpec.model)));
    check('[52] container line carries the LG JF2 catalog rating verbatim',
      model.feeders.every(f => f.pcs.every(p => p.containerLine.includes(LG_JF2_SPEC.rating))));
    check('[52] aux branch present with Hitachi rating verbatim (config has aux)',
      !!model.aux && model.aux.transformerLabel.includes(HITACHI_AUX_XFMR_SPEC.rating));

    // Conductor callouts carry the routed feeder's size/material/length/amps.
    check('[52] conductor callout carries size + material',
      model.feeders.every((mf, i) =>
        mf.conductorLine.includes(sldFeeders[i].size) &&
        mf.conductorLine.includes(sldFeeders[i].material === 'Al' ? 'AL' : 'CU')));
    check('[52] load callout carries length and amps',
      model.feeders.every((mf, i) =>
        mf.loadLine.includes(sldFeeders[i].totalLengthFt.toFixed(0)) &&
        mf.loadLine.includes(`BOL ${sldFeeders[i].amps.toFixed(0)} A`) &&
        mf.loadLine.includes(`EOL ${(sldFeeders[i].eolAmps || sldFeeders[i].amps).toFixed(0)} A`) &&
        mf.loadLine.includes(`EOL AMPACITY ${(Math.max(1, sldFeeders[i].parallelSets || 1) *
          (sldFeeders[i].effectiveAmpacity || sldFeeders[i].ampacity)).toFixed(0)} A DERATED`)));

    // Feeder-group fidelity: the SLD mirrors the routed circuits EXACTLY —
    // same order, same idx/label, same PCS membership per feeder — for any
    // input order (drafter overrides keep their own bucket order).
    const mirrors = (m: ReturnType<typeof buildSldModel>, fs: typeof sldFeeders) =>
      m.feeders.length === fs.length &&
      m.feeders.every((mf, i) =>
        mf.idx === fs[i].idx &&
        mf.label === `FEEDER #${feederDisplayName(fs[i])}` &&
        mf.pcs.length === fs[i].inverterIds.length &&
        mf.pcs.every((p, j) => p.label === nexteraLabel(invById.get(fs[i].inverterIds[j])!)));
    check('[52] SLD feeder groups mirror the routed circuits exactly', mirrors(model, sldFeeders));
    const revFeeders = [...sldFeeders].reverse();
    check('[52] mirrored for reversed input order (no re-sorting inside the SLD)',
      mirrors(buildSldModel(design, revFeeders, config), revFeeders));

    // Shared PCS unit data block: the identical model/rating/%Z/container
    // callouts print ONCE (they used to repeat under every PCS and smear
    // neighboring columns together).
    check('[52] shared PCS data block carries rating, %Z and container callouts once',
      model.pcsDataLines.some(l => l.includes(invSpec.rating)) &&
      model.pcsDataLines.some(l => l.includes('MV STEP-UP %Z')) &&
      model.pcsDataLines.some(l => l.includes(LG_JF2_SPEC.rating)));

    // Column-fit guard: replay the display list at 1:1 schematic scale and
    // assert every text in the per-PCS band (below the sub-bus, above the
    // notes) fits inside one PCS column width — neighboring PCS columns can
    // then never overlap regardless of feeder size.
    {
      const { buildShortCircuitStudy, DEFAULT_SC_INPUTS } = await import('../client/src/lib/nextera/shortCircuit');
      const { inverterAmps } = await import('../client/src/lib/nextera/feeders');
      const nInv = design.equipment.filter(e => e.kind === 'inverter').length;
      const study = buildShortCircuitStudy(
        sldFeeders, nInv, inverterAmps(config.blockMW), DEFAULT_SC_INPUTS, { hasAux: true });
      // Parallel sets act as parallel impedance: doubling sets on every
      // feeder must never LOWER the available fault duty at any bus.
      {
        const twoSet = sldFeeders.map(f => ({ ...f, parallelSets: 2 }));
        const study2 = buildShortCircuitStudy(
          twoSet, nInv, inverterAmps(config.blockMW), DEFAULT_SC_INPUTS, { hasAux: true });
        check('[631] SC study: 2 parallel sets never lower worst fault duty',
          study2.worstSymKA >= study.worstSymKA - 1e-9,
          `1-set ${study.worstSymKA} vs 2-set ${study2.worstSymKA}`);
        check('[631] SC study: set count changes cable-impedance results',
          JSON.stringify(study2.buses) !== JSON.stringify(study.buses));
      }
      const fitModel = buildSldModel(design, sldFeeders, config, { study });
      const W = sldSchematicWidth(fitModel);
      const texts: { x: number; y: number; h: number; t: string }[] = [];
      const rec: any = {
        addLine: () => {}, addPolyline: () => {}, addArc: () => {},
        addText: (x: number, y: number, h: number, t: string) => texts.push({ x, y, h, t }),
      };
      drawSldInto(rec, fitModel, { minX: 0, minY: 0, maxX: W, maxY: 400 });
      const PCS_COL_W = 46;  // PCS_W in sld.ts
      const AUX_COL_W = 90;  // AUX_W in sld.ts
      const GAP = 34;        // FEEDER_GAP in sld.ts
      // Aux branch is the rightmost column (AUX_W wide, flanked by gaps);
      // its texts may use the gaps but must never reach a PCS column.
      const auxX0 = fitModel.aux ? W - GAP - AUX_COL_W : Infinity;
      const band = texts.filter(op => op.y >= 50 && op.y <= 215);
      check('[52] fixture: per-PCS band has text to measure', band.length >= nInv);
      const wide = band.filter(op => {
        const w = op.t.length * op.h * 0.84;
        const isAux = op.x + w / 2 > auxX0;
        return w > (isAux ? AUX_COL_W + 2 * GAP : PCS_COL_W);
      });
      check('[52] every per-PCS text fits its column width (no cross-column smear)',
        wide.length === 0, wide.slice(0, 3).map(o => o.t).join(' | '));
      // Aux-vs-feeder strict separation (tighter than the AUX_W + 2*GAP
      // budget above): aux-branch texts may spill into the flanking gaps,
      // but their extents must never reach the neighboring feeder column's
      // text zone. The last feeder's PCS columns end at auxX0 - GAP, so the
      // aux text left edge must stay at or right of that line; the right
      // edge must stay on the sheet (< W).
      if (fitModel.aux) {
        const lastFeederX1 = auxX0 - GAP;
        const auxTexts = band.filter(op => {
          const w = op.t.length * op.h * 0.84;
          return op.x + w / 2 > auxX0; // same aux classification as above
        });
        check('[52] fixture: aux branch renders text in the per-PCS band', auxTexts.length >= 2);
        const crossing = auxTexts.filter(op =>
          op.x < lastFeederX1 || op.x + op.t.length * op.h * 0.84 > W);
        check('[52] aux text extents never cross into the neighboring feeder column',
          crossing.length === 0,
          crossing.slice(0, 3).map(o => `${o.t} [x0=${o.x.toFixed(1)} < ${lastFeederX1}]`).join(' | '));
      }
      // Direct "printed once only" guarantee: the long shared strings never
      // appear as per-column text ops (they live in the shared data block).
      const sharedLong = new Set(
        fitModel.feeders.flatMap(ff => ff.pcs.flatMap(p =>
          [p.rating, p.xfmrLine, p.containerLine, p.faultLine ?? ''])).filter(Boolean));
      check('[52] long PCS strings never render per-column',
        band.every(op => !sharedLong.has(op.t)));
    }

    // DXF sheet: valid structure, deterministic, byte-identical rebuilds.
    const sldDxf = buildSldDxfString(design, 'Hondo_SLD', sldFeeders, config, {});
    check('[52] SLD DXF has HEADER/TABLES/ENTITIES sections and EOF',
      sldDxf.includes('HEADER') && sldDxf.includes('TABLES') &&
      sldDxf.includes('ENTITIES') && sldDxf.trimEnd().endsWith('EOF'));
    check('[52] SLD DXF has no NaN', !sldDxf.includes('NaN'));
    check('[52] SLD DXF titled SINGLE-LINE DIAGRAM', sldDxf.includes('SINGLE-LINE DIAGRAM'));
    check('[52] SLD DXF labels every feeder',
      model.feeders.every(f => sldDxf.includes(f.label)));
    check('[52] SLD DXF rebuild is byte-identical',
      sldDxf === buildSldDxfString(design, 'Hondo_SLD', sldFeeders, config, {}));

    // Transformer symbols must survive as valid ARC entities: a full 0..2π
    // arc normalizes to 50=0/51=0 (zero sweep) and many CAD viewers drop it,
    // so circles are drawn as two half arcs with distinct angles.
    const arcAngles: { a1: number; a2: number }[] = [];
    {
      const lines = sldDxf.split('\n');
      for (let i = 0; i < lines.length - 1; i++) {
        if (lines[i].trim() === '0' && lines[i + 1] === 'ARC') {
          let a1 = NaN, a2 = NaN;
          for (let j = i + 2; j < Math.min(i + 60, lines.length - 1); j++) {
            if (lines[j].trim() === '50') a1 = parseFloat(lines[j + 1]);
            if (lines[j].trim() === '51') { a2 = parseFloat(lines[j + 1]); break; }
            if (lines[j].trim() === '0') break;
          }
          arcAngles.push({ a1, a2 });
        }
      }
    }
    // Circles on the sheet (2 half-arcs each): transformer pairs per PCS +
    // aux, plus the POI metering cluster (CT + 2-circle PT + WH meter).
    // Plus 2 tilde arcs (AC wave) inside every PCS converter box.
    const circleCount = 2 * (totalInv + (model.aux ? 1 : 0)) + 4;
    const expectedArcs = 2 * circleCount + 2 * totalInv;
    check('[52] transformer/metering symbols present as ARC entities (2 half-arcs per circle)',
      arcAngles.length === expectedArcs, `${arcAngles.length} vs ${expectedArcs}`);
    check('[52] no zero-sweep ARC entities (every arc has distinct 50/51 angles)',
      arcAngles.every(a => Number.isFinite(a.a1) && Number.isFinite(a.a2) && Math.abs(a.a1 - a.a2) > 1e-9));

    // PDF twin: rendered from the same display list, byte-deterministic.
    const { buildSldPdfString } = await import('../client/src/lib/nextera/pdfPlot');
    const sldCtx = { design, projectName: 'Hondo_SLD', config, meta: {} };
    const sldPdf = buildSldPdfString(sldCtx, sldFeeders);
    check('[52] SLD PDF is non-trivial and starts with %PDF', sldPdf.startsWith('%PDF') && sldPdf.length > 10000);
    check('[52] SLD PDF rebuild is byte-identical', sldPdf === buildSldPdfString(sldCtx, sldFeeders));

    // Schematic fits the plan rect (all ops inside with margin).
    const w = new DxfWriter();
    const rect = sldPlanRect(design);
    drawSldInto(w, model, rect);
    const eps = 1e-6;
    let inRect = true;
    for (const op of w.ops) {
      const pts: number[][] =
        op.kind === 'line' ? [[op.x1, op.y1], [op.x2, op.y2]] :
        op.kind === 'poly' ? op.pts :
        op.kind === 'arc' ? [[op.cx - op.r, op.cy - op.r], [op.cx + op.r, op.cy + op.r]] :
        op.kind === 'text' ? [[op.x, op.y]] : [];
      for (const p of pts) {
        if (p[0] < rect.minX - eps || p[0] > rect.maxX + eps || p[1] < rect.minY - eps || p[1] > rect.maxY + eps) {
          inRect = false;
        }
      }
    }
    check('[52] SLD schematic geometry stays inside the plan rect', inRect);
    check('[52] schematic width is positive and covers all feeders',
      sldSchematicWidth(model) >= model.feeders.length * 46);

    // Isolation: the default yard exports must not touch the SLD module.
    // (dxfSheets DOES import it now, but only inside the opt-in appended-
    // sheet branches — the registry itself must stay SLD/BOM-free.)
    const dxfSrc52 = readFileSync('client/src/lib/nextera/dxfExport.ts', 'utf8');
    const sheetsSrc52 = readFileSync('client/src/lib/nextera/dxfSheets.ts', 'utf8');
    check('[52] dxfExport does not import the sld module', !dxfSrc52.includes("./sld"));
    const registryLiteral = sheetsSrc52.match(/SHEET_REGISTRY: SheetDef\[\] = \[[\s\S]*?\];/)?.[0] ?? '';
    check('[52] SLD/BOM are NOT in the drawing-package registry (only appended when ctx opts in)',
      registryLiteral.length > 0 && !/sld|bom/i.test(registryLiteral) &&
      sheetsSrc52.includes('if (ctx.sldSheet)') && sheetsSrc52.includes('if (ctx.bomSheet)'));
    const yardDxfAfter = buildDesignDxfString(design, 'Hondo_Test');
    check('[52] yard DXF unchanged after SLD build', yardDxfAfter === dxf);

    // -----------------------------------------------------------------
    // [52b] Standards-compliant SLD upgrades: IEEE C37.2 device tags, the
    // opt-in IEC 60617 symbol set, fault duties from the short-circuit
    // study, and the NEC 706 / NFPA 855 notes block.
    // -----------------------------------------------------------------
    check('[52b] POI devices carry IEEE C37.2 tags (52-POI breaker, 89-POI disconnect)',
      model.poi.breakerTag === '52-POI' && model.poi.disconnectTag === '89-POI');
    check('[52b] every feeder breaker is tagged with its breaker-position name',
      model.feeders.every((f, i) => f.breakerTag === `52-${feederDisplayName(sldFeeders[i])}`));
    check('[52b] aux branch breaker tagged 52-AUX', !model.aux || model.aux.breakerTag === '52-AUX');
    check('[52b] DXF carries the device tags and metering callout',
      sldDxf.includes('52-POI') && sldDxf.includes('89-POI') &&
      sldDxf.includes(`52-${feederDisplayName(sldFeeders[0])}`) && sldDxf.includes('REVENUE METERING'));
    check('[52b] PCS step-up %Z callout present and flagged for verification',
      model.feeders.every(f => f.pcs.every(p => p.xfmrLine.includes('%Z') && p.xfmrLine.includes('VERIFY'))));
    // Provenance: no invented numerics — %Z prints only from project input.
    check('[52b] default sheet never prints an invented %Z number (states NOT PROVIDED)',
      model.feeders.every(f => f.pcs.every(p => p.xfmrLine.includes('NOT PROVIDED') && !/%Z = /.test(p.xfmrLine))) &&
      (!model.aux || model.aux.impedanceLine.includes('NOT PROVIDED')));
    {
      const zModel = buildSldModel(design, sldFeeders, config, { pcsXfmrZPct: 6.25, auxXfmrZPct: 5.5 });
      check('[52b] drafter-entered nameplate %Z prints with PROJECT INPUT provenance',
        zModel.feeders.every(f => f.pcs.every(p => p.xfmrLine.includes('%Z = 6.25') && p.xfmrLine.includes('PROJECT INPUT'))) &&
        !!zModel.aux && zModel.aux.impedanceLine.includes('%Z = 5.5') &&
        zModel.aux.impedanceLine.includes('PROJECT INPUT'));
    }
    check('[52b] notes block carries the NEC 706 / NFPA 855 / UL 9540 disclosures',
      model.notes.some(n => n.includes('NEC ART. 706') && n.includes('NFPA 855')) &&
      model.notes.some(n => n.includes('UL 9540')) &&
      model.notes.some(n => n.includes('706.15')) &&
      sldDxf.includes('IEEE C37.2'));
    check('[52b] default (no opts) model uses ANSI symbols', model.standard === 'ANSI');

    // IEC 60617 opt-in: different bytes, still deterministic, never mixed.
    const iecModel = buildSldModel(design, sldFeeders, config, { standard: 'IEC' });
    check('[52b] IEC option flips the model standard and the legend note',
      iecModel.standard === 'IEC' && iecModel.notes.some(n => n.includes('IEC 60617')));
    const iecDxf = buildSldDxfString(design, 'Hondo_SLD', sldFeeders, config, {}, { standard: 'IEC' });
    check('[52b] IEC sheet differs from the ANSI sheet (real alternate symbol set)', iecDxf !== sldDxf);
    check('[52b] IEC sheet rebuild is byte-identical',
      iecDxf === buildSldDxfString(design, 'Hondo_SLD', sldFeeders, config, {}, { standard: 'IEC' }));
    check('[52b] IEC sheet has no zero-sweep arcs and no NaN',
      !iecDxf.includes('NaN'));

    // Fault duties from the short-circuit study (IEEE 141 practice).
    {
      const { buildShortCircuitStudy, DEFAULT_SC_INPUTS } = await import('../client/src/lib/nextera/shortCircuit');
      const { inverterAmps } = await import('../client/src/lib/nextera/feeders');
      const study = buildShortCircuitStudy(
        sldFeeders, totalInv, inverterAmps(config.blockMW), DEFAULT_SC_INPUTS, { hasAux: true });
      const fModel = buildSldModel(design, sldFeeders, config, { study });
      check('[52b] study attaches a fault-duty line to the main bus',
        !!fModel.poi.faultLine && fModel.poi.faultLine.includes('KA SYM') && fModel.poi.faultLine.includes('KA PEAK'));
      check('[52b] study attaches fault-duty lines to every PCS MV terminal',
        fModel.feeders.every(f => f.pcs.every(p => !!p.faultLine && p.faultLine.includes('KA SYM'))));
      check('[52b] study attaches a fault-duty line to the 480 V aux bus',
        !!fModel.aux && !!fModel.aux.faultLine);
      const fDxf = buildSldDxfString(design, 'Hondo_SLD', sldFeeders, config, {}, { study });
      check('[52b] fault duties appear on the sheet only when the study is attached',
        fDxf.includes('FAULT DUTY:') && !sldDxf.includes('FAULT DUTY:'));
      check('[52b] fault-duty sheet rebuild is byte-identical',
        fDxf === buildSldDxfString(design, 'Hondo_SLD', sldFeeders, config, {}, { study }));
      check('[52b] aux %Z callout follows the study inputs',
        fModel.aux!.impedanceLine.includes(String(study.inputs.auxPctZ)));
    }

    // -----------------------------------------------------------------
    // [52c] BOM schedule sheet: rows verbatim from buildBomRows + the
    // rollup (exactly the Full BOM CSV line items), valid deterministic
    // AC1015 sheet + PDF twin.
    // -----------------------------------------------------------------
    {
      const { buildBomSheetLines, buildBomSheetDxfString, BOM_SHEET_TITLE_1 } =
        await import('../client/src/lib/nextera/bomSheet');
      const { buildCableScheduleRows } = await import('../client/src/lib/nextera/cableSchedule');
      const { buildBomRollup, fullBomToCsv } = await import('../client/src/lib/nextera/bomRollup');
      const lines = buildBomSheetLines(design, sldFeeders, config);
      check('[52c] BOM sheet has all core sections',
        ['MAJOR EQUIPMENT', 'CABLE', 'TERMINATIONS', 'CONDUIT', 'CIVIL']
          .every(s => lines.some(l => l.section === s)));
      // Line-for-line agreement with the Full BOM CSV (same builders); the CSV
      // additionally appends the PARTS (90% PKG) template section at the end.
      const csv = fullBomToCsv(design, config, sldFeeders,
        buildBomRollup(buildCableScheduleRows(design, sldFeeders), design, sldFeeders, null));
      const csvDataLines = csv.trim().split('\r\n').slice(1)
        .filter(l => !l.startsWith('PARTS (90% PKG),'));
      check('[52c] BOM sheet line count matches the Full BOM CSV (sans parts) exactly',
        lines.length === csvDataLines.length, `${lines.length} vs ${csvDataLines.length}`);
      check('[52c] BOM sheet descriptions match the CSV order verbatim',
        lines.every((l, i) => csvDataLines[i].includes(String(l.qty)) &&
          csvDataLines[i].startsWith(`${l.section},`)));
      const bomDxf = buildBomSheetDxfString(design, 'Hondo_BOM', sldFeeders, config, {});
      check('[52c] BOM sheet DXF valid structure, titled, no NaN',
        bomDxf.includes('ENTITIES') && bomDxf.trimEnd().endsWith('EOF') &&
        bomDxf.includes(BOM_SHEET_TITLE_1) && !bomDxf.includes('NaN'));
      check('[52c] BOM sheet DXF rebuild is byte-identical',
        bomDxf === buildBomSheetDxfString(design, 'Hondo_BOM', sldFeeders, config, {}));
      const { buildBomSheetPdfString } = await import('../client/src/lib/nextera/pdfPlot');
      const bomPdf = buildBomSheetPdfString(sldCtx, sldFeeders);
      check('[52c] BOM sheet PDF is non-trivial, deterministic',
        bomPdf.startsWith('%PDF') && bomPdf === buildBomSheetPdfString(sldCtx, sldFeeders));
    }

    // -----------------------------------------------------------------
    // [52d] Package opt-in: absent ctx fields ⇒ the DXF package is byte-
    // identical to the default; opting in APPENDS sheets 08/09 without
    // touching the first seven.
    // -----------------------------------------------------------------
    {
      const { buildDxfPackage } = await import('../client/src/lib/nextera/dxfSheets');
      const baseCtx = { design, projectName: 'Hondo_Test', config, meta: {}, feeders: sldFeeders, substation: sub };
      const defPkg = buildDxfPackage(baseCtx);
      const defPkg2 = buildDxfPackage({ ...baseCtx });
      check('[52d] default package is 7 sheets and deterministic',
        defPkg.length === 7 &&
        defPkg.every((s, i) => s.filename === defPkg2[i].filename && s.content === defPkg2[i].content));
      const optPkg = buildDxfPackage({ ...baseCtx, sldSheet: {}, bomSheet: {} });
      check('[52d] opting in appends SLD + both B018 BOM sheets as 08/09/10',
        optPkg.length === 10 &&
        optPkg[7].filename === '08_Single_Line_Diagram.dxf' &&
        optPkg[8].filename === '09_Bill_of_Materials_1.dxf' &&
        optPkg[9].filename === '10_Bill_of_Materials_2.dxf');
      check('[52d] the first seven sheets stay byte-identical when opting in',
        defPkg.every((s, i) => optPkg[i].filename === s.filename && optPkg[i].content === s.content));
      check('[52d] appended SLD sheet honors the SLD options',
        buildDxfPackage({ ...baseCtx, sldSheet: { options: { standard: 'IEC' } } })[7].content !==
        optPkg[7].content);

      // ezdxf structural audit on the two new sheets (same bar as [65]+).
      const { spawnSync } = await import('child_process');
      const probe = spawnSync('python3', ['-c', 'import ezdxf'], { timeout: 20000 });
      if (probe.status === 0) {
        const { writeFileSync: wf, mkdtempSync } = await import('fs');
        const os = await import('os');
        const dir = mkdtempSync(path.join(os.tmpdir(), 'sldbom-audit-'));
        const fSld = path.join(dir, 'sld.dxf');
        const fBom = path.join(dir, 'bom.dxf');
        wf(fSld, optPkg[7].content, 'utf8');
        wf(fBom, optPkg[8].content, 'utf8');
        const py = `
import sys
from ezdxf import recover
for f in ["${fSld.replace(/\\/g, '/')}", "${fBom.replace(/\\/g, '/')}"]:
    doc, auditor = recover.readfile(f)
    if auditor.has_errors:
        print(f"{f}: {len(auditor.errors)} audit errors", file=sys.stderr); sys.exit(1)
    if doc.dxfversion != "AC1015":
        print(f"{f}: version {doc.dxfversion}", file=sys.stderr); sys.exit(1)
sys.exit(0)
`;
        const audit = spawnSync('python3', ['-c', py], { timeout: 120000 });
        check('[52d] SLD + BOM sheets pass the ezdxf recover/audit as valid AC1015',
          audit.status === 0, audit.status === 0 ? undefined : String(audit.stderr));
      } else {
        console.log('  (ezdxf not available — SLD/BOM structural audit skipped)');
      }

      // [52e] Worker request path: the one-click package export goes through
      // handleDxfPackage (designWorkerCore). Absent request fields ⇒ byte-
      // identical to the direct default build; opting in appends 08/09.
      {
        const { handleDxfPackage } = await import('../client/src/lib/nextera/designWorkerCore');
        const baseReq = {
          kind: 'dxfPackage' as const,
          design, projectName: 'Hondo_Test',
          meta: {}, feeders: sldFeeders, substation: sub,
        };
        // The request carries no configId, so mirror that on the direct build.
        const noCfgCtx = { ...baseCtx, config: undefined };
        const wDef = handleDxfPackage(baseReq as any);
        check('[52e] worker default package matches the direct default build byte-for-byte',
          wDef.length === defPkg.length &&
          wDef.every((s, i) => {
            const d = buildDxfPackage(noCfgCtx);
            return s.filename === d[i].filename && s.content === d[i].content;
          }));
        const wOpt = handleDxfPackage({ ...baseReq, sldSheet: { options: { standard: 'IEC' } }, bomSheet: {} } as any);
        check('[52e] worker opt-in appends SLD + both BOM sheets as 08/09/10',
          wOpt.length === 10 &&
          wOpt[7].filename === '08_Single_Line_Diagram.dxf' &&
          wOpt[8].filename === '09_Bill_of_Materials_1.dxf' &&
          wOpt[9].filename === '10_Bill_of_Materials_2.dxf');
        check('[52e] worker opt-in leaves the first seven sheets byte-identical',
          wDef.every((s, i) => wOpt[i].filename === s.filename && wOpt[i].content === s.content));
        check('[52e] worker SLD sheet honors the request options (IEC differs from ANSI)',
          wOpt[7].content === buildDxfPackage({ ...noCfgCtx, sldSheet: { options: { standard: 'IEC' } } })[7].content);
        // UI wiring scan: the one-click package/plot handlers must thread the
        // opt-in through (checkbox-gated), never unconditionally.
        const panelSrc52e = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
        check('[52e] package export threads the checkbox-gated sldSheet/bomSheet into the worker',
          /buildDxfPackageInWorker\([\s\S]*?includeSldBom \? \{ options: sldOpts \} : null,\s*includeSldBom \? \{ options: \{ groundingPlan \} \} : null/.test(panelSrc52e));
        check('[52e] PDF plot export threads the same opt-in into buildPdfPlot',
          /\.\.\.\(includeSldBom\s*\?\s*\{ sldSheet: \{ options: sldOpts \}, bomSheet: \{ options: \{ groundingPlan \} \} \}/.test(panelSrc52e));
      }
    }
  }

  // ---------------------------------------------------------------
  // [53] The 3D preview's ContourOverlay (TerrainMesh.tsx) and the DXF
  // export path (contoursForDxf, called from DesignControlPanel) both honor
  // the drafter's contourIntervalFt preference (0 = auto). If either side
  // changes how "Auto" or an explicit interval is resolved without the
  // other, drafters would see one contour ladder on screen and export
  // another. Source-scan (same pattern as the configureGroundTexture scan)
  // pins both resolution expressions to each other, plus the wiring that
  // feeds the same store preference to both call sites; a behavioral check
  // proves contoursForDxf's output matches the overlay's formula applied to
  // the same grid.
  {
    console.log('\n[53] 3D contour overlay and DXF export resolve the interval identically');
    const T53 = await import('../client/src/lib/nextera/terrain');
    const meshSrc = readFileSync('client/src/components/TerrainMesh.tsx', 'utf8');
    const terrSrc = readFileSync('client/src/lib/nextera/terrain.ts', 'utf8');
    const panelSrc53 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
    const sceneSrc53 = readFileSync('client/src/components/DesignScene.tsx', 'utf8');

    // Isolate the two function bodies so the expression match can't hit an
    // unrelated occurrence elsewhere in either file.
    const sliceFn = (src: string, marker: string) => {
      const start = src.indexOf(marker);
      if (start < 0) return '';
      const tail = src.slice(start);
      const end = tail.search(/\n(?:export )?function |\nexport const /);
      return end > 0 ? tail.slice(0, end) : tail;
    };
    const overlaySrc = sliceFn(meshSrc, 'function ContourOverlay');
    const dxfFnSrc = sliceFn(terrSrc, 'export function contoursForDxf');
    check('[53] found ContourOverlay in TerrainMesh.tsx', overlaySrc.length > 0);
    check('[53] found contoursForDxf in terrain.ts', dxfFnSrc.length > 0);

    // Interval resolution parity: extract the `const interval = ...`
    // expression from both sides and require them to be textually identical
    // (whitespace-normalized). True parity, not a pinned rule: if both sides
    // change together the test stays green; if only one changes, it fails.
    const resolveExpr = (src: string) => {
      const m = src.match(/const interval\s*=\s*([^;]+);/);
      return m ? m[1].replace(/\s+/g, ' ').trim() : '';
    };
    const overlayExpr = resolveExpr(overlaySrc);
    const dxfExpr = resolveExpr(dxfFnSrc);
    check('[53] both sides resolve the interval with the SAME expression',
      overlayExpr !== '' && overlayExpr === dxfExpr,
      `overlay(${overlayExpr || 'missing'}) vs dxf(${dxfExpr || 'missing'})`);
    // The shared expression must honor an explicit interval and fall back to
    // the shared auto ladder — never a private re-derivation.
    check('[53] shared expression: explicit interval wins, auto uses pickContourInterval',
      /intervalFt\s*>\s*0\s*\?\s*intervalFt\s*:\s*pickContourInterval\(/.test(overlayExpr),
      overlayExpr);

    // Auto-interval input parity: both sides must derive min/max elevation
    // the same way (finite-only scan of grid.valuesFt) so the auto ladder
    // sees the same relief on both paths.
    const minMaxScan = (src: string) =>
      /for\s*\(const v of grid\.valuesFt\)\s*\{\s*if\s*\(!Number\.isFinite\(v\)\)\s*continue;/.test(
        src.replace(/\s+/g, ' '));
    check('[53] overlay derives min/max with a finite-only scan of grid.valuesFt', minMaxScan(overlaySrc));
    check('[53] contoursForDxf derives min/max with the same finite-only scan', minMaxScan(dxfFnSrc));
    check('[53] both feed pickContourInterval(minV, maxV)',
      overlaySrc.includes('pickContourInterval(minV, maxV)') &&
      dxfFnSrc.includes('pickContourInterval(minV, maxV)'));
    check('[53] both hand the resolved interval to computeContours',
      /computeContours\(grid,\s*rect,\s*interval\)/.test(overlaySrc) &&
      /computeContours\(grid,\s*rect,\s*interval\)/.test(dxfFnSrc));

    // Wiring: the SAME store preference reaches both call sites. The scene
    // reads contourIntervalFt from the store and passes it to TerrainMesh,
    // TerrainMesh forwards it as the overlay's intervalFt prop, and the
    // panel's DXF export passes it straight to contoursForDxf.
    check('[53] scene reads contourIntervalFt from the store and passes it to TerrainMesh',
      /const contourIntervalFt = useDesignStore\(s => s\.contourIntervalFt\)/.test(sceneSrc53) &&
      /contourIntervalFt=\{contourIntervalFt\}/.test(sceneSrc53));
    check('[53] TerrainMesh forwards contourIntervalFt to the overlay intervalFt prop',
      /intervalFt=\{contourIntervalFt\}/.test(meshSrc));
    check('[53] DXF export path passes the same preference to contoursForDxf',
      /contoursForDxf\(terrainYard,\s*d\.boundary\.origin,\s*contourIntervalFt\)/.test(panelSrc53));

    // Behavioral proof on a synthetic ramp: applying the overlay's formula
    // (explicit wins, else pickContourInterval on finite min/max) to the
    // grid gives exactly the interval contoursForDxf exports, for auto and
    // for an explicit pick.
    const o51 = { lat: 29.3, lon: -99.1 };
    const fpl = 364000 * Math.cos((o51.lat * Math.PI) / 180);
    const r51 = { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };
    const n51 = 32;
    const vals51: number[] = [];
    for (let r = 0; r < n51; r++) {
      const y = r51.maxY - (r + 0.5) * ((r51.maxY - r51.minY) / n51);
      for (let c = 0; c < n51; c++) vals51.push(0.04 * (r51.minX + (c + 0.5) * ((r51.maxX - r51.minX) / n51)) + 0.001 * y);
    }
    const grid51 = {
      width: n51, height: n51,
      bounds: {
        west: o51.lon + r51.minX / fpl, east: o51.lon + r51.maxX / fpl,
        south: o51.lat + r51.minY / 364000, north: o51.lat + r51.maxY / 364000,
      },
      valuesFt: vals51, source: 'synthetic', resolutionM: 10, noDataCount: 0,
    } as any;
    const overlayResolve = (intervalFt: number) => {
      let minV = Infinity, maxV = -Infinity;
      for (const v of grid51.valuesFt) {
        if (!Number.isFinite(v)) continue;
        if (v < minV) minV = v;
        if (v > maxV) maxV = v;
      }
      return intervalFt > 0 ? intervalFt : T53.pickContourInterval(minV, maxV);
    };
    for (const pick of [0, 0.5, 2, 10]) {
      const exported = T53.contoursForDxf(grid51, o51, pick);
      check(`[53] interval pick ${pick || 'auto'}: export matches the overlay's resolution`,
        exported !== null && exported.intervalFt === overlayResolve(pick),
        `export ${exported?.intervalFt} vs overlay ${overlayResolve(pick)}`);
    }
  }

  // ---------------------------------------------------------------
  // [54] Cable & conduit schedule: one row per non-ref routed run plus one
  // per MV feeder circuit, lengths tied 1:1 to routed geometry with a
  // configurable slack factor shown separately, NEC Chapter 9 conduit
  // sizing with hand-checkable fill %, deterministic CSV/DXF exports, and
  // the default yard DXF untouched.
  {
    console.log('\n[54] Cable & conduit schedule (rows, slack, conduit fill, exports)');
    const CS = await import('../client/src/lib/nextera/cableSchedule');
    const { generateFeeders } = await import('../client/src/lib/nextera/feeders');
    const { MV_CONDUCTOR_OD_IN, CONDUIT_SCH40_ID_IN, necMaxFill } =
      await import('../client/src/lib/nextera/catalog');

    const sub54 = { x: 2500, y: 0 };
    const feeders54 = generateFeeders(design, sub54, config.blockMW);
    const rows = CS.buildCableScheduleRows(design, feeders54);

    // Row counts: every non-ref cable run + every feeder circuit, no more.
    const nonRef = design.cables.filter(c => !c.ref);
    check('[54] one row per non-ref run + one per feeder',
      rows.length === nonRef.length + feeders54.length,
      `${rows.length} vs ${nonRef.length} + ${feeders54.length}`);
    check('[54] reference-only runs (dc-aug/mv-future) are excluded',
      rows.every(r => !r.circuitId.startsWith('DC-AUG') && !r.circuitId.startsWith('MV-FUTURE')));
    const ids = rows.map(r => r.circuitId);
    check('[54] circuit IDs are unique and deterministic', new Set(ids).size === ids.length);

    // Lengths tie to routed geometry (raw) and slack is applied on top.
    const yardRows = rows.filter(r => !r.circuitId.startsWith('FDR-'));
    const runById = new Map(nonRef.map(c => [c.id.toUpperCase(), c]));
    check('[54] every yard row raw length matches its routed polyline (0.1 ft rounding)',
      yardRows.every(r => {
        const run = runById.get(r.circuitId);
        return !!run && Math.abs(r.rawLengthFt - CS.polylineLengthFt(run.pts)) < 0.06;
      }));
    check('[54] default slack is 10% and total = raw * 1.1 (0.1 ft rounding)',
      rows.every(r => r.slackPct === CS.DEFAULT_SLACK_PCT &&
        Math.abs(r.totalLengthFt - r.rawLengthFt * 1.1) < 0.06));
    const rows25 = CS.buildCableScheduleRows(design, feeders54, { slackPct: 25 });
    check('[54] configurable slack: 25% applies to every row',
      rows25.every(r => r.slackPct === 25 && Math.abs(r.totalLengthFt - r.rawLengthFt * 1.25) < 0.07));
    check('[54] slack changes totals but never raw lengths',
      rows25.every((r, i) => r.rawLengthFt === rows[i].rawLengthFt));

    // Feeder rows carry the sized conductor from the feeder study.
    const fdrRows = rows.filter(r => r.circuitId.startsWith('FDR-'));
    check('[54] feeder rows carry size + material + routed length',
      fdrRows.every((r, i) => {
        const f = feeders54[i];
        // Parallel sets each run in their own conduit, so the scheduled
        // length is the route length TIMES the number of sets.
        const sets = Math.max(1, f.parallelSets || 1);
        return r.conductor.includes(String(f.size)) &&
          r.conductor.includes(f.material === 'Al' ? 'AL' : 'CU') &&
          (sets === 1 || r.conductor.includes(`${sets} PARALLEL SETS`)) &&
          Math.abs(r.rawLengthFt - f.totalLengthFt * sets) < 0.06 * sets + 0.06;
      }));

    // Hand-checkable fill math: (3) 500 kcmil MV, OD 1.64" in 4" Sch 40
    // (ID 3.998"): fill = 3*pi*0.82^2 / (pi*1.999^2) = 50.5% > 40%, so the
    // 4" fails and 5" (ID 5.016") gives 3*0.82^2/2.508^2 = 32.1% <= 40%.
    const mv500 = CS.sizeConduit(MV_CONDUCTOR_OD_IN['500'], 3);
    const expFill = (3 * Math.PI * (1.64 / 2) ** 2) / (Math.PI * (5.016 / 2) ** 2) * 100;
    check('[54] (3) 500 kcmil MV lands in 5" Sch 40', mv500.trade === '5"', mv500.trade);
    check('[54] fill % matches hand math (32.1%)',
      Math.abs(mv500.fillPct - Math.round(expFill * 10) / 10) < 0.05,
      `${mv500.fillPct} vs ${expFill.toFixed(1)}`);
    check('[54] NEC Table 1 limits: 53% (1), 31% (2), 40% (3+)',
      necMaxFill(1) === 0.53 && necMaxFill(2) === 0.31 && necMaxFill(3) === 0.4 && necMaxFill(4) === 0.4);
    check('[54] every row fill respects its NEC limit (or is the max trade size)',
      rows.every(r => r.fillPct <= necMaxFill(r.conductors) * 100 + 0.05 ||
        r.conduit === CONDUIT_SCH40_ID_IN[CONDUIT_SCH40_ID_IN.length - 1].trade));
    check('[54] conduit trade sizes come from the Sch 40 catalog table',
      rows.every(r => CONDUIT_SCH40_ID_IN.some(c => c.trade === r.conduit)));

    // Endpoints: DC rows run container -> its block PCS; no blank endpoints.
    const eqById54 = new Map(design.equipment.map(e => [e.id, e]));
    const dcRows = rows.filter(r => r.cableClass === 'DC');
    check('[54] schedule has DC, MV, LVAC and FIBER rows',
      (['DC', 'MV', 'LVAC', 'FIBER'] as const).every(c => rows.some(r => r.cableClass === c)));
    check('[54] every row has non-empty from/to/trench text',
      rows.every(r => r.from.length > 0 && r.to.length > 0 && r.trenchRef.length > 0));
    check('[54] DC rows never fall back to "-" endpoints',
      dcRows.every(r => r.from !== '-' && r.to !== '-'));

    // CSV: header + one line per row, CRLF, byte-deterministic.
    const csv = CS.cableScheduleToCsv(rows);
    check('[54] CSV has header + one line per row (CRLF)',
      csv.split('\r\n').filter(l => l.length).length === rows.length + 1);
    check('[54] CSV rebuild is byte-identical',
      csv === CS.cableScheduleToCsv(CS.buildCableScheduleRows(design, feeders54)));

    // DXF table sheet: valid, titled, deterministic, geometry inside rect.
    const csDxf = CS.buildCableScheduleDxfString(design, 'Hondo_CS', feeders54, config, {});
    check('[54] schedule DXF has HEADER/TABLES/ENTITIES sections and EOF',
      csDxf.includes('HEADER') && csDxf.includes('TABLES') &&
      csDxf.includes('ENTITIES') && csDxf.trimEnd().endsWith('EOF'));
    check('[54] schedule DXF titled CABLE & CONDUIT SCHEDULE',
      csDxf.includes('CABLE & CONDUIT SCHEDULE'));
    check('[54] schedule DXF has no NaN', !csDxf.includes('NaN'));
    check('[54] schedule DXF rebuild is byte-identical',
      csDxf === CS.buildCableScheduleDxfString(design, 'Hondo_CS', feeders54, config, {}));

    // Isolation: default exports untouched by the schedule module.
    const dxfSrc54 = readFileSync('client/src/lib/nextera/dxfExport.ts', 'utf8');
    const sheetsSrc54 = readFileSync('client/src/lib/nextera/dxfSheets.ts', 'utf8');
    check('[54] dxfExport does not import the cableSchedule module',
      !dxfSrc54.includes('cableSchedule'));
    check('[54] cableSchedule is NOT in the drawing-package registry',
      !sheetsSrc54.includes('cableSchedule'));
    const yardDxfAfter54 = buildDesignDxfString(design, 'Hondo_Test');
    check('[54] yard DXF unchanged after schedule build', yardDxfAfter54 === dxf);
  }

  // ---------------------------------------------------------------
  // [55] BOM rollup consumes the schedule rows EXACTLY: cable LF sums equal
  // per-circuit schedule sums (same slack), termination counts follow
  // topology (2 per run + 2 per FJB pass-through), conduit sticks come from
  // the schedule's raw lengths, and the full-BOM CSV is deterministic.
  {
    console.log('\n[55] BOM rollup ties to the cable schedule (priced-quantity ready)');
    const CS = await import('../client/src/lib/nextera/cableSchedule');
    const BR = await import('../client/src/lib/nextera/bomRollup');
    const { generateFeeders } = await import('../client/src/lib/nextera/feeders');
    const { roadRegionAreaSqFt } = await import('../client/src/lib/nextera/scenarios');
    const { summarizeCableLengths } = await import('../client/src/lib/nextera/cableRouting');
    const { buildBomRows, bomToCsv } = await import('../client/src/lib/nextera/bom');

    const sub55 = { x: 2500, y: 0 };
    const feeders55 = generateFeeders(design, sub55, config.blockMW);
    const rows55 = CS.buildCableScheduleRows(design, feeders55);
    const rollup = BR.buildBomRollup(rows55, design, feeders55);

    // Cable LF: rollup sums equal per-circuit schedule sums per group.
    const groupSum = new Map<string, number>();
    for (const r of rows55) {
      const k = `${r.cableClass} CABLE ${r.conductor}`;
      groupSum.set(k, (groupSum.get(k) || 0) + r.totalLengthFt);
    }
    check('[55] one rollup line per class+conductor group',
      rollup.cable.length === groupSum.size,
      `${rollup.cable.length} vs ${groupSum.size}`);
    check('[55] every cable rollup qty = ceil(sum of schedule totals) for its group',
      rollup.cable.every(l => {
        const key = Array.from(groupSum.keys()).find(k => l.description.startsWith(k));
        return !!key && l.qty === Math.ceil(groupSum.get(key)!);
      }));
    const rollupLf = rollup.cable.reduce((s, l) => s + l.qty, 0);
    const schedLf = Array.from(groupSum.values()).reduce((s, v) => s + Math.ceil(v), 0);
    check('[55] total rollup LF equals total schedule LF (slack included, no recompute)',
      rollupLf === schedLf, `${rollupLf} vs ${schedLf}`);

    // Terminations: 2 per run + 2 per FJB pass-through feeder.
    const termTotal = rollup.terminations.reduce((s, l) => s + l.qty, 0);
    const fjbCount = feeders55.filter(f => f.fjbId).length;
    check('[55] termination count = 2 per row + 2 per FJB feeder',
      termTotal === 2 * rows55.length + 2 * fjbCount,
      `${termTotal} vs ${2 * rows55.length + 2 * fjbCount}`);
    const mvTerm = rollup.terminations.find(l => l.description.startsWith('MV'));
    const mvRows = rows55.filter(r => r.cableClass === 'MV').length;
    check('[55] MV terminations carry the FJB splice pairs',
      !!mvTerm && mvTerm.qty === 2 * mvRows + 2 * fjbCount);

    // Conduit sticks: per trade size, raw LF + waste over 20 ft sticks.
    const conduitLf = new Map<string, number>();
    for (const r of rows55) conduitLf.set(r.conduit, (conduitLf.get(r.conduit) || 0) + r.rawLengthFt);
    check('[55] one conduit line per trade size in the schedule',
      rollup.conduit.length === conduitLf.size);
    check('[55] stick counts = ceil(raw LF * 1.05 / 20) per trade size',
      rollup.conduit.every(l => {
        const trade = Array.from(conduitLf.keys()).find(t => l.description.startsWith(t));
        return !!trade && l.qty === Math.ceil((conduitLf.get(trade)! * 1.05) / BR.CONDUIT_STICK_FT);
      }));

    // Civil: trench LF and road/surfacing quantities from the design.
    // CorridorTrenches are the canonical physical records for shared
    // LVAC/fiber runs.  Omitting them here compares the BOM's physical civil
    // quantity against the older cable-polyline approximation instead.
    const trenchLf = summarizeCableLengths(
      design.cables, design.trench, design.corridorTrenches,
    ).trench;
    if (trenchLf > 0) {
      const t = rollup.civil.find(l => l.description.includes('TRENCH'));
      check('[55] civil trench LF matches the routed trench band',
        !!t && t.qty === Math.ceil(trenchLf),
        `${t?.qty ?? 'missing'} LF vs ${Math.ceil(trenchLf)} LF routed`);
    }
    const roadSf = roadRegionAreaSqFt(design);
    if (roadSf > 0) {
      const rd = rollup.civil.find(l => l.unit === 'SF');
      check('[55] civil road area matches roadRegionAreaSqFt',
        !!rd && rd.qty === Math.ceil(roadSf));
    }
    if (design.surfacing && design.surfacing.areaSqFt > 0) {
      const sf = rollup.civil.find(l => l.unit === 'TON');
      check('[55] civil surfacing tons match the surfacing plan',
        !!sf && sf.qty === Math.ceil(design.surfacing.tons));
    }

    // Full BOM CSV: sectioned, includes existing equipment rows, CRLF,
    // byte-deterministic; and the plain equipment BOM CSV is unchanged.
    const fullCsv = BR.fullBomToCsv(design, config, feeders55, rollup);
    check('[55] full BOM CSV has all five sections',
      ['MAJOR EQUIPMENT', 'CABLE,', 'TERMINATIONS,', 'CONDUIT,', 'CIVIL,']
        .every(s => fullCsv.includes(s)));
    const bomRows55 = buildBomRows(design, config, feeders55);
    check('[55] full BOM carries every existing equipment row',
      bomRows55.every(r => fullCsv.includes(r.description.includes(',') ? `"${r.description.replace(/"/g, '""')}"` : r.description)));
    check('[55] full BOM CSV rebuild is byte-identical',
      fullCsv === BR.fullBomToCsv(design, config, feeders55,
        BR.buildBomRollup(CS.buildCableScheduleRows(design, feeders55), design, feeders55)));
    check('[55] existing BOM CSV output is unchanged by the rollup module',
      bomToCsv(bomRows55) === bomToCsv(buildBomRows(design, config, feeders55)));

    // Grounding section: opt-in, sourced from buildGroundingPlan (never recomputed).
    check('[55] rollup grounding section is empty when no plan is passed',
      rollup.grounding.length === 0);
    check('[55] full BOM CSV has no GROUNDING section when grounding is off',
      !fullCsv.includes('GROUNDING,'));
    check('[55] explicit null grounding plan gives a byte-identical full BOM CSV',
      BR.fullBomToCsv(design, config, feeders55,
        BR.buildBomRollup(rows55, design, feeders55, null)) === fullCsv);
    const gplan55 = buildGroundingPlan(design);
    check('[55] grounding plan builds for the BOM grounding test', !!gplan55);
    if (gplan55) {
      const gRollup = BR.buildBomRollup(rows55, design, feeders55, gplan55);
      const gs = gplan55.summary;
      check('[55] grounding section has conductor LF, rods, and exothermic lines',
        gRollup.grounding.length === 3);
      const condLine = gRollup.grounding.find(l => l.unit === 'LF');
      check('[55] bare copper LF = ceil(plan totalConductorFt), never recomputed',
        !!condLine && condLine.qty === Math.ceil(gs.totalConductorFt)
        && condLine.description.includes('BARE COPPER'));
      const rodLine = gRollup.grounding.find(l => l.description.startsWith('GROUND RODS'));
      check('[55] ground rod qty = plan rodCount at the plan rod spacing',
        !!rodLine && rodLine.qty === gs.rodCount
        && rodLine.description.includes(`${gs.rodSpacingFt} FT`));
      const exoLine = gRollup.grounding.find(l => l.description.startsWith('EXOTHERMIC'));
      check('[55] exothermic connections = rodCount + tapCount + crossingCount from the plan',
        !!exoLine && exoLine.qty === gs.rodCount + gs.tapCount + gs.crossingCount);
      check('[55] other rollup sections unchanged by grounding plan',
        JSON.stringify({ ...gRollup, grounding: [] }) === JSON.stringify(rollup));
      const gCsv = BR.fullBomToCsv(design, config, feeders55, gRollup);
      check('[55] full BOM CSV gains a GROUNDING section when the plan is on',
        gCsv.includes('GROUNDING,'));
      // (The PARTS (90% PKG) section is always the final section, so the
      // grounding rows insert between CIVIL and PARTS rather than appending
      // at the very end.)
      const partsAt = (s: string) => s.indexOf('PARTS (90% PKG),');
      check('[55] grounding rows insert after CIVIL, before the PARTS section; rest identical',
        gCsv.startsWith(fullCsv.slice(0, partsAt(fullCsv))) &&
        gCsv.slice(partsAt(gCsv)) === fullCsv.slice(partsAt(fullCsv)) &&
        gCsv.indexOf('GROUNDING,') > gCsv.indexOf('CIVIL,') &&
        gCsv.indexOf('GROUNDING,') < partsAt(gCsv));
      check('[55] grounding full BOM CSV rebuild is byte-identical',
        BR.fullBomToCsv(design, config, feeders55,
          BR.buildBomRollup(rows55, design, feeders55, buildGroundingPlan(design))) === gCsv);

      // Plain BOM CSV grounding lines: quantities verbatim from the
      // GroundingPlan summary; default output byte-identical when off.
      const { buildGroundingBomRows } = await import('../client/src/lib/nextera/bom');
      const gRows = buildGroundingBomRows(gplan55);
      check('[55] plain-BOM grounding rows are conductor LF + rod EA lines',
        gRows.length === 2 && gRows[0].unit === 'LF' && gRows[1].unit === 'EA');
      check('[55] plain-BOM grounding conductor qty = ceil(summary.totalConductorFt)',
        gRows[0].qty === Math.ceil(gplan55.summary.totalConductorFt));
      check('[55] plain-BOM grounding conductor description carries loop/tap breakdown verbatim',
        gRows[0].description.includes(`LOOP ${Math.ceil(gplan55.summary.loopLengthFt)} LF`) &&
        gRows[0].description.includes(`${gplan55.summary.tapCount} TAPS ${Math.ceil(gplan55.summary.tapLengthFt)} LF`));
      check('[55] plain-BOM grounding rod qty = summary.rodCount verbatim',
        gRows[1].qty === gplan55.summary.rodCount &&
        gRows[1].description.includes(`${gplan55.summary.rodSpacingFt}'`));
      const bomWithG = buildBomRows(design, config, feeders55, gplan55);
      check('[55] BOM with grounding = default rows + grounding rows appended',
        JSON.stringify(bomWithG) === JSON.stringify([...bomRows55, ...gRows]));
      check('[55] default plain BOM CSV byte-identical when grounding is off',
        bomToCsv(buildBomRows(design, config, feeders55)) === bomToCsv(bomRows55) &&
        bomToCsv(buildBomRows(design, config, feeders55, null)) === bomToCsv(bomRows55));
    }
  }

  // ---------------------------------------------------------------
  // [56] POI data sheet: interconnection one-pager pulled verbatim from the
  // design/catalog/feeder model, screening short-circuit math, deterministic
  // one-page PDF, and zero impact on the default exports.
  {
    console.log('\n[56] POI data sheet (interconnection one-pager)');
    const POI = await import('../client/src/lib/nextera/poiDataSheet');
    const { GE_FLEX_1571_SPEC, LG_JF2_SPEC } = await import('../client/src/lib/nextera/catalog');
    const sub56 = { x: 2500, y: 0 };
    const feeders56 = generateFeeders(design, sub56, config.blockMW);
    const now56 = new Date('2026-03-01T12:00:00Z');
    const tb56 = { projectName: 'Hondo Storage', location: 'Hondo, TX', drafter: 'ECI', revision: 'B', date: '2026-03-01' };
    const model = POI.buildPoiDataSheetModel(design, config, {
      titleBlock: tb56, feeders: feeders56, substation: sub56, now: now56,
    });

    // Project identity comes from the title block, geometry from the boundary
    check('[56] project fields from the title block', model.project.projectName === 'Hondo Storage' &&
      model.project.location === 'Hondo, TX' && model.project.revision === 'B' && model.project.drafter === 'ECI');
    check('[56] parcel acreage matches the boundary', model.project.parcelAreaAcres === design.boundary.areaAcres);
    check('[56] generatedAt uses the injected clock (fixed UTC format)',
      model.generatedAt === '2026-03-01 12:00 UTC');
    const modelNoTb = POI.buildPoiDataSheetModel(design, config, { feeders: feeders56 });
    check('[56] project name falls back to the boundary name',
      modelNoTb.project.projectName === design.boundary.name);

    // Rating & equipment verbatim from the design/catalog
    check('[56] rating matches the design', model.rating.achievedMW === design.achievedMW &&
      model.rating.achievedMWh === design.achievedMWh && model.rating.blocksPlaced === design.blocksPlaced);
    const invCount = design.equipment.filter(e => e.kind === 'inverter').length;
    const bessCount = design.equipment.filter(e => e.kind === 'bess').length;
    check('[56] inverter make/model/rating/qty from the catalog spec',
      model.inverter.manufacturer === GE_FLEX_1571_SPEC.manufacturer &&
      model.inverter.model === GE_FLEX_1571_SPEC.model &&
      model.inverter.rating === GE_FLEX_1571_SPEC.rating &&
      model.inverter.qty === invCount);
    check('[56] storage container model/qty from catalog + design',
      model.storage.containerQty === bessCount &&
      model.storage.containerModel === `${LG_JF2_SPEC.manufacturer} ${LG_JF2_SPEC.model}` &&
      model.storage.containerMWh === config.containerMWh);

    // Interconnection: 34.5 kV, feeder rows 1:1 with the routed circuits
    check('[56] interconnection voltage is 34.5 kV', model.interconnection.voltageKV === 34.5);
    check('[56] one feeder summary row per routed feeder',
      model.interconnection.feederCount === feeders56.length &&
      model.interconnection.feeders.length === feeders56.length &&
      model.interconnection.feeders.every((r, i) =>
        r.feeder === feederDisplayName(feeders56[i]) &&
        r.pcsCount === feeders56[i].inverterIds.length &&
        r.amps === feeders56[i].amps &&
        r.conductor === `${feeders56[i].size} kcmil ${feeders56[i].material}`));
    const aggAmps = feeders56.reduce((s, f) => s + f.amps, 0);
    check('[56] aggregate bus amps = sum of feeder amps',
      Math.abs(model.interconnection.totalFeederAmps - aggAmps) < 1e-9);

    // Screening short-circuit contribution: inverter-limited, documented multiplier
    const unitA = inverterAmps(config.blockMW);
    check('[56] unit amps = inverterAmps(blockMW)', Math.abs(model.inverter.unitAmps - unitA) < 1e-9);
    check('[56] screening SC amps = qty × rated amps × 1.2 multiplier',
      model.shortCircuit.multiplier === POI.POI_SC_SCREENING_MULTIPLIER &&
      POI.POI_SC_SCREENING_MULTIPLIER === 1.2 &&
      Math.abs(model.shortCircuit.totalRatedAmps - invCount * unitA) < 1e-9 &&
      Math.abs(model.shortCircuit.screeningAmps - invCount * unitA * 1.2) < 1e-9);
    check('[56] screening MVA = √3 × 34.5 kV × screening amps',
      Math.abs(model.shortCircuit.screeningMVA -
        (Math.sqrt(3) * MV_VOLTAGE * model.shortCircuit.screeningAmps) / 1e6) < 1e-9);

    // Pure content layer: 4 sections, PF range + screening disclaimer present
    const sections = POI.poiSections(model);
    check('[56] four numbered sections', sections.length === 4 &&
      sections.map(s => s.id).join(',') === 'project,rating,interconnection,short-circuit');
    const allText = sections.flatMap(s => s.rows.flat()).join('\n');
    check('[56] power factor range stated', allText.includes('0.95 leading to 0.95 lagging'));
    check('[56] short-circuit clearly labeled screening only',
      allText.includes('SCREENING ESTIMATE ONLY'));
    check('[56] interconnection section lists every feeder with conductor size',
      sections.find(s => s.id === 'interconnection')!.rows
        .filter(r => r[0].startsWith('Feeder #')).length === feeders56.length);
    check('[56] sections rebuild is deterministic',
      JSON.stringify(sections) === JSON.stringify(POI.poiSections(
        POI.buildPoiDataSheetModel(design, config, { titleBlock: tb56, feeders: feeders56, substation: sub56, now: now56 }))));

    // One-page PDF, pinned metadata, byte-identical rebuilds
    const pdf = POI.buildPoiPdf(model).output();
    check('[56] output is a single-page PDF',
      pdf.startsWith('%PDF') && (pdf.match(/\/Type \/Page\b(?!s)/g) || []).length === 1);
    check('[56] PDF metadata pinned (no live timestamp)', pdf.includes('20260101000000'));
    check('[56] PDF rebuild is byte-identical', POI.buildPoiPdf(model).output() === pdf);

    // Additive module: default yard DXF untouched
    check('[56] yard DXF unchanged after POI build',
      buildDesignDxfString(design, 'Hondo_Test') === dxf);
    const dxfExportSrc = readFileSync(path.resolve('client/src/lib/nextera/dxfExport.ts'), 'utf8');
    check('[56] dxfExport does not import the poiDataSheet module',
      !dxfExportSrc.includes('poiDataSheet'));
  }


  // ---------------------------------------------------------------
  {
    console.log('\n[57] Grounding grid screening layout (opt-in DXF layer)');

    // Default export byte-identity: no grounding argument -> unchanged
    check('[57] default DXF byte-identical with grounding feature present',
      buildDesignDxfString(design, 'Hondo_Test') === dxf);
    check('[57] default DXF has no grounding layer or note',
      !dxf.includes('EQUIP - GROUNDING') && !dxf.includes('GROUNDING (SCREENING)'));
    check('[57] explicit null grounding is also byte-identical',
      buildDesignDxfString(design, 'Hondo_Test', undefined, undefined, undefined, undefined, undefined, null) === dxf);

    const gplan = buildGroundingPlan(design);
    check('[57] grounding plan builds for the Hondo design', !!gplan);
    if (gplan) {
      // Determinism
      check('[57] plan rebuild is deterministic',
        JSON.stringify(buildGroundingPlan(design)) === JSON.stringify(gplan));

      // [463] Envelope scoping: loops[] present, primary loop is the largest,
      // and for the single-island Hondo yard the plan carries exactly one
      // envelope loop that is meaningfully SMALLER than the legacy
      // full-yard fence-inset loop (grid confined to the equipment island).
      const gLoops = gplan.loops;
      check('[463] plan exposes loops[] with the primary loop first-class',
        Array.isArray(gLoops) && gLoops.length >= 1 && gLoops.includes(gplan.loop));
      check('[463] Hondo is a single equipment island (one envelope loop)',
        gLoops.length === 1, `${gLoops.length} loops`);
      {
        const insetYard = insetPolygon(design.fence, GROUND_LOOP_INSET_FT);
        const areaOf = (poly: Pt[]) => Math.abs(poly.reduce((sAcc, a, i) => {
          const b = poly[(i + 1) % poly.length];
          return sAcc + a.x * b.y - b.x * a.y;
        }, 0)) / 2;
        check('[463] envelope area is well below the full-yard inset loop area',
          gplan.summary.gridAreaSqFt < 0.75 * areaOf(insetYard),
          `${gplan.summary.gridAreaSqFt} vs yard ${Math.round(areaOf(insetYard))}`);
        // No conductor outside the envelope (+ tiny tolerance): every loop
        // vertex, grid endpoint, rod, crossing and tap source stays inside
        // the combined loop bounding boxes.
        const MARGIN = 0.1;
        const inSomeEnvelope = (p: Pt) => gLoops.some(lp => {
          const xs = lp.map(q => q.x), ys = lp.map(q => q.y);
          return p.x >= Math.min(...xs) - MARGIN && p.x <= Math.max(...xs) + MARGIN &&
            p.y >= Math.min(...ys) - MARGIN && p.y <= Math.max(...ys) + MARGIN;
        });
        check('[463] no grid conductor outside the envelope bounds',
          gplan.grid.every(([a, b]) => inSomeEnvelope(a) && inSomeEnvelope(b)));
        check('[463] rods, crossings, wells and tap sources stay inside the envelope',
          gplan.rods.every(inSomeEnvelope) && gplan.crossings.every(inSomeEnvelope) &&
          gplan.testWells.every(inSomeEnvelope) && gplan.taps.every(t => inSomeEnvelope(t.from)));
        // Envelope keeps a border bay around every grounded footprint: all
        // tap bond points (on enclosure edges) sit inside the envelope too.
        check('[463] equipment bond points stay inside the envelope',
          gplan.taps.every(t => inSomeEnvelope(t.to)));
      }

      // Loop geometry: inside the fence at ~the design inset
      check('[57] loops have >= 3 vertices and sit inside the fence',
        gLoops.every(lp => lp.length >= 3 && lp.every(p => pointInPolygon(p, design.fence))));
      check('[57] loop keeps at least half the design inset clearance to the fence',
        gLoops.every(lp => lp.every(p => distanceToPolygonEdge(p, design.fence) >= GROUND_LOOP_INSET_FT * 0.5)));

      // Rods: on the loop boundary, corners covered, no gap over spacing
      const onLoop = (p: Pt) => gLoops.some(lp => {
        const q = groundingNearestPointOnLoop(p, lp);
        return Math.hypot(q.x - p.x, q.y - p.y) < 0.05;
      });
      check('[57] every rod lies on the loop boundary', gplan.rods.every(onLoop));
      check('[57] every loop corner has a rod within merge distance',
        gLoops.every(lp => lp.every(c => gplan.rods.some(r => Math.hypot(r.x - c.x, r.y - c.y) < 2.5))));
      // Max gap between adjacent rods along each edge <= spacing (+ tolerance)
      let maxGap = 0;
      for (const lp of gLoops) for (let i = 0; i < lp.length; i++) {
        const a = lp[i], b = lp[(i + 1) % lp.length];
        const len = Math.hypot(b.x - a.x, b.y - a.y);
        if (len < 1e-6) continue;
        const ux = (b.x - a.x) / len, uy = (b.y - a.y) / len;
        const ts = gplan.rods
          .map(r => ({ t: (r.x - a.x) * ux + (r.y - a.y) * uy, r }))
          .filter(({ t, r }) => t >= -0.1 && t <= len + 0.1 &&
            Math.abs((r.x - a.x) * -uy + (r.y - a.y) * ux) < 0.1)
          .map(({ t }) => Math.max(0, Math.min(len, t)))
          .sort((x, y) => x - y);
        const stops = [0, ...ts, len];
        for (let k = 1; k < stops.length; k++) maxGap = Math.max(maxGap, stops[k] - stops[k - 1]);
      }
      check('[57] no rod gap exceeds the default spacing', maxGap <= DEFAULT_ROD_SPACING_FT + 0.5,
        `max gap ${maxGap.toFixed(1)} ft`);
      check('[57] gate rod present near the gate',
        !design.gate || gplan.rods.some(r => {
          const g = groundingNearestPointOnLoop({ x: design.gate!.x, y: design.gate!.y }, gplan.loop);
          return Math.hypot(r.x - g.x, r.y - g.y) < 2.5;
        }));

      // Taps: multi-point per container/PCS (reference-sheet pigtails — 2
      // bonds along the long axis), single bond for aux gear/FJBs; each stub
      // runs to the nearest buried conductor (loop OR grid), so pigtails
      // stay short instead of long straight shots to the loop.
      const tapKinds = new Set(['bess', 'inverter', 'auxTransformer', 'auxSwitchgear', 'feederJunctionBox']);
      const multiTapKinds = new Set(['bess', 'inverter']);
      const expectTapCount = design.equipment.reduce(
        (n, e) => n + (tapKinds.has(e.kind) ? (multiTapKinds.has(e.kind) ? 2 : 1) : 0), 0);
      check('[57] two bonds per container/PCS, one per aux/FJB',
        gplan.taps.length === expectTapCount && expectTapCount > 0,
        `${gplan.taps.length} taps vs ${expectTapCount} expected`);
      const onConductor = (p: Pt) => {
        if (onLoop(p)) return true;
        return gplan.grid.some(([a, b]) => {
          const dx = b.x - a.x, dy = b.y - a.y;
          const L2 = dx * dx + dy * dy;
          const t = L2 > 0 ? Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.y - a.y) * dy) / L2)) : 0;
          return Math.hypot(a.x + t * dx - p.x, a.y + t * dy - p.y) < 0.05;
        });
      };
      check('[57] tap from-points lie on a buried conductor (loop or grid)',
        gplan.taps.every(t => onConductor(t.from)));
      check('[57] pigtails are short stubs, not straight shots to the loop',
        gplan.taps.every(t => Math.hypot(t.to.x - t.from.x, t.to.y - t.from.y) < 60));
      check('[57] every containered/PCS item has exactly 2 taps, others 1',
        design.equipment.filter(e => tapKinds.has(e.kind)).every(e =>
          gplan.taps.filter(t => t.equipId === e.id).length === (multiTapKinds.has(e.kind) ? 2 : 1)));
      check('[57] tap equipment ids all match the design',
        gplan.taps.every(t => design.equipment.some(e => e.id === t.equipId)));

      // Summary quantities agree with geometry (all envelope loops)
      const loopLF = gLoops.reduce((tot, lp) => tot + lp.reduce((sAcc, a, i) => {
        const b = lp[(i + 1) % lp.length];
        return sAcc + Math.hypot(b.x - a.x, b.y - a.y);
      }, 0), 0);
      check('[57] summary loop/total lengths agree with geometry',
        Math.abs(gplan.summary.loopLengthFt - loopLF) < 0.5 &&
        Math.abs(gplan.summary.totalConductorFt -
          (gplan.summary.loopLengthFt + gplan.summary.gridLengthFt + gplan.summary.tapLengthFt)) < 0.05 &&
        gplan.summary.rodCount === gplan.rods.length &&
        gplan.summary.crossingCount === gplan.crossings.length &&
        gplan.summary.testWellCount === gplan.testWells.length &&
        gplan.summary.tapCount === gplan.taps.length);

      // Reference-sheet fidelity: full-yard lattice (max bay), crossing
      // connections at actual lattice crossings, test wells on the loop.
      {
        const rowY = [...new Set(gplan.grid.filter(([a, b]) => Math.abs(a.y - b.y) < 0.011).map(([a]) => a.y))].sort((x, y) => x - y);
        const colX = [...new Set(gplan.grid.filter(([a, b]) => Math.abs(a.x - b.x) < 0.011).map(([a]) => a.x))].sort((x, y) => x - y);
        const lys = gLoops.flat().map(p => p.y), lxs = gLoops.flat().map(p => p.x);
        const maxBay = (vals: number[], lo: number, hi: number) => {
          const stops = [lo, ...vals, hi];
          let m = 0;
          for (let i = 1; i < stops.length; i++) m = Math.max(m, stops[i] - stops[i - 1]);
          return m;
        };
        check('[57] no lattice bay exceeds MAX_GRID_BAY_FT (rows and columns)',
          maxBay(rowY, Math.min(...lys), Math.max(...lys)) <= MAX_GRID_BAY_FT + 0.5 &&
          maxBay(colX, Math.min(...lxs), Math.max(...lxs)) <= MAX_GRID_BAY_FT + 0.5,
          `row bay ${maxBay(rowY, Math.min(...lys), Math.max(...lys)).toFixed(1)}, col bay ${maxBay(colX, Math.min(...lxs), Math.max(...lxs)).toFixed(1)}`);
        check('[57] crossings exist and sit on both a row and a column run',
          gplan.crossings.length > 0 && gplan.crossings.every(c =>
            gplan.grid.some(([a, b]) => Math.abs(a.y - b.y) < 0.011 && Math.abs(a.y - c.y) < 0.05 &&
              c.x >= Math.min(a.x, b.x) - 0.05 && c.x <= Math.max(a.x, b.x) + 0.05) &&
            gplan.grid.some(([a, b]) => Math.abs(a.x - b.x) < 0.011 && Math.abs(a.x - c.x) < 0.05 &&
              c.y >= Math.min(a.y, b.y) - 0.05 && c.y <= Math.max(a.y, b.y) + 0.05)));
        check('[57] crossings are connections, not rods (rod count stays at package scale)',
          gplan.summary.rodCount === gplan.rods.length && gplan.rods.length < 200);
        check('[57] every test well coincides with a perimeter rod',
          gplan.testWells.length > 0 &&
          gplan.testWells.every(w => gplan.rods.some(r => Math.hypot(r.x - w.x, r.y - w.y) < 0.05)));
        check('[57] test wells are unique and roughly one per 200 ft of loop',
          new Set(gplan.testWells.map(w => `${w.x},${w.y}`)).size === gplan.testWells.length &&
          gplan.testWells.length >= Math.max(1, Math.floor(loopLF / TEST_WELL_SPACING_FT) - 2) &&
          gplan.testWells.length <= Math.floor(loopLF / TEST_WELL_SPACING_FT) + 1,
          `${gplan.testWells.length} wells on ${Math.round(loopLF)} LF loop`);
      }

      // Interior grid conductors (90% pkg CAR-D-B009-1A/1B: E-W run per
      // container row, N-S tie per column, ends on the perimeter loop).
      {
        const inLoop = (p: { x: number; y: number }) =>
          onLoop(p) || pointInPolygon(p, gplan.loop);
        check('[57] interior grid conductors exist for a containered design',
          gplan.grid.length > 0);
        check('[57] grid segment endpoints land on the perimeter loop',
          gplan.grid.every(([a, b]) => onLoop(a) && onLoop(b)));
        check('[57] grid segments are axis-aligned rows/columns',
          gplan.grid.every(([a, b]) =>
            Math.abs(a.x - b.x) < 0.011 || Math.abs(a.y - b.y) < 0.011));
        const rowYs = new Set(gplan.grid.filter(([a, b]) => Math.abs(a.y - b.y) < 0.011).map(([a]) => a.y));
        const colXs = new Set(gplan.grid.filter(([a, b]) => Math.abs(a.x - b.x) < 0.011).map(([a]) => a.x));
        check('[57] grid has both row runs and column ties',
          rowYs.size > 0 && colXs.size > 0, `${rowYs.size} rows, ${colXs.size} cols`);
        // Island (QTY3) blocks stagger a crosswise third container, so a
        // container center no longer coincides with a N-S tie. Every
        // container still sits ON an E-W run, and fill runs cap each bay at
        // MAX_GRID_BAY_FT — so half a bay is the real column-tie invariant.
        check('[57] every container row/column center has a matching grid line',
          design.equipment.filter(e => e.kind === 'bess').every(e =>
            [...rowYs].some(y => Math.abs(y - e.y) < 6.01) &&
            [...colXs].some(x => Math.abs(x - e.x) <= MAX_GRID_BAY_FT / 2 + 0.01)));
        check('[57] grid LF matches geometry',
          Math.abs(gplan.summary.gridLengthFt -
            gplan.grid.reduce((sAcc, [a, b]) => sAcc + Math.hypot(b.x - a.x, b.y - a.y), 0)) < 0.5);
        void inLoop;
      }
      // Material specs pinned to the 90% package grounding BOM (CAR-D-B009-0)
      check('[57] conductor/rod specs match CAR-D-B009-0 items 0020/0940',
        GROUND_CONDUCTOR_SPEC === '#4/0 AWG BARE CU' &&
        GROUND_ROD_SPEC === '3/4" X 10\'-0" COPPERBONDED');

      // Spacing options change rod count monotonically
      const g25 = buildGroundingPlan(design, { rodSpacingFt: 25 });
      const g100 = buildGroundingPlan(design, { rodSpacingFt: 100 });
      check('[57] tighter spacing -> more rods; wider -> fewer',
        !!g25 && !!g100 && g25.rods.length >= gplan.rods.length &&
        g100.rods.length <= gplan.rods.length &&
        ROD_SPACING_OPTIONS.join(',') === '25,50,100');

      // Opt-in DXF: grounding layer, entities and screening note appear
      const dxfG = buildDesignDxfString(design, 'Hondo_Test', undefined, undefined, undefined, undefined, undefined, gplan);
      check('[57] opt-in DXF declares the grounding layer', dxfG.includes('EQUIP - GROUNDING'));
      check('[57] opt-in DXF includes the screening key note',
        dxfG.includes('GROUNDING (SCREENING)') && dxfG.includes('QUANTITY TAKEOFF ONLY'));
      check('[57] opt-in DXF is deterministic',
        buildDesignDxfString(design, 'Hondo_Test', undefined, undefined, undefined, undefined, undefined, gplan) === dxfG);
      check('[57] opt-in DXF strictly adds content', dxfG.length > dxf.length);
    }

    // Package sheets: site-plan sheet byte-identical without grounding,
    // gains the layer only when the ctx opts in.
    {
      const { SHEET_REGISTRY, buildSheetDxfString } = await import('../client/src/lib/nextera/dxfSheets');
      const spIdx = SHEET_REGISTRY.findIndex(sd => sd.id === 'site-plan');
      const spDef = SHEET_REGISTRY[spIdx];
      const ctxBase = { design, projectName: 'Hondo_Test', config } as any;
      const spPlain = buildSheetDxfString(spDef, ctxBase, spIdx);
      check('[57] package site-plan sheet default is byte-deterministic and grounding-free',
        buildSheetDxfString(spDef, ctxBase, spIdx) === spPlain &&
        buildSheetDxfString(spDef, { ...ctxBase, grounding: null }, spIdx) === spPlain &&
        !spPlain.includes('EQUIP - GROUNDING'));
      if (gplan) {
        const spG = buildSheetDxfString(spDef, { ...ctxBase, grounding: gplan }, spIdx);
        check('[57] package site-plan sheet draws grounding when ctx opts in',
          spG.includes('EQUIP - GROUNDING') && spG.length > spPlain.length);
      }
    }

    // Degenerate fence -> null, never a crash
    check('[57] degenerate fence returns null plan',
      buildGroundingPlan({ fence: [{ x: 0, y: 0 }, { x: 1, y: 0 }], gate: null as any, equipment: [] } as any) === null);

    // No BESS containers -> the full-yard lattice still fills the open area
    // at MAX_GRID_BAY_FT (reference sheet grids open/future areas too);
    // never a crash. Totals stay internally consistent.
    {
      const gNoBess = buildGroundingPlan({
        fence: [{ x: 0, y: 0 }, { x: 200, y: 0 }, { x: 200, y: 200 }, { x: 0, y: 200 }],
        gate: null as any,
        equipment: [{ id: 'aux1', kind: 'aux', x: 100, y: 100, w: 20, h: 10, rotation: 0 }],
      } as any);
      check('[57] no-BESS design still gets the open-area lattice fill',
        !!gNoBess && gNoBess.grid.length > 0 && gNoBess.summary.gridLengthFt > 0 &&
        Math.abs(gNoBess.summary.totalConductorFt -
          (gNoBess.summary.loopLengthFt + gNoBess.summary.gridLengthFt + gNoBess.summary.tapLengthFt)) < 0.05);
    }

    // [463] Aug bays / future-aug zones adjacent to a container extend the
    // island envelope so those areas stay gridded (reference sheet grids
    // future/aug areas INSIDE the envelope; open yard carries no grid).
    {
      const sqFence: Pt[] = [{ x: 0, y: 0 }, { x: 400, y: 0 }, { x: 400, y: 300 }, { x: 0, y: 300 }];
      const bess1 = { id: 'zb1', kind: 'bess', x: 100, y: 100, length: 60, width: 10, rotation: 0 };
      const bare = buildGroundingPlan({ fence: sqFence, gate: null, equipment: [bess1] } as any);
      const withAug = buildGroundingPlan({
        fence: sqFence, gate: null, equipment: [bess1],
        augmentationZones: [{ id: 'az1', x: 170, y: 130, length: 40, width: 20 }],
        reservedZones: [{ id: 'rz1', kind: 'futureAug', x: 100, y: 160, length: 60, width: 20, label: 'FUTURE' }],
      } as any);
      const bbox = (lp: Pt[]) => ({
        minX: Math.min(...lp.map(p => p.x)), maxX: Math.max(...lp.map(p => p.x)),
        minY: Math.min(...lp.map(p => p.y)), maxY: Math.max(...lp.map(p => p.y)),
      });
      check('[463] aug/future-aug zones expand the island envelope',
        !!bare && !!withAug && withAug.loops.length === 1 &&
        bbox(withAug.loops[0]).maxX > bbox(bare!.loops[0]).maxX + 20 &&
        bbox(withAug.loops[0]).maxY > bbox(bare!.loops[0]).maxY + 20,
        bare && withAug ? `bare ${JSON.stringify(bbox(bare.loops[0]))} aug ${JSON.stringify(bbox(withAug.loops[0]))}` : 'null plan');
      check('[463] open yard outside the envelope carries no conductor',
        !!withAug && withAug.grid.every(([a, b]) => [a, b].every(p => p.x <= 200 && p.y <= 200)) &&
        withAug.rods.every(p => p.x <= 200 && p.y <= 200));
    }

    // Highly concave U-shaped fence: one row line crosses the loop in TWO
    // disjoint interior spans (one per prong). Concave-safe span clipping
    // must pair the crossings correctly — a mis-pairing would bridge a
    // conductor across the open notch (outside the loop) and silently
    // inflate the BOM LF.
    {
      // 600 x 400 U with a 200-wide notch cut from the top down to y=100.
      const uFence: Pt[] = [
        { x: 0, y: 0 }, { x: 600, y: 0 }, { x: 600, y: 400 },
        { x: 400, y: 400 }, { x: 400, y: 100 }, { x: 200, y: 100 },
        { x: 200, y: 400 }, { x: 0, y: 400 },
      ];
      const uEquip = [
        // One BESS per prong on the same row line (y=250, inside the notch's
        // y-range) so the clipped row must split into two disjoint spans.
        { id: 'ub1', kind: 'bess', x: 100, y: 250, length: 60, width: 10, rotation: 0 },
        { id: 'ub2', kind: 'bess', x: 500, y: 250, length: 60, width: 10, rotation: 0 },
        // A second row in the connected bottom band (single span).
        { id: 'ub3', kind: 'bess', x: 300, y: 50, length: 60, width: 10, rotation: 0 },
      ];
      const gU = buildGroundingPlan({ fence: uFence, gate: null, equipment: uEquip } as any);
      check('[57] U-fence grounding plan builds', !!gU);
      if (gU) {
        // [463] Three widely separated BESS containers -> three island
        // envelope loops, joined by interconnecting conductor.
        check('[463] U-fence yields one envelope loop per island group',
          gU.loops.length === 3, `${gU.loops.length} loops`);
        check('[57] U-fence loops stay inside the concave fence with inset clearance',
          gU.loops.every(lp => lp.every(p => pointInPolygon(p, uFence) &&
            distanceToPolygonEdge(p, uFence) >= GROUND_LOOP_INSET_FT * 0.5)));

        // The y=250 row line must clip into >= 2 disjoint spans (one per prong).
        const rowSpans = gU.grid.filter(([a, b]) =>
          Math.abs(a.y - 250) < 1 && Math.abs(b.y - 250) < 1);
        check('[57] U-fence notch row clips into multiple disjoint spans',
          rowSpans.length >= 2, `${rowSpans.length} spans at y=250`);
        // Disjoint: sorted by x, each span ends before the next begins
        // (the gap is the open notch, > 100 ft wide even after insets).
        const sorted = [...rowSpans].sort((s, t) => Math.min(s[0].x, s[1].x) - Math.min(t[0].x, t[1].x));
        let disjoint = true;
        for (let i = 1; i < sorted.length; i++) {
          const prevMax = Math.max(sorted[i - 1][0].x, sorted[i - 1][1].x);
          const nextMin = Math.min(sorted[i][0].x, sorted[i][1].x);
          if (nextMin - prevMax < 100) disjoint = false;
        }
        check('[57] U-fence row spans are separated by the open notch', disjoint);

        // Every grid span (rows AND columns): lattice runs end on their own
        // envelope loop; interconnect segments chain loop-to-loop (an elbow
        // vertex is shared by exactly two segments). Nothing bridges the
        // open notch (outside the fence).
        const onLoopEdge = (p: Pt) => gU.loops.some(lp => distanceToPolygonEdge(p, lp) < 0.05);
        const endpointOk = (p: Pt) =>
          onLoopEdge(p) ||
          gU.grid.filter(([a, b]) =>
            Math.hypot(a.x - p.x, a.y - p.y) < 0.05 || Math.hypot(b.x - p.x, b.y - p.y) < 0.05
          ).length >= 2; // interconnect elbow shared by two segments
        check('[57] U-fence: every grid span endpoint lands on a loop or an interconnect elbow',
          gU.grid.length > 0 && gU.grid.every(([a, b]) => endpointOk(a) && endpointOk(b)));
        const interiorOk = gU.grid.every(([a, b]) =>
          [0.25, 0.5, 0.75].every(t => {
            const q = { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
            // Inside some envelope loop, or (interconnect) inside the fence
            // with clearance — never across the open notch.
            return gU.loops.some(lp => pointInPolygon(q, lp) || distanceToPolygonEdge(q, lp) < 0.05) ||
              (pointInPolygon(q, uFence) && distanceToPolygonEdge(q, uFence) >= 1);
          }));
        check('[57] U-fence: every grid span stays inside the fence (no notch bridge)', interiorOk);
        // [463] Lattice conductors stay confined to their envelope: no row
        // or column run extends outside every loop's bounding box.
        const inSomeLoopBBox = ([a, b]: [Pt, Pt]) => gU.loops.some(lp => {
          const xs = lp.map(p => p.x), ys = lp.map(p => p.y);
          const loX = Math.min(...xs) - 0.1, hiX = Math.max(...xs) + 0.1;
          const loY = Math.min(...ys) - 0.1, hiY = Math.max(...ys) + 0.1;
          return [a, b].every(p => p.x >= loX && p.x <= hiX && p.y >= loY && p.y <= hiY);
        });
        const lattice = gU.grid.filter(seg => onLoopEdge(seg[0]) && onLoopEdge(seg[1]));
        const interconnects = gU.grid.filter(seg => !(onLoopEdge(seg[0]) && onLoopEdge(seg[1])));
        check('[463] U-fence lattice runs stay inside their own envelope',
          lattice.length > 0 && lattice.every(inSomeLoopBBox));
        check('[463] U-fence loops are joined by interconnecting conductor (spanning tree)',
          interconnects.length >= gU.loops.length - 1,
          `${interconnects.length} interconnect segs for ${gU.loops.length} loops`);

        // gridLengthFt matches the summed span geometry.
        const summed = gU.grid.reduce((s, [a, b]) => s + Math.hypot(b.x - a.x, b.y - a.y), 0);
        check('[57] U-fence gridLengthFt matches summed span geometry',
          Math.abs(gU.summary.gridLengthFt - summed) < 0.05,
          `${gU.summary.gridLengthFt} vs ${summed.toFixed(2)}`);
        // And no span was silently dropped: both prongs and the bottom band
        // each contribute a row span, plus the two column ties.
        check('[57] U-fence grid keeps prong rows, bottom row, and column ties',
          gU.grid.length >= rowSpans.length + 1 + 2, `${gU.grid.length} spans`);
      }
    }
  }

  // ---------------------------------------------------------------
  // [471] Multi-island grounding interconnect on a REAL generated layout:
  // Rio Hondo 200 MW QTY3 mirrored-pair islands (design.islands populated)
  // splits into multiple envelope loops joined by interconnecting conductor.
  // The synthetic U-fence above forces the split; this catches
  // clustering-threshold surprises on real geometry before a drafter sees
  // a strange grounding sheet.
  {
    console.log('\n[471] Multi-island grounding interconnect (Rio Hondo 200MW QTY3)');
    const RIO200_KMZ = path.resolve('attached_assets/Rio_Hondo_200MW_TGR_with_Parcel_1784325593748.kmz');
    const rio200 = await loadKmzBoundary(RIO200_KMZ);
    const cfg471 = getConfiguration('ge-aux-400');
    const d471 = generateSiteDesign(rio200, cfg471, 200, 800, { hotClimate: true, containersPerPcs: 3 });
    check('[471] Rio Hondo 200MW QTY3 places all required blocks',
      d471.blocksPlaced === d471.blocksRequired && d471.blocksPlaced > 0,
      `${d471.blocksPlaced}/${d471.blocksRequired}`);
    const isl471 = d471.islands ?? [];
    check('[471] design is a real multi-island layout (islands populated, >= 2)',
      isl471.length >= 2, `${isl471.length} islands`);

    const g471 = buildGroundingPlan(d471);
    check('[471] grounding plan builds for the real multi-island design', !!g471);
    if (g471) {
      check('[471] plan rebuild is deterministic',
        JSON.stringify(buildGroundingPlan(d471)) === JSON.stringify(g471));

      // Envelope count is sensible: the islands split into MULTIPLE loops
      // (this layout's island groups sit far apart), but never more loops
      // than islands — islands within the cluster gap must merge, so roads
      // between paired islands cannot shatter the yard into tiny loops.
      check('[471] real layout splits into multiple envelope loops',
        g471.loops.length >= 2, `${g471.loops.length} loops`);
      check('[471] never more envelope loops than islands (close islands merge)',
        g471.loops.length <= isl471.length,
        `${g471.loops.length} loops vs ${isl471.length} islands`);

      // Merge invariant: any two SEPARATE loops must be farther apart than
      // the cluster gap minus both border bays — otherwise their island
      // groups were within ENVELOPE_CLUSTER_GAP_FT and should have merged.
      const bboxOf = (lp: Pt[]) => ({
        minX: Math.min(...lp.map(p => p.x)), maxX: Math.max(...lp.map(p => p.x)),
        minY: Math.min(...lp.map(p => p.y)), maxY: Math.max(...lp.map(p => p.y)),
      });
      const boxes = g471.loops.map(bboxOf);
      const boxGap = (a: typeof boxes[0], b: typeof boxes[0]) => Math.hypot(
        Math.max(a.minX - b.maxX, b.minX - a.maxX, 0),
        Math.max(a.minY - b.maxY, b.minY - a.maxY, 0));
      let minGap = Infinity;
      for (let i = 0; i < boxes.length; i++) {
        for (let j = i + 1; j < boxes.length; j++) minGap = Math.min(minGap, boxGap(boxes[i], boxes[j]));
      }
      check('[471] separate loops are genuinely beyond the cluster gap',
        minGap > ENVELOPE_CLUSTER_GAP_FT - 2 * ENVELOPE_BORDER_FT - 0.5,
        `min loop gap ${minGap.toFixed(1)} ft vs threshold ${ENVELOPE_CLUSTER_GAP_FT - 2 * ENVELOPE_BORDER_FT}`);

      // Interconnects exist exactly because loops are separate: lattice runs
      // start and end on a loop edge; anything else is interconnecting
      // conductor, and separate loops need at least a spanning tree of them.
      const onLoopEdge471 = (p: Pt) => g471.loops.some(lp => distanceToPolygonEdge(p, lp) < 0.05);
      const lattice471 = g471.grid.filter(s => onLoopEdge471(s[0]) && onLoopEdge471(s[1]));
      const inter471 = g471.grid.filter(s => !(onLoopEdge471(s[0]) && onLoopEdge471(s[1])));
      check('[471] interconnects exist only because loops are separate',
        g471.loops.length === 1 ? inter471.length === 0 : inter471.length >= g471.loops.length - 1,
        `${inter471.length} interconnect segs for ${g471.loops.length} loops`);

      // No conductor outside envelope bounds: lattice, rods, crossings,
      // wells and tap sources stay inside SOME loop's bbox; interconnect
      // segments run loop-to-loop entirely inside the fence with clearance.
      const MARGIN = 0.1;
      const inSomeBox = (p: Pt) => boxes.some(b =>
        p.x >= b.minX - MARGIN && p.x <= b.maxX + MARGIN &&
        p.y >= b.minY - MARGIN && p.y <= b.maxY + MARGIN);
      check('[471] lattice runs stay inside their own envelope bounds',
        lattice471.length > 0 && lattice471.every(([a, b]) => inSomeBox(a) && inSomeBox(b)));
      check('[471] rods, crossings, wells and tap points stay inside envelope bounds',
        g471.rods.every(inSomeBox) && g471.crossings.every(inSomeBox) &&
        g471.testWells.every(inSomeBox) &&
        g471.taps.every(t => inSomeBox(t.from) && inSomeBox(t.to)));
      const interOk = inter471.every(([a, b]) =>
        [0, 0.25, 0.5, 0.75, 1].every(t => {
          const q = { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
          return pointInPolygon(q, d471.fence) && distanceToPolygonEdge(q, d471.fence) >= 1;
        }));
      check('[471] interconnect conductor stays inside the fence with clearance', interOk);

      // Summary stays internally consistent across multiple loops.
      const loopLF471 = g471.loops.reduce((tot, lp) => tot + lp.reduce((sAcc, a, i) => {
        const b = lp[(i + 1) % lp.length];
        return sAcc + Math.hypot(b.x - a.x, b.y - a.y);
      }, 0), 0);
      check('[471] summary counts all loops and totals stay consistent',
        Math.abs(g471.summary.loopLengthFt - loopLF471) < 0.5 &&
        Math.abs(g471.summary.totalConductorFt -
          (g471.summary.loopLengthFt + g471.summary.gridLengthFt + g471.summary.tapLengthFt)) < 0.05);

      // The grounding DXF renders ALL loops: one closed LWPOLYLINE on the
      // grounding layer per envelope loop.
      const dxf471 = buildDesignDxfString(d471, 'Rio200_Test', undefined, undefined, undefined, undefined, undefined, g471);
      let closedGroundPolys = 0;
      for (const entRaw of dxf471.split(/\n  0\n/)) {
        if (!entRaw.startsWith('LWPOLYLINE')) continue;
        const layerM = entRaw.match(/\n  8\n(.+)/);
        if (layerM?.[1] === 'EQUIP - GROUNDING' && /\n 70\n1\n/.test(entRaw + '\n')) closedGroundPolys++;
      }
      check('[471] grounding DXF draws one closed polyline per envelope loop',
        closedGroundPolys === g471.loops.length,
        `${closedGroundPolys} closed grounding polylines vs ${g471.loops.length} loops`);

      // PDF figure + in-app preview render all loops too: both consume the
      // loops[] array (with the legacy single-loop fallback), never loop only.
      const pdfSrc471 = readFileSync('client/src/lib/nextera/permitPdf.ts', 'utf8');
      const prevSrc471 = readFileSync('client/src/components/GroundingFigurePreview.tsx', 'utf8');
      check('[471] permit PDF grounding figure iterates all loops',
        pdfSrc471.includes('grounding.loops ?? [grounding.loop]'));
      check('[471] in-app grounding preview iterates all loops',
        prevSrc471.includes('grounding.loops ?? [grounding.loop]'));
    }
  }

  // ---------------------------------------------------------------
  // [473] Grounding interconnect avoids equipment pads: an obstacle placed
  // between two island envelopes must be detoured around (buried conductor
  // still respects pads/foundations like cable reroutes do), falling back to
  // the never-drop straight run only when no clear route exists.
  {
    console.log('\n[473] Grounding interconnect avoids equipment pads');
    const fence473: Pt[] = [{ x: 0, y: 0 }, { x: 800, y: 0 }, { x: 800, y: 300 }, { x: 0, y: 300 }];
    const bessA = { id: 'ka', kind: 'bess', x: 100, y: 150, length: 60, width: 10, rotation: 0 };
    const bessB = { id: 'kb', kind: 'bess', x: 700, y: 150, length: 60, width: 10, rotation: 0 };
    // Non-tap-kind pad squarely between the two islands, straddling the
    // straight interconnect line at y=150 (it must NOT form its own
    // envelope, so the interconnect has to route around it).
    const pad = { id: 'kp', kind: 'fireControlPanel', x: 400, y: 150, length: 60, width: 40, rotation: 0 };
    const padRect = { minX: 370, minY: 130, maxX: 430, maxY: 170 };

    const onLoop473 = (g: NonNullable<ReturnType<typeof buildGroundingPlan>>) =>
      (p: Pt) => g.loops.some(lp => distanceToPolygonEdge(p, lp) < 0.05);
    // Interconnect = any grid segment that is not a lattice run confined to a
    // single loop: an endpoint off every loop (detour elbow leg) or the two
    // endpoints on DIFFERENT loops (a straight loop-to-loop run).
    const interOf = (g: NonNullable<ReturnType<typeof buildGroundingPlan>>) => {
      const loopIdx = (p: Pt) => g.loops.findIndex(lp => distanceToPolygonEdge(p, lp) < 0.05);
      return g.grid.filter(([a, b]) => {
        const ia = loopIdx(a), ib = loopIdx(b);
        return ia === -1 || ib === -1 || ia !== ib;
      });
    };
    const crossesPad = (segs: [Pt, Pt][], r: typeof padRect) => segs.some(([a, b]) => {
      const n = Math.max(2, Math.ceil(Math.hypot(b.x - a.x, b.y - a.y) / 5));
      for (let k = 0; k <= n; k++) {
        const t = k / n;
        const q = { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
        if (q.x > r.minX + 0.01 && q.x < r.maxX - 0.01 && q.y > r.minY + 0.01 && q.y < r.maxY - 0.01) return true;
      }
      return false;
    });

    // Baseline (no obstacle): the straight aligned run is used.
    const gClear = buildGroundingPlan({ fence: fence473, gate: null, equipment: [bessA, bessB] } as any);
    check('[473] two far islands split into two envelope loops', !!gClear && gClear.loops.length === 2);
    if (gClear) {
      const inter = interOf(gClear);
      check('[473] no obstacle -> single straight interconnect', inter.length === 1);
    }

    // Obstacle in the corridor: interconnect detours around the pad.
    const gPad = buildGroundingPlan({ fence: fence473, gate: null, equipment: [bessA, bessB, pad] } as any);
    check('[473] plan still builds with a pad in the corridor', !!gPad && gPad.loops.length === 2);
    if (gPad) {
      const inter = interOf(gPad);
      check('[473] interconnect still joins the loops (spanning tree intact)', inter.length >= 1);
      check('[473] interconnect detours around the equipment pad',
        inter.length >= 3 && !crossesPad(inter, padRect),
        `${inter.length} segs, crosses=${crossesPad(inter, padRect)}`);
      check('[473] detour stays inside the fence with clearance',
        inter.every(([a, b]) => [0, 0.25, 0.5, 0.75, 1].every(t => {
          const q = { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
          return pointInPolygon(q, fence473) && distanceToPolygonEdge(q, fence473) >= 1;
        })));
      // Chain continuity: consecutive detour segments share endpoints, and
      // the route starts/ends on the two loops.
      const onLoop = onLoop473(gPad);
      const ends = inter.flatMap(s => s);
      check('[473] detour route starts and ends on the island loops',
        ends.filter(onLoop).length >= 2);
      check('[473] plan with pad is deterministic',
        JSON.stringify(buildGroundingPlan({ fence: fence473, gate: null, equipment: [bessA, bessB, pad] } as any)) === JSON.stringify(gPad));
    }

    // Laydown reserved zone blocks the corridor too.
    const gLay = buildGroundingPlan({
      fence: fence473, gate: null, equipment: [bessA, bessB],
      reservedZones: [{ id: 'ld', kind: 'laydown', x: 400, y: 150, length: 60, width: 40, label: 'LAYDOWN' }],
    } as any);
    check('[473] laydown zone is detoured like an equipment pad',
      !!gLay && !crossesPad(interOf(gLay), padRect) && interOf(gLay).length >= 3);

    // Unavoidable wall: pad spans the full fence height -> never-drop
    // fallback keeps the loops joined with the straight run through it.
    const wall = { id: 'kw', kind: 'fireControlPanel', x: 400, y: 150, length: 60, width: 296, rotation: 0 };
    const gWall = buildGroundingPlan({ fence: fence473, gate: null, equipment: [bessA, bessB, wall] } as any);
    check('[473] unavoidable pad -> never-drop straight fallback keeps loops joined',
      !!gWall && gWall.loops.length === 2 && interOf(gWall).length >= 1);
  }

  // [475] Grounding interconnect respects road clear zones: crossings are
  // allowed only as short perpendicular cuts — a leg may never run
  // longitudinally down a road (or its 3 ft clear zone). Roads are NOT hard
  // obstacles (islands are separated by roads, so crossing is unavoidable);
  // the route shifts the along-road leg outside the strip instead.
  {
    console.log('\n[475] Grounding interconnect crosses roads perpendicular only');
    const fence475: Pt[] = [{ x: 0, y: 0 }, { x: 800, y: 0 }, { x: 800, y: 300 }, { x: 0, y: 300 }];
    const bessA = { id: 'ra', kind: 'bess', x: 100, y: 150, length: 60, width: 10, rotation: 0 };
    const bessB = { id: 'rb', kind: 'bess', x: 700, y: 150, length: 60, width: 10, rotation: 0 };
    // Horizontal 24 ft aisle strip lying exactly on the straight interconnect
    // line (y=150), spanning x 200..600: the straight run would travel 400 ft
    // down the road, so the route must Z-detour to cross clear of the strip
    // (here: around its end / outside the clear zone).
    const road = { x: 400, y: 150, length: 400, width: 24, rotation: 0 };
    const roadRect = { minX: 200, minY: 138, maxX: 600, maxY: 162 };
    const CLEAR = 3, SLACK = 1;
    const maxRun = 24 + 2 * CLEAR + SLACK;
    const interOf = (g: NonNullable<ReturnType<typeof buildGroundingPlan>>) => {
      const loopIdx = (p: Pt) => g.loops.findIndex(lp => distanceToPolygonEdge(p, lp) < 0.05);
      return g.grid.filter(([a, b]) => {
        const ia = loopIdx(a), ib = loopIdx(b);
        return ia === -1 || ib === -1 || ia !== ib;
      });
    };
    // Length of an axis-aligned segment inside the road's clear zone.
    const inRoadLen = ([a, b]: [Pt, Pt]) => {
      const minX = roadRect.minX - CLEAR, maxX = roadRect.maxX + CLEAR;
      const minY = roadRect.minY - CLEAR, maxY = roadRect.maxY + CLEAR;
      if (Math.abs(a.y - b.y) < 0.5) {
        if (a.y <= minY || a.y >= maxY) return 0;
        return Math.max(0, Math.min(Math.max(a.x, b.x), maxX) - Math.max(Math.min(a.x, b.x), minX));
      }
      if (a.x <= minX || a.x >= maxX) return 0;
      return Math.max(0, Math.min(Math.max(a.y, b.y), maxY) - Math.max(Math.min(a.y, b.y), minY));
    };

    // Baseline (no road): single straight run.
    const gNoRoad = buildGroundingPlan({ fence: fence475, gate: null, equipment: [bessA, bessB] } as any);
    check('[475] no road -> single straight interconnect', !!gNoRoad && interOf(gNoRoad).length === 1);

    // Aisle strip in play: every interconnect leg stays within the
    // perpendicular-crossing budget inside the road clear zone.
    const withRoad = { fence: fence475, gate: null, equipment: [bessA, bessB], roads: [], aisles: [road] } as any;
    const gRoad = buildGroundingPlan(withRoad);
    check('[475] plan still builds with an aisle on the corridor', !!gRoad && gRoad.loops.length === 2);
    if (gRoad) {
      const inter = interOf(gRoad);
      check('[475] loops stay joined across the road', inter.length >= 1);
      check('[475] route reroutes around the along-road run (multi-leg)', inter.length >= 3,
        `${inter.length} segs`);
      const worst = Math.max(...inter.map(inRoadLen));
      check('[475] no leg runs longitudinally in the road clear zone',
        worst <= maxRun, `worst in-road run ${worst.toFixed(1)} ft (budget ${maxRun})`);
      check('[475] detour stays inside the fence with clearance',
        inter.every(([a, b]) => [0, 0.25, 0.5, 0.75, 1].every(t => {
          const q = { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
          return pointInPolygon(q, fence475) && distanceToPolygonEdge(q, fence475) >= 1;
        })));
      check('[475] road-aware plan is deterministic',
        JSON.stringify(buildGroundingPlan(withRoad)) === JSON.stringify(gRoad));
    }

    // A road perpendicular to the corridor (vertical strip) is crossed
    // straight through — the aligned run is a legal perpendicular crossing.
    const vroad = { x: 400, y: 150, length: 300, width: 24, rotation: Math.PI / 2 };
    const gV = buildGroundingPlan({ fence: fence475, gate: null, equipment: [bessA, bessB], aisles: [vroad] } as any);
    check('[475] perpendicular road -> straight crossing kept', !!gV && interOf(gV).length === 1);

    // [476] Angled road segments are enforced too — legs are checked in the
    // road's local frame (not an AABB, which would over-block the corridor).
    // A diagonal strip lying on the corridor: the straight run would cross it
    // obliquely (run inside the clear zone > perpendicular budget), so the
    // route must detour around the strip's end instead.
    const diag = { x: 400, y: 150, length: 400, width: 24, rotation: Math.PI / 5 };
    const diagRunLen = ([a, b]: [Pt, Pt]) => {
      // Length of the leg inside the diagonal road's clear zone, measured in
      // the road's local frame (independent check mirroring the rule).
      const cos = Math.cos(diag.rotation), sin = Math.sin(diag.rotation);
      const loc = (p: Pt) => ({
        x: (p.x - diag.x) * cos + (p.y - diag.y) * sin,
        y: -(p.x - diag.x) * sin + (p.y - diag.y) * cos,
      });
      const A = loc(a), B = loc(b);
      const hx = diag.length / 2 + CLEAR, hy = diag.width / 2 + CLEAR;
      const dx = B.x - A.x, dy = B.y - A.y;
      let t0 = 0, t1 = 1;
      const clip = (p: number, q: number) => {
        if (Math.abs(p) < 1e-9) return q >= 0;
        const t = q / p;
        if (p < 0) { if (t > t1) return false; if (t > t0) t0 = t; }
        else { if (t < t0) return false; if (t < t1) t1 = t; }
        return true;
      };
      if (!clip(-dx, A.x + hx) || !clip(dx, hx - A.x) ||
          !clip(-dy, A.y + hy) || !clip(dy, hy - A.y)) return 0;
      return (t1 - t0) * Math.hypot(dx, dy);
    };
    const withDiag = { fence: fence475, gate: null, equipment: [bessA, bessB], roads: [diag] } as any;
    const gD = buildGroundingPlan(withDiag);
    check('[476] plan still builds with an angled road on the corridor',
      !!gD && gD.loops.length === 2);
    if (gD) {
      const interD = interOf(gD);
      check('[476] loops stay joined across the angled road', interD.length >= 1);
      check('[476] route reroutes around the angled strip (multi-leg)', interD.length >= 3,
        `${interD.length} segs`);
      const worstD = Math.max(...interD.map(diagRunLen));
      check('[476] no leg runs longitudinally in the angled road clear zone',
        worstD <= maxRun, `worst in-road run ${worstD.toFixed(1)} ft (budget ${maxRun})`);
      check('[476] angled-road detour stays inside the fence with clearance',
        interD.every(([a, b]) => [0, 0.25, 0.5, 0.75, 1].every(t => {
          const q = { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
          return pointInPolygon(q, fence475) && distanceToPolygonEdge(q, fence475) >= 1;
        })));
      check('[476] angled-road plan is deterministic',
        JSON.stringify(buildGroundingPlan(withDiag)) === JSON.stringify(gD));
    }
    // A short angled stub off the corridor must not block the straight run —
    // its AABB would cover the corridor, but the actual rotated strip doesn't.
    const stub = { x: 400, y: 240, length: 120, width: 24, rotation: Math.PI / 4 };
    const gS = buildGroundingPlan({ fence: fence475, gate: null, equipment: [bessA, bessB], roads: [stub] } as any);
    check('[476] angled road off the corridor keeps the straight run',
      !!gS && interOf(gS).length === 1);

    // Wall-to-wall road (spans the whole fence, no way around): never-drop
    // fallback keeps the loops joined with the straight run through it.
    const wallRoad = { x: 400, y: 150, length: 800, width: 296, rotation: 0 };
    const gW = buildGroundingPlan({ fence: fence475, gate: null, equipment: [bessA, bessB], aisles: [wallRoad] } as any);
    check('[475] unavoidable road -> never-drop fallback keeps loops joined',
      !!gW && gW.loops.length === 2 && interOf(gW).length >= 1);
  }

  // ---------------------------------------------------------------
  // [474] The pad-avoiding interconnect route ships all the way through the
  // drawings: because detours live in the plan's grid[] segments, the
  // grounding DXF layer and the permit PDF figure must render the actual
  // detour legs (never a straight line through the pad). Any rendering path
  // that re-derives loop-to-loop interconnects would fail these checks.
  {
    console.log('\n[474] Pad-avoiding interconnect route reaches DXF + PDF figure');
    const fence474: Pt[] = [{ x: 0, y: 0 }, { x: 800, y: 0 }, { x: 800, y: 300 }, { x: 0, y: 300 }];
    const eq474 = [
      { id: 'ka', kind: 'bess', x: 100, y: 150, length: 60, width: 10, rotation: 0 },
      { id: 'kb', kind: 'bess', x: 700, y: 150, length: 60, width: 10, rotation: 0 },
      { id: 'kp', kind: 'fireControlPanel', x: 400, y: 150, length: 60, width: 40, rotation: 0 },
    ];
    const padRect474 = { minX: 370, minY: 130, maxX: 430, maxY: 170 };
    // Minimal but well-formed design so the full DXF composer runs.
    const d474 = {
      boundary: { polygon: fence474.map(p => ({ x: p.x - 20, y: p.y - 20 })).map((p, i) => (
        [{ x: -20, y: -20 }, { x: 820, y: -20 }, { x: 820, y: 320 }, { x: -20, y: 320 }][i])), areaAcres: 6 },
      fence: fence474,
      equipment: eq474,
      augmentationZones: [], reservedZones: [], reserveSummary: null,
      roads: [], aisles: [], roadNetwork: null, gate: null,
      cables: [], trench: null, surfacing: null, blockRows: [], rowEditGeom: null,
      blocksPlaced: 2, blocksRequired: 2,
      achievedMW: 8, achievedMWh: 32, targetMW: 8, targetMWh: 32, warnings: [],
    } as any;
    const g474 = buildGroundingPlan(d474);
    check('[474] grounding plan builds on the pad-in-corridor design',
      !!g474 && g474.loops.length === 2, `${g474?.loops.length ?? 0} loops`);
    if (g474) {
      const loopIdx474 = (p: Pt) => g474.loops.findIndex(lp => distanceToPolygonEdge(p, lp) < 0.05);
      const inter474 = g474.grid.filter(([a, b]) => {
        const ia = loopIdx474(a), ib = loopIdx474(b);
        return ia === -1 || ib === -1 || ia !== ib;
      });
      const crossesPad474 = (a: Pt, b: Pt) => {
        const n = Math.max(2, Math.ceil(Math.hypot(b.x - a.x, b.y - a.y) / 5));
        for (let k = 0; k <= n; k++) {
          const t = k / n;
          const q = { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
          if (q.x > padRect474.minX + 0.01 && q.x < padRect474.maxX - 0.01 &&
              q.y > padRect474.minY + 0.01 && q.y < padRect474.maxY - 0.01) return true;
        }
        return false;
      };
      check('[474] plan routes a multi-leg detour around the pad',
        inter474.length >= 3 && inter474.every(([a, b]) => !crossesPad474(a, b)),
        `${inter474.length} interconnect legs`);

      // --- DXF: every grounding-layer LINE is collected and compared against
      // the plan's grid + taps; every detour leg must appear verbatim, and no
      // grounding conductor may pass through the pad.
      const dxf474 = buildDesignDxfString(d474, 'GND474', undefined, undefined, undefined, undefined, undefined, g474);
      const dxfSegs: [Pt, Pt][] = [];
      for (const entRaw of dxf474.split(/\n  0\n/)) {
        if (!entRaw.startsWith('LINE')) continue;
        if (!/\n  8\nEQUIP - GROUNDING\n/.test(entRaw)) continue;
        const g = (code: string) => {
          const m = entRaw.match(new RegExp(`\\n ${code}\\n(-?[\\d.eE+]+)`));
          return m ? parseFloat(m[1]) : NaN;
        };
        dxfSegs.push([{ x: g('10'), y: g('20') }, { x: g('11'), y: g('21') }]);
      }
      const sameSeg = (s: [Pt, Pt], t: [Pt, Pt]) => {
        const eq = (p: Pt, q: Pt) => Math.abs(p.x - q.x) < 0.01 && Math.abs(p.y - q.y) < 0.01;
        return (eq(s[0], t[0]) && eq(s[1], t[1])) || (eq(s[0], t[1]) && eq(s[1], t[0]));
      };
      check('[474] DXF grounding layer contains every detour leg verbatim',
        inter474.every(seg => dxfSegs.some(ds => sameSeg(ds, seg))),
        `${dxfSegs.length} grounding LINEs`);
      check('[474] no DXF grounding conductor passes through the pad',
        dxfSegs.length > 0 && dxfSegs.every(([a, b]) => !crossesPad474(a, b)));
      // The straight pad-piercing shortcut is NOT in the DXF (a renderer that
      // re-derived interconnects as loop-to-loop straight lines would emit it).
      const aOn = (p: Pt, li: number) => distanceToPolygonEdge(p, g474.loops[li]) < 0.05;
      check('[474] DXF has no straight loop-to-loop line through the pad',
        !dxfSegs.some(([a, b]) => crossesPad474(a, b) &&
          ((aOn(a, 0) && aOn(b, 1)) || (aOn(a, 1) && aOn(b, 0)))));

      // --- PDF figure: parse the actual vector content stream, invert the
      // figure transform back to site coordinates, and make the same
      // assertions about what is DRAWN (not just what the plan holds).
      {
        const { drawGroundingFigure } = await import('../client/src/lib/nextera/permitPdf');
        const { jsPDF } = await import('jspdf');
        const doc = new jsPDF({ orientation: 'portrait', unit: 'pt', format: 'letter' });
        doc.setCreationDate(new Date('2026-01-01T00:00:00Z'));
        (doc as any).setFileId('00000000000000000000000000000000');
        const box = { x: 54, y: 100, w: 504, h: 500 };
        drawGroundingFigure(doc, g474, d474, box);
        // Reproduce the figure's fit transform (bounds = loops + boundary + fence).
        let mnX = Infinity, mnY = Infinity, mxX = -Infinity, mxY = -Infinity;
        const acc = (p: Pt) => {
          if (p.x < mnX) mnX = p.x; if (p.x > mxX) mxX = p.x;
          if (p.y < mnY) mnY = p.y; if (p.y > mxY) mxY = p.y;
        };
        for (const lp of g474.loops) for (const p of lp) acc(p);
        for (const p of d474.boundary.polygon) acc(p);
        for (const p of d474.fence) acc(p);
        const fpad = 10;
        const sc = Math.min((box.w - 2 * fpad) / (mxX - mnX), (box.h - 2 * fpad) / (mxY - mnY));
        const ox = box.x + (box.w - (mxX - mnX) * sc) / 2;
        const oy = box.y + (box.h - (mxY - mnY) * sc) / 2;
        const ph = doc.internal.pageSize.getHeight(); // jsPDF flips y in the stream
        const inv = (sx: number, sy: number): Pt => ({
          x: mnX + (sx - ox) / sc,
          y: mxY - ((ph - sy) - oy) / sc,
        });
        // jsPDF doc.line emits "x y m x y l S" pairs into the page stream.
        const stream = doc.output();
        const pdfSegs: [Pt, Pt][] = [];
        const re = /(-?[\d.]+) (-?[\d.]+) m\n(-?[\d.]+) (-?[\d.]+) l/g;
        let m: RegExpExecArray | null;
        while ((m = re.exec(stream))) {
          pdfSegs.push([inv(parseFloat(m[1]), parseFloat(m[2])), inv(parseFloat(m[3]), parseFloat(m[4]))]);
        }
        check('[474] PDF figure emits parseable vector line work', pdfSegs.length > 10, `${pdfSegs.length} segments`);
        const sameSegTol = (s: [Pt, Pt], t: [Pt, Pt]) => {
          const eq = (p: Pt, q: Pt) => Math.abs(p.x - q.x) < 0.5 && Math.abs(p.y - q.y) < 0.5;
          return (eq(s[0], t[0]) && eq(s[1], t[1])) || (eq(s[0], t[1]) && eq(s[1], t[0]));
        };
        check('[474] PDF figure draws every detour leg',
          inter474.every(seg => pdfSegs.some(ps => sameSegTol(ps, seg))));
        // No drawn line work passes through the pad interior (pad OUTLINE
        // edges sit on the boundary and are excluded by the interior test).
        check('[474] no PDF line work passes through the pad interior',
          pdfSegs.every(([a, b]) => !crossesPad474(a, b)));
      }
    }
  }

  // ---------------------------------------------------------------
  // Source-scan (same pattern as [50]): the in-panel GroundingFigurePreview
  // manually mirrors drawGroundingFigure in permitPdf.ts and must be fed the
  // exact same buildGroundingPlan output the packet embeds. Expected styling
  // values are extracted from permitPdf.ts so a PDF-side change fails here
  // until the preview follows.
  {
    console.log('\n[58] Grounding figure preview mirrors the permit packet figure');
    const prevSrc = readFileSync('client/src/components/GroundingFigurePreview.tsx', 'utf8');
    const pdfSrc = readFileSync('client/src/lib/nextera/permitPdf.ts', 'utf8');
    const panelSrc = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');

    // The preview is actually mounted in the panel (the scan is moot otherwise).
    check('[58] panel mounts GroundingFigurePreview',
      panelSrc.includes('<GroundingFigurePreview') &&
      panelSrc.includes("from './GroundingFigurePreview'"));

    // Data parity: the panel has exactly ONE buildGroundingPlan call site
    // (the shared groundingPlan memo); the packet path passes that same
    // variable as the packet grounding, and the preview mount receives the
    // same variable — so preview and packet cannot diverge by construction.
    const planCalls = [...panelSrc.matchAll(/buildGroundingPlan\(/g)];
    check('[58] panel builds the grounding plan exactly once (shared memo)', planCalls.length === 1);
    const packetGrounding = panelSrc.match(/grounding:\s*exportGroundingDxf\s*\?\s*(\w+)\s*:\s*null/);
    const mount = panelSrc.match(/<GroundingFigurePreview\b([\s\S]*?)\/>/);
    const mountGrounding = mount?.[1].match(/grounding=\{(\w+)\}/);
    check('[58] packet path and preview mount use the SAME plan variable',
      !!packetGrounding && !!mountGrounding && packetGrounding[1] === mountGrounding[1],
      `packet(${packetGrounding?.[1]}) vs preview(${mountGrounding?.[1]})`);
    // The preview appears exactly when the packet section will (same opt-in).
    const mountGate = panelSrc.match(/\{(\S[^\n]*?)\s*&&[^\n]*\n\s*<GroundingFigurePreview/);
    check('[58] preview is gated on the packet opt-in (exportGroundingDxf)',
      !!mountGate && mountGate[1].includes('exportGroundingDxf'), mountGate?.[1] ?? 'no gate found');

    // Isolate the PDF figure function body.
    const figStart = pdfSrc.indexOf('export function drawGroundingFigure');
    const figTail = pdfSrc.slice(figStart);
    const figEnd = figTail.indexOf('\nexport function', 10);
    const figSrc = figStart >= 0 ? (figEnd > 0 ? figTail.slice(0, figEnd) : figTail) : '';
    check('[58] drawGroundingFigure found in permitPdf.ts', figSrc.length > 0);

    // Extract the figure's styling from the PDF source: sequential
    // setDrawColor/setLineWidth pairs are boundary, fence (reuses boundary
    // width), equipment, taps; then the dashed loop and rod fill/radius.
    // The boundary stroke is the shared property-line constant (spread
    // form, per [898]); resolve it to its RGB value in source order.
    const { PROPERTY_LINE_FIGURE_RGB: plRgb58 } =
      await import('../client/src/lib/nextera/propertyLineColor');
    const colors = [...figSrc.matchAll(/setDrawColor\((?:(\d+),\s*(\d+),\s*(\d+)|\.\.\.PROPERTY_LINE_FIGURE_RGB)\)/g)]
      .map(m => m[1] !== undefined ? `${m[1]},${m[2]},${m[3]}` : plRgb58.join(','));
    const widths = [...figSrc.matchAll(/setLineWidth\(([\d.]+)\)/g)].map(m => m[1]);
    const dash = figSrc.match(/setLineDashPattern\(\[(\d+),\s*(\d+)\]/);
    const fill = figSrc.match(/setFillColor\((\d+),\s*(\d+),\s*(\d+)\)/);
    const rodR = figSrc.match(/rodR\s*=\s*([\d.]+)/);
    check('[58] extracted stroke colors + widths + dash + rod style from the PDF figure',
      colors.length >= 4 && widths.length >= 4 && !!dash && !!fill && !!rodR,
      `colors=${colors.length} widths=${widths.length}`);

    // Boundary parity by shared source: the preview may stroke it via
    // BOUNDARY_STROKE derived from the same PROPERTY_LINE_FIGURE_RGB.
    const sharedStroke58 = prevSrc.includes("PROPERTY_LINE_FIGURE_RGB.join(',')");
    const hasStroke = (color: string, width: string) =>
      new RegExp(`stroke="rgb\\(${color.replace(/,/g, ',\\s*')}\\)"\\s+strokeWidth=\\{${width}\\}`,)
        .test(prevSrc.replace(/\n\s*/g, ' ')) ||
      (color === plRgb58.join(',') && sharedStroke58 &&
        new RegExp(`stroke=\\{BOUNDARY_STROKE\\}\\s+strokeWidth=\\{${width}\\}`)
          .test(prevSrc.replace(/\n\s*/g, ' ')));
    check('[58] preview boundary stroke matches the PDF figure', hasStroke(colors[0], widths[0]),
      `expect rgb(${colors[0]}) @ ${widths[0]}`);
    check('[58] preview fence stroke matches the PDF figure (same width as boundary)',
      hasStroke(colors[1], widths[0]), `expect rgb(${colors[1]}) @ ${widths[0]}`);
    check('[58] preview equipment stroke matches the PDF figure', hasStroke(colors[2], widths[1]),
      `expect rgb(${colors[2]}) @ ${widths[1]}`);
    check('[58] preview tap stroke matches the PDF figure', hasStroke(colors[3], widths[2]),
      `expect rgb(${colors[3]}) @ ${widths[2]}`);
    // Loop: same green, heavier dashed line with the PDF's dash pattern.
    check('[58] preview loop stroke + dash match the PDF figure',
      !!dash &&
      new RegExp(`stroke="rgb\\(${colors[3].replace(/,/g, ',\\s*')}\\)"\\s+strokeWidth=\\{${widths[3]}\\}\\s+strokeDasharray="${dash[1]} ${dash[2]}"`)
        .test(prevSrc.replace(/\n\s*/g, ' ')));
    // Rods: same fill color and radius.
    check('[58] preview rod dots match the PDF figure (fill + radius)',
      !!fill && !!rodR &&
      prevSrc.includes(`r={${rodR[1]}}`) &&
      prevSrc.includes(`fill="rgb(${fill[1]},${fill[2]},${fill[3]})"`));
    // Structural parity: equipment corners from the same rotated-rect math,
    // and both bail identically on an empty loop.
    check('[58] both derive equipment corners with the same rotated-rect corner list',
      prevSrc.includes('[-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy],') &&
      figSrc.includes('[-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy],'));
    check('[58] both bail identically on empty grounding loops (multi-loop aware)',
      prevSrc.includes('(grounding.loops ?? [grounding.loop]).filter(l => l.length > 2)') &&
      figSrc.includes('(grounding.loops ?? [grounding.loop]).filter(l => l.length > 2)'));
    // Caption parity: the preview's caption states the same rod/tap summary
    // fields and screening disclaimer the PDF caption prints.
    check('[58] preview caption mirrors the PDF caption summary fields',
      prevSrc.includes('rodCount') && prevSrc.includes('rodSpacingFt') &&
      prevSrc.includes('tapCount') && prevSrc.includes('testWellCount') &&
      prevSrc.includes('crossingCount') && prevSrc.includes('not an IEEE 80 study') &&
      figSrc.includes('testWellCount') && figSrc.includes('crossingCount') &&
      figSrc.includes('not an IEEE 80 study'));
    // Marker parity: crossings (small filled dots) and test wells (open
    // circles) draw in both the PDF figure and the preview.
    check('[58] preview draws crossings + test wells like the PDF figure',
      prevSrc.includes('crossings') && prevSrc.includes('testWells') &&
      figSrc.includes('crossings') && figSrc.includes('testWells'));
  }

  // ---------------------------------------------------------------
  {
    console.log('\n[59] IEEE-80 grounding grid study');
    const {
      buildIeee80Study, buildIeee80StudyFromPlan, geometryFromGroundingPlan,
      sanitizeIeee80Inputs, DEFAULT_IEEE80_INPUTS, surfaceDeratingCs,
      decrementFactorDf, requiredConductorKcmil, sverakRg,
    } = await import('../client/src/lib/nextera/ieee80');
    const { buildGroundingPlan } = await import('../client/src/lib/nextera/grounding');
    const { buildPermitPacketModel } = await import('../client/src/lib/nextera/permitReport');
    const { permitPacketSections } = await import('../client/src/lib/nextera/permitPdf');
    const near = (v: number, exp: number, tolPct: number) =>
      Math.abs(v - exp) <= Math.abs(exp) * tolPct / 100;

    // --- Benchmark: IEEE Std 80-2013 Annex B.1 (70m × 70m grid, 11 × 11
    // conductors, D = 7 m, h = 0.5 m, no rods, ρ = 400 Ω·m, 0.102 m of
    // 2500 Ω·m rock, IG = 1908 A, tf = 0.5 s, 50 kg limits).
    const annexInputs = {
      ...DEFAULT_IEEE80_INPUTS,
      soilRhoOhmM: 400, surfaceRhoOhmM: 2500, surfaceThicknessM: 0.102,
      faultCurrentA: 1908, faultDurationS: 0.5, splitFactorSf: 1, xOverR: 0,
      bodyWeightKg: 50 as const, burialDepthM: 0.5, conductorDiamM: 0.01,
    };
    const annexGeom = {
      areaM2: 4900, perimeterM: 280, conductorM: 1540, rodCount: 0,
      rodLengthM: 0, lxM: 70, lyM: 70, spacingDM: 7, perimeterRods: false,
    };
    const annex = buildIeee80Study(annexGeom, annexInputs);
    check('[59] Annex B.1: Cs ≈ 0.74', near(annex.cs, 0.74, 1), `cs=${annex.cs.toFixed(4)}`);
    check('[59] Annex B.1: Etouch50 ≈ 620.4 V', near(annex.etouchV, 620.4, 1), `et=${annex.etouchV.toFixed(1)}`);
    // Eq. 29 hand math: (1000 + 6·Cs·ρs)·0.116/√0.5 with Cs ≈ 0.7407 → ≈ 1992 V.
    check('[59] Annex B.1: Estep50 ≈ 1992 V (Eq. 29)', near(annex.estepV, 1992, 1), `es=${annex.estepV.toFixed(1)}`);
    check('[59] Annex B.1: Rg ≈ 2.78 Ω (Sverak Eq. 57)', near(annex.rgOhm, 2.78, 1), `rg=${annex.rgOhm.toFixed(3)}`);
    check('[59] Annex B.1: n ≈ 11', near(annex.n, 11, 2), `n=${annex.n.toFixed(2)}`);
    check('[59] Annex B.1: Km ≈ 0.89', near(annex.km, 0.89, 1.5), `km=${annex.km.toFixed(3)}`);
    check('[59] Annex B.1: Ki ≈ 2.272', near(annex.ki, 2.272, 1), `ki=${annex.ki.toFixed(3)}`);
    check('[59] Annex B.1: Ks ≈ 0.406', near(annex.ks, 0.406, 1.5), `ks=${annex.ks.toFixed(3)}`);
    check('[59] Annex B.1: GPR ≈ 5304 V', near(annex.gprV, 5304, 1), `gpr=${annex.gprV.toFixed(0)}`);
    check('[59] Annex B.1: Em ≈ 1002 V', near(annex.emV, 1002.1, 1), `em=${annex.emV.toFixed(1)}`);
    check('[59] Annex B.1: touch FAILS (Em > Etouch50) as in the standard',
      !annex.touchPass && annex.emV > annex.etouchV);
    check('[59] Annex B.1: step passes (Es < Estep50)', annex.stepPass && annex.esV < annex.estepV);
    check('[59] Annex B.1: Df = 1 when X/R = 0', annex.df === 1);

    // Elementary-factor spot checks.
    check('[59] Cs = 1 with no surface layer', surfaceDeratingCs(400, 2500, 0) === 1);
    check('[59] Df > 1 with DC offset and decreasing in tf',
      decrementFactorDf(20, 0.1) > decrementFactorDf(20, 1) && decrementFactorDf(20, 1) > 1);
    check('[59] Eq. 37 sizing: 50 kA / 0.5 s needs > 4/0 Cu, 5 kA / 0.25 s does not',
      requiredConductorKcmil(50000, 0.5) > 211.6 && requiredConductorKcmil(5000, 0.25) < 211.6);
    // Kf = 7.06 hand math: 20 kA / 0.5 s → 20 × 7.06 × √0.5 ≈ 99.8 kcmil.
    check('[59] Eq. 37 sizing: 20 kA / 0.5 s ≈ 99.8 kcmil',
      near(requiredConductorKcmil(20000, 0.5), 99.8, 1));

    // --- Plan-derived study on the Hondo design.
    const gp59 = buildGroundingPlan(design);
    check('[59] grounding plan available for the study', !!gp59);
    if (gp59) {
      const geom = geometryFromGroundingPlan(gp59, DEFAULT_IEEE80_INPUTS.rodLengthM);
      check('[59] plan geometry: positive area/perimeter/conductor, rods counted',
        geom.areaM2 > 0 && geom.perimeterM > 0 && geom.conductorM > 0 &&
        geom.rodCount === gp59.summary.rodCount && geom.spacingDM >= 2);
      check('[59] plan geometry matches summary within rounding',
        near(geom.areaM2, gp59.summary.gridAreaSqFt * 0.3048 * 0.3048, 0.1) &&
        near(geom.conductorM, gp59.summary.totalConductorFt * 0.3048, 0.1));
      const st = buildIeee80StudyFromPlan(gp59, DEFAULT_IEEE80_INPUTS);
      check('[59] plan study: finite positive results', [st.rgOhm, st.gprV, st.emV, st.esV, st.etouchV, st.estepV]
        .every(v => Number.isFinite(v) && v > 0));
      check('[59] plan study: deterministic',
        JSON.stringify(buildIeee80StudyFromPlan(gp59, DEFAULT_IEEE80_INPUTS)) === JSON.stringify(st));
      // Schwarz with sparse perimeter rods on a hollow loop lands near the
      // loop-only Sverak value (mutual term can push it slightly above) —
      // assert closeness and sanity, not strict ordering.
      const loopOnly = sverakRg(DEFAULT_IEEE80_INPUTS.soilRhoOhmM, geom.conductorM, geom.areaM2, DEFAULT_IEEE80_INPUTS.burialDepthM);
      check('[59] Schwarz Rg (with rods) is positive and within 20% of loop-only Sverak',
        st.rgOhm > 0 && near(st.rgOhm, loopOnly, 20), `schwarz=${st.rgOhm.toFixed(3)} sverak=${loopOnly.toFixed(3)}`);
      check('[59] study reports both Rg flavors, Schwarz selected with rods',
        st.rgSverakOhm > 0 && st.geometry.rodCount > 0 && st.rgOhm !== st.rgSverakOhm);
      check('[59] plan study: notes present and screening-scoped',
        st.notes.length > 0 && st.notes.join(' ').toLowerCase().includes('uniform'));

      // --- Permit packet: byte-identity when off, new section when on.
      const config59 = config;
      const baseModel = buildPermitPacketModel(design, config59, { now: new Date('2026-01-01T00:00:00Z') });
      const offModel = buildPermitPacketModel(design, config59, { now: new Date('2026-01-01T00:00:00Z'), ieee80: null });
      check('[59] packet model: omitted and explicit-null ieee80 are identical',
        JSON.stringify(baseModel) === JSON.stringify(offModel));
      const secOff = permitPacketSections(baseModel);
      check('[59] packet sections: no IEEE-80 section when off',
        secOff.every(t => t.id !== 'ieee80') && !JSON.stringify(secOff).includes('IEEE Std 80-2013'));
      const onModel = buildPermitPacketModel(design, config59, { now: new Date('2026-01-01T00:00:00Z'), ieee80: st });
      const secOn = permitPacketSections(onModel);
      const ieeeSec = secOn.find(t => t.id === 'ieee80');
      check('[59] packet sections: IEEE-80 section present when on, before appendix',
        !!ieeeSec && secOn.findIndex(t => t.id === 'ieee80') === secOn.findIndex(t => t.id === 'exceptions') - 1);
      check('[59] packet section: status column + PASS/FAIL rows + Rg/GPR values',
        !!ieeeSec && ieeeSec.statusCol === 2 &&
        ieeeSec.rows.some(r => r[2] === 'PASS' || r[2] === 'FAIL') &&
        JSON.stringify(ieeeSec.rows).includes(st.rgOhm.toFixed(3)));
      check('[59] packet sections: all non-IEEE sections unchanged when on',
        JSON.stringify(secOn.filter(t => t.id !== 'ieee80').map(t => ({ ...t, title: t.title.replace(/^\d+\. /, '') }))) ===
        JSON.stringify(secOff.map(t => ({ ...t, title: t.title.replace(/^\d+\. /, '') }))));
    }

    // --- Sanitizer: bad/partial input snaps back to defaults.
    check('[59] sanitizer: garbage → defaults',
      JSON.stringify(sanitizeIeee80Inputs(null)) === JSON.stringify(DEFAULT_IEEE80_INPUTS) &&
      JSON.stringify(sanitizeIeee80Inputs({ soilRhoOhmM: NaN, bodyWeightKg: 60, faultDurationS: -1 })) ===
      JSON.stringify(DEFAULT_IEEE80_INPUTS));
    check('[59] sanitizer: valid overrides survive',
      sanitizeIeee80Inputs({ soilRhoOhmM: 250, bodyWeightKg: 50 }).soilRhoOhmM === 250 &&
      sanitizeIeee80Inputs({ bodyWeightKg: 50 }).bodyWeightKg === 50);

    // --- Panel wiring parity (source scan, same style as [58]).
    const panelSrc59 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
    check('[59] panel: study derives from the shared grounding plan memo',
      panelSrc59.includes('buildIeee80StudyFromPlan(groundingPlan, ieee80Inputs)'));
    check('[59] panel: packet receives the same study variable the card shows',
      /ieee80:\s*ieee80Study/.test(panelSrc59) && panelSrc59.includes('ieee80Study.overallPass'));
  }

  // ---------------------------------------------------------------
  // [60] Per-bus short-circuit study ("ETAP-lite"): hand-checked fixture
  // math, POI data sheet opt-in section, sanitizer, and byte-identity of
  // the default sheet when the study is absent.
  {
    console.log('\n[60] Per-bus short-circuit study');
    const SC = await import('../client/src/lib/nextera/shortCircuit');
    const {
      buildShortCircuitStudy, DEFAULT_SC_INPUTS, sanitizeScInputs,
      CONDUCTOR_X_PER_KFT, peakFactorKappa,
    } = SC;
    const POI = await import('../client/src/lib/nextera/poiDataSheet');
    const { CONDUCTOR_R_PER_KFT } = await import('../client/src/lib/nextera/feeders');
    const near = (a: number, b: number, tol: number) => Math.abs(a - b) <= tol;

    // --- Hand-checked 2-feeder fixture. F1: two PCS daisy-chained
    // (1000 ft hop + 2000 ft home run); F2: one PCS through an FJB
    // (500 ft approach + 3000 ft home run). 500 kcmil Al.
    const seg = (lengthFt: number, amps: number) =>
      ({ pts: [{ x: 0, y: 0 }, { x: lengthFt, y: 0 }], lengthFt, amps });
    const mkFeeder = (over: Partial<import('../client/src/lib/nextera/feeders').FeederCircuit>) => ({
      idx: 1, inverterIds: [], loadMW: 4, amps: 67, segments: [],
      totalLengthFt: 0, size: '500' as const, material: 'Al' as const,
      vdVolts: 0, vdPct: 0, overLimit: false, recommendedSize: null,
      ampacity: 400, fjbId: null, overAmpacity: false,
      ampacityRecommendedSize: null, parallelRunsNeeded: 1,
      futurePcs: 0, eolAmps: 67, parallelSets: 1, effectiveAmpacity: 400,
      adjacentCircuits: 1, derateFactor: 1, governing: 'ampacity' as const, ...over,
    });
    const unitA = 67.3; // rated amps per PCS in the fixture
    const f1 = mkFeeder({
      idx: 1, inverterIds: ['PCS01-01', 'PCS01-02'],
      segments: [seg(1000, unitA), seg(2000, 2 * unitA)],
    });
    const f2 = mkFeeder({
      idx: 2, inverterIds: ['PCS02-01'], fjbId: 'fjb-1',
      segments: [seg(500, unitA), seg(3000, unitA)],
    });
    const inputs60 = { ...DEFAULT_SC_INPUTS }; // 1500 MVA, X/R 10, k 1.2
    const study = buildShortCircuitStudy([f1 as any, f2 as any], 3, unitA, inputs60, { hasAux: true });

    // Hand math: Zsrc = 34.5kV² / 1500 MVA = 0.79350 Ω, θ = atan(10)
    const zs = (34500 * 34500) / 1500e6;
    const th = Math.atan(10);
    const Rs = zs * Math.cos(th), Xs = zs * Math.sin(th);
    const invKA = (1.2 * 3 * unitA) / 1000;
    const rHome1 = (CONDUCTOR_R_PER_KFT.Al['500'] / 1000) * 2000;
    const xHome1 = (CONDUCTOR_X_PER_KFT['500'] / 1000) * 2000;

    const main = study.buses.find(b => b.kind === 'main')!;
    const utilMainKA = 34500 / Math.sqrt(3) / zs / 1000;
    check('[60] main bus: utility kA = V/(√3·Zsrc), inverters added arithmetically',
      near(main.utilityKA, utilMainKA, 0.001) && near(main.symKA, utilMainKA + invKA, 0.001));
    check('[60] main bus X/R equals the entered utility X/R', near(main.xOverR, 10, 0.001));
    check('[60] peak = κ·√2·sym with IEC κ from X/R',
      near(main.peakKA, peakFactorKappa(10) * Math.SQRT2 * main.symKA, 1e-9) &&
      near(peakFactorKappa(10), 1.02 + 0.98 * Math.exp(-0.3), 1e-12));

    // PCS01-02 (chain index 1, nearest launch): path = home run only.
    const p12 = study.buses.find(b => b.id === 'PCS01-02')!;
    const zTot12 = Math.hypot(Rs + rHome1, Xs + xHome1);
    check('[60] PCS at chain end: utility path = home run only (hand math)',
      near(p12.utilityKA, 34500 / Math.sqrt(3) / zTot12 / 1000, 0.001) &&
      near(p12.pathOhms, Math.hypot(rHome1, xHome1), 1e-9));
    // PCS01-01 (chain head): path = home run + 1000 ft hop.
    const p11 = study.buses.find(b => b.id === 'PCS01-01')!;
    const rHop = (CONDUCTOR_R_PER_KFT.Al['500'] / 1000) * 1000;
    const xHop = (CONDUCTOR_X_PER_KFT['500'] / 1000) * 1000;
    check('[60] PCS at chain head adds the hop impedance',
      near(p11.pathOhms, Math.hypot(rHome1 + rHop, xHome1 + xHop), 1e-9) &&
      p11.utilityKA < p12.utilityKA);
    check('[60] inverter contribution identical at every MV bus (current sources)',
      study.buses.filter(b => b.kind !== 'aux').every(b => near(b.inverterKA, invKA, 1e-12)));

    // FJB bus: F2 has 3 segments for 1 PCS → approach hop detected; the FJB
    // path is the 3000 ft home run only (single sharer, no parallel).
    const fjb = study.buses.find(b => b.kind === 'fjb')!;
    const rHome2 = (CONDUCTOR_R_PER_KFT.Al['500'] / 1000) * 3000;
    const xHome2 = (CONDUCTOR_X_PER_KFT['500'] / 1000) * 3000;
    check('[60] FJB bus path = home run only (approach hop excluded)',
      near(fjb.pathOhms, Math.hypot(rHome2, xHome2), 1e-9));
    // PCS02-01 behind the FJB adds the 500 ft approach hop.
    const p21 = study.buses.find(b => b.id === 'PCS02-01')!;
    check('[60] PCS behind FJB = home run + approach hop',
      near(p21.pathOhms, Math.hypot(
        rHome2 + (CONDUCTOR_R_PER_KFT.Al['500'] / 1000) * 500,
        xHome2 + (CONDUCTOR_X_PER_KFT['500'] / 1000) * 500), 1e-9));

    // Aux 480 V bus: utility through Zsrc' + Zxfmr (hand math).
    const aux = study.buses.find(b => b.kind === 'aux')!;
    const t = 480 / 34500;
    const zbLV = (480 * 480) / (inputs60.auxKVA * 1000);
    const zxLV = (inputs60.auxPctZ / 100) * zbLV;
    const thx = Math.atan(inputs60.auxXOverR);
    const zTotLV = Math.hypot(Rs * t * t + zxLV * Math.cos(thx), Xs * t * t + zxLV * Math.sin(thx));
    check('[60] aux 480V bus: utility kA through Zsrc″ + Zxfmr (hand math)',
      near(aux.utilityKA, 480 / Math.sqrt(3) / zTotLV / 1000, 0.001) && aux.voltageV === 480);
    check('[60] aux bus excluded when hasAux is false',
      buildShortCircuitStudy([f1 as any], 2, unitA, inputs60, { hasAux: false })
        .buses.every(b => b.kind !== 'aux'));

    // Rating margin: only when a rating is entered, MV buses only.
    check('[60] no rating → margin null everywhere and overRatedCount 0',
      study.buses.every(b => b.marginPct === null) && study.overRatedCount === 0);
    const rated = buildShortCircuitStudy([f1 as any, f2 as any], 3, unitA,
      { ...inputs60, equipmentRatingKA: 25 }, { hasAux: true });
    check('[60] rating margin on MV buses, null at 480V aux',
      rated.buses.filter(b => b.kind !== 'aux').every(b =>
        b.marginPct !== null && near(b.marginPct, (25 - b.symKA) / 25 * 100, 1e-9)) &&
      rated.buses.find(b => b.kind === 'aux')!.marginPct === null);
    check('[60] worstSymKA is the max over the MV buses',
      near(study.worstSymKA, Math.max(...study.buses.filter(b => b.kind !== 'aux').map(b => b.symKA)), 1e-12));
    check('[60] study is deterministic',
      JSON.stringify(buildShortCircuitStudy([f1 as any, f2 as any], 3, unitA, inputs60, { hasAux: true })) === JSON.stringify(study));

    // --- Sanitizer: garbage snaps to defaults, valid overrides survive.
    check('[60] sanitizer: garbage → defaults',
      JSON.stringify(sanitizeScInputs(null)) === JSON.stringify(DEFAULT_SC_INPUTS) &&
      JSON.stringify(sanitizeScInputs({ utilityFaultMVA: NaN, inverterK: 99, auxPctZ: -3 })) ===
      JSON.stringify(DEFAULT_SC_INPUTS));
    check('[60] sanitizer: valid overrides survive, bad rating → null',
      sanitizeScInputs({ utilityFaultMVA: 800, equipmentRatingKA: 25 }).utilityFaultMVA === 800 &&
      sanitizeScInputs({ equipmentRatingKA: 25 }).equipmentRatingKA === 25 &&
      sanitizeScInputs({ equipmentRatingKA: -5 }).equipmentRatingKA === null);

    // --- POI data sheet: byte-identity when absent, section 5 when present.
    const sub60 = { x: 2500, y: 0 };
    const feeders60 = generateFeeders(design, sub60, config.blockMW);
    const now60 = new Date('2026-03-01T12:00:00Z');
    const tb60 = { projectName: 'Hondo Storage', location: 'Hondo, TX', drafter: 'ECI', revision: 'B', date: '2026-03-01' };
    const base60 = POI.buildPoiDataSheetModel(design, config, { titleBlock: tb60, feeders: feeders60, substation: sub60, now: now60 });
    const null60 = POI.buildPoiDataSheetModel(design, config, { titleBlock: tb60, feeders: feeders60, substation: sub60, now: now60, shortCircuitStudy: null });
    check('[60] POI model: omitted and explicit-null study are identical',
      JSON.stringify(base60) === JSON.stringify(null60) && base60.shortCircuitStudy === null);
    // Structural twin of the string check ([69] pattern): deep-compare the
    // two models so any field the study toggle leaks is named structurally.
    check('[60] POI model: omitted and explicit-null study deep-equal in every field',
      (await import('node:util')).isDeepStrictEqual(base60, null60));
    check('[60] POI sections: still exactly 4 when no study (screening untouched)',
      POI.poiSections(base60).length === 4 &&
      !JSON.stringify(POI.poiSections(base60)).includes('Per-Bus'));
    check('[60] default POI PDF byte-identical with the feature absent',
      POI.buildPoiPdf(base60).output() === POI.buildPoiPdf(null60).output());
    const invCount60 = design.equipment.filter(e => e.kind === 'inverter').length;
    const study60 = buildShortCircuitStudy(feeders60, invCount60, inverterAmps(config.blockMW), inputs60, { hasAux: config.hasAuxEquipment });
    const on60 = POI.buildPoiDataSheetModel(design, config, { titleBlock: tb60, feeders: feeders60, substation: sub60, now: now60, shortCircuitStudy: study60 });
    const secOn60 = POI.poiSections(on60);
    check('[60] POI sections: study appends section 5 after the screening section',
      secOn60.length === 5 && secOn60[4].id === 'short-circuit-study' &&
      secOn60[4].title.startsWith('5.') &&
      JSON.stringify(secOn60.slice(0, 4)) === JSON.stringify(POI.poiSections(base60)));
    check('[60] POI study section: one row per bus + disclaimer + source assumptions',
      secOn60[4].rows.filter(r => study60.buses.some(b => b.label === r[0])).length === study60.buses.length &&
      JSON.stringify(secOn60[4].rows).includes('SIMPLIFIED STUDY') &&
      JSON.stringify(secOn60[4].rows).includes('MVA available'));
    check('[60] POI PDF with study rebuilds byte-identical',
      POI.buildPoiPdf(on60).output() === POI.buildPoiPdf(on60).output());

    // --- Additive module: default exports and dxfExport untouched.
    check('[60] yard DXF unchanged after study build',
      buildDesignDxfString(design, 'Hondo_Test') === dxf);
    const dxfSrc60 = readFileSync(path.resolve('client/src/lib/nextera/dxfExport.ts'), 'utf8');
    check('[60] dxfExport does not import the shortCircuit module',
      !dxfSrc60.includes('shortCircuit'));

    // --- Panel wiring parity (source scan, same style as [58]/[59]).
    const panelSrc60 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
    check('[60] panel: study derives from the routed feeders + persisted inputs',
      panelSrc60.includes('buildShortCircuitStudy(') && panelSrc60.includes('scInputs'));
    check('[60] panel: POI export receives the same study variable the card shows',
      panelSrc60.includes('shortCircuitStudy: scStudy') && panelSrc60.includes('scStudy.buses.map'));
  }

  // ---------------------------------------------------------------
  // [61] Grading-optimized layout rotation (earthwork vs yard rotation)
  {
    console.log('\n[61] Grading-optimized rotation');
    const G = await import('../client/src/lib/nextera/gradingOptimizer');
    const T61 = await import('../client/src/lib/nextera/terrain');
    const origin61 = { lat: 29.3, lon: -99.1 };
    const FT_PER_DEG_LAT = 364000;
    const ftPerLon61 = FT_PER_DEG_LAT * Math.cos((origin61.lat * Math.PI) / 180);
    const makeGrid61 = (rect: { minX: number; maxX: number; minY: number; maxY: number }, n: number, z: (x: number, y: number) => number) => {
      const bounds = {
        west: origin61.lon + rect.minX / ftPerLon61,
        east: origin61.lon + rect.maxX / ftPerLon61,
        south: origin61.lat + rect.minY / FT_PER_DEG_LAT,
        north: origin61.lat + rect.maxY / FT_PER_DEG_LAT,
      };
      const valuesFt: number[] = [];
      for (let r = 0; r < n; r++) {
        const y = rect.maxY - ((r + 0.5) / n) * (rect.maxY - rect.minY); // row 0 = north
        for (let c = 0; c < n; c++) valuesFt.push(z(rect.minX + ((c + 0.5) / n) * (rect.maxX - rect.minX), y));
      }
      return { width: n, height: n, bounds, valuesFt, source: 'synthetic', resolutionM: 10, noDataCount: 0 } as any;
    };

    // --- Pure rotation helpers
    const pv = { x: 100, y: 50 };
    const p0 = { x: 340, y: -120 };
    const rt61 = G.rotatePt(G.rotatePt(p0, 37, pv), -37, pv);
    check('[61] rotatePt round-trips (+37 then -37) to <1e-9 ft',
      Math.abs(rt61.x - p0.x) < 1e-9 && Math.abs(rt61.y - p0.y) < 1e-9);
    check('[61] rotatePt deg=0 is exact identity (same values)',
      G.rotatePt(p0, 0, pv).x === p0.x && G.rotatePt(p0, 0, pv).y === p0.y);
    const poly61 = [{ x: 0, y: 0 }, { x: 2000, y: 0 }, { x: 2000, y: 1200 }, { x: 0, y: 1200 }];
    check('[61] polygonPivot is the vertex mean',
      G.polygonPivot(poly61).x === 1000 && G.polygonPivot(poly61).y === 600);
    const b61: SiteBoundary = {
      name: 'grading-rect', polygon: poly61, origin: origin61,
      areaAcres: (2000 * 1200) / 43560,
    };
    check('[61] boundaryForYardRotation(0) returns the SAME object (byte identity)',
      G.boundaryForYardRotation(b61, 0) === b61);
    const b30 = G.boundaryForYardRotation(b61, 30);
    check('[61] rotated boundary preserves vertex count, area and pivot',
      b30.polygon.length === 4 &&
      Math.abs(Math.abs(polygonArea(b30.polygon)) - Math.abs(polygonArea(poly61))) < 1e-6 &&
      Math.abs(G.polygonPivot(b30.polygon).x - 1000) < 1e-9 &&
      Math.abs(G.polygonPivot(b30.polygon).y - 600) < 1e-9);

    // --- Grid resampling: tilted plane in the geo frame, sampled in the
    // yard frame, must equal the plane evaluated at the rotated-back point.
    const planeZ = (x: number, y: number) => 100 + 0.02 * x + 0.005 * y;
    const geoGrid = makeGrid61({ minX: -2000, maxX: 4000, minY: -2000, maxY: 3200 }, 96, planeZ);
    check('[61] resampleGridForYardRotation(0) returns the SAME grid object',
      G.resampleGridForYardRotation(geoGrid, origin61, 0, pv) === geoGrid);
    const yard25 = G.resampleGridForYardRotation(geoGrid, origin61, 25, G.polygonPivot(poly61));
    const rect25 = T61.terrainLocalRect(yard25, origin61);
    let maxErr = 0;
    for (const p of [{ x: 200, y: 300 }, { x: 1500, y: 900 }, { x: 900, y: 100 }]) {
      const geoP = G.rotatePt(p, 25, G.polygonPivot(poly61));
      const err = Math.abs(T61.sampleElevationFt(yard25, rect25, p.x, p.y) - planeZ(geoP.x, geoP.y));
      if (err > maxErr) maxErr = err;
    }
    check('[61] yard-frame samples match the geo plane at rotated-back points (<0.5 ft)',
      maxErr < 0.5, `maxErr=${maxErr.toFixed(3)}`);
    check('[61] resampled bounds round-trip: terrainLocalRect covers the rotated bbox',
      rect25.maxX - rect25.minX > 6000 - 1 && rect25.maxY - rect25.minY > 5200 - 1);

    // --- Ranking rules on crafted candidates (feasible-first, tie -> lowest angle)
    const mk = (deg: number, cut: number, fill: number, feasible: boolean) => ({
      rotationDeg: deg, padElevationFt: 0, cutCY: cut, fillCY: fill,
      netCY: cut - fill, totalCY: cut + fill, blocksPlaced: feasible ? 10 : 5, feasible,
    });
    const ranked = G.rankGradingCandidates(
      [mk(40, 50, 50, true), mk(10, 30, 70, true), mk(5, 999, 1, false), mk(20, 70, 30, true)], 'total');
    check('[61] rank(total): feasible first, ties broken by lowest angle',
      ranked.map(c => c.rotationDeg).join(',') === '10,20,40,5');
    const rankedNet = G.rankGradingCandidates(
      [mk(40, 50, 50, true), mk(10, 30, 70, true), mk(5, 999, 1, false), mk(20, 70, 30, true)], 'net');
    check('[61] rank(net): |cut-fill| ordering, feasible still first',
      rankedNet.map(c => c.rotationDeg).join(',') === '40,10,20,5');

    // --- Full sweep on a real layout: valley grid tilted along a known axis.
    // Plane rises along the geo x-axis only; the elongated parcel fits its
    // rows differently per pose, but the sweep must be deterministic and the
    // 0° candidate must exactly match computeCutFill on the raw inputs.
    const cfg61 = getEffectiveConfiguration('ge-aux-400', 4); // legacy QTY4 grid fixtures: pinned so the new QTY3 island default cannot silently reshape them
    const opts61 = { hotClimate: true, roadMode: 'roads' as const };
    const res61 = G.optimizeGrading(b61, geoGrid, cfg61, 40, 160, opts61, 'total', 45);
    check('[61] sweep evaluates 0..175 in 45° steps (4 poses), none cancelled',
      res61.total === 4 && res61.evaluated === 4 && !res61.cancelled && res61.candidates.length === 4);
    const c0 = res61.candidates.find(c => c.rotationDeg === 0)!;
    const d0 = generateSiteDesign(b61, cfg61, 40, 160, opts61);
    const cf0 = T61.computeCutFill(geoGrid, T61.terrainLocalRect(geoGrid, origin61), d0.fence)!;
    check('[61] 0° candidate matches computeCutFill on the raw grid exactly',
      c0.cutCY === cf0.cutCY && c0.fillCY === cf0.fillCY && c0.padElevationFt === cf0.padElevationFt &&
      c0.blocksPlaced === d0.blocksPlaced && c0.feasible);
    check('[61] baselineBlocks is the 0° pose block count',
      res61.baselineBlocks === d0.blocksPlaced);
    const res61b = G.optimizeGrading(b61, geoGrid, cfg61, 40, 160, opts61, 'total', 45);
    check('[61] sweep is deterministic (byte-equal JSON on rerun)',
      JSON.stringify(res61) === JSON.stringify(res61b));
    const feas61 = res61.candidates.filter(c => c.feasible);
    const scores61 = feas61.map(c => c.totalCY);
    check('[61] feasible candidates ranked by non-decreasing total earthwork',
      scores61.every((s, i) => i === 0 || s >= scores61[i - 1]));

    // --- Infeasible marking: a tiny parcel where only the 90° pose fits a
    // block. The 0° baseline is 0 blocks, so zero-block poses must be
    // marked infeasible (feasible requires blocksPlaced > 0) and the one
    // pose that places a block must rank first.
    const tiny61: SiteBoundary = {
      name: 'grading-tiny',
      polygon: [{ x: 0, y: 0 }, { x: 220, y: 0 }, { x: 220, y: 180 }, { x: 0, y: 180 }],
      origin: origin61, areaAcres: (220 * 180) / 43560,
    };
    const tinyGrid = makeGrid61({ minX: -600, maxX: 800, minY: -600, maxY: 800 }, 64, planeZ);
    const resTiny = G.optimizeGrading(tiny61, tinyGrid, cfg61, 20, 80, opts61, 'total', 45);
    const t0 = resTiny.candidates.find(c => c.rotationDeg === 0)!;
    const t90 = resTiny.candidates.find(c => c.rotationDeg === 90)!;
    check('[61] tiny parcel baseline (0°) places no blocks',
      resTiny.baselineBlocks === 0 && t0.blocksPlaced === 0);
    check('[61] zero-block poses are marked infeasible even at a 0-block baseline',
      !t0.feasible && resTiny.candidates.filter(c => c.blocksPlaced === 0).every(c => !c.feasible));
    // 1 block (not 2) since the fence returned to the 25 ft lot-line inset:
    // the setback shrinks this deliberately-tiny yard's usable envelope.
    check('[61] the one pose that places blocks is feasible',
      t90.blocksPlaced === 1 && t90.feasible,
      `t90 blocks=${t90.blocksPlaced} feasible=${t90.feasible}`);
    check('[61] infeasible poses never outrank the feasible one',
      resTiny.candidates[0] === t90);

    // --- Comparison rows: signed deltas vs the current pose, and the
    // current pose is ALWAYS in the table even outside the top N.
    const mkRes = (cands: any[]): any => ({
      candidates: cands, baselineBlocks: 10, objective: 'total' as const,
      stepDeg: 5, evaluated: cands.length, total: cands.length, cancelled: false,
    });
    const cmpCands = [mk(10, 100, 100, true), mk(20, 150, 150, true), mk(30, 200, 200, true),
      mk(40, 250, 250, true), mk(50, 300, 300, true), mk(60, 400, 400, true), mk(70, 500, 500, true)];
    const rowsCur70 = G.buildGradingComparisonRows(mkRes(cmpCands), 70, 5);
    check('[61] comparison rows pin the current pose when it is outside the top 5',
      rowsCur70.length === 6 && rowsCur70[5].isCurrent && rowsCur70[5].candidate.rotationDeg === 70 &&
      rowsCur70.slice(0, 5).every(r => !r.isCurrent));
    check('[61] deltas are signed vs the current pose (negative = saves earthwork)',
      rowsCur70[0].deltaCY === 200 - 1000 && rowsCur70[1].deltaCY === 300 - 1000 &&
      rowsCur70[5].deltaCY === 0);
    const rowsCur20 = G.buildGradingComparisonRows(mkRes(cmpCands), 20, 5);
    check('[61] current pose inside the top 5 is marked, not duplicated',
      rowsCur20.length === 5 && rowsCur20.filter(r => r.isCurrent).length === 1 &&
      rowsCur20[1].isCurrent && rowsCur20[1].deltaCY === 0 &&
      rowsCur20[0].deltaCY === 200 - 300 && rowsCur20[2].deltaCY === 400 - 300);
    const rowsNoCur = G.buildGradingComparisonRows(mkRes(cmpCands), 33, 5);
    check('[61] unevaluated current rotation -> null deltas, no current row',
      rowsNoCur.length === 5 && rowsNoCur.every(r => !r.isCurrent && r.deltaCY === null));
    const rowsNet = G.buildGradingComparisonRows(
      { ...mkRes([mk(10, 30, 70, true), mk(20, 70, 30, true)]), objective: 'net' }, 20, 5);
    check('[61] net objective deltas use |cut-fill|',
      rowsNet.find(r => r.candidate.rotationDeg === 10)!.deltaCY === Math.abs(30 - 70) - Math.abs(70 - 30));
    check('[61] empty candidate list -> no rows',
      G.buildGradingComparisonRows(mkRes([]), 0, 5).length === 0);

    // --- θ = 0 byte identity through the store's regenerate path: the yard
    // boundary IS the raw boundary object, so the DXF is the same string.
    const dxf61a = buildDesignDxfString(generateSiteDesign(G.boundaryForYardRotation(b61, 0), cfg61, 40, 160, opts61), 'Grading_Identity');
    const dxf61b = buildDesignDxfString(generateSiteDesign(b61, cfg61, 40, 160, opts61), 'Grading_Identity');
    check('[61] θ=0 export path is byte-identical to the pre-feature output',
      dxf61a === dxf61b);

    // --- Rotation state round-trips the project file / session sanitizer.
    const store61 = await import('../client/src/lib/stores/useDesignStore');
    const storeSrc61 = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
    check('[61] store: regenerate builds the yard-frame boundary via boundaryForYardRotation',
      storeSrc61.includes('boundaryForYardRotation(rawBoundary, yardRotationDeg)'));
    check('[61] store: setYardRotation pushes history and regenerates synchronously',
      storeSrc61.includes('setYardRotation:') &&
      /setYardRotation:[\s\S]{0,600}?pushHistory[\s\S]{0,600}?regenerate\(\{ sync: true \}\)/.test(storeSrc61));
    check('[61] store: applyBoundary/clearSite reset the rotation to 0',
      (storeSrc61.match(/yardRotationDeg: 0/g) ?? []).length >= 2);
    check('[61] store: session/project import sanitizes the rotation (finite, mod 180)',
      storeSrc61.includes('sanitizeYardRotation'));
    void store61;

    // --- Additive-feature guards (source scans, same style as [58]-[60]).
    const dxfSrc61 = readFileSync('client/src/lib/nextera/dxfExport.ts', 'utf8');
    check('[61] dxfExport never imports the grading optimizer (WYSIWYG untouched)',
      !dxfSrc61.includes('gradingOptimizer'));
    const pdfSrc61 = readFileSync('client/src/lib/nextera/pdfPlot.ts', 'utf8');
    check('[61] PDF cover: yardRotation is opt-in and a no-op when absent',
      pdfSrc61.includes('ctx.yardRotation') && /yr && yr\.deg !== 0/.test(pdfSrc61));
    const panelSrc61 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
    check('[61] panel: sweep runs in the worker with cancel support',
      panelSrc61.includes('optimizeGradingInWorker(') && panelSrc61.includes("cancelChannel('grading')"));
    check('[61] panel: terrain consumers read the yard-frame grid',
      panelSrc61.includes('resampleGridForYardRotation(terrain, boundary.origin, yardRotationDeg') &&
      panelSrc61.includes('computeCutFill(terrainYard'));
    check('[61] panel: layout optimizer searches in the yard frame',
      panelSrc61.includes('boundaryForYardRotation(boundary, yardRotationDeg)'));
    check('[61] panel: table rows come from buildGradingComparisonRows(current pose)',
      panelSrc61.includes('buildGradingComparisonRows(gradResult, yardRotationDeg)'));
    check('[61] panel: table renders the signed Δ CY column vs the current pose',
      panelSrc61.includes('Δ CY') && panelSrc61.includes('deltaCY') &&
      /deltaCY > 0 \? '\+' : deltaCY < 0 \? '−' : ''/.test(panelSrc61));
    const sceneSrc61 = readFileSync('client/src/components/DesignScene.tsx', 'utf8');
    check('[61] scene: satellite drape counter-rotates about the yard pivot',
      sceneSrc61.includes('yardPivot.x, 0, -yardPivot.y') &&
      sceneSrc61.includes('-(yardRotationDeg * Math.PI) / 180'));
  }

  // ---------------------------------------------------------------
  // [62] Interconnection package: relay one-line + LGIA data sheet
  {
    console.log('\n[62] Interconnection package (relay one-line + LGIA data sheet)');
    const R = await import('../client/src/lib/nextera/relayOneLine');
    const L = await import('../client/src/lib/nextera/lgiaDataSheet');
    const { generateFeeders } = await import('../client/src/lib/nextera/feeders');
    const { DxfWriter } = await import('../client/src/lib/nextera/dxfExport');
    const { sldPlanRect } = await import('../client/src/lib/nextera/sld');
    const POI62 = await import('../client/src/lib/nextera/poiDataSheet');

    const sub62 = { x: 2500, y: 0 };
    const feeders62 = generateFeeders(design, sub62, config.blockMW);
    check('[62] fixture: Hondo routes at least 2 feeders', feeders62.length >= 2, `${feeders62.length}`);

    // --- CT sizing rule: next standard primary above 125% of bus amps
    check('[62] nextStandardCt picks the next standard ratio above 125%',
      R.nextStandardCt(100) === 150 &&           // 125 → 150
      R.nextStandardCt(160) === 200 &&           // 200 exact
      R.nextStandardCt(161) === 250 &&           // 201.25 → 250
      R.nextStandardCt(900) === 1200 &&          // 1125 → 1200
      R.nextStandardCt(40) === 50);
    check('[62] nextStandardCt clamps at the largest standard primary',
      R.nextStandardCt(1e6) === R.STANDARD_CT_PRIMARIES[R.STANDARD_CT_PRIMARIES.length - 1]);
    check('[62] CT sizing factor is 125%', R.CT_SIZING_FACTOR === 1.25);

    // --- Model topology & device complement
    const rModel = R.buildRelayOneLineModel(design, feeders62, config);
    check('[62] one relay branch per routed feeder', rModel.feeders.length === feeders62.length);
    check('[62] every feeder branch carries the 50/51 device',
      rModel.feeders.every(f => f.devices.length === 1 && f.devices[0] === '50/51'));
    check('[62] main relay complement is 50/51, 50N/51N, 27/59, 81O/U, 25',
      rModel.mainDevices.join(',') === '50/51,50N/51N,27/59,81O/U,25');
    check('[62] per-feeder CT sized from that feeder\'s amps',
      rModel.feeders.every((f, i) => f.ctPrimary === R.nextStandardCt(feeders62[i].amps) &&
        f.ctLine.includes(`${f.ctPrimary}:5`)));
    check('[62] main CT sized from the aggregate bus current',
      rModel.mainCtPrimary === R.nextStandardCt(feeders62.reduce((s, f) => s + f.amps, 0)));
    check('[62] main bus amps are the aggregate of feeder amps',
      Math.abs(rModel.totalAmps - feeders62.reduce((s, f) => s + f.amps, 0)) < 1e-9);
    check('[62] breaker labels follow 52-M / 52-<circuit name>',
      rModel.mainBreakerLabel.startsWith('52-M') &&
      rModel.feeders.every((f, i) => f.breakerLabel === `52-${feederDisplayName(feeders62[i])}`));
    check('[62] metering block: M1 revenue meter, 0.15S CTs, 34500:120 VTs',
      rModel.metering.meterLabel.startsWith('M1') &&
      rModel.metering.ctLine.includes('0.15S') &&
      rModel.metering.vtLine.includes('34500:120'));

    // --- DXF sheet: valid, deterministic, disclaimer present
    const rDxf = R.buildRelayOneLineDxfString(design, 'Hondo_Relay', feeders62, config, {});
    check('[62] relay DXF has HEADER/TABLES/ENTITIES sections and EOF',
      rDxf.includes('HEADER') && rDxf.includes('TABLES') &&
      rDxf.includes('ENTITIES') && rDxf.trimEnd().endsWith('EOF'));
    check('[62] relay DXF has no NaN', !rDxf.includes('NaN'));
    check('[62] relay DXF titled RELAY & METERING ONE-LINE and labeled SHEET RLY-1',
      rDxf.includes(R.RELAY_SHEET_TITLE) && rDxf.includes('SHEET RLY-1'));
    check('[62] relay DXF carries every ANSI device number',
      [...rModel.mainDevices, '86'].every(d => rDxf.includes(d)));
    check('[62] relay DXF renders the main relay VT annotation',
      rDxf.includes(rModel.mainVtLine));
    check('[62] relay DXF carries the screening disclaimer',
      rDxf.includes('VERIFY WITH THE PROTECTION AND COORDINATION STUDY'));
    check('[62] relay DXF rebuild is byte-identical',
      rDxf === R.buildRelayOneLineDxfString(design, 'Hondo_Relay', feeders62, config, {}));

    // No zero-sweep ARCs (CT/relay bubbles are two half-arcs, SLD convention)
    {
      const lines62 = rDxf.split('\n');
      let badArc = false, arcCount = 0;
      for (let i = 0; i < lines62.length - 1; i++) {
        if (lines62[i].trim() === '0' && lines62[i + 1] === 'ARC') {
          arcCount++;
          let a1 = NaN, a2 = NaN;
          for (let j = i + 2; j < Math.min(i + 60, lines62.length - 1); j++) {
            if (lines62[j].trim() === '50') a1 = parseFloat(lines62[j + 1]);
            if (lines62[j].trim() === '51') { a2 = parseFloat(lines62[j + 1]); break; }
            if (lines62[j].trim() === '0') break;
          }
          if (!Number.isFinite(a1) || !Number.isFinite(a2) || Math.abs(a1 - a2) < 1e-9) badArc = true;
        }
      }
      check('[62] relay DXF has CT/relay circles with no zero-sweep ARCs',
        arcCount > 0 && !badArc, `${arcCount} arcs`);
    }

    // Schematic fits the plan rect
    {
      const w62 = new DxfWriter();
      const rect62 = sldPlanRect(design);
      R.drawRelayOneLineInto(w62, rModel, rect62);
      const eps = 1e-6;
      let inRect = true;
      for (const op of w62.ops) {
        const pts: number[][] =
          op.kind === 'line' ? [[op.x1, op.y1], [op.x2, op.y2]] :
          op.kind === 'poly' ? op.pts :
          op.kind === 'arc' ? [[op.cx - op.r, op.cy - op.r], [op.cx + op.r, op.cy + op.r]] :
          op.kind === 'text' ? [[op.x, op.y]] : [];
        for (const p of pts) {
          if (p[0] < rect62.minX - eps || p[0] > rect62.maxX + eps ||
              p[1] < rect62.minY - eps || p[1] > rect62.maxY + eps) { inRect = false; break; }
        }
        if (!inRect) break;
      }
      check('[62] relay schematic fits inside the plan rect', inRect);
    }

    // PDF twin, byte-deterministic
    const { buildRelayPdfString } = await import('../client/src/lib/nextera/pdfPlot');
    const rCtx = { design, projectName: 'Hondo_Relay', config, meta: {} };
    const rPdf = buildRelayPdfString(rCtx, feeders62);
    check('[62] relay PDF is non-trivial and starts with %PDF', rPdf.startsWith('%PDF') && rPdf.length > 10000);
    check('[62] relay PDF rebuild is byte-identical', rPdf === buildRelayPdfString(rCtx, feeders62));

    // --- LGIA data sheet model
    const now62 = new Date('2026-07-25T12:00:00Z');
    const tb62 = { projectName: 'Hondo BESS', location: 'Hondo, TX', drafter: 'AB', revision: 'B', date: '2026-07-25' } as any;
    const lModel = L.buildLgiaDataSheetModel(design, config, {
      titleBlock: tb62, feeders: feeders62, substation: sub62, now: now62,
    });
    check('[62] LGIA nameplate MVA = MW / 0.95',
      Math.abs(lModel.nameplate.mvaAtRatedPf - design.achievedMW / 0.95) < 1e-9);
    check('[62] LGIA fault contribution matches the POI screening rule',
      Math.abs(lModel.faultContribution.screeningAmps -
        POI62.buildPoiDataSheetModel(design, config, { feeders: feeders62 }).shortCircuit.screeningAmps) < 1e-9);
    check('[62] LGIA feeder schedule has one row per feeder with conductor + length',
      lModel.interconnection.feeders.length === feeders62.length &&
      lModel.interconnection.feeders.every((f, i) =>
        f.conductor.includes(feeders62[i].size) && f.lengthFt === feeders62[i].totalLengthFt));
    check('[62] LGIA references the relay one-line sheet',
      lModel.oneLineReference.includes('RLY-1'));
    check('[62] LGIA ride-through cites IEEE 2800 and is marked placeholder',
      lModel.rideThrough.includes('IEEE 2800') && lModel.rideThrough.includes(L.PLACEHOLDER));
    check('[62] LGIA certifications cite UL 1741 SB and are marked placeholder',
      lModel.certifications.includes('UL 1741 SB') && lModel.certifications.includes(L.PLACEHOLDER));
    check('[62] LGIA transformer lines carry catalog data + placeholder impedance',
      lModel.transformers.pcsStepUpLine.includes(L.PLACEHOLDER) &&
      lModel.transformers.auxLine !== null && lModel.transformers.auxLine.includes('HITACHI'));

    // Drafter-entered LGIA inputs replace the placeholders — and ONLY where
    // a value was actually supplied.
    {
      const lFilled = L.buildLgiaDataSheetModel(design, config, {
        titleBlock: tb62, feeders: feeders62, substation: sub62, now: now62,
        lgiaInputs: {
          pcsXfmrZPct: 6.5, auxXfmrZPct: 5.75,
          rideThroughDetail: 'Category III; zero-voltage ride-through 0.16 s',
          certificationDetail: 'CSA listing, file no. 123456',
        },
      });
      check('[62] entered PCS step-up %Z replaces the impedance placeholder',
        lFilled.transformers.pcsStepUpLine.includes('Z = 6.5%') &&
        !lFilled.transformers.pcsStepUpLine.includes(L.PLACEHOLDER));
      check('[62] entered aux %Z replaces the impedance placeholder',
        lFilled.transformers.auxLine !== null &&
        lFilled.transformers.auxLine.includes('Z = 5.75%') &&
        !lFilled.transformers.auxLine.includes(L.PLACEHOLDER));
      check('[62] entered ride-through settings replace the placeholder but keep the IEEE 2800 statement',
        lFilled.rideThrough.includes('IEEE 2800') &&
        lFilled.rideThrough.includes('Category III') &&
        !lFilled.rideThrough.includes(L.PLACEHOLDER));
      check('[62] entered UL 1741 SB certificate detail replaces the placeholder',
        lFilled.certifications.includes('UL 1741 SB') &&
        lFilled.certifications.includes('file no. 123456') &&
        !lFilled.certifications.includes(L.PLACEHOLDER));

      // Partially-filled: untouched fields keep their placeholders.
      const lPartial = L.buildLgiaDataSheetModel(design, config, {
        titleBlock: tb62, feeders: feeders62, substation: sub62, now: now62,
        lgiaInputs: { ...L.DEFAULT_LGIA_INPUTS, pcsXfmrZPct: 6 },
      });
      check('[62] partial inputs: PCS %Z filled, aux/ride-through/cert keep placeholders',
        lPartial.transformers.pcsStepUpLine.includes('Z = 6%') &&
        lPartial.transformers.auxLine!.includes(L.PLACEHOLDER) &&
        lPartial.rideThrough.includes(L.PLACEHOLDER) &&
        lPartial.certifications.includes(L.PLACEHOLDER));

      // Sanitizer: garbage snaps back to "missing" (placeholder), text is
      // trimmed/flattened/capped, valid values round to 2 decimals.
      const san = L.sanitizeLgiaInputs({
        pcsXfmrZPct: 'garbage', auxXfmrZPct: 55, rideThroughDetail: '  a\nb\t c  ',
        certificationDetail: 'x'.repeat(1000),
      });
      check('[62] sanitizeLgiaInputs: non-numeric / out-of-range %Z snap to null',
        san.pcsXfmrZPct === null && san.auxXfmrZPct === null);
      check('[62] sanitizeLgiaInputs: text flattened + trimmed + length-capped',
        san.rideThroughDetail === 'a b c' && san.certificationDetail.length === 300);
      check('[62] sanitizeLgiaInputs: valid values pass through (2-decimal rounding)',
        L.sanitizeLgiaInputs({ pcsXfmrZPct: 6.499, auxXfmrZPct: '5.75' }).pcsXfmrZPct === 6.5 &&
        L.sanitizeLgiaInputs({ auxXfmrZPct: '5.75' }).auxXfmrZPct === 5.75);
      // New/cleared site must not carry a previous project's LGIA nameplate
      // values (would silently suppress placeholders on a fresh design).
      const storeSrc62b = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
      check('[62] store: applyBoundary/clearSite reset LGIA inputs to placeholders',
        (storeSrc62b.match(/lgiaInputs: \{ \.\.\.DEFAULT_LGIA_INPUTS \}/g) ?? []).length >= 3);

      check('[62] sanitizeLgiaInputs: garbage input yields the all-placeholder defaults',
        JSON.stringify(L.sanitizeLgiaInputs(undefined)) === JSON.stringify(L.DEFAULT_LGIA_INPUTS) &&
        JSON.stringify(L.sanitizeLgiaInputs(42)) === JSON.stringify(L.DEFAULT_LGIA_INPUTS));

      // Filled-input PDF stays deterministic.
      const lFilledPdf = L.buildLgiaPdfString(lFilled);
      check('[62] filled-input LGIA PDF is deterministic and differs from the placeholder PDF',
        lFilledPdf.startsWith('%PDF') &&
        lFilledPdf === L.buildLgiaPdfString(L.buildLgiaDataSheetModel(design, config, {
          titleBlock: tb62, feeders: feeders62, substation: sub62, now: now62,
          lgiaInputs: {
            pcsXfmrZPct: 6.5, auxXfmrZPct: 5.75,
            rideThroughDetail: 'Category III; zero-voltage ride-through 0.16 s',
            certificationDetail: 'CSA listing, file no. 123456',
          },
        })) &&
        lFilledPdf !== L.buildLgiaPdfString(lModel));
    }

    const lSecs = L.lgiaSections(lModel);
    check('[62] LGIA sections: 7 numbered sections',
      lSecs.length === 7 && lSecs.every((s, i) => s.title.startsWith(`${i + 1}.`)));
    const fs62 = lSecs.find(s => s.id === 'feeder-schedule')!;
    check('[62] feeder schedule section is 6-column tabular',
      fs62.head.length === 6 && fs62.rows.every(r => r.length === 6) &&
      fs62.rows.length === feeders62.length);
    check('[62] fault section carries the short-circuit disclaimer',
      lSecs.find(s => s.id === 'fault')!.rows.some(r => r[1].includes('SIMPLIFIED STUDY')));
    check('[62] metering section lists the metering equipment and one-line reference',
      lSecs.find(s => s.id === 'metering')!.rows.some(r => r[1].includes('0.15S')) &&
      lSecs.find(s => s.id === 'metering')!.rows.some(r => r[1].includes('RLY-1')));

    // Per-bus study opt-in appends rows without disturbing the basis rule
    {
      const { buildShortCircuitStudy, DEFAULT_SC_INPUTS } = await import('../client/src/lib/nextera/shortCircuit');
      const { inverterAmps: invAmps62 } = await import('../client/src/lib/nextera/feeders');
      const invCount62 = design.equipment.filter(e => e.kind === 'inverter').length;
      const study62 = buildShortCircuitStudy(
        feeders62, invCount62, invAmps62(config.blockMW), DEFAULT_SC_INPUTS,
        { hasAux: config.hasAuxEquipment });
      const lStudy = L.buildLgiaDataSheetModel(design, config, {
        titleBlock: tb62, feeders: feeders62, substation: sub62, now: now62, shortCircuitStudy: study62,
      });
      const faultRows = L.lgiaSections(lStudy).find(s => s.id === 'fault')!.rows;
      check('[62] opt-in study adds one row per bus to the fault section',
        faultRows.length === 3 + study62.buses.length, `${faultRows.length}`);
      check('[62] study basis line names the per-bus study',
        lStudy.faultContribution.basis.includes('per-bus'));
    }

    // PDF: deterministic bytes with injected now
    const lPdf = L.buildLgiaPdfString(lModel);
    check('[62] LGIA PDF is non-trivial and starts with %PDF', lPdf.startsWith('%PDF') && lPdf.length > 5000);
    check('[62] LGIA PDF rebuild is byte-identical (injected now)',
      lPdf === L.buildLgiaPdfString(L.buildLgiaDataSheetModel(design, config, {
        titleBlock: tb62, feeders: feeders62, substation: sub62, now: now62,
      })));

    // --- Additive-feature guards: default exports untouched
    const dxfSrc62 = readFileSync('client/src/lib/nextera/dxfExport.ts', 'utf8');
    const sheetsSrc62 = readFileSync('client/src/lib/nextera/dxfSheets.ts', 'utf8');
    check('[62] dxfExport never imports relayOneLine or lgiaDataSheet',
      !dxfSrc62.includes('relayOneLine') && !dxfSrc62.includes('lgiaDataSheet'));
    check('[62] drawing-package registry never imports relayOneLine or lgiaDataSheet',
      !sheetsSrc62.includes('relayOneLine') && !sheetsSrc62.includes('lgiaDataSheet'));
    const dxf62a = buildDesignDxfString(design, 'Hondo_Test');
    check('[62] default design DXF is byte-identical with the feature present',
      dxf62a === dxf);
  }

  // ---------------------------------------------------------------
  // [63] Proposed grading surface engine (FG pads / benches / balance)
  {
    console.log('\n[63] Grading surface engine (FG pads, benches, earthwork balance)');
    const G = await import('../client/src/lib/nextera/gradingSurface');
    const T63 = await import('../client/src/lib/nextera/terrain');

    const origin63 = { lat: 29.35, lon: -99.15 };
    const ftPerLon63 = 364000 * Math.cos((origin63.lat * Math.PI) / 180);
    const makeGrid63 = (rect: { minX: number; maxX: number; minY: number; maxY: number }, n: number, z: (x: number, y: number) => number) => {
      const bounds = {
        west: origin63.lon + rect.minX / ftPerLon63,
        east: origin63.lon + rect.maxX / ftPerLon63,
        south: origin63.lat + rect.minY / 364000,
        north: origin63.lat + rect.maxY / 364000,
      };
      const cellX = (rect.maxX - rect.minX) / n, cellY = (rect.maxY - rect.minY) / n;
      const valuesFt: number[] = [];
      for (let r = 0; r < n; r++) {
        const y = rect.maxY - (r + 0.5) * cellY; // row 0 = north
        for (let c = 0; c < n; c++) valuesFt.push(z(rect.minX + (c + 0.5) * cellX, y));
      }
      return {
        grid: { width: n, height: n, bounds, valuesFt, source: 'synthetic', resolutionM: 10, noDataCount: 0 },
        rect,
      };
    };
    const fence63: { x: number; y: number }[] = [
      { x: 100, y: 100 }, { x: 900, y: 100 }, { x: 900, y: 900 }, { x: 100, y: 900 },
    ];
    const rect63 = { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };

    // --- Sanitizer: garbage snaps back to defaults, finite values clamp
    const sanBad = G.sanitizeGradingInputs({ padSlopePct: 'x', slopeDirDeg: NaN, benchMode: 3, maxBenchHeightFt: null });
    check('[63] sanitizer: non-numeric garbage snaps every field to defaults',
      JSON.stringify(sanBad) === JSON.stringify(G.DEFAULT_GRADING_INPUTS));
    check('[63] sanitizer: null/array/undefined input returns pure defaults',
      JSON.stringify(G.sanitizeGradingInputs(null)) === JSON.stringify(G.DEFAULT_GRADING_INPUTS) &&
      JSON.stringify(G.sanitizeGradingInputs([1, 2])) === JSON.stringify(G.DEFAULT_GRADING_INPUTS) &&
      JSON.stringify(G.sanitizeGradingInputs(undefined)) === JSON.stringify(G.DEFAULT_GRADING_INPUTS));
    const sanClamp = G.sanitizeGradingInputs({ padSlopePct: 99, cutRatioH: 0.1, shrinkPct: -5, slopeDirDeg: -90, maxBenchHeightFt: 100 });
    check('[63] sanitizer: finite values clamp into engineering ranges',
      sanClamp.padSlopePct === 5 && sanClamp.cutRatioH === 1 && sanClamp.shrinkPct === 0 &&
      sanClamp.maxBenchHeightFt === 20);
    check('[63] sanitizer: slope azimuth normalizes into [0, 360)',
      sanClamp.slopeDirDeg === 270 &&
      G.sanitizeGradingInputs({ slopeDirDeg: 450 }).slopeDirDeg === 90);

    // --- Flat site, flat pad: FG == OG, zero earthwork everywhere
    const flat63 = makeGrid63(rect63, 64, () => 250);
    const fgFlat = G.buildFgSurface(flat63.grid, flat63.rect, fence63,
      { padSlopePct: 0, shrinkPct: 0, topsoilStripIn: 0, balanceBiasCY: 0 })!;
    check('[63] flat site + flat pad: cut and fill are both ~0',
      fgFlat !== null && fgFlat.earthwork.cutCY < 1 && fgFlat.earthwork.fillCY < 1,
      `cut ${fgFlat?.earthwork.cutCY}, fill ${fgFlat?.earthwork.fillCY}`);
    check('[63] flat site: FG pad elevation equals existing grade (250 ft)',
      Math.abs(G.fgPadElevationAt(fgFlat, 500, 500) - 250) < 0.01);
    check('[63] flat site: single bench when bench mode is off',
      fgFlat.benches.length === 1 && fgFlat.earthwork.maxBenchStepFt === 0);

    // --- Sloped plane, flat pad: balance solver hits adjustedNet == bias
    const ramp63 = makeGrid63(rect63, 64, x => 200 + 0.04 * x);
    const fgRamp = G.buildFgSurface(ramp63.grid, ramp63.rect, fence63,
      { padSlopePct: 0, shrinkPct: 0, topsoilStripIn: 0, balanceBiasCY: 0 })!;
    check('[63] sloped site: balance solver zeroes adjusted net (|net| < 5 CY)',
      Math.abs(fgRamp.earthwork.adjustedNetCY) < 5, `${fgRamp.earthwork.adjustedNetCY.toFixed(2)} CY`);
    check('[63] sloped site, no shrink: cut ~ fill (within 1%)',
      Math.abs(fgRamp.earthwork.cutCY - fgRamp.earthwork.fillCY) < 0.01 * fgRamp.earthwork.cutCY);
    check('[63] sloped site: flat pad lands near the mid-ramp elevation',
      Math.abs(G.fgPadElevationAt(fgRamp, 500, 500) - 220) < 1.5,
      `${G.fgPadElevationAt(fgRamp, 500, 500).toFixed(2)} vs 220`);

    // --- Shrink math: adjustedFill = fill / (1 - shrink), solver still balances
    const fgShrink = G.buildFgSurface(ramp63.grid, ramp63.rect, fence63,
      { padSlopePct: 0, shrinkPct: 20, topsoilStripIn: 0, balanceBiasCY: 0 })!;
    check('[63] shrink: adjustedFill == fill / (1 - shrink/100)',
      Math.abs(fgShrink.earthwork.adjustedFillCY - fgShrink.earthwork.fillCY / 0.8) < 0.01);
    check('[63] shrink: solver rebalances so adjusted net ~ 0, so cut > fill',
      Math.abs(fgShrink.earthwork.adjustedNetCY) < 5 &&
      fgShrink.earthwork.cutCY > fgShrink.earthwork.fillCY);
    check('[63] shrink: FG drops below the no-shrink pad (extra cut feeds shrink)',
      G.fgPadElevationAt(fgShrink, 500, 500) < G.fgPadElevationAt(fgRamp, 500, 500));
    check('[63] haul loose volume = cut * (1 + swell/100)',
      Math.abs(fgShrink.earthwork.haulLooseCY -
        fgShrink.earthwork.cutCY * (1 + fgShrink.inputs.swellPct / 100)) < 0.01);

    // --- Balance bias: positive target -> that much import
    const fgBias = G.buildFgSurface(ramp63.grid, ramp63.rect, fence63,
      { padSlopePct: 0, shrinkPct: 0, topsoilStripIn: 0, balanceBiasCY: 5000 })!;
    check('[63] balance bias: adjusted net hits the +5000 CY import target',
      Math.abs(fgBias.earthwork.adjustedNetCY - 5000) < 5, `${fgBias.earthwork.adjustedNetCY.toFixed(1)}`);
    check('[63] balance bias: import target raises the pad above balanced FG',
      G.fgPadElevationAt(fgBias, 500, 500) > G.fgPadElevationAt(fgRamp, 500, 500));

    // --- Pad drainage slope: 1% east means -1 ft per 100 ft eastward
    const fgSlope = G.buildFgSurface(flat63.grid, flat63.rect, fence63,
      { padSlopePct: 1, slopeDirDeg: 90, shrinkPct: 0, topsoilStripIn: 0 })!;
    const dEast = G.fgPadElevationAt(fgSlope, 300, 500) - G.fgPadElevationAt(fgSlope, 400, 500);
    const dNorth = G.fgPadElevationAt(fgSlope, 500, 300) - G.fgPadElevationAt(fgSlope, 500, 400);
    check('[63] pad slope: 1% toward east drops 1 ft per 100 ft east, 0 north',
      Math.abs(dEast - 1) < 1e-6 && Math.abs(dNorth) < 1e-6, `east ${dEast}, north ${dNorth}`);

    // --- Bench mode: relief/maxBench sets the count, steps stay capped
    const steep63 = makeGrid63(rect63, 64, x => 100 + 0.05 * x); // ~40 ft relief in fence
    const fgBench = G.buildFgSurface(steep63.grid, steep63.rect, fence63,
      { padSlopePct: 0, slopeDirDeg: 90, benchMode: true, maxBenchHeightFt: 8, shrinkPct: 0, topsoilStripIn: 0 })!;
    check('[63] bench mode: ~40 ft relief / 8 ft max -> 5 benches',
      fgBench.benches.length === 5, `${fgBench.benches.length}`);
    check('[63] bench mode: max step between benches respects the 8 ft cap',
      fgBench.earthwork.maxBenchStepFt > 0 && fgBench.earthwork.maxBenchStepFt <= 8 + 1e-6,
      `${fgBench.earthwork.maxBenchStepFt.toFixed(2)} ft`);
    check('[63] bench mode: benches ordered downhill with monotone extents',
      fgBench.benches.every((b, i) => i === 0 || b.proj0 >= fgBench.benches[i - 1].proj1 - 1e-6));
    check('[63] bench mode: ramp screening reports required ramp length',
      fgBench.earthwork.requiredRampLenFt ===
        fgBench.earthwork.maxBenchStepFt / (fgBench.inputs.maxRoadGradePct / 100));
    const cliff63 = makeGrid63(rect63, 64, x => 0.5 * x); // 400 ft relief
    const fgCliff = G.buildFgSurface(cliff63.grid, cliff63.rect, fence63,
      { benchMode: true, maxBenchHeightFt: 2, shrinkPct: 0, topsoilStripIn: 0 })!;
    check('[63] bench count is capped at 12 on extreme relief',
      fgCliff.benches.length === 12);
    check('[63] extreme relief: bench-step clamp caps every step at the 2 ft max',
      fgCliff.earthwork.maxBenchStepFt <= 2 + 1e-6, `${fgCliff.earthwork.maxBenchStepFt.toFixed(2)} ft`);
    const fgRampWarn = G.buildFgSurface(steep63.grid, steep63.rect, fence63,
      { padSlopePct: 0, slopeDirDeg: 90, benchMode: true, maxBenchHeightFt: 8, maxRoadGradePct: 2, shrinkPct: 0, topsoilStripIn: 0 })!;
    check('[63] ramp longer than a bench emits the ramp warning',
      fgRampWarn.earthwork.warnings.some(w => w.includes('Ramp between benches')));

    // --- Ramp transitions: benches connect via graded ramps, not vertical steps
    // Scan the FG pad along the downhill axis (east) at 1 ft spacing: the
    // surface must be continuous and its grade must respect maxRoadGradePct
    // wherever the ramp band is not clamped by bench depth.
    ((): void => {
      let maxJump = 0, maxGradePct63 = 0;
      let prev = G.fgPadElevationAt(fgBench, 101, 500);
      for (let x = 102; x <= 899; x += 1) {
        const v = G.fgPadElevationAt(fgBench, x, 500);
        maxJump = Math.max(maxJump, Math.abs(v - prev));
        maxGradePct63 = Math.max(maxGradePct63, Math.abs(v - prev) * 100);
        prev = v;
      }
      check('[63] bench FG is continuous along the slope (no vertical steps, <0.25 ft/ft)',
        maxJump < 0.25, `max jump ${maxJump.toFixed(3)} ft over 1 ft`);
      check('[63] ramp bands climb at <= max road grade (8% + tolerance)',
        maxGradePct63 <= fgBench.inputs.maxRoadGradePct + 0.5,
        `max grade ${maxGradePct63.toFixed(2)}%`);
    })();
    check('[63] ramp midpoint sits between the two bench planes',
      ((): boolean => {
        const b0 = fgBench.benches[0], b1 = fgBench.benches[1];
        // Boundary projection = east coordinate (dir = east).
        const x = b1.proj0;
        const v = G.fgPadElevationAt(fgBench, x, 500);
        const e0 = b0.baseElevFt, e1 = b1.baseElevFt;
        return v >= Math.min(e0, e1) - 1e-6 && v <= Math.max(e0, e1) + 1e-6;
      })());
    check('[63] ramp corridors are integrated in the earthwork (balance still holds)',
      Math.abs(fgBench.earthwork.adjustedNetCY - fgBench.inputs.balanceBiasCY) < 5,
      `${fgBench.earthwork.adjustedNetCY.toFixed(1)} CY`);

    // --- Tie-in band and daylight polygon
    check('[63] sloped site: tie-in band area > 0 and counted as disturbed',
      fgRamp.earthwork.tieInAreaSqFt > 0 &&
      Math.abs(fgRamp.earthwork.disturbedAreaSqFt -
        (fgRamp.earthwork.padAreaSqFt + fgRamp.earthwork.tieInAreaSqFt)) < 1e-6);
    check('[63] daylight polygon: one vertex per fence vertex, none inside the fence interior',
      fgRamp.daylightPolygon.length === fence63.length &&
      fgRamp.daylightPolygon.every(p => {
        const inside = ((): boolean => {
          // strict interior test with a small inward tolerance
          const eps = 0.01;
          return p.x > 100 + eps && p.x < 900 - eps && p.y > 100 + eps && p.y < 900 - eps;
        })();
        return !inside;
      }));
    check('[63] topsoil: 6 in strip over disturbed area in CY',
      ((): boolean => {
        const fgT = G.buildFgSurface(ramp63.grid, ramp63.rect, fence63,
          { padSlopePct: 0, shrinkPct: 0, topsoilStripIn: 6 })!;
        const expect63 = (fgT.earthwork.disturbedAreaSqFt * 0.5) / 27;
        return Math.abs(fgT.earthwork.topsoilCY - expect63) < 0.01;
      })());

    // --- fgElevationAt: continuous across the fence, back to OG past daylight
    const rectT = T63.terrainLocalRect(ramp63.grid, origin63);
    const inEdge = G.fgElevationAt(fgRamp, ramp63.grid, rectT, 899.9, 500);
    const outEdge = G.fgElevationAt(fgRamp, ramp63.grid, rectT, 900.1, 500);
    check('[63] fgElevationAt is continuous across the fence line (<0.2 ft jump)',
      Math.abs(inEdge - outEdge) < 0.2, `in ${inEdge.toFixed(2)}, out ${outEdge.toFixed(2)}`);
    check('[63] fgElevationAt in the cut band: slope face rises at 1 ft per cutRatioH',
      ((): boolean => {
        // 10 ft outside a cut edge, face is fgEdge + 10/cutRatioH (below OG)
        const fgEdge = G.fgPadElevationAt(fgRamp, 900, 500);
        const v = G.fgElevationAt(fgRamp, ramp63.grid, rectT, 910, 500);
        return Math.abs(v - (fgEdge + 10 / fgRamp.inputs.cutRatioH)) < 0.05;
      })());
    const farOut = G.fgElevationAt(fgRamp, ramp63.grid, rectT, 900 + 200, 500);
    const ogFar = T63.sampleElevationFt(ramp63.grid, rectT, 1100, 500);
    check('[63] fgElevationAt returns existing ground beyond the daylight band',
      Math.abs(farOut - ogFar) < 1e-9);

    // --- Determinism: identical inputs -> byte-identical surface
    const fgA = G.buildFgSurface(steep63.grid, steep63.rect, fence63,
      { benchMode: true, maxBenchHeightFt: 8 })!;
    const fgB = G.buildFgSurface(steep63.grid, steep63.rect, fence63,
      { benchMode: true, maxBenchHeightFt: 8 })!;
    check('[63] buildFgSurface is deterministic (identical JSON on re-run)',
      JSON.stringify(fgA) === JSON.stringify(fgB));

    // --- Degenerate inputs never crash
    check('[63] degenerate fence (<3 pts) returns null',
      G.buildFgSurface(flat63.grid, flat63.rect, [{ x: 0, y: 0 }, { x: 1, y: 1 }], {}) === null);

    // --- Additive-feature guards: exports untouched
    const dxfSrc63 = readFileSync('client/src/lib/nextera/dxfExport.ts', 'utf8');
    const sheetsSrc63 = readFileSync('client/src/lib/nextera/dxfSheets.ts', 'utf8');
    check('[63] dxfExport never imports gradingSurface',
      !dxfSrc63.includes('gradingSurface'));
    check('[63] drawing-package registry never imports gradingSurface',
      !sheetsSrc63.includes('gradingSurface'));
    const dxf63a = buildDesignDxfString(design, 'Hondo_Test');
    check('[63] default design DXF is byte-identical with the feature present',
      dxf63a === dxf);
  }

  // ---------------------------------------------------------------
  // [64] Drainage screening (D8 flow, ponding, swales, rational method)
  {
    console.log('\n[64] Drainage screening (flow paths, ponding, swales, discharge points)');
    const G = await import('../client/src/lib/nextera/gradingSurface');
    const D = await import('../client/src/lib/nextera/drainage');

    const origin64 = { lat: 29.35, lon: -99.15 };
    const ftPerLon64 = 364000 * Math.cos((origin64.lat * Math.PI) / 180);
    const makeGrid64 = (rect: { minX: number; maxX: number; minY: number; maxY: number }, n: number, z: (x: number, y: number) => number) => {
      const bounds = {
        west: origin64.lon + rect.minX / ftPerLon64,
        east: origin64.lon + rect.maxX / ftPerLon64,
        south: origin64.lat + rect.minY / 364000,
        north: origin64.lat + rect.maxY / 364000,
      };
      const cellX = (rect.maxX - rect.minX) / n, cellY = (rect.maxY - rect.minY) / n;
      const valuesFt: number[] = [];
      for (let r = 0; r < n; r++) {
        const y = rect.maxY - (r + 0.5) * cellY; // row 0 = north
        for (let c = 0; c < n; c++) valuesFt.push(z(rect.minX + (c + 0.5) * cellX, y));
      }
      return {
        grid: { width: n, height: n, bounds, valuesFt, source: 'synthetic', resolutionM: 10, noDataCount: 0 },
        rect,
      };
    };
    const fence64: { x: number; y: number }[] = [
      { x: 100, y: 100 }, { x: 900, y: 100 }, { x: 900, y: 900 }, { x: 100, y: 900 },
    ];
    const rect64 = { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };
    const flat64 = makeGrid64(rect64, 64, () => 250);

    // --- Sanitizer: garbage snaps to defaults, finite values clamp
    check('[64] sanitizer: garbage snaps every field to defaults',
      JSON.stringify(D.sanitizeDrainageInputs({ runoffC: 'x', manningN: NaN, swaleGradePct: null })) ===
      JSON.stringify(D.DEFAULT_DRAINAGE_INPUTS) &&
      JSON.stringify(D.sanitizeDrainageInputs(null)) === JSON.stringify(D.DEFAULT_DRAINAGE_INPUTS));
    const sanC = D.sanitizeDrainageInputs({ runoffC: 5, rainfallIntensityInHr: -3, manningN: 0.001, swaleSideSlopeH: 99, swaleGradePct: 0 });
    check('[64] sanitizer: finite values clamp into engineering ranges',
      sanC.runoffC === 0.95 && sanC.rainfallIntensityInHr === 0.5 &&
      sanC.manningN === 0.012 && sanC.swaleSideSlopeH === 6 && sanC.swaleGradePct === 0.2);

    // --- Manning triangular section hand math: z=3, s=1%, n=0.03, d=1 ft
    //     A = 3, P = 2*sqrt(10), R = A/P, Q = (1.49/0.03)*A*R^(2/3)*0.1
    {
      const A = 3, P = 2 * Math.sqrt(10), R = A / P;
      const qHand = (1.49 / 0.03) * A * Math.pow(R, 2 / 3) * Math.sqrt(0.01);
      const sec = D.triangularSwaleSection(qHand, 1, 3, 0.03);
      check('[64] Manning section solves the hand-math normal depth (d = 1 ft)',
        Math.abs(sec.depthFt - 1) < 0.01, `${sec.depthFt.toFixed(4)} ft`);
      check('[64] Manning section: top width = 2 z d, velocity = Q / A',
        Math.abs(sec.topWidthFt - 6) < 0.05 && Math.abs(sec.velocityFps - qHand / A) < 0.05);
      check('[64] Manning section: zero flow needs zero section',
        D.triangularSwaleSection(0, 1, 3, 0.03).depthFt === 0);
    }

    // --- Kirpich Tc hand math + 5-minute floor
    check('[64] Kirpich Tc matches hand math (L=1000 ft, drop=10 ft)',
      ((): boolean => {
        const hand = 0.0078 * Math.pow(1000, 0.77) * Math.pow(10 / 1000, -0.385);
        return Math.abs(D.kirpichTcMin(1000, 10) - hand) < 1e-9;
      })());
    check('[64] Kirpich Tc floors at 5 minutes for short steep paths',
      D.kirpichTcMin(50, 20) === 5 && D.kirpichTcMin(0, 0) === 5);

    // --- Tilted pad on an east-falling site: pad slope matches the fall
    //     line, so sheet flow exits east (a tilted pad on a FLAT site would
    //     correctly pond in the trough at the low fence edge).
    const rampE64 = makeGrid64(rect64, 64, x => 250 - 0.01 * x);
    const fgEast = G.buildFgSurface(rampE64.grid, rampE64.rect, fence64,
      { padSlopePct: 1, slopeDirDeg: 90, shrinkPct: 0, topsoilStripIn: 0 })!;
    const dEast = D.buildDrainageModel(rampE64.grid, rampE64.rect, fgEast, {})!;
    check('[64] tilted pad: drainage model builds', dEast !== null);
    check('[64] tilted pad on falling site: no ponding on the pad (sheet flow east)',
      dEast.ponding.every(p => !p.onPad),
      dEast.ponding.filter(p => p.onPad).map(p => `${p.x},${p.y}`).join(' '));
    check('[64] tilted pad: flow arrows point east (dx > 0.5)',
      dEast.flowArrows.length > 0 && dEast.flowArrows.every(a => a.dx > 0.5));
    // A tilted pad on a FLAT site DOES pond along the low fence edge — the
    // tie-in ramps back up to OG and forms a trough. Screening must flag it.
    check('[64] tilted pad on a flat site: trough at the low edge is flagged on-pad',
      ((): boolean => {
        const fgFlatTilt = G.buildFgSurface(flat64.grid, flat64.rect, fence64,
          { padSlopePct: 1, slopeDirDeg: 90, shrinkPct: 0, topsoilStripIn: 0 })!;
        const m = D.buildDrainageModel(flat64.grid, flat64.rect, fgFlatTilt, {})!;
        return m.ponding.some(p => p.onPad && p.x > 850);
      })());
    check('[64] tilted pad: at least one discharge point with positive Q',
      dEast.discharges.length >= 1 && dEast.discharges.some(d => d.qCfs > 0));
    check('[64] tilted pad: discharge sits on the low (east) side',
      ((): boolean => {
        const q = dEast.discharges.reduce((a, b) => (b.qCfs > a.qCfs ? b : a));
        return q.p.x > 500;
      })());
    check('[64] rational method: total Q across discharges = C·i·A over the lattice',
      ((): boolean => {
        const totalAcres = dEast.discharges.reduce((s, d) => s + d.areaAcres, 0);
        const totalQ = dEast.discharges.reduce((s, d) => s + d.qCfs, 0);
        const expect = dEast.inputs.runoffC * dEast.inputs.rainfallIntensityInHr * totalAcres;
        return Math.abs(totalQ - expect) < 1e-6;
      })());
    check('[64] swale runs exist, ordered toward their discharge point',
      dEast.swales.length >= 1 && dEast.swales.every(s => {
        const dp = dEast.discharges[s.dischargeIdx].p;
        const last = s.pts[s.pts.length - 1];
        return Math.hypot(last.x - dp.x, last.y - dp.y) < 1 && s.lengthFt > 0;
      }));
    check('[64] swale sections sized for their discharge Q (capacity ~ Q)',
      dEast.swales.every(s => {
        const q = dEast.discharges[s.dischargeIdx].qCfs;
        return q <= 0 || Math.abs(s.section.capacityCfs - q) / q < 0.01;
      }));
    check('[64] flow paths are downstream-monotone in FG elevation',
      ((): boolean => {
        const rectT = { minX: rect64.minX, maxX: rect64.maxX, minY: rect64.minY, maxY: rect64.maxY };
        return dEast.flowPaths.every(fp => {
          for (let i = 1; i < fp.pts.length; i++) {
            const a = G.fgElevationAt(fgEast, rampE64.grid, rectT, fp.pts[i - 1].x, fp.pts[i - 1].y);
            const b = G.fgElevationAt(fgEast, rampE64.grid, rectT, fp.pts[i].x, fp.pts[i].y);
            if (b > a + 1e-6) return false;
          }
          return true;
        });
      })());

    // --- Bowl site: dead-flat pad on a bowl leaves an interior sink flagged
    const bowl64 = makeGrid64(rect64, 64, (x, y) => {
      const r = Math.hypot(x - 500, y - 500);
      return 250 + 0.06 * Math.max(0, r - 150); // flat bottom, rising rim
    });
    const fgBowlPad = G.buildFgSurface(bowl64.grid, bowl64.rect, fence64,
      { padSlopePct: 0, shrinkPct: 0, topsoilStripIn: 0 })!;
    const dBowl = D.buildDrainageModel(bowl64.grid, bowl64.rect, fgBowlPad, {})!;
    check('[64] flat pad in a bowl: ponding detected (water cannot leave the pad)',
      dBowl.ponding.length > 0);
    check('[64] bowl ponding is flagged on the pad and warned about',
      dBowl.ponding.some(p => p.onPad) &&
      dBowl.warnings.some(w => w.includes('ON THE PAD')),
      dBowl.warnings.join('; '));

    // --- Determinism: identical inputs -> byte-identical model
    const dA = D.buildDrainageModel(rampE64.grid, rampE64.rect, fgEast, {})!;
    const dB = D.buildDrainageModel(rampE64.grid, rampE64.rect, fgEast, {})!;
    check('[64] buildDrainageModel is deterministic (identical JSON on re-run)',
      JSON.stringify(dA) === JSON.stringify(dB));

    // --- Disclaimer always present
    check('[64] screening disclaimer is attached to every model',
      dEast.disclaimer.includes('Screening') && dBowl.disclaimer === D.DRAINAGE_DISCLAIMER);

    // --- Degenerate inputs never crash
    check('[64] degenerate fence surface returns null drainage',
      ((): boolean => {
        const tiny = { ...fgEast, fence: [{ x: 0, y: 0 }, { x: 1, y: 1 }], daylightPolygon: [] as { x: number; y: number }[] };
        return D.buildDrainageModel(rampE64.grid, rampE64.rect, tiny, {}) === null;
      })());

    // --- Additive-feature guards: exports untouched
    const dxfSrc64 = readFileSync('client/src/lib/nextera/dxfExport.ts', 'utf8');
    const sheetsSrc64 = readFileSync('client/src/lib/nextera/dxfSheets.ts', 'utf8');
    check('[64] dxfExport never imports drainage', !dxfSrc64.includes('drainage'));
    check('[64] drawing-package registry never imports drainage', !sheetsSrc64.includes('drainage'));
    const dxf64 = buildDesignDxfString(design, 'Hondo_Test');
    check('[64] default design DXF is byte-identical with the feature present',
      dxf64 === dxf);
  }

  // ---------------------------------------------------------------
  // [65] Grading plan sheet (GP-1), earthwork table, LandXML TIN export
  {
    console.log('\n[65] Grading plan sheet (DXF/PDF twin) + LandXML surface export');
    const G = await import('../client/src/lib/nextera/gradingSurface');
    const D = await import('../client/src/lib/nextera/drainage');
    const GP = await import('../client/src/lib/nextera/gradingPlan');
    const LX = await import('../client/src/lib/nextera/landxml');

    const origin65 = { lat: 29.35, lon: -99.15 };
    const ftPerLon65 = 364000 * Math.cos((origin65.lat * Math.PI) / 180);
    const makeGrid65 = (rect: { minX: number; maxX: number; minY: number; maxY: number }, n: number, z: (x: number, y: number) => number) => {
      const bounds = {
        west: origin65.lon + rect.minX / ftPerLon65,
        east: origin65.lon + rect.maxX / ftPerLon65,
        south: origin65.lat + rect.minY / 364000,
        north: origin65.lat + rect.maxY / 364000,
      };
      const cellX = (rect.maxX - rect.minX) / n, cellY = (rect.maxY - rect.minY) / n;
      const valuesFt: number[] = [];
      for (let r = 0; r < n; r++) {
        const y = rect.maxY - (r + 0.5) * cellY; // row 0 = north
        for (let c = 0; c < n; c++) valuesFt.push(z(rect.minX + (c + 0.5) * cellX, y));
      }
      return {
        grid: { width: n, height: n, bounds, valuesFt, source: 'synthetic', resolutionM: 10, noDataCount: 0 },
        rect,
      };
    };
    const fence65: { x: number; y: number }[] = [
      { x: 100, y: 100 }, { x: 900, y: 100 }, { x: 900, y: 900 }, { x: 100, y: 900 },
    ];
    const rect65 = { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };
    // East-falling ramp so benches / slope direction are non-trivial.
    const ramp65 = makeGrid65(rect65, 64, x => 250 - 0.01 * x);
    const fg65 = G.buildFgSurface(ramp65.grid, ramp65.rect, fence65,
      { padSlopePct: 1, slopeDirDeg: 90, benchMode: true, maxBenchHeightFt: 4 })!;
    const dr65 = D.buildDrainageModel(ramp65.grid, ramp65.rect, fg65, {})!;
    check('[65] FG surface + drainage build on the ramp site', fg65 !== null && dr65 !== null);

    // --- Proposed contours from the continuous FG surface
    const prop65 = GP.buildProposedContours(ramp65.grid, ramp65.rect, fg65);
    check('[65] proposed contours: non-empty with a positive interval',
      prop65.lines.length > 0 && prop65.intervalFt > 0);
    check('[65] proposed contour vertices are finite (no NaN geometry)',
      prop65.lines.every(l => l.pts.every(p => Number.isFinite(p.x) && Number.isFinite(p.y))));
    check('[65] proposed contours are deterministic (identical JSON on re-run)',
      JSON.stringify(prop65) === JSON.stringify(GP.buildProposedContours(ramp65.grid, ramp65.rect, fg65)));

    // --- Grading plan DXF sheet (uses the real Hondo design for the frame)
    const T = await import('../client/src/lib/nextera/terrain');
    const exist65 = T.computeContours(ramp65.grid as any, ramp65.rect, 2);
    const gpData = { fg: fg65, proposed: prop65, existing: exist65, drainage: dr65 };
    const gpDxf = GP.buildGradingPlanDxfString(design, 'Hondo_Test', gpData);
    check('[65] grading plan DXF ends with EOF and has no NaN coordinates',
      gpDxf.trimEnd().endsWith('EOF') && !gpDxf.includes('NaN'));
    check('[65] grading plan DXF declares the proposed/daylight/spot/swale layers',
      ['C - PROPOSED CONTOUR', 'C - PROPOSED CONTOUR MAJOR', 'C - DAYLIGHT LIMIT',
       'C - SPOT ELEVATION', 'C - SLOPE ARROW', 'C - SWALE', 'C - DISCHARGE POINT']
        .every(l => gpDxf.includes(l)));
    check('[65] grading plan DXF carries the sheet title, earthwork table and disclaimer',
      gpDxf.includes('GRADING PLAN') && gpDxf.includes('EARTHWORK QUANTITIES') &&
      gpDxf.includes('CUT (BANK)') && gpDxf.includes('NOT FOR CONSTRUCTION'));
    check('[65] grading plan DXF labels discharge points with rational Q',
      dr65.discharges.length === 0 || gpDxf.includes('DP-1') && gpDxf.includes('CFS'));
    check('[65] grading plan DXF is byte-deterministic',
      gpDxf === GP.buildGradingPlanDxfString(design, 'Hondo_Test', gpData));
    check('[65] grading plan without drainage still exports (swale layers omitted)',
      ((): boolean => {
        const s = GP.buildGradingPlanDxfString(design, 'Hondo_Test', { fg: fg65, proposed: prop65 });
        return s.trimEnd().endsWith('EOF') && !s.includes('C - SWALE') && !s.includes('C - DISCHARGE POINT');
      })());

    // --- Cut/fill isopach shading (opt-in)
    // The benched 1%-east FG matches the 1% ramp almost exactly (near-zero
    // earthwork), so shading is tested against a FLAT pad on the same ramp:
    // ~4 ft of cut on the high (west) side and ~4 ft of fill on the east.
    const fgFlat65 = G.buildFgSurface(ramp65.grid, ramp65.rect, fence65, { padSlopePct: 0 })!;
    const cf65 = GP.buildCutFillRegions(ramp65.grid, ramp65.rect, fgFlat65);
    check('[65] zero-earthwork FG yields no shading regions (bands empty)',
      GP.buildCutFillRegions(ramp65.grid, ramp65.rect, fg65).bands.every(b => b.polygons.length === 0));
    check('[65] cut/fill regions: at least one band populated on the flat-pad ramp',
      cf65.bands.some(b => b.polygons.length > 0));
    check('[65] cut/fill regions: band order matches CUT_FILL_BANDS and vertices are finite',
      cf65.bands.length === GP.CUT_FILL_BANDS.length &&
      cf65.bands.every((b, i) => b.def === GP.CUT_FILL_BANDS[i] &&
        b.polygons.every(poly => poly.every(ring =>
          ring.length >= 3 && ring.every(p => Number.isFinite(p[0]) && Number.isFinite(p[1]))))));
    check('[65] cut/fill regions: rings do not repeat the closing vertex',
      cf65.bands.every(b => b.polygons.every(poly => poly.every(ring => {
        const a = ring[0], z = ring[ring.length - 1];
        return a[0] !== z[0] || a[1] !== z[1];
      }))));
    check('[65] cut/fill regions are deterministic (identical JSON on re-run)',
      JSON.stringify(cf65) === JSON.stringify(GP.buildCutFillRegions(ramp65.grid, ramp65.rect, fgFlat65)));
    // Flat pad on the east-falling ramp: cut west of center, fill east.
    check('[65] ramp site produces both cut and fill shading',
      cf65.bands.some(b => b.def.kind === 'cut' && b.polygons.length > 0) &&
      cf65.bands.some(b => b.def.kind === 'fill' && b.polygons.length > 0));
    // Per-band legend areas: shoelace sums over the merged regions.
    const areas65 = GP.cutFillBandAreasSqFt(cf65);
    check('[65] band areas: one finite non-negative value per band, positive iff populated',
      areas65.length === GP.CUT_FILL_BANDS.length &&
      areas65.every((a, i) => Number.isFinite(a) && a >= 0 &&
        (a > 0) === (cf65.bands[i].polygons.length > 0)));
    check('[65] band areas match independent per-ring shoelace (outer minus holes)',
      ((): boolean => {
        const shoelace = (ring: number[][]) => {
          let s = 0;
          for (let i = 0; i < ring.length; i++) {
            const [x0, y0] = ring[i], [x1, y1] = ring[(i + 1) % ring.length];
            s += x0 * y1 - x1 * y0;
          }
          return Math.abs(s) / 2;
        };
        return cf65.bands.every((b, i) => {
          let a = 0;
          for (const poly of b.polygons)
            poly.forEach((ring, r) => { a += (r === 0 ? 1 : -1) * shoelace(ring); });
          return Math.abs(a - areas65[i]) < 1e-6;
        });
      })());
    check('[65] fmtBandArea: SF below 0.25 AC, AC (2 decimals) at/above',
      GP.fmtBandArea(5000) === '5,000 SF' &&
      GP.fmtBandArea(0.25 * 43560) === '0.25 AC' &&
      GP.fmtBandArea(1.3 * 43560) === '1.30 AC');
    const gpDxfCf = GP.buildGradingPlanDxfString(design, 'Hondo_Test', { ...gpData, cutFill: cf65 });
    check('[65] legend lists per-band areas for populated bands only',
      cf65.bands.every((b, i) => {
        const row = `${b.def.label.padEnd(14, ' ')}..... ${GP.fmtBandArea(areas65[i])}`;
        return (b.polygons.length > 0) === gpDxfCf.includes(row);
      }));
    check('[65] cut/fill DXF declares only the populated band layers and hatches them',
      cf65.bands.every(b => (b.polygons.length > 0) === gpDxfCf.includes(b.def.layer)) &&
      gpDxfCf.includes('ANSI31') && gpDxfCf.includes('CUT SHADING'));
    check('[65] cut/fill DXF is byte-deterministic',
      gpDxfCf === GP.buildGradingPlanDxfString(design, 'Hondo_Test', { ...gpData, cutFill: cf65 }));
    check('[65] baseline GP-1 has no cut/fill layers; cutFill:null is byte-identical to absent',
      !gpDxf.includes('C - CUT') && !gpDxf.includes('C - FILL') &&
      gpDxf === GP.buildGradingPlanDxfString(design, 'Hondo_Test', { ...gpData, cutFill: null }));

    // --- PDF twin renders from the same display list
    const PP = await import('../client/src/lib/nextera/pdfPlot');
    const gpPdf = PP.buildGradingPlanPdfString(
      { design, projectName: 'Hondo_Test' } as any, gpData);
    check('[65] grading plan PDF is a 1-page vector PDF, byte-deterministic',
      gpPdf.startsWith('%PDF') && gpPdf.includes('/Count 1') &&
      gpPdf === PP.buildGradingPlanPdfString({ design, projectName: 'Hondo_Test' } as any, gpData));
    const gpPdfCf = PP.buildGradingPlanPdfString(
      { design, projectName: 'Hondo_Test' } as any, { ...gpData, cutFill: cf65 });
    check('[65] cut/fill PDF twin renders (differs from baseline, byte-deterministic)',
      gpPdfCf.startsWith('%PDF') && gpPdfCf !== gpPdf &&
      gpPdfCf === PP.buildGradingPlanPdfString({ design, projectName: 'Hondo_Test' } as any, { ...gpData, cutFill: cf65 }));

    // --- LandXML 1.2 TIN export
    const xml65 = LX.buildLandXmlString(fg65, ramp65.grid as any, ramp65.rect, 'Hondo_Test', 16);
    check('[65] LandXML is well-formed XML with the LandXML-1.2 namespace',
      ((): boolean => {
        const doc = new DOMParser().parseFromString(xml65, 'text/xml');
        const root = doc.documentElement!;
        return root.nodeName === 'LandXML' &&
          root.getAttribute('xmlns') === 'http://www.landxml.org/schema/LandXML-1.2' &&
          root.getAttribute('version') === '1.2';
      })());
    check('[65] LandXML TIN: n*n points, 2*(n-1)^2 faces, faces reference valid 1-based ids',
      ((): boolean => {
        const pnts = xml65.match(/<P id="\d+">/g) ?? [];
        const faces = xml65.match(/<F>(\d+) (\d+) (\d+)<\/F>/g) ?? [];
        if (pnts.length !== 16 * 16 || faces.length !== 2 * 15 * 15) return false;
        return faces.every(f => {
          const ids = f.replace(/<\/?F>/g, '').split(' ').map(Number);
          return ids.every(i => i >= 1 && i <= 256) && new Set(ids).size === 3;
        });
      })());
    check('[65] LandXML point elevations match the FG surface (northing easting elev)',
      ((): boolean => {
        const m = xml65.match(/<P id="1">([-\d.]+) ([-\d.]+) ([-\d.]+)<\/P>/);
        if (!m) return false;
        const y = Number(m[1]), x = Number(m[2]), z = Number(m[3]);
        const want = G.fgElevationAt(fg65, ramp65.grid as any, ramp65.rect, x, y);
        return Math.abs(z - want) < 0.001;
      })());
    check('[65] LandXML has no NaN and is byte-deterministic (pinned date)',
      !xml65.includes('NaN') && xml65.includes('date="2026-01-01"') &&
      xml65 === LX.buildLandXmlString(fg65, ramp65.grid as any, ramp65.rect, 'Hondo_Test', 16));

    // --- Civil 3D importer quirks: surface names become drawing object names,
    //     so the whole file must stay 7-bit ASCII (em dashes etc. get mangled
    //     by codepage round-trips in some LandXML consumers); degenerate
    //     (zero-area) faces make Civil 3D drop or crumple the TIN.
    check('[65] LandXML is 7-bit ASCII (surface name is importer-safe)',
      // eslint-disable-next-line no-control-regex
      !/[^\x00-\x7f]/.test(xml65) && xml65.includes('- Proposed FG (screening)'));
    check('[65] LandXML sanitizes non-ASCII project names instead of emitting them',
      ((): boolean => {
        const s = LX.buildLandXmlString(fg65, ramp65.grid as any, ramp65.rect, 'Hondo — Café', 4);
        return !/[^\x00-\x7f]/.test(s) && s.includes('Hondo _ Caf_');
      })());
    check('[65] LandXML TIN has no degenerate (zero-area) faces',
      ((): boolean => {
        const pts = new Map<number, { x: number; y: number }>();
        for (const m of xml65.matchAll(/<P id="(\d+)">([-\d.]+) ([-\d.]+) [-\d.]+<\/P>/g))
          pts.set(Number(m[1]), { y: Number(m[2]), x: Number(m[3]) });
        for (const m of xml65.matchAll(/<F>(\d+) (\d+) (\d+)<\/F>/g)) {
          const [a, b, c] = [pts.get(Number(m[1]))!, pts.get(Number(m[2]))!, pts.get(Number(m[3]))!];
          const area2 = Math.abs((b.y - a.y) * (c.x - a.x) - (c.y - a.y) * (b.x - a.x));
          if (area2 < 1e-9) return false;
        }
        return true;
      })());

    // --- Official LandXML-1.2 XSD validation (the strongest offline proxy
    //     for a Civil 3D import): validated with lxml against the vendored
    //     schema in scripts/landxml-1.2.xsd. Skipped if python3/lxml missing.
    {
      const { spawnSync: spawnLx } = await import('child_process');
      const probeLx = spawnLx('python3', ['-c', 'import lxml'], { timeout: 20000 });
      if (probeLx.status === 0) {
        const fsLx = await import('fs');
        const osLx = await import('os');
        const pathLx = await import('path');
        const dirLx = fsLx.mkdtempSync(pathLx.join(osLx.tmpdir(), 'landxml-'));
        const xmlPath = pathLx.join(dirLx, 'sample.xml');
        // Full-size export (48x48 lattice) like a real project would produce.
        fsLx.writeFileSync(xmlPath,
          LX.buildLandXmlString(fg65, ramp65.grid as any, ramp65.rect, 'Hondo_Test', 48));
        const xsdPath = pathLx.join(process.cwd(), 'scripts', 'landxml-1.2.xsd');
        const py = [
          'import sys',
          'from lxml import etree',
          'schema = etree.XMLSchema(etree.parse(sys.argv[1]))',
          'doc = etree.parse(sys.argv[2])',
          'ok = schema.validate(doc)',
          'print("VALID" if ok else "INVALID")',
          'for e in schema.error_log: print(e.line, e.message)',
        ].join('\n');
        const res = spawnLx('python3', ['-c', py, xsdPath, xmlPath],
          { timeout: 60000, encoding: 'utf8' });
        check('[65] LandXML validates against the official LandXML-1.2 XSD',
          res.status === 0 && (res.stdout ?? '').includes('VALID') &&
          !(res.stdout ?? '').includes('INVALID'));
        if (res.status !== 0 || !(res.stdout ?? '').includes('VALID') ||
            (res.stdout ?? '').includes('INVALID'))
          console.log('    XSD validator output:', res.stdout, res.stderr);
      } else {
        console.log('  [65] (skip) python3/lxml unavailable — XSD validation not run');
      }
    }

    // --- ezdxf structural audit: the grading plan sheet must be a loadable,
    //     audit-clean AC1015 document. Skipped if python3/ezdxf is unavailable.
    {
      const { spawnSync } = await import('child_process');
      const probe = spawnSync('python3', ['-c', 'import ezdxf'], { timeout: 20000 });
      if (probe.status === 0) {
        const { writeFileSync: wf, mkdtempSync } = await import('fs');
        const os = await import('os');
        const dir = mkdtempSync(path.join(os.tmpdir(), 'gp-audit-'));
        const fp = path.join(dir, 'gp1.dxf');
        const fpCf = path.join(dir, 'gp1_cutfill.dxf');
        wf(fp, gpDxf, 'utf8');
        wf(fpCf, gpDxfCf, 'utf8');
        const py = `
import sys
from ezdxf import recover
for f in ["${fp.replace(/\\/g, '/')}", "${fpCf.replace(/\\/g, '/')}"]:
    doc, auditor = recover.readfile(f)
    if auditor.has_errors:
        print(f"{f}: {len(auditor.errors)} audit errors", file=sys.stderr); sys.exit(1)
    if doc.dxfversion != "AC1015":
        print(f"{f}: version {doc.dxfversion}", file=sys.stderr); sys.exit(1)
sys.exit(0)
`;
        const audit = spawnSync('python3', ['-c', py], { timeout: 120000 });
        check('[65] grading plan DXF (plain + cut/fill shading) passes the ezdxf recover/audit as valid AC1015',
          audit.status === 0,
          audit.status === 0 ? undefined : String(audit.stderr));
      } else {
        console.log('  (ezdxf not available — grading plan structural audit skipped)');
      }
    }

    // --- Additive-feature guards: default exports untouched
    const dxfSrc65 = readFileSync('client/src/lib/nextera/dxfExport.ts', 'utf8');
    const sheetsSrc65 = readFileSync('client/src/lib/nextera/dxfSheets.ts', 'utf8');
    check('[65] dxfExport never imports gradingPlan/landxml',
      !dxfSrc65.includes('gradingPlan') && !dxfSrc65.includes('landxml'));
    check('[65] drawing-package registry never imports gradingPlan/landxml',
      !sheetsSrc65.includes('gradingPlan') && !sheetsSrc65.includes('landxml'));
    check('[65] default design DXF has no proposed-contour layer and is byte-identical',
      ((): boolean => {
        const d65 = buildDesignDxfString(design, 'Hondo_Test');
        return !d65.includes('PROPOSED CONTOUR') && d65 === dxf;
      })());

    // ---------------------------------------------------------------
    console.log('\n[66] Earthwork cost estimate (unit rates + BoQ on GP-1)');
    const EC = await import('../client/src/lib/nextera/earthworkCost');

    // --- Sanitizer: garbage snaps to defaults, finite values clamp
    const dR = EC.DEFAULT_EARTHWORK_RATES;
    check('[66] sanitizer: non-object inputs return defaults',
      [null, undefined, 'x', 42, []].every(v =>
        JSON.stringify(EC.sanitizeEarthworkRates(v)) === JSON.stringify(dR)));
    check('[66] sanitizer: NaN/Infinity/strings snap to defaults per field',
      ((): boolean => {
        const s = EC.sanitizeEarthworkRates({ cutPerCY: NaN, fillPerCY: Infinity, haulPerCY: 'cheap', topsoilPerCY: {}, mobilizationLump: null });
        return s.cutPerCY === dR.cutPerCY && s.fillPerCY === dR.fillPerCY &&
          s.haulPerCY === dR.haulPerCY && s.topsoilPerCY === dR.topsoilPerCY &&
          s.mobilizationLump === dR.mobilizationLump;
      })());
    check('[66] sanitizer: out-of-range finite values clamp into range',
      ((): boolean => {
        const s = EC.sanitizeEarthworkRates({ cutPerCY: -5, fillPerCY: 9999, mobilizationLump: 99_000_000_000 });
        return s.cutPerCY === 0 && s.fillPerCY === 500 && s.mobilizationLump === 10_000_000 &&
          s.haulPerCY === dR.haulPerCY;
      })());
    check('[66] sanitizer: in-range values pass through untouched',
      ((): boolean => {
        const s = EC.sanitizeEarthworkRates({ cutPerCY: 3.25, fillPerCY: 7, haulPerCY: 15, topsoilPerCY: 2, mobilizationLump: 0 });
        return s.cutPerCY === 3.25 && s.fillPerCY === 7 && s.haulPerCY === 15 &&
          s.topsoilPerCY === 2 && s.mobilizationLump === 0;
      })());

    // --- Hand-math verification against a synthetic earthwork summary
    const ewHand = {
      ...fg65.earthwork,
      cutCY: 1000.4, fillCY: 2000.6, haulLooseCY: 500.2, topsoilCY: 300.5,
    };
    const ratesHand = { cutPerCY: 4, fillPerCY: 6, haulPerCY: 10, topsoilPerCY: 3, mobilizationLump: 25000 };
    const costHand = EC.computeEarthworkCost(ewHand as any, ratesHand);
    // qty rounds first: 1000*4 + 2001*6 + 500*10 + 301*3 + 25000
    const wantTotal = 1000 * 4 + 2001 * 6 + 500 * 10 + 301 * 3 + 25000;
    check('[66] cost lines: quantities round to whole CY before pricing',
      costHand.lines[0].qtyCY === 1000 && costHand.lines[1].qtyCY === 2001 &&
      costHand.lines[2].qtyCY === 500 && costHand.lines[3].qtyCY === 301);
    check('[66] cost total is the sum of rounded line amounts (hand math)',
      costHand.totalUSD === wantTotal &&
      costHand.totalUSD === costHand.lines.reduce((s, l) => s + l.amount, 0),
      `${costHand.totalUSD} vs ${wantTotal}`);
    check('[66] mobilization line is LS and omitted when the lump sum is 0',
      costHand.lines[4]?.unit === 'LS' && costHand.lines[4]?.qtyCY === null &&
      EC.computeEarthworkCost(ewHand as any, { ...ratesHand, mobilizationLump: 0 }).lines.length === 4);
    check('[66] cost summary carries the screening disclaimer',
      costHand.disclaimer === 'SCREENING-LEVEL ESTIMATE — NOT A BID' &&
      EC.buildCostTableRows(costHand).some(r => r.includes('NOT A BID')));
    check('[66] cost computation is deterministic (identical JSON on re-run)',
      JSON.stringify(costHand) === JSON.stringify(EC.computeEarthworkCost(ewHand as any, ratesHand)));
    check('[66] computeEarthworkCost sanitizes garbage rates instead of pricing them',
      EC.computeEarthworkCost(ewHand as any, { cutPerCY: NaN } as any).lines[0].rate === dR.cutPerCY);

    // --- GP-1 integration: cost box only when opted in; default bytes frozen
    const cost66 = EC.computeEarthworkCost(fg65.earthwork, dR);
    const gpDxfCost = GP.buildGradingPlanDxfString(design, 'Hondo_Test', { ...gpData, cost: cost66 });
    check('[66] costed GP-1 DXF carries the cost box title + disclaimer + total',
      gpDxfCost.includes('EARTHWORK COST ESTIMATE (SCREENING)') &&
      gpDxfCost.includes('NOT A BID') && gpDxfCost.includes('TOTAL (SCREENING)'));
    check('[66] costed GP-1 DXF is byte-deterministic',
      gpDxfCost === GP.buildGradingPlanDxfString(design, 'Hondo_Test', { ...gpData, cost: cost66 }));
    check('[66] default GP-1 has no cost box; cost:null is byte-identical to absent',
      !gpDxf.includes('EARTHWORK COST ESTIMATE') && !gpDxf.includes('NOT A BID') &&
      gpDxf === GP.buildGradingPlanDxfString(design, 'Hondo_Test', { ...gpData, cost: null }));
    const gpPdfCost = PP.buildGradingPlanPdfString(
      { design, projectName: 'Hondo_Test' } as any, { ...gpData, cost: cost66 });
    check('[66] costed GP-1 PDF twin renders (differs from baseline, byte-deterministic)',
      gpPdfCost.startsWith('%PDF') && gpPdfCost !== gpPdf &&
      gpPdfCost === PP.buildGradingPlanPdfString({ design, projectName: 'Hondo_Test' } as any, { ...gpData, cost: cost66 }));

    // --- Additive-feature guards: rates never leak into project data,
    //     default package/DXF writers never touch the cost module.
    check('[66] dxfExport/dxfSheets never import earthworkCost',
      !dxfSrc65.includes('earthworkCost') && !sheetsSrc65.includes('earthworkCost'));
    check('[66] project JSON export never carries earthwork rates (per-browser pref only)',
      ((): boolean => {
        const storeSrc = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
        const m = storeSrc.match(/const projectFromState[\s\S]*?^\};/m);
        return !!m && !m[0].includes('earthworkRates') && !m[0].includes('exportCostEstimate');
      })());

    // --- ezdxf audit of the costed sheet (same bar as the [65] sheets)
    {
      const { spawnSync } = await import('child_process');
      const probe = spawnSync('python3', ['-c', 'import ezdxf'], { timeout: 20000 });
      if (probe.status === 0) {
        const { writeFileSync: wf, mkdtempSync } = await import('fs');
        const os = await import('os');
        const dir = mkdtempSync(path.join(os.tmpdir(), 'gp-cost-audit-'));
        const fp = path.join(dir, 'gp1_cost.dxf');
        wf(fp, gpDxfCost, 'utf8');
        const py = `
import sys
from ezdxf import recover
doc, auditor = recover.readfile("${fp.replace(/\\/g, '/')}")
if auditor.has_errors:
    print(f"{len(auditor.errors)} audit errors", file=sys.stderr); sys.exit(1)
if doc.dxfversion != "AC1015":
    print(f"version {doc.dxfversion}", file=sys.stderr); sys.exit(1)
sys.exit(0)
`;
        const audit = spawnSync('python3', ['-c', py], { timeout: 120000 });
        check('[66] costed grading plan DXF passes the ezdxf recover/audit as valid AC1015',
          audit.status === 0,
          audit.status === 0 ? undefined : String(audit.stderr));
      } else {
        console.log('  (ezdxf not available — costed grading plan audit skipped)');
      }
    }

    // ---------------------------------------------------------------
    console.log('\n[67] Grading cross-sections sheet (GP-2) + GP-1 markers');
    const GS = await import('../client/src/lib/nextera/gradingSections');

    // --- Section engine: automatic placement + profile sampling
    const secs67 = GS.buildGradingSections(ramp65.grid, ramp65.rect, fg65);
    check('[67] default engine yields exactly A-A\' (grade axis) + B-B\' (perpendicular)',
      secs67.sections.length === 2 &&
      secs67.sections[0].label === 'A' && secs67.sections[1].label === 'B');
    const secs67q = GS.buildGradingSections(ramp65.grid, ramp65.rect, fg65, { quarterPoints: true });
    check('[67] quarter-point option adds C-C\' and D-D\' (4 sections total)',
      secs67q.sections.length === 4 &&
      secs67q.sections.map(s => s.label).join('') === 'ABCD');
    check('[67] A-A\' runs along the downhill axis; B-B\' is perpendicular to it',
      ((): boolean => {
        const a = secs67.sections[0], b = secs67.sections[1];
        const ax = (a.p1.x - a.p0.x) / a.lengthFt, ay = (a.p1.y - a.p0.y) / a.lengthFt;
        const bx = (b.p1.x - b.p0.x) / b.lengthFt, by = (b.p1.y - b.p0.y) / b.lengthFt;
        return Math.abs(ax * fg65.dir.x + ay * fg65.dir.y) > 0.999 &&
          Math.abs(ax * bx + ay * by) < 1e-9;
      })());
    check('[67] section traces are finite with monotone stations spanning the line',
      secs67q.sections.every(s =>
        s.samples.length === secs67q.sampleCount + 1 &&
        s.samples.every(sm => Number.isFinite(sm.og) && Number.isFinite(sm.fg) && Number.isFinite(sm.station)) &&
        s.samples.every((sm, i) => i === 0 || sm.station > s.samples[i - 1].station) &&
        Math.abs(s.samples[s.samples.length - 1].station - s.lengthFt) < 1e-6));
    check('[67] FG trace matches fgElevationAt re-sampled at the same plan points',
      ((): boolean => {
        const s = secs67.sections[0];
        return s.samples.every((sm, i) => {
          const t = i / secs67.sampleCount;
          const x = s.p0.x + (s.p1.x - s.p0.x) * t;
          const y = s.p0.y + (s.p1.y - s.p0.y) * t;
          return Math.abs(sm.fg - G.fgElevationAt(fg65, ramp65.grid as any, ramp65.rect, x, y)) < 1e-9;
        });
      })());
    check('[67] section engine is deterministic (identical JSON on re-run)',
      JSON.stringify(secs67q) === JSON.stringify(GS.buildGradingSections(ramp65.grid, ramp65.rect, fg65, { quarterPoints: true })));
    // Flat pad on the east-falling ramp guarantees real cut and fill, so the
    // profiles must cross existing ground somewhere = daylight points.
    const secsFlat67 = GS.buildGradingSections(ramp65.grid, ramp65.rect, fgFlat65);
    check('[67] flat-pad sections carry daylight points within the station range',
      secsFlat67.sections.some(s => s.daylightStations.length > 0) &&
      secsFlat67.sections.every(s => s.daylightStations.every(st => st >= 0 && st <= s.lengthFt)));

    // --- Cut/fill loop geometry between the traces
    check('[67] cut/fill loops: closed regions with finite vertices, both kinds across the flat-pad sections',
      ((): boolean => {
        // A-A' runs along the (south) grade axis where the east-falling ramp
        // is level, so cut vs fill splits across sections: B-B' (east-west)
        // carries the cut-west / fill-east crossing. Aggregate over all.
        let cutN = 0, fillN = 0;
        const ok = (ls: number[][][]) => ls.every(l =>
          l.length >= 4 && l.every(p => Number.isFinite(p[0]) && Number.isFinite(p[1])));
        for (const s of secsFlat67.sections) {
          const loops = GS.sectionCutFillLoops(s.samples, st => st, z => z);
          if (!ok(loops.cut) || !ok(loops.fill)) return false;
          cutN += loops.cut.length;
          fillN += loops.fill.length;
        }
        return cutN > 0 && fillN > 0;
      })());

    // --- GP-2 DXF sheet
    const xsDxf = GS.buildGradingSectionsDxfString(design, 'Hondo_Test', secs67q);
    check('[67] GP-2 DXF ends with EOF and has no NaN coordinates',
      xsDxf.trimEnd().endsWith('EOF') && !xsDxf.includes('NaN'));
    check('[67] GP-2 DXF declares the profile/hatch/grid/daylight layers',
      ['X - OG PROFILE', 'X - FG PROFILE', 'X - CUT AREA', 'X - FILL AREA',
       'X - SECTION GRID', 'X - SECTION TEXT', 'X - DAYLIGHT POINT']
        .every(l => xsDxf.includes(l)));
    check('[67] GP-2 DXF carries the sheet label, title, VE note, stations and disclaimer',
      xsDxf.includes('SHEET GP-2') && xsDxf.includes('GRADING CROSS-SECTIONS') &&
      xsDxf.includes('VERT EXAG') && xsDxf.includes("SECTION A-A'") &&
      xsDxf.includes("SECTION D-D'") && xsDxf.includes('EL ') &&
      xsDxf.includes('NOT FOR CONSTRUCTION'));
    check('[67] GP-2 DXF is byte-deterministic',
      xsDxf === GS.buildGradingSectionsDxfString(design, 'Hondo_Test', secs67q));

    // --- GP-2 PDF twin
    const xsPdf = PP.buildGradingSectionsPdfString({ design, projectName: 'Hondo_Test' } as any, secs67q);
    check('[67] GP-2 PDF is a 1-page vector PDF, byte-deterministic',
      xsPdf.startsWith('%PDF') && xsPdf.includes('/Count 1') &&
      xsPdf === PP.buildGradingSectionsPdfString({ design, projectName: 'Hondo_Test' } as any, secs67q));

    // --- GP-1 section markers: only when sections are passed in
    const gpDxfSec = GP.buildGradingPlanDxfString(design, 'Hondo_Test', { ...gpData, sections: secs67q });
    check('[67] GP-1 with sections draws the marker layer and A/A\' ... D/D\' labels',
      gpDxfSec.includes('C - SECTION LINE') && gpDxfSec.includes("A'") &&
      gpDxfSec.includes("D'") && gpDxfSec.includes('SEE SHEET GP-2'));
    check('[67] GP-1 with sections is byte-deterministic',
      gpDxfSec === GP.buildGradingPlanDxfString(design, 'Hondo_Test', { ...gpData, sections: secs67q }));
    check('[67] baseline GP-1 has no section markers; sections:null is byte-identical to absent',
      !gpDxf.includes('C - SECTION LINE') && !gpDxf.includes('GP-2') &&
      gpDxf === GP.buildGradingPlanDxfString(design, 'Hondo_Test', { ...gpData, sections: null }));

    // --- Additive-feature guards: default exports + project JSON untouched
    check('[67] dxfExport/dxfSheets never import gradingSections',
      !dxfSrc65.includes('gradingSections') && !sheetsSrc65.includes('gradingSections'));
    check('[67] GP-2 is never registered in the drawing-package SHEET_REGISTRY',
      !sheetsSrc65.includes('GP-2'));
    check('[67] project JSON export never carries the sections toggle (per-browser pref only)',
      ((): boolean => {
        const storeSrc = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
        const m = storeSrc.match(/const projectFromState[\s\S]*?^\};/m);
        return !!m && !m[0].includes('exportSections');
      })());
    check('[67] default design DXF has no section layers and is byte-identical',
      ((): boolean => {
        const d67 = buildDesignDxfString(design, 'Hondo_Test');
        return !d67.includes('SECTION LINE') && !d67.includes('X - OG PROFILE') && d67 === dxf;
      })());

    // --- ezdxf audit: GP-2 + the sectioned GP-1 (same bar as [65]/[66])
    {
      const { spawnSync } = await import('child_process');
      const probe = spawnSync('python3', ['-c', 'import ezdxf'], { timeout: 20000 });
      if (probe.status === 0) {
        const { writeFileSync: wf, mkdtempSync } = await import('fs');
        const os = await import('os');
        const dir = mkdtempSync(path.join(os.tmpdir(), 'gp2-audit-'));
        const fp = path.join(dir, 'gp2.dxf');
        const fpSec = path.join(dir, 'gp1_sections.dxf');
        wf(fp, xsDxf, 'utf8');
        wf(fpSec, gpDxfSec, 'utf8');
        const py = `
import sys
from ezdxf import recover
for f in ["${fp.replace(/\\/g, '/')}", "${fpSec.replace(/\\/g, '/')}"]:
    doc, auditor = recover.readfile(f)
    if auditor.has_errors:
        print(f"{f}: {len(auditor.errors)} audit errors", file=sys.stderr); sys.exit(1)
    if doc.dxfversion != "AC1015":
        print(f"{f}: version {doc.dxfversion}", file=sys.stderr); sys.exit(1)
sys.exit(0)
`;
        const audit = spawnSync('python3', ['-c', py], { timeout: 120000 });
        check('[67] GP-2 + sectioned GP-1 DXF pass the ezdxf recover/audit as valid AC1015',
          audit.status === 0,
          audit.status === 0 ? undefined : String(audit.stderr));
      } else {
        console.log('  (ezdxf not available — GP-2 structural audit skipped)');
      }
    }
  }

  // ---------------------------------------------------------------
  // [68] Multi-pad grading zones (opt-in): sanitizer, validation,
  // FG surface behavior, byte-identity guards and GP-1 annotations.
  {
    console.log('[68] Multi-pad grading zones');
    const G = await import('../client/src/lib/nextera/gradingSurface');
    const GP = await import('../client/src/lib/nextera/gradingPlan');
    const fence68: { x: number; y: number }[] = [
      { x: 100, y: 100 }, { x: 900, y: 100 }, { x: 900, y: 900 }, { x: 100, y: 900 },
    ];
    const rect68 = { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };
    // Synthetic elevation grid (same construction as the [65] fixture, local
    // scope): east-falling 1% ramp on a 64×64 lattice.
    const origin68 = { lat: 29.35, lon: -99.14 };
    const ftPerLon68 = 364000 * Math.cos(origin68.lat * Math.PI / 180);
    const makeGrid68 = (rect: { minX: number; maxX: number; minY: number; maxY: number }, n: number, z: (x: number, y: number) => number) => {
      const bounds = {
        west: origin68.lon + rect.minX / ftPerLon68,
        east: origin68.lon + rect.maxX / ftPerLon68,
        south: origin68.lat + rect.minY / 364000,
        north: origin68.lat + rect.maxY / 364000,
      };
      const cellX = (rect.maxX - rect.minX) / n, cellY = (rect.maxY - rect.minY) / n;
      const valuesFt: number[] = [];
      for (let r = 0; r < n; r++) {
        const y = rect.maxY - (r + 0.5) * cellY; // row 0 = north
        for (let c = 0; c < n; c++) valuesFt.push(z(rect.minX + (c + 0.5) * cellX, y));
      }
      return {
        grid: { width: n, height: n, bounds, valuesFt, source: 'synthetic', resolutionM: 10, noDataCount: 0 },
        rect,
      };
    };
    const ramp68 = makeGrid68(rect68, 64, x => 250 - 0.01 * x);
    const mkZone = (over: Partial<G.GradingZone> = {}): G.GradingZone => ({
      id: 'z1', name: 'BESS PAD A', x: 300, y: 300, lengthFt: 200, widthFt: 150,
      mode: 'offset', offsetFt: 2, ...over,
    });

    // --- Sanitizer: garbage dropped, out-of-range values clamped, cap held
    check('[68] sanitizer drops garbage entries and clamps out-of-range values',
      ((): boolean => {
        const clean = G.sanitizeGradingZones([
          mkZone(),
          null, 42, 'x', { id: 'z2' }, // garbage — dropped
          { ...mkZone({ id: 'z1' }) }, // duplicate id — dropped
          mkZone({ id: 'z3', x: NaN }), // non-finite — dropped
          mkZone({ id: 'z4', lengthFt: 5 }), // below min size — clamped up
          mkZone({ id: 'z5', offsetFt: 999 }), // offset — clamped into range
          mkZone({ id: 'z6', mode: 'weird' as any }), // bad mode — dropped
        ]);
        return clean.length === 3 &&
          clean[0].id === 'z1' && clean[0].offsetFt === 2 &&
          clean[1].id === 'z4' && clean[1].lengthFt === G.ZONE_MIN_SIZE_FT &&
          clean[2].id === 'z5' && clean[2].offsetFt === G.ZONE_MAX_OFFSET_FT;
      })());
    check('[68] sanitizer never returns more than the 4-zone cap',
      G.sanitizeGradingZones(
        [1, 2, 3, 4, 5, 6].map(i => mkZone({ id: `c${i}` }))).length === G.MAX_GRADING_ZONES);
    check('[68] sanitizer returns [] for non-arrays',
      G.sanitizeGradingZones(undefined).length === 0 &&
      G.sanitizeGradingZones({ 0: mkZone() }).length === 0);

    // --- Validation: inside fence, non-overlapping, count cap
    check('[68] reject: zone poking outside the fence',
      G.gradingZonesRejectReason([mkZone({ x: 120, y: 120 })], fence68) !== null);
    check('[68] reject: overlapping zones',
      G.gradingZonesRejectReason(
        [mkZone(), mkZone({ id: 'z2', x: 350, y: 350 })], fence68) !== null);
    check('[68] reject: more than 4 zones',
      G.gradingZonesRejectReason(
        [1, 2, 3, 4, 5].map(i => mkZone({ id: `z${i}`, x: 200 + i * 1000, y: 300 })),
        fence68) !== null);
    check('[68] per-zone fence test: in-fence true, poking-out false, no-fence true',
      G.gradingZoneInsideFence(mkZone(), fence68) &&
      !G.gradingZoneInsideFence(mkZone({ x: 120, y: 120 }), fence68) &&
      G.gradingZoneInsideFence(mkZone({ x: 120, y: 120 }), []));
    check('[68] accept: two disjoint in-fence zones',
      G.gradingZonesRejectReason(
        [mkZone(), mkZone({ id: 'z2', x: 700, y: 700 })], fence68) === null);

    // --- Zero-zone byte identity: [] and undefined produce identical JSON
    const base68 = G.buildFgSurface(ramp68.grid, ramp68.rect, fence68, { padSlopePct: 0 })!;
    check('[68] zero zones: FG JSON is byte-identical ([] vs absent)',
      JSON.stringify(base68) ===
      JSON.stringify(G.buildFgSurface(ramp68.grid, ramp68.rect, fence68, { padSlopePct: 0 }, undefined, [])) &&
      !('zones' in base68));

    // --- Fixed-offset zone: pad raised inside the rect, untouched far away
    const zOff = mkZone({ x: 300, y: 300, lengthFt: 200, widthFt: 150, mode: 'offset', offsetFt: 3 });
    const fgOff = G.buildFgSurface(ramp68.grid, ramp68.rect, fence68, { padSlopePct: 0 }, undefined, [zOff])!;
    // The balance solver re-solves the base pad with the zone included, so
    // compare within the SAME surface: the zone pad must sit exactly the
    // offset above the surface's own far-field pad (flat 0% pad).
    check('[68] offset zone pad sits exactly the offset above the base pad',
      Math.abs((G.fgPadElevationAt(fgOff, 300, 300) - G.fgPadElevationAt(fgOff, 800, 800)) - 3) < 1e-6);
    check('[68] far-field pad is flat and unaffected by the zone shape',
      Math.abs(G.fgPadElevationAt(fgOff, 800, 800) - G.fgPadElevationAt(fgOff, 800, 200)) < 1e-6 &&
      Math.abs(G.fgPadElevationAt(fgOff, 800, 800) - G.fgPadElevationAt(base68, 800, 800)) < 2);
    check('[68] solved zones carry mode/offset and finite blend',
      !!fgOff.zones && fgOff.zones.length === 1 && fgOff.zones[0].mode === 'offset' &&
      fgOff.zones[0].offsetFt === 3 && Number.isFinite(fgOff.zones[0].blendFt) && fgOff.zones[0].blendFt >= 10);

    // --- Auto zone: solved offset tracks the local terrain median
    const zAuto = mkZone({ id: 'za', mode: 'auto', offsetFt: 0, x: 300, y: 300 });
    const fgAuto = G.buildFgSurface(ramp68.grid, ramp68.rect, fence68, { padSlopePct: 0 }, undefined, [zAuto])!;
    check('[68] auto zone: solved offset ≈ local OG median minus base pad',
      ((): boolean => {
        const z = fgAuto.zones?.[0];
        if (!z) return false;
        // OG at zone center on the ramp: 250 − 0.01·300 = 247; base pad is flat.
        const expected = 247 - G.fgPadElevationAt(base68, 300, 300);
        return Math.abs(z.offsetFt - expected) < 1.5;
      })());
    check('[68] FG with zones is deterministic (identical JSON on re-run)',
      JSON.stringify(fgOff) ===
      JSON.stringify(G.buildFgSurface(ramp68.grid, ramp68.rect, fence68, { padSlopePct: 0 }, undefined, [zOff])));
    check('[68] earthwork with zones stays finite and cut/fill both non-negative',
      Number.isFinite(fgOff.earthwork.cutCY) && Number.isFinite(fgOff.earthwork.fillCY) &&
      fgOff.earthwork.cutCY >= 0 && fgOff.earthwork.fillCY >= 0);

    // --- Drag-ghost pad preview: previewZonePadInfo mirrors the builder solve
    // Offset zone: preview reports the fixed offset and base pad + offset.
    const pvOff = G.previewZonePadInfo(base68, ramp68.grid, ramp68.rect, zOff);
    check('[68] preview: offset zone returns its fixed offset and base+offset pad',
      pvOff.solved && pvOff.offsetFt === 3 &&
      Math.abs(pvOff.padElevFt - (G.fgPadElevationAt(base68, 300, 300) + 3)) < 1e-6);
    // Auto zone at its committed rect: preview offset matches the builder's
    // solved offset (same lattice + median rule; balance re-solve is 2nd order).
    const pvAuto = G.previewZonePadInfo(base68, ramp68.grid, ramp68.rect, zAuto);
    check('[68] preview: auto zone offset ≈ builder-solved offset at same rect',
      pvAuto.solved && Math.abs(pvAuto.offsetFt - (fgAuto.zones?.[0]?.offsetFt ?? 999)) < 0.5);
    // Auto zone moved uphill on the ramp: preview offset moves with terrain.
    const pvAutoUp = G.previewZonePadInfo(base68, ramp68.grid, ramp68.rect,
      mkZone({ id: 'za2', mode: 'auto', offsetFt: 0, x: 700, y: 300 }));
    check('[68] preview: moving an auto zone re-solves against local terrain',
      pvAutoUp.solved && Math.abs(pvAutoUp.offsetFt - pvAuto.offsetFt) > 0.5);
    // Candidate rect with no samples (degenerate off-fence rect) is flagged.
    const pvNone = G.previewZonePadInfo(base68, ramp68.grid, ramp68.rect,
      mkZone({ id: 'zn', mode: 'auto', offsetFt: 0, x: 5000, y: 5000 }));
    check('[68] preview: auto zone with no terrain samples reports solved=false, offset 0',
      !pvNone.solved && pvNone.offsetFt === 0);
    // Scene wiring: the gzone ghost branch computes the live pad label.
    const scenePv68 = readFileSync('client/src/components/DesignScene.tsx', 'utf8');
    check('[68] scene ghost shows live pad elevation for grading-zone drags',
      scenePv68.includes('previewZonePadInfo(fgSurface, terrainYard, rect, cand)') &&
      scenePv68.includes('PAD ≈ ') &&
      /ghost && 'label' in ghost && ghost\.label/.test(scenePv68));

    // --- GP-1: zone layer/labels only when zones exist; baseline untouched
    const prop68 = GP.buildProposedContours(ramp68.grid, ramp68.rect, base68);
    const gpBase68 = GP.buildGradingPlanDxfString(design, 'Hondo_Test', { fg: base68, proposed: prop68 });
    const propZ68 = GP.buildProposedContours(ramp68.grid, ramp68.rect, fgOff);
    const gpZone68 = GP.buildGradingPlanDxfString(design, 'Hondo_Test', { fg: fgOff, proposed: propZ68 });
    check('[68] baseline GP-1 has no grading-zone layer or legend row',
      !gpBase68.includes('C - GRADING ZONE') && !gpBase68.includes('GRADING ZONE ...'));
    check('[68] zoned GP-1 draws the zone layer, name and PAD EL label',
      gpZone68.includes('C - GRADING ZONE') && gpZone68.includes('BESS PAD A') &&
      gpZone68.includes('PAD EL') && gpZone68.includes('+3.0 FT'));
    check('[68] zoned GP-1 is byte-deterministic',
      gpZone68 === GP.buildGradingPlanDxfString(design, 'Hondo_Test', { fg: fgOff, proposed: propZ68 }));

    // --- GP-2 cross-sections: FG traces carry zone pads, crossings labeled,
    // zero-zone sheet byte-identical.
    const GS68 = await import('../client/src/lib/nextera/gradingSections');
    const secsBase68 = GS68.buildGradingSections(ramp68.grid, ramp68.rect, base68);
    // Default A-A'/B-B' pass through the fence centroid (x=500 / y=500) and
    // miss the 200..400 × 225..375 zone; the quarter-point cut D-D' at
    // y≈300 crosses it, exercising the crossing math.
    const secsZone68 = GS68.buildGradingSections(ramp68.grid, ramp68.rect, fgOff, { quarterPoints: true });
    check('[68] zero-zone sections carry no zoneCrossings field (JSON byte-identical)',
      secsBase68.sections.every(s => !('zoneCrossings' in s)) &&
      JSON.stringify(secsBase68) ===
      JSON.stringify(GS68.buildGradingSections(ramp68.grid, ramp68.rect, base68)));
    check('[68] zoned sections report the crossing with correct stations and offset',
      ((): boolean => {
        // The zone rect spans x 200..400, y 225..375; A-A' (grade axis on the
        // east-falling ramp, through the fence centroid y=500) misses it,
        // some section must cross it with a positive-width interval.
        const all = secsZone68.sections.flatMap(s => s.zoneCrossings ?? []);
        return all.length > 0 && all.every(zc =>
          zc.name === 'BESS PAD A' && zc.offsetFt === 3 && zc.mode === 'offset' &&
          Number.isFinite(zc.sta0) && Number.isFinite(zc.sta1) && zc.sta1 > zc.sta0);
      })());
    check('[68] zoned FG trace steps up by the zone offset inside the crossing',
      ((): boolean => {
        for (const s of secsZone68.sections) {
          for (const zc of s.zoneCrossings ?? []) {
            const mid = (zc.sta0 + zc.sta1) / 2;
            const t = mid / s.lengthFt;
            const x = s.p0.x + (s.p1.x - s.p0.x) * t;
            const y = s.p0.y + (s.p1.y - s.p0.y) * t;
            const inZone = G.fgPadElevationAt(fgOff, x, y);
            const farField = G.fgPadElevationAt(fgOff, 800, 800);
            if (Math.abs((inZone - farField) - 3) > 1e-6) return false;
            // The sampled FG trace itself must agree at the nearest sample.
            const sm = s.samples.reduce((a2, b2) =>
              Math.abs(a2.station - mid) < Math.abs(b2.station - mid) ? a2 : b2);
            if (Math.abs(sm.fg - G.fgElevationAt(fgOff, ramp68.grid as any, ramp68.rect, x, y)) > 0.2) return false;
          }
        }
        return true;
      })());
    // A zone centered on the fence centroid is crossed by BOTH default
    // sections (A-A' and B-B' pass through x=500 / y=500).
    check('[68] default A-A\' and B-B\' both report a crossing for a centroid zone',
      ((): boolean => {
        const zc68 = mkZone({ id: 'zc', name: 'CENTER PAD', x: 500, y: 500 });
        const fgC = G.buildFgSurface(ramp68.grid, ramp68.rect, fence68, { padSlopePct: 0 }, undefined, [zc68])!;
        const secsC = GS68.buildGradingSections(ramp68.grid, ramp68.rect, fgC);
        return secsC.sections.length === 2 && secsC.sections.every(s => {
          const zcs = s.zoneCrossings ?? [];
          return zcs.length === 1 && zcs[0].name === 'CENTER PAD' &&
            zcs[0].sta1 - zcs[0].sta0 > 100; // 200x150 rect through the middle
        });
      })());
    const xsBase68 = GS68.buildGradingSectionsDxfString(design, 'Hondo_Test', secsBase68);
    const xsZone68 = GS68.buildGradingSectionsDxfString(design, 'Hondo_Test', secsZone68);
    check('[68] baseline GP-2 has no zone layer, bracket or legend row',
      !xsBase68.includes('X - GRADING ZONE') && !xsBase68.includes('GRADING ZONE ...') &&
      !xsBase68.includes('BESS PAD A'));
    check('[68] zoned GP-2 declares the zone layer, legend row and labeled bracket',
      xsZone68.includes('X - GRADING ZONE') &&
      xsZone68.includes('GRADING ZONE ............. CYAN BRACKET, SEE SHEET GP-1') &&
      xsZone68.includes('BESS PAD A (PAD +3.0 FT)'));
    check('[68] zoned GP-2 is byte-deterministic',
      xsZone68 === GS68.buildGradingSectionsDxfString(design, 'Hondo_Test', secsZone68));
    const PP68 = await import('../client/src/lib/nextera/pdfPlot');
    const xsPdfZone68 = PP68.buildGradingSectionsPdfString(
      { design, projectName: 'Hondo_Test' } as any, secsZone68);
    check('[68] zoned GP-2 PDF twin renders and is byte-deterministic',
      xsPdfZone68.startsWith('%PDF') &&
      xsPdfZone68 === PP68.buildGradingSectionsPdfString(
        { design, projectName: 'Hondo_Test' } as any, secsZone68));

    // --- Project JSON: zones only written when non-empty
    check('[68] projectFromState writes gradingZones only when non-empty',
      ((): boolean => {
        const storeSrc = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
        const m = storeSrc.match(/const projectFromState[\s\S]*?^\};/m);
        return !!m && /gradingZones\.length/.test(m[0]);
      })());

    // --- Every design-apply path (restore, import, layout regenerate — sync
    // and worker) re-validates zones against the just-applied fence and drops
    // invalid ones, matching the setGradingZones reject contract.
    check('[68] regenerate apply() geometrically re-validates zones against the new fence',
      ((): boolean => {
        const storeSrc = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
        // Match the apply() parameter LIST, not one exact signature: apply
        // takes extra optional arguments now, and pinning the old signature
        // made this guard silently stop guarding anything.
        const m = storeSrc.match(/const apply = \(design: SiteDesign[,)][\s\S]*?\n    \};/);
        return !!m && /gradingZonesRejectReason\([^)]*design\.fence\)/.test(m[0]) &&
          /gradingZones: \[\]/.test(m[0]);
      })());
    check('[68] out-of-fence zone from a saved file is rejected by the shared validator',
      ((): boolean => {
        // Same helper both paths call: a zone poking outside the fence must
        // produce a rejection reason (restore/import then drop to []).
        const bad = mkZone({ id: 'zbad', x: -500, y: 300 });
        return G.gradingZonesRejectReason([bad], fence68) !== null;
      })());

    // --- ezdxf audit: zoned GP-1 must still be valid AC1015
    {
      const { spawnSync } = await import('child_process');
      const probe = spawnSync('python3', ['-c', 'import ezdxf'], { timeout: 20000 });
      if (probe.status === 0) {
        const { writeFileSync: wf, mkdtempSync } = await import('fs');
        const os = await import('os');
        const dir = mkdtempSync(path.join(os.tmpdir(), 'gz-audit-'));
        const fp = path.join(dir, 'gp1_zones.dxf');
        const fpXs = path.join(dir, 'gp2_zones.dxf');
        wf(fp, gpZone68, 'utf8');
        wf(fpXs, xsZone68, 'utf8');
        const py = `
import sys
from ezdxf import recover
for f in ["${fp.replace(/\\/g, '/')}", "${fpXs.replace(/\\/g, '/')}"]:
    doc, auditor = recover.readfile(f)
    if auditor.has_errors:
        print(f"{f}: {len(auditor.errors)} audit errors", file=sys.stderr); sys.exit(1)
    if doc.dxfversion != "AC1015":
        print(f"{f}: version {doc.dxfversion}", file=sys.stderr); sys.exit(1)
sys.exit(0)
`;
        const audit = spawnSync('python3', ['-c', py], { timeout: 120000 });
        check('[68] zoned GP-1 + GP-2 DXF pass the ezdxf recover/audit as valid AC1015',
          audit.status === 0,
          audit.status === 0 ? undefined : String(audit.stderr));
      } else {
        console.log('  (ezdxf not available — zoned GP-1 structural audit skipped)');
      }
    }

    // --- Scene drag editing: zones are draggable/resizable rectangles in the
    // layout-edit layer, gated on gradingEnabled, and every commit routes
    // through setGradingZones (reject→warn→keep) — source-scanned so the
    // wiring can't silently regress.
    {
      const sceneSrc68 = readFileSync('client/src/components/DesignScene.tsx', 'utf8');
      check('[68] scene zones are gated on gradingEnabled (zero zones render nothing)',
        /const gzones = gradingEnabled \? gradingZonesAll : \[\]/.test(sceneSrc68) &&
        /\{gzones\.map\(z =>/.test(sceneSrc68));
      check('[68] scene has move + corner-resize drag kinds for grading zones',
        /kind: 'gzone'; id: string/.test(sceneSrc68) &&
        /kind: 'gzone-resize'; id: string; sx: 1 \| -1; sy: 1 \| -1/.test(sceneSrc68));
      check('[68] zone drop commits through setGradingZones and toasts the reject reason',
        /setGradingZones\(gzones\.map\(g => \(g\.id === z\.id \? cand : g\)\)\)/.test(sceneSrc68) &&
        /if \(err\) toast\.error\(`\$\{err\} Snapped back\.`\)/.test(sceneSrc68));
      check('[68] zone drag ghost uses the shared fence/overlap validator',
        /const reason = gradingZonesRejectReason\(candSet, design\.fence\)/.test(sceneSrc68));
      check('[68] zone resize keeps the opposite corner fixed and clamps to the engine minimum',
        /function resizeGradingZoneRect\(/.test(sceneSrc68) &&
        /Math\.max\(ZONE_MIN_SIZE_FT, sx \* \(movX - fixedX\)\)/.test(sceneSrc68));
      // Raycast precedence: zones overlap rows (y 0.45) and equipment (y 0.5)
      // pick planes, and the nearest hit wins in R3F — so the zone MOVE grab
      // band must sit ABOVE both (0.62) and the resize handles above the band
      // (0.64), or overlapping planes steal the drag.
      check('[68] zone move grab band + handles sit above the row/equipment pick planes',
        /gzone-band-\$\{z\.id\}-\$\{i\}/.test(sceneSrc68) &&
        /position=\{\[s\.x, 0\.62, -s\.y\]\}/.test(sceneSrc68) &&
        /position=\{\[hxp, 0\.64, -hyp\]\}/.test(sceneSrc68));
    }

    // --- Panel exact-dimensions entry: center x/y and length/width are
    // draft-based fields that commit on Enter/blur through setGradingZones
    // (reject→warn→keep, drafts resync from drag edits when not focused) —
    // source-scanned so the wiring can't silently regress to per-keystroke
    // commits that snap back mid-typing.
    {
      const panelSrc68 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
      check('[68] panel exact-entry fields are draft-based, committing on Enter/blur',
        /function ZoneDimField\(/.test(panelSrc68) &&
        /onBlur=\{commit\}/.test(panelSrc68) &&
        /if \(e\.key === 'Enter'\) \(e\.target as HTMLInputElement\)\.blur\(\)/.test(panelSrc68));
      check('[68] panel exact-entry drafts resync from external (drag) edits when not focused',
        /if \(!editing\) setDraft\(String\(value\)\);/.test(panelSrc68));
      check('[68] panel exact-entry commits route through setGradingZones and surface the reject reason',
        /const err = setGradingZones\(zonesNow\.map\(g => g\.id === z\.id \? \{ \.\.\.g, \[key\]: v \} : g\)\);/.test(panelSrc68) &&
        /setZoneError\(err\);/.test(panelSrc68));
      check('[68] panel exact-entry length/width are bounded by the engine zone size limits',
        /\['Length', 'lengthFt', 5, ZONE_MIN_SIZE_FT, ZONE_MAX_SIZE_FT\]/.test(panelSrc68) &&
        /\['Width', 'widthFt', 5, ZONE_MIN_SIZE_FT, ZONE_MAX_SIZE_FT\]/.test(panelSrc68));
      check('[68] panel exact-entry reverts the draft when a commit is rejected',
        /if \(err\) setDraft\(String\(value\)\);/.test(panelSrc68));
    }
  }

  // ---------------------------------------------------------------
  // [69] Energy & dispatch simulation: IEC 62933-2-1 AC-PoC RTE,
  // NREL semi-empirical degradation, augmentation planning — hand
  // computed reference values, sanitizer clamps, project-file opt-in
  // byte identity and source-scanned UI/store wiring.
  console.log('\n[69] Energy & dispatch simulation');
  {
    const {
      buildRteBreakdown, buildEnergySim, sanitizeEnergySimInputs,
      DEFAULT_ENERGY_SIM_INPUTS, cohortSoh, arrheniusFactor,
      DEFAULT_CABLE_LOSS_FRAC, XFMR_NO_LOAD_FRAC, XFMR_LOAD_LOSS_FRAC,
      CAL_FADE_PER_SQRT_YEAR, CYC_FADE_PER_EFC_100DOD, CELL_TEMP_RISE_C,
      SOH_FLOOR, DAYS_PER_YEAR,
    } = await import('../client/src/lib/nextera/energySim');

    // ---- RTE loss chain, hand-computed ---------------------------------
    // 400 MWh BOL, 100% DOD, 1 cycle/day, 80 containers, default losses.
    const inp0 = sanitizeEnergySimInputs({ ...DEFAULT_ENERGY_SIM_INPUTS, dodPct: 100, cyclesPerDay: 1 });
    const rte = buildRteBreakdown(
      { usableMWhPerCycle: 400, containers: 80, cableLossFrac: DEFAULT_CABLE_LOSS_FRAC, cyclesPerDay: 1 },
      inp0
    );
    const xfmr = 1 - (XFMR_NO_LOAD_FRAC + XFMR_LOAD_LOSS_FRAC);
    const oneWay = 0.985 * xfmr * (1 - DEFAULT_CABLE_LOSS_FRAC); // PCS·xfmr·cable
    // Battery losses are charged on the way in (E_dc/rteDc), the DC bus
    // energy discharges through the one-way BoP chain on the way out.
    const expDischarge = 400 * oneWay;
    const expCharge = 400 / 0.94 / oneWay;
    const expAux = 80 * 3.5 * 24 / 1000; // MWh/day
    const expRte = expDischarge / (expCharge + expAux);
    check('[69] RTE: daily AC discharge matches hand computation',
      Math.abs(rte.dailyDischargeMWh - expDischarge) < 1e-9);
    check('[69] RTE: daily AC charge matches hand computation',
      Math.abs(rte.dailyChargeMWh - expCharge) < 1e-9);
    check('[69] RTE: aux energy = containers × kW × 24h',
      Math.abs(rte.dailyAuxMWh - expAux) < 1e-9);
    check('[69] RTE: system AC-PoC RTE incl. aux matches hand computation',
      Math.abs(rte.acRtePct - expRte * 100) < 1e-9);
    check('[69] RTE: ex-aux AC RTE = battery RTE × (one-way chain)²',
      Math.abs(rte.acRteExAuxPct - 0.94 * oneWay * oneWay * 100) < 1e-9);
    check('[69] RTE: incl-aux RTE is strictly below ex-aux RTE',
      rte.acRtePct < rte.acRteExAuxPct);
    check('[69] RTE: plausible LFP system band (80–90% ex-aux)',
      rte.acRteExAuxPct > 80 && rte.acRteExAuxPct < 90);

    // ---- Degradation: Arrhenius + √t calendar + EFC cycle ---------------
    check('[69] Arrhenius factor is 1 at the 25 °C reference cell temp',
      Math.abs(arrheniusFactor(25) - 1) < 1e-12);
    check('[69] Arrhenius factor roughly doubles per +12 °C',
      arrheniusFactor(37) / arrheniusFactor(25) > 1.35 &&
      arrheniusFactor(37) / arrheniusFactor(25) < 1.65);
    // cohortSoh hand check at 25 °C ambient? cell = ambient + 5 → use
    // ambient 20 so cell = 25 and the Arrhenius factor is exactly 1.
    const inpDeg = sanitizeEnergySimInputs({
      ...DEFAULT_ENERGY_SIM_INPUTS, avgAmbientC: 25 - CELL_TEMP_RISE_C,
      cyclesPerDay: 1, dodPct: 100,
    });
    const efcYr = 1 * DAYS_PER_YEAR;
    const expSoh4 = 1 - CAL_FADE_PER_SQRT_YEAR * Math.sqrt(4)
      - CYC_FADE_PER_EFC_100DOD * efcYr * 4 * Math.sqrt(1);
    check('[69] cohort SOH at year 4 matches hand computation (cell at reference temp)',
      Math.abs(cohortSoh(4, inpDeg) - expSoh4) < 1e-9);
    check('[69] cohort SOH is monotonically non-increasing over 40 years',
      Array.from({ length: 40 }, (_, i) => cohortSoh(i + 1, inpDeg))
        .every((v, i, a) => i === 0 || v <= a[i - 1] + 1e-12));
    check('[69] cohort SOH never falls below the model floor',
      cohortSoh(4000, inpDeg) >= SOH_FLOOR);
    check('[69] hotter site degrades faster (calendar Arrhenius)',
      cohortSoh(10, sanitizeEnergySimInputs({ ...inpDeg, avgAmbientC: 35 })) <
      cohortSoh(10, inpDeg));
    check('[69] deeper DOD degrades faster (√DOD stress factor)',
      cohortSoh(10, inpDeg) <
      cohortSoh(10, sanitizeEnergySimInputs({ ...inpDeg, dodPct: 50 })));

    // ---- Full simulation + augmentation planner -------------------------
    const plant = {
      bolMWh: 408, containers: 80, containerMWh: 5.1, containersPerBlock: 4,
      augZoneBlocks: 3, cableLossFrac: DEFAULT_CABLE_LOSS_FRAC,
    };
    const noContract = buildEnergySim(plant, sanitizeEnergySimInputs({ ...DEFAULT_ENERGY_SIM_INPUTS, contractMWh: 0 }));
    check('[69] sim: no contract → no augmentation events',
      noContract.augmentation.length === 0 && noContract.totalAddedContainers === 0 &&
      noContract.zonesSufficient);
    check('[69] sim: one row per project year',
      noContract.years.length === DEFAULT_ENERGY_SIM_INPUTS.projectLifeYears);
    check('[69] sim: usable energy declines monotonically without augmentation',
      noContract.years.every((y, i, a) => i === 0 || y.usableMWh <= a[i - 1].usableMWh + 1e-9));
    // Year-1 discharge cycles the END-of-year-1 usable capacity (post-fade),
    // so it sits just below the BOL daily discharge × 365 headline.
    check('[69] sim: year-1 discharge slightly below BOL daily discharge × 365 (year-1 fade)',
      noContract.annualThroughputBolMWh > 0 &&
      noContract.annualThroughputBolMWh < noContract.rte.dailyDischargeMWh * DAYS_PER_YEAR &&
      noContract.annualThroughputBolMWh > 0.9 * noContract.rte.dailyDischargeMWh * DAYS_PER_YEAR);

    const contracted = buildEnergySim(plant, sanitizeEnergySimInputs({
      ...DEFAULT_ENERGY_SIM_INPUTS, contractMWh: 360, projectLifeYears: 20,
    }));
    check('[69] sim: contract forces at least one augmentation over 20 years',
      contracted.augmentation.length > 0 && contracted.totalAddedContainers > 0);
    check('[69] sim: usable energy meets the contract every year after augmentation',
      contracted.years.every(y => y.usableMWh >= 360 - 1e-6));
    check('[69] sim: augmentation adds whole containers (nameplate = n × 5.1 MWh)',
      contracted.augmentation.every(a =>
        a.containers >= 1 && Math.abs(a.mwh - a.containers * 5.1) < 1e-9));
    check('[69] sim: zone capacity = augZoneBlocks × containersPerBlock',
      contracted.zoneCapacityContainers === 12);
    check('[69] sim: zonesSufficient flag matches the container arithmetic',
      contracted.zonesSufficient === (contracted.totalAddedContainers <= 12));
    const noZones = buildEnergySim({ ...plant, augZoneBlocks: 0 }, sanitizeEnergySimInputs({
      ...DEFAULT_ENERGY_SIM_INPUTS, contractMWh: 360, projectLifeYears: 20,
    }));
    check('[69] sim: zero reserved zones with needed augmentation → insufficient',
      noZones.totalAddedContainers > 0 && !noZones.zonesSufficient);
    check('[69] sim: deterministic across runs (byte-identical JSON)',
      JSON.stringify(contracted) === JSON.stringify(buildEnergySim(plant, sanitizeEnergySimInputs({
        ...DEFAULT_ENERGY_SIM_INPUTS, contractMWh: 360, projectLifeYears: 20,
      }))));
    check('[69] sim: notes carry the IEC framing and the screening disclaimer',
      contracted.notes.some(n => n.includes('IEC 62933-2-1')) &&
      contracted.notes.some(n => n.includes('SCREENING ONLY')));

    // ---- Sanitizer clamps ------------------------------------------------
    const dirty = sanitizeEnergySimInputs({
      cyclesPerDay: 99, avgAmbientC: NaN, projectLifeYears: -3,
      contractMWh: 'x', dodPct: 5, batteryRteDc: 2, pcsEff: 0.1,
      auxKwPerContainer: 1e9,
    });
    check('[69] sanitize: out-of-range and non-numeric inputs clamp to safe values',
      dirty.cyclesPerDay <= 4 && dirty.avgAmbientC === DEFAULT_ENERGY_SIM_INPUTS.avgAmbientC &&
      dirty.projectLifeYears >= 1 && dirty.contractMWh === 0 &&
      dirty.dodPct >= 10 && dirty.batteryRteDc <= 1 && dirty.pcsEff >= 0.9 &&
      dirty.auxKwPerContainer <= 20);
    check('[69] sanitize: undefined → documented defaults',
      JSON.stringify(sanitizeEnergySimInputs(undefined)) === JSON.stringify(DEFAULT_ENERGY_SIM_INPUTS));

    // ---- Project-file opt-in key: byte identity while off ---------------
    {
      const { useDesignStore, validateProjectFile } = await import('../client/src/lib/stores/useDesignStore');
      useDesignStore.getState().clearSite();
      useDesignStore.setState({ boundary: hondo, targetMW: 100, targetMWh: 400 });
      useDesignStore.getState().regenerate();
      const baseJson = useDesignStore.getState().exportProjectJson();
      if (baseJson) {
        check('[69] project file omits the energySim key while the study is off',
          !('energySim' in JSON.parse(baseJson)));
        useDesignStore.getState().setEnergySimEnabled(true);
        useDesignStore.getState().setEnergySimInputs({ contractMWh: 360 });
        const onJson = useDesignStore.getState().exportProjectJson()!;
        const onParsed = JSON.parse(onJson);
        check('[69] project file carries energySim {enabled, inputs} while on',
          onParsed.energySim?.enabled === true && onParsed.energySim?.inputs?.contractMWh === 360);
        check('[69] project file with energySim still validates',
          validateProjectFile(onParsed) === null);
        check('[69] validate rejects a non-object energySim section',
          validateProjectFile({ ...onParsed, energySim: [1] }) !== null);
        useDesignStore.getState().setEnergySimEnabled(false);
        const offJson = useDesignStore.getState().exportProjectJson()!;
        // savedAt is a wall-clock timestamp, so normalize it before the
        // byte comparison — everything else must match exactly.
        const stripSavedAt = (j: string) => j.replace(/"savedAt": "[^"]*"/, '"savedAt": "X"');
        check('[69] turning the study off restores byte-identical project JSON (savedAt normalized)',
          stripSavedAt(offJson) === stripSavedAt(baseJson));
        // Structural twin of the string check: parse both files, drop the
        // savedAt wall-clock field, and deep-compare. This catches any field
        // that drifts between on→off and baseline with a clearer failure
        // signal than a byte mismatch (the string check above defines "byte
        // identity" as identical modulo the savedAt timestamp only).
        const offParsed = JSON.parse(offJson);
        const baseParsed = JSON.parse(baseJson);
        delete offParsed.savedAt;
        delete baseParsed.savedAt;
        const { isDeepStrictEqual } = await import('node:util');
        check('[69] on→off export deep-equals the baseline in every field except savedAt',
          isDeepStrictEqual(offParsed, baseParsed));
        // Import roundtrip restores the study; clearSite resets it.
        check('[69] importProject restores energySim enabled + inputs',
          useDesignStore.getState().importProject(onJson) === null &&
          useDesignStore.getState().energySimEnabled === true &&
          useDesignStore.getState().energySimInputs.contractMWh === 360);
        useDesignStore.getState().clearSite();
        check('[69] clearSite resets the energy study to disabled defaults',
          useDesignStore.getState().energySimEnabled === false &&
          JSON.stringify(useDesignStore.getState().energySimInputs) === JSON.stringify(DEFAULT_ENERGY_SIM_INPUTS));
        check('[69] importing a file without the key leaves the study disabled',
          useDesignStore.getState().importProject(baseJson) === null &&
          useDesignStore.getState().energySimEnabled === false);
        // gradingZones is the other opt-in project-file key: apply the same
        // string + structural (deep-compare) guard so a future change that
        // leaks zone state into the export is named structurally, not just
        // flagged as a byte mismatch.
        const gzBase = useDesignStore.getState().exportProjectJson()!;
        check('[69] project file omits the gradingZones key while no zones exist',
          !('gradingZones' in JSON.parse(gzBase)));
        const fence69 = useDesignStore.getState().design!.fence;
        const gzCx = fence69.reduce((a, p) => a + p.x, 0) / fence69.length;
        const gzCy = fence69.reduce((a, p) => a + p.y, 0) / fence69.length;
        useDesignStore.setState({
          gradingZones: [{
            id: 'gz69', name: 'BESS PAD Z', x: gzCx, y: gzCy,
            lengthFt: 20, widthFt: 20, mode: 'offset' as const, offsetFt: 2,
          }],
        });
        const gzOnJson = useDesignStore.getState().exportProjectJson()!;
        check('[69] project file carries gradingZones while a zone exists',
          JSON.parse(gzOnJson).gradingZones?.[0]?.id === 'gz69');
        useDesignStore.setState({ gradingZones: [] });
        const gzOffJson = useDesignStore.getState().exportProjectJson()!;
        check('[69] removing all zones restores byte-identical project JSON (savedAt normalized)',
          stripSavedAt(gzOffJson) === stripSavedAt(gzBase));
        const gzOffParsed = JSON.parse(gzOffJson);
        const gzBaseParsed = JSON.parse(gzBase);
        delete gzOffParsed.savedAt;
        delete gzBaseParsed.savedAt;
        check('[69] zones on→off export deep-equals the baseline in every field except savedAt',
          isDeepStrictEqual(gzOffParsed, gzBaseParsed));
      } else {
        check('[69] project JSON available for energySim byte-identity test', false, 'exportProjectJson returned null');
      }
    }

    // ---- Source scan: UI + PDF wiring can't silently regress -------------
    {
      const panelSrc69 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
      check('[69] panel derives the sim from layout + feeders and gates on the toggle',
        /if \(!energySimEnabled \|\| !design \|\| design\.blocksPlaced <= 0\) return null;/.test(panelSrc69) &&
        /augZoneBlocks: design\.reserveSummary\?\.augBlocksPlaced \?\? 0/.test(panelSrc69) &&
        /electricalReport\.totalPeakLossKW \/ \(design\.achievedMW \* 1000\)/.test(panelSrc69));
      check('[69] panel inputs route through setEnergySimInputs (sanitized store patch)',
        /setEnergySimInputs\(\{ cyclesPerDay: v \}\)/.test(panelSrc69) &&
        /setEnergySimInputs\(\{ contractMWh: v \}\)/.test(panelSrc69));
      check('[69] panel exposes RTE overrides (battery DC RTE + PCS one-way eff, entered as %)',
        /setEnergySimInputs\(\{ batteryRteDc: v \/ 100 \}\)/.test(panelSrc69) &&
        /setEnergySimInputs\(\{ pcsEff: v \/ 100 \}\)/.test(panelSrc69));
      check('[69] panel exports the report through buildEnergySimPdf + saveBlob',
        /buildEnergySimPdf\(energySim, energySimInputs, \{/.test(panelSrc69) &&
        /_Energy_Simulation_\$\{new Date\(\)\.toISOString\(\)\.slice\(0, 10\)\}\.pdf/.test(panelSrc69));
    }

    // ---- Source scan (same pattern as [50]/[58]): the in-panel
    // CapacityCurvePreview mirrors drawCapacityChart in energySimPdf.ts and
    // must be fed the exact same buildEnergySim result the report embeds.
    // Expected styling is extracted from energySimPdf.ts so a PDF-side
    // change fails here until the preview follows.
    {
      const panelSrc69 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
      const prevSrc69 = readFileSync('client/src/components/CapacityCurvePreview.tsx', 'utf8');
      const pdfSrc69 = readFileSync('client/src/lib/nextera/energySimPdf.ts', 'utf8');

      // The preview is actually mounted in the panel...
      check('[69] panel mounts CapacityCurvePreview',
        panelSrc69.includes('<CapacityCurvePreview') &&
        panelSrc69.includes("from './CapacityCurvePreview'"));
      // ...fed the SAME shared energySim memo the report export uses, so
      // preview and PDF cannot diverge by construction.
      const simCalls69 = [...panelSrc69.matchAll(/buildEnergySim\(\{/g)];
      check('[69] panel builds the energy sim exactly once (shared memo)', simCalls69.length === 1);
      const mount69 = panelSrc69.match(/<CapacityCurvePreview\b([\s\S]*?)\/>/);
      const mountResult69 = mount69?.[1].match(/result=\{(\w+)\}/);
      check('[69] preview mount and PDF export use the SAME sim variable',
        !!mountResult69 && mountResult69[1] === 'energySim' &&
        /buildEnergySimPdf\(energySim,/.test(panelSrc69),
        `preview(${mountResult69?.[1]})`);

      // Isolate the PDF chart function body.
      const chartStart69 = pdfSrc69.indexOf('function drawCapacityChart');
      const chartTail69 = pdfSrc69.slice(chartStart69);
      const chartEnd69 = chartTail69.indexOf('\nexport function', 10);
      const chartSrc69 = chartStart69 >= 0 ? (chartEnd69 > 0 ? chartTail69.slice(0, chartEnd69) : chartTail69) : '';
      check('[69] drawCapacityChart found in energySimPdf.ts', chartSrc69.length > 0);

      const flatPrev69 = prevSrc69.replace(/\n\s*/g, ' ');
      // Curve: same blue stroke and width as the PDF polyline.
      const curveColor69 = chartSrc69.match(/setDrawColor\((\d+), (\d+), (\d+)\);\s*doc\.setLineWidth\(([\d.]+)\);\s*let prevX/);
      check('[69] extracted curve stroke from the PDF chart', !!curveColor69);
      check('[69] preview curve stroke matches the PDF chart',
        !!curveColor69 && new RegExp(
          `stroke="rgb\\(${curveColor69[1]},${curveColor69[2]},${curveColor69[3]}\\)" strokeWidth=\\{${curveColor69[4]}\\}`
        ).test(flatPrev69),
        `expect rgb(${curveColor69?.slice(1, 4).join(',')}) @ ${curveColor69?.[4]}`);
      // Contract line: same red, width and dash pattern.
      const contract69 = chartSrc69.match(/setDrawColor\((\d+), (\d+), (\d+)\);\s*doc\.setLineWidth\(([\d.]+)\);\s*doc\.setLineDashPattern\(\[(\d+), (\d+)\]/);
      check('[69] extracted contract line style from the PDF chart', !!contract69);
      check('[69] preview contract line matches the PDF chart (color, width, dash)',
        !!contract69 && new RegExp(
          `stroke="rgb\\(${contract69[1]},${contract69[2]},${contract69[3]}\\)" strokeWidth=\\{${contract69[4]}\\} strokeDasharray="${contract69[5]} ${contract69[6]}"`
        ).test(flatPrev69),
        `expect rgb(${contract69?.slice(1, 4).join(',')}) @ ${contract69?.[4]} dash ${contract69?.[5]},${contract69?.[6]}`);
      // Augmentation markers: same orange fill, same triangle geometry offsets.
      const augFill69 = chartSrc69.match(/setFillColor\((\d+), (\d+), (\d+)\)/);
      check('[69] extracted augmentation marker fill from the PDF chart', !!augFill69);
      check('[69] preview augmentation triangles match the PDF chart fill',
        !!augFill69 && flatPrev69.includes(`fill="rgb(${augFill69[1]},${augFill69[2]},${augFill69[3]})"`));
      check('[69] preview triangle geometry matches the PDF chart (\u00b13 x, -4.5/+1.5 y)',
        /my - 4\.5/.test(chartSrc69) && /mx - 3/.test(chartSrc69) &&
        prevSrc69.includes('my - 4.5') && prevSrc69.includes('mx - 3') && prevSrc69.includes('mx + 3'));
      // Same 1/2/5 y-tick ladder and full-year x scale as the PDF chart.
      const ladder69 = '(norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 5 ? 5 : 10) * mag';
      check('[69] preview y-axis tick ladder matches the PDF chart',
        chartSrc69.includes(ladder69) && prevSrc69.includes(ladder69));
      check('[69] preview x-axis ticks match the PDF chart (year 1, every 5th, final)',
        /yr === 1 \|\| yr === nYears \|\| yr % 5 === 0/.test(chartSrc69) &&
        /yr === 1 \|\| yr === nYears \|\| yr % 5 === 0/.test(prevSrc69));
      check('[69] preview plots the full year series (never condensed rows)',
        /const years = result\.years;/.test(prevSrc69));
    }

    // ---- PDF: strictly one page across the full allowed horizon ---------
    {
      const { buildEnergySimPdf } = await import('../client/src/lib/nextera/energySimPdf');
      const meta = {
        titleBlock: { projectName: 'HONDO BESS', projectNumber: '', location: '', client: '', drawnBy: '', date: '' } as any,
        configLabel: 'GE FLEXRESERVOIR 5.1',
        achievedMW: 100.5, achievedMWh: 408, containers: 80,
      };
      const plant40 = { bolMWh: 408, containers: 80, containerMWh: 5.1, containersPerBlock: 4, augZoneBlocks: 6, cableLossFrac: DEFAULT_CABLE_LOSS_FRAC };
      const sim40 = buildEnergySim(plant40, sanitizeEnergySimInputs({
        ...DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: 40, contractMWh: 360,
      }));
      const doc40 = buildEnergySimPdf(sim40, sanitizeEnergySimInputs({ ...DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: 40, contractMWh: 360 }), meta);
      check('[69] PDF stays one page at the 40-year maximum horizon (milestone-year condensation)',
        doc40.getNumberOfPages() === 1);
      const sim20 = buildEnergySim(plant40, sanitizeEnergySimInputs({
        ...DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: 20, contractMWh: 360,
      }));
      const doc20 = buildEnergySimPdf(sim20, sanitizeEnergySimInputs({ ...DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: 20, contractMWh: 360 }), meta);
      check('[69] PDF stays one page at a 20-year horizon with every year listed',
        doc20.getNumberOfPages() === 1);
      // 25 years is the longest full (non-condensed) table — the chart
      // height flexes down so this worst case still fits one page.
      const sim25 = buildEnergySim(plant40, sanitizeEnergySimInputs({
        ...DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: 25, contractMWh: 360,
      }));
      const doc25 = buildEnergySimPdf(sim25, sanitizeEnergySimInputs({ ...DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: 25, contractMWh: 360 }), meta);
      check('[69] PDF stays one page at the 25-year full-table worst case (with chart)',
        doc25.getNumberOfPages() === 1);

      // Capacity chart: deterministic vector output — two builds of the
      // same model are byte-identical once the wall-clock CreationDate/ID
      // trailer entries are normalized.
      const normalizePdf = (s: string) => s
        .replace(/\/CreationDate \([^)]*\)/g, '/CreationDate (X)')
        .replace(/\/ID \[[^\]]*\]/g, '/ID [X]');
      const doc20b = buildEnergySimPdf(sim20, sanitizeEnergySimInputs({ ...DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: 20, contractMWh: 360 }), meta);
      check('[69] PDF rebuild is byte-identical for the same model (CreationDate/ID normalized)',
        normalizePdf(doc20.output()) === normalizePdf(doc20b.output()));

      // Source scan: the report must draw the capacity curve chart with
      // pure vector primitives from the FULL year series (never the
      // condensed milestone rows), mark augmentation years, and draw the
      // contract requirement as a dashed line.
      const pdfSrc69 = readFileSync('client/src/lib/nextera/energySimPdf.ts', 'utf8');
      check('[69] report draws the capacity chart between the year table and the zone check',
        /drawCapacityChart\(doc, result, margin, y, pageW - 2 \* margin, chartH\)/.test(pdfSrc69));
      check('[69] chart plots the full year series with contract dashed line and augmentation markers',
        /const years = result\.years;/.test(pdfSrc69) &&
        /setLineDashPattern\(\[3, 2\], 0\)/.test(pdfSrc69) &&
        /augAddedContainers > 0/.test(pdfSrc69) &&
        /doc\.triangle\(/.test(pdfSrc69));
      check('[69] chart height flexes down on long horizons so the page cannot overflow',
        /const chartH = condensed \? 118 : Math\.max\(78, 118 - \(result\.years\.length - 20\) \* 8\);/.test(pdfSrc69));
      check('[69] chart uses no raster images (vector-only primitives)',
        !/addImage\(/.test(pdfSrc69));

      // Worst-case density: hot site + deep DOD + 2 cycles/day + tight
      // contract forces augmentation in ~half the 40 years, so the
      // milestone filter keeps far more than the every-5th-year rows.
      const worstInputs = sanitizeEnergySimInputs({
        ...DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: 40, contractMWh: 330,
        avgAmbientC: 45, dodPct: 100, cyclesPerDay: 2,
      });
      const simWorst = buildEnergySim(plant40, worstInputs);
      const worstAugYears = simWorst.years.filter(yr => yr.augAddedContainers > 0).length;
      check('[69] worst-case scenario actually triggers frequent augmentation (>=15 aug years)',
        worstAugYears >= 15);
      const docWorst = buildEnergySimPdf(simWorst, worstInputs, {
        ...meta, titleBlock: { ...meta.titleBlock, projectName: 'X'.repeat(40) },
      });
      check('[69] PDF stays one page in the augmentation-heavy 40-year worst case',
        docWorst.getNumberOfPages() === 1);

      // Off-scale contract handling: a contract far below BOL (< 50%) must
      // not compress the curve — the axis zooms to the usable range and the
      // contract line is pinned at the bottom edge with an explicit
      // "below scale" note.
      check('[69] chart clips a far-below-BOL contract out of the y-scale (axis zoom)',
        /const contractOffScale = contract > 0 && contract < 0\.5 \* bolMWh;/.test(pdfSrc69) &&
        /if \(contract > 0 && !contractOffScale\) vals\.push\(contract\);/.test(pdfSrc69));
      check('[69] off-scale contract is pinned at the plot bottom with a "below scale" note',
        /const cy = contractOffScale \? py \+ ph : sy\(contract\);/.test(pdfSrc69) &&
        /below scale \\u2014 axis zoomed to usable range/.test(pdfSrc69));
      // Functional: a 50 MWh contract on a 408 MWh yard still builds a
      // one-page, byte-deterministic report.
      const simLow = buildEnergySim(plant40, sanitizeEnergySimInputs({
        ...DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: 20, contractMWh: 50,
      }));
      const inputsLow = sanitizeEnergySimInputs({ ...DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: 20, contractMWh: 50 });
      const docLow = buildEnergySimPdf(simLow, inputsLow, meta);
      const docLowB = buildEnergySimPdf(simLow, inputsLow, meta);
      check('[69] one-page + byte-determinism hold with an off-scale (50 MWh on 408 MWh) contract',
        docLow.getNumberOfPages() === 1 &&
        normalizePdf(docLow.output()) === normalizePdf(docLowB.output()));
    }
  }

  // ---------------------------------------------------------------
  // [70] Drainage A+ package: NOAA Atlas 14 IDF, weighted C, trapezoidal
  //      channels + riprap, detention screening, culverts, DR-1 sheet.
  {
    console.log('\n[70] Drainage A+ (Atlas 14 IDF, weighted C, channels, detention, culverts, DR-1)');
    const G = await import('../client/src/lib/nextera/gradingSurface');
    const D = await import('../client/src/lib/nextera/drainage');
    const R = await import('../client/src/lib/nextera/rainfall');

    // ---- NOAA PFDS parser on a synthetic intensity CSV -------------------
    const ari70 = [1, 2, 5, 10, 25, 50, 100];
    const mkRow = (label: string, base: number) =>
      `${label}:,` + ari70.map((_, k) => (base * (1 + 0.15 * k)).toFixed(3)).join(',');
    const csv70 = [
      'Point precipitation frequency estimates (inches/hour)',
      'NOAA Atlas 14 Volume 8 Version 2',
      'Precipitation intensity estimates',
      'PRECIPITATION FREQUENCY ESTIMATES by duration for ARI (years):,' + ari70.join(','),
      mkRow('5-min', 6.0), mkRow('10-min', 4.5), mkRow('15-min', 3.7),
      mkRow('30-min', 2.6), mkRow('60-min', 1.7), mkRow('2-hr', 1.0),
      mkRow('3-hr', 0.75), mkRow('6-hr', 0.45), mkRow('12-hr', 0.27),
      mkRow('24-hr', 0.16), mkRow('2-day', 0.09), mkRow('3-day', 0.065),
      '',
    ].join('\n');
    const idf70 = R.parseNoaaPfdsCsv(csv70, 29.35, -99.15);
    check('[70] PFDS parser: source line, 12 ascending durations, 7 ARI columns',
      idf70.source.includes('NOAA Atlas 14 Volume 8') &&
      idf70.durationsMin.length === 12 && idf70.ariYears.length === 7 &&
      idf70.durationsMin[0] === 5 && idf70.durationsMin[11] === 4320 &&
      idf70.durationsMin.every((d, i) => i === 0 || d > idf70.durationsMin[i - 1]));
    check('[70] PFDS parser: rejects a non-intensity payload (depth table)',
      ((): boolean => {
        try { R.parseNoaaPfdsCsv(csv70.replace(/intensity/gi, 'depth'), 29, -99); return false; }
        catch { return true; }
      })());
    check('[70] PFDS parser: rejects a truncated table (<5 duration rows)',
      ((): boolean => {
        const short = csv70.split('\n').slice(0, 7).join('\n');
        try { R.parseNoaaPfdsCsv(short, 29, -99); return false; } catch { return true; }
      })());

    // ---- IDF sanitizer + log-log interpolation ---------------------------
    check('[70] IDF sanitizer: round-trips a valid table, rejects garbage',
      JSON.stringify(R.sanitizeAtlas14Idf(JSON.parse(JSON.stringify(idf70)))) === JSON.stringify(idf70) &&
      R.sanitizeAtlas14Idf(null) === null &&
      R.sanitizeAtlas14Idf({ ...idf70, lat: 999 }) === null &&
      R.sanitizeAtlas14Idf({ ...idf70, intensityInHr: idf70.intensityInHr.slice(1) }) === null &&
      R.sanitizeAtlas14Idf({ ...idf70, durationsMin: [...idf70.durationsMin].reverse() }) === null);
    check('[70] idfIntensityAt: exact at listed durations, snaps ARI to nearest column',
      Math.abs(R.idfIntensityAt(idf70, 25, 15) - idf70.intensityInHr[2][4]) < 1e-9 &&
      Math.abs(R.idfIntensityAt(idf70, 24, 15) - idf70.intensityInHr[2][4]) < 1e-9);
    check('[70] idfIntensityAt: log-log interpolation lands between bracketing rows',
      ((): boolean => {
        const v = R.idfIntensityAt(idf70, 25, 20); // between 15 and 30 min
        return v < idf70.intensityInHr[2][4] && v > idf70.intensityInHr[3][4];
      })());
    check('[70] idfIntensityAt: clamps to the table range (no extrapolation)',
      Math.abs(R.idfIntensityAt(idf70, 25, 1) - idf70.intensityInHr[0][4]) < 1e-9 &&
      Math.abs(R.idfIntensityAt(idf70, 25, 99999) - idf70.intensityInHr[11][4]) < 1e-9);

    // ---- Trapezoidal Manning hand math: b=2, z=3, s=1%, n=0.03, d=1 ft ---
    {
      const A = (2 + 3 * 1) * 1, P = 2 + 2 * Math.sqrt(10), Rh = A / P;
      const qHand = (1.49 / 0.03) * A * Math.pow(Rh, 2 / 3) * Math.sqrt(0.01);
      const sec = D.trapezoidalSwaleSection(qHand, 1, 3, 0.03, 2);
      check('[70] trapezoidal Manning solves hand-math normal depth (d = 1 ft)',
        Math.abs(sec.depthFt - 1) < 0.01, `${sec.depthFt.toFixed(4)} ft`);
      check('[70] trapezoidal section: top width = b + 2 z d, velocity = Q/A',
        Math.abs(sec.topWidthFt - 8) < 0.1 && Math.abs(sec.velocityFps - qHand / A) < 0.05);
      check('[70] channelSectionFor honors the shape switch',
        ((): boolean => {
          const base = D.sanitizeDrainageInputs({});
          const tri = D.channelSectionFor(base, 10);
          const trap = D.channelSectionFor({ ...base, channelShape: 'trapezoidal' as const }, 10);
          return trap.depthFt < tri.depthFt && trap.depthFt > 0;
        })());
    }

    // ---- Riprap Isbash ladder --------------------------------------------
    {
      const slow = D.riprapFor(2, 0.5, 4);
      const fast = D.riprapFor(12, 1.5, 8);
      check('[70] riprap: D50 on the DOT ladder and monotone with velocity',
        [6, 9, 12, 18, 24].includes(slow.d50In) && [6, 9, 12, 18, 24].includes(fast.d50In) &&
        fast.d50In > slow.d50In);
      check('[70] riprap: Isbash hand math (V=12 fps → raw D50 ≈ 27.5 in → 24 in max class)',
        ((): boolean => {
          const raw = (144 / (2 * 32.2 * 0.86 * 0.86 * 1.65)) * 1.25 * 12;
          return Math.abs(raw - 27.5) < 0.5 && fast.d50In === 24;
        })());
      check('[70] riprap: apron L ≥ 10 ft, thickness = max(2·D50, 12 in)',
        slow.apronLengthFt >= 10 && slow.thicknessIn >= 12 &&
        fast.thicknessIn === Math.max(12, 2 * fast.d50In));
    }

    // ---- Culvert inlet control -------------------------------------------
    {
      const small = D.culvertInletControl(3, 0.01);
      const big = D.culvertInletControl(60, 0.01);
      check('[70] culvert: diameter on the CMP ladder, monotone with Q, HW/D ≤ 1.5',
        small.diaIn >= 18 && big.diaIn > small.diaIn && big.diaIn <= 72 &&
        small.hwOverD <= 1.5 && big.hwOverD <= 1.5);
      check('[70] culvert: monotone HW/D in Q at a fixed diameter',
        ((): boolean => {
          for (let q = 5; q <= 50; q += 5) {
            const a = D.culvertInletControl(q, 0.01);
            const b = D.culvertInletControl(q + 5, 0.01);
            if (b.diaIn < a.diaIn) return false;
          }
          return true;
        })());
    }

    // ---- Model-level fixture: east-falling ramp (same style as [64]) -----
    const origin70 = { lat: 29.35, lon: -99.15 };
    const ftPerLon70 = 364000 * Math.cos((origin70.lat * Math.PI) / 180);
    const rect70 = { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };
    const makeGrid70 = (n: number, z: (x: number, y: number) => number) => {
      const bounds = {
        west: origin70.lon + rect70.minX / ftPerLon70,
        east: origin70.lon + rect70.maxX / ftPerLon70,
        south: origin70.lat + rect70.minY / 364000,
        north: origin70.lat + rect70.maxY / 364000,
      };
      const cellX = (rect70.maxX - rect70.minX) / n, cellY = (rect70.maxY - rect70.minY) / n;
      const valuesFt: number[] = [];
      for (let r = 0; r < n; r++) {
        const y = rect70.maxY - (r + 0.5) * cellY;
        for (let c = 0; c < n; c++) valuesFt.push(z(rect70.minX + (c + 0.5) * cellX, y));
      }
      return { grid: { width: n, height: n, bounds, valuesFt, source: 'synthetic', resolutionM: 10, noDataCount: 0 }, rect: rect70 };
    };
    const fence70 = [
      { x: 100, y: 100 }, { x: 900, y: 100 }, { x: 900, y: 900 }, { x: 100, y: 900 },
    ];
    const ramp70 = makeGrid70(64, x => 250 - 0.01 * x);
    const fg70 = G.buildFgSurface(ramp70.grid, ramp70.rect, fence70,
      { padSlopePct: 1, slopeDirDeg: 90, shrinkPct: 0, topsoilStripIn: 0 })!;
    const surfaces70: import('../client/src/lib/nextera/drainage').DrainageSurfaces = {
      pads: [{ x: 400, y: 500, length: 200, width: 100, rotation: 0 }],
      roads: [{ x: 500, y: 200, length: 1100, width: 30, rotation: 0 }],
      gravel: [{ outer: fence70, holes: [] }],
      parcel: [{ x: 0, y: 0 }, { x: 1000, y: 0 }, { x: 1000, y: 1000 }, { x: 0, y: 1000 }],
    };

    // ---- Legacy identity: features off + opts supplied = byte-identical --
    const base70 = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70, {})!;
    const withOpts = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70, {}, undefined,
      { idf: idf70, surfaces: null })!;
    check('[70] features off: supplying an IDF alone leaves the model byte-identical',
      JSON.stringify(withOpts) === JSON.stringify(base70));
    check('[70] legacy model has no A+ keys (subcatchments/detention/culverts/idfSource absent)',
      !('detention' in base70) && !('culverts' in base70) && !('idfSource' in base70) &&
      base70.discharges.every(d => !('compositeC' in d) && !('intensityInHr' in d) && !('riprap' in d) || true) &&
      base70.discharges.every(d => d.compositeC === undefined && d.intensityInHr === undefined));

    // ---- NOAA IDF active: intensity at Tc replaces the manual value ------
    const mNoaa = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70,
      { useNoaaIdf: true, stormAriYears: 25 }, undefined, { idf: idf70 })!;
    check('[70] IDF on: every discharge carries intensityInHr = idfIntensityAt(Tc, ARI)',
      mNoaa.discharges.length > 0 && mNoaa.discharges.every(d =>
        d.intensityInHr !== undefined &&
        Math.abs(d.intensityInHr - R.idfIntensityAt(idf70, 25, d.tcMin)) < 1e-9));
    check('[70] IDF on: Q = C · i(Tc) · A per discharge and provenance recorded',
      mNoaa.idfSource === idf70.source &&
      mNoaa.discharges.every(d =>
        Math.abs(d.qCfs - mNoaa.inputs.runoffC * (d.intensityInHr ?? 0) * d.areaAcres) < 1e-6));
    check('[70] IDF on without a fetched table: falls back to manual intensity + warning',
      ((): boolean => {
        const m = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70,
          { useNoaaIdf: true }, undefined, { idf: null })!;
        return m.discharges.every(d => d.intensityInHr === undefined) &&
          m.warnings.some(w => /NOAA|IDF/i.test(w));
      })());

    // ---- Weighted C from layout surfaces ---------------------------------
    const mWc = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70,
      { weightedC: true }, undefined, { surfaces: surfaces70 })!;
    check('[70] weighted C: every discharge carries a compositeC inside [cUndisturbed, cPad]',
      mWc.discharges.length > 0 && mWc.discharges.every(d =>
        d.compositeC !== undefined &&
        d.compositeC >= mWc.inputs.cUndisturbed - 1e-9 && d.compositeC <= mWc.inputs.cPad + 1e-9));
    check('[70] weighted C: Q uses the composite C (not the scalar runoffC)',
      mWc.discharges.every(d =>
        Math.abs(d.qCfs - (d.compositeC ?? 0) * mWc.inputs.rainfallIntensityInHr * d.areaAcres) < 1e-6));
    check('[70] weighted C: all-gravel yard at cGravel=cRoad=cPad=cUndisturbed=0.5 gives C=0.5',
      ((): boolean => {
        const m = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70,
          { weightedC: true, cPad: 0.5, cRoad: 0.5, cGravel: 0.5, cUndisturbed: 0.5 },
          undefined, { surfaces: surfaces70 })!;
        return m.discharges.every(d => Math.abs((d.compositeC ?? 0) - 0.5) < 1e-9);
      })());
    check('[70] subcatchments: loops close, cover the lattice area, one set per discharge',
      ((): boolean => {
        if (!mWc.subcatchments || mWc.subcatchments.length === 0) return false;
        const total = mWc.subcatchments.reduce((s, sc) => s + sc.areaSqFt, 0);
        const latticeAcres = mWc.discharges.reduce((s, d) => s + d.areaAcres, 0);
        return Math.abs(total / 43560 - latticeAcres) < 0.05 * latticeAcres &&
          mWc.subcatchments.every(sc =>
            sc.loops.every(lp => lp.length >= 4) && sc.dischargeIdx < mWc.discharges.length);
      })());

    // ---- Riprap attaches at discharges with flow --------------------------
    check('[70] riprap attaches to every positive-Q discharge, sized to its swale velocity',
      ((): boolean => {
        const m = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70, {}, undefined,
          { surfaces: surfaces70 })!;
        return m.discharges.filter(d => d.qCfs > 0).every(d => d.riprap !== undefined &&
          [6, 9, 12, 18, 24].includes(d.riprap.d50In));
      })());

    // ---- Culverts at swale × road crossings --------------------------------
    check('[70] culverts appear where the perimeter swale crosses the access road',
      ((): boolean => {
        const m = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70, {}, undefined,
          { surfaces: surfaces70 })!;
        if (!m.culverts || m.culverts.length === 0) return false;
        return m.culverts.every(c =>
          c.diaIn >= 18 && c.diaIn <= 72 && c.hwOverD <= 1.5 + 1e-9 &&
          c.lengthFt >= 30 && c.dischargeIdx < m.discharges.length);
      })());

    // ---- Detention screening ----------------------------------------------
    const mDet = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70,
      { detention: true, preDevC: 0.3, useNoaaIdf: true, stormAriYears: 25 },
      undefined, { idf: idf70, surfaces: surfaces70 })!;
    check('[70] detention: modified-rational storage with IDF, release < developed peak',
      mDet.detention !== undefined &&
      mDet.detention.prePeakCfs < mDet.detention.postPeakCfs &&
      mDet.detention.requiredCf > 0 && /modified rational/i.test(mDet.detention.method));
    check('[70] detention: suggested basin provides at least the required volume when placed',
      !mDet.detention!.placed || mDet.detention!.providedCf >= mDet.detention!.requiredCf * 0.999);
    check('[70] detention without an IDF: triangle-approximation storage still computed',
      ((): boolean => {
        const m = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70,
          { detention: true }, undefined, { surfaces: surfaces70 })!;
        return m.detention !== undefined && m.detention.requiredCf > 0 &&
          !/modified rational/i.test(m.detention.method);
      })());

    // ---- Freeboard warning path -------------------------------------------
    check('[70] freeboard: deep-flow swale with max freeboard raises a warning',
      ((): boolean => {
        const m = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70,
          { rainfallIntensityInHr: 12, freeboardFt: 2, swaleGradePct: 0.2 })!;
        const deep = m.swales.some(s => s.section.depthFt + 2 > 3);
        return !deep || m.warnings.some(w => /freeboard/i.test(w));
      })());

    // ---- Determinism of the full A+ model ----------------------------------
    const full70a = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70,
      { useNoaaIdf: true, weightedC: true, detention: true, channelShape: 'trapezoidal' as const },
      undefined, { idf: idf70, surfaces: surfaces70 })!;
    const full70b = D.buildDrainageModel(ramp70.grid, ramp70.rect, fg70,
      { useNoaaIdf: true, weightedC: true, detention: true, channelShape: 'trapezoidal' as const },
      undefined, { idf: idf70, surfaces: surfaces70 })!;
    check('[70] full A+ model is deterministic (byte-identical JSON on re-run)',
      JSON.stringify(full70a) === JSON.stringify(full70b));

    // ---- drainageSurfacesFromDesign maps the layout 1:1 ---------------------
    check('[70] drainageSurfacesFromDesign: pads/roads/gravel/parcel map from the design',
      ((): boolean => {
        const s = D.drainageSurfacesFromDesign(design as any);
        return s.pads.length === design.equipment.length &&
          s.roads.length === design.roads.length + design.aisles.length &&
          (design.surfacing ? (s.gravel?.length ?? 0) === design.surfacing.regions.length : s.gravel === null) &&
          Array.isArray(s.parcel) && s.parcel!.length === design.boundary.polygon.length;
      })());

    // ---- DR-1 sheet: DXF/PDF twin -------------------------------------------
    {
      const DS = await import('../client/src/lib/nextera/drainageSheet');
      const tb70 = { projectName: 'HONDO BESS', location: 'Hondo, TX', drafter: 'QA', revision: 'A', date: '01/01/2026' } as any;
      const P = await import('../client/src/lib/nextera/pdfPlot');
      const dxf70 = DS.buildDrainageSheetDxfString(design, 'Hondo_Test', fg70, full70a, config, tb70);
      check('[70] DR-1 DXF ends with EOF and carries no NaN coordinates',
        dxf70.trimEnd().endsWith('EOF') && !dxf70.includes('NaN'));
      check('[70] DR-1 DXF declares the DR- layers and the sheet title',
        dxf70.includes('DR - SUBCATCHMENT') && dxf70.includes('DRAINAGE AREA MAP'));
      check('[70] DR-1 DXF carries hydrology / riprap / culvert / detention schedules',
        dxf70.includes('RATIONAL METHOD') &&
        (full70a.culverts?.length ? dxf70.includes('CULVERT') : true) &&
        (full70a.detention ? dxf70.includes('DETENTION') : true));
      check('[70] DR-1 DXF is byte-deterministic',
        DS.buildDrainageSheetDxfString(design, 'Hondo_Test', fg70, full70a, config, tb70) === dxf70);
      const pdf70 = P.buildDrainageSheetPdfString(
        { design, projectName: 'Hondo_Test', config, meta: tb70 }, fg70, full70a);
      const normalizePdf = (s: string) => s
        .replace(/\/CreationDate \([^)]*\)/g, '/CreationDate (X)')
        .replace(/\/ID \[[^\]]*\]/g, '/ID [X]');
      check('[70] DR-1 PDF twin renders and is byte-deterministic (normalized)',
        pdf70.startsWith('%PDF') &&
        normalizePdf(P.buildDrainageSheetPdfString(
          { design, projectName: 'Hondo_Test', config, meta: tb70 }, fg70, full70a)) === normalizePdf(pdf70));
    }

    // ---- Additive guards: default exports untouched ---------------------------
    const dxfSrc70 = readFileSync('client/src/lib/nextera/dxfExport.ts', 'utf8');
    const sheetsSrc70 = readFileSync('client/src/lib/nextera/dxfSheets.ts', 'utf8');
    check('[70] dxfExport still never imports drainage/rainfall',
      !dxfSrc70.includes('drainage') && !dxfSrc70.includes('rainfall'));
    check('[70] drawing-package registry still never imports drainage',
      !sheetsSrc70.includes('drainage'));
    check('[70] default design DXF is byte-identical with the A+ package present',
      buildDesignDxfString(design, 'Hondo_Test') === dxf);

    // ---- Store + UI wiring source scans ----------------------------------------
    {
      const storeSrc70 = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
      check('[70] store: drainage IDF persists per-browser through the Atlas 14 sanitizer',
        storeSrc70.includes("'nextera-drainage-idf'") && storeSrc70.includes('sanitizeAtlas14Idf'));
      check('[70] store: project JSON export/import never mentions the drainage IDF',
        ((): boolean => {
          const exp = storeSrc70.indexOf('exportProjectJson');
          const seg = storeSrc70.slice(exp, exp + 4000);
          return exp > 0 && !seg.includes('drainageIdf');
        })());
      const panelSrc70 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
      check('[70] panel: model builds with the IDF + layout surfaces (both call sites)',
        /idf: drainageIdf,\s*\n\s*surfaces: drainageSurfacesFromDesign\(design\)/.test(panelSrc70) &&
        /idf: drainageIdf,\s*\n\s*surfaces: drainageSurfacesFromDesign\(design\)/.test(
          readFileSync('client/src/components/DesignScene.tsx', 'utf8')));
      check('[70] panel: NOAA fetch routes through fetchNoaaIdf into setDrainageIdf',
        panelSrc70.includes('fetchNoaaIdf(lat, lon)') && panelSrc70.includes('setDrainageIdf(idf)'));
      check('[70] panel: every A+ input has a control (ARI, shape, freeboard, C set, detention)',
        /setDrainageInputs\(\{ stormAriYears/.test(panelSrc70) &&
        /setDrainageInputs\(\{ channelShape/.test(panelSrc70) &&
        /<DrainageNumField\s+field="bottomWidthFt"/.test(panelSrc70) &&
        /<DrainageNumField\s+field="freeboardFt"/.test(panelSrc70) &&
        /<DrainageNumField\s+field="preDevC"/.test(panelSrc70) &&
        /<DrainageNumField\s+field="basinDepthFt"/.test(panelSrc70) &&
        panelSrc70.includes('weightedC: e.target.checked') &&
        panelSrc70.includes('detention: e.target.checked') &&
        panelSrc70.includes('useNoaaIdf: e.target.checked'));
      check('[70] panel: DR-1 DXF/PDF export handlers wired to the sheet builders',
        panelSrc70.includes('buildDrainageSheetDxfString(design, exportName, fgSurface, drainageModel') &&
        panelSrc70.includes('buildDrainageSheetPdf(') &&
        /_Drainage_Map_\$\{new Date\(\)\.toISOString\(\)\.slice\(0, 10\)\}\.dxf/.test(panelSrc70));
    }

    // ---- Server proxy source scan -----------------------------------------------
    {
      const routesSrc70 = readFileSync('server/routes.ts', 'utf8');
      check('[70] server: /api/rainfall proxy validates lat/lon and caches responses',
        routesSrc70.includes("'/api/rainfall'") &&
        /queryNumber\(req\.query\.lat,\s*'lat',\s*15,\s*72\)/.test(routesSrc70) &&
        /queryNumber\(req\.query\.lon,\s*'lon',\s*-180,\s*-60\)/.test(routesSrc70) &&
        /const NOAA_PFDS = 'https:\/\/hdsc\.nws\.noaa\.gov\/cgi-bin\/new\/fe_text_mean\.csv';/.test(routesSrc70) &&
        /new BoundedTtlCache<unknown>\(60,\s*12 \* 1024 \* 1024,\s*60 \* 60_000\)/.test(routesSrc70) &&
        /fetchFixed\(url,\s*\{\s*timeoutMs: 25_000,\s*maxBytes: 2 \* 1024 \* 1024,\s*redirect: 'error',\s*\}\)/.test(routesSrc70));
    }
  }

  // ---------------------------------------------------------------
  // [71] Design-grade drainage: TR-55 Tc, NRCS/SCS hydrographs, routed
  //      detention (level pool), HDS-5 outlet control, DR-2 sheet.
  {
    console.log('\n[71] Design-grade drainage (TR-55, SCS hydrographs, routing, outlet control, DR-2)');
    const G = await import('../client/src/lib/nextera/gradingSurface');
    const D = await import('../client/src/lib/nextera/drainage');
    const H = await import('../client/src/lib/nextera/hydrology');

    // ---- TR-55 sheet-flow hand math ---------------------------------------
    // Tt = 0.007 (nL)^0.8 / (P2^0.5 s^0.4): n=0.15, L=100, P2=3.6, s=0.02.
    {
      const hand = 0.007 * Math.pow(0.15 * 100, 0.8) / (Math.sqrt(3.6) * Math.pow(0.02, 0.4));
      const tc = H.tr55TimeOfConcentration({
        sheetLenFt: 100, sheetSlope: 0.02, sheetN: 0.15, p2In: 3.6,
        shallowLenFt: 0, shallowSlope: 0.02, shallowPaved: false,
        channelLenFt: 0, channelVelFps: 0,
      });
      check('[71] TR-55 sheet flow matches the Chapter 3 hand math',
        Math.abs(tc.sheetMin - hand * 60) < 0.05, `${tc.sheetMin.toFixed(2)} min vs ${(hand * 60).toFixed(2)}`);
      check('[71] TR-55 shallow concentrated: V = 16.1345 sqrt(s) unpaved',
        ((): boolean => {
          const t = H.tr55TimeOfConcentration({
            sheetLenFt: 0, sheetSlope: 0.01, sheetN: 0.15, p2In: 3.6,
            shallowLenFt: 968.07, shallowSlope: 0.01, shallowPaved: false,
            channelLenFt: 0, channelVelFps: 0,
          });
          // V = 16.1345 * 0.1 = 1.61345 fps → 968.07 ft / 1.61345 / 60 = 10 min
          return Math.abs(t.shallowMin - 10) < 0.05;
        })());
      check('[71] TR-55 caps sheet length at 100 ft and floors total Tc at 5 min',
        ((): boolean => {
          const capped = H.tr55TimeOfConcentration({
            sheetLenFt: 500, sheetSlope: 0.02, sheetN: 0.15, p2In: 3.6,
            shallowLenFt: 0, shallowSlope: 0.02, shallowPaved: false,
            channelLenFt: 0, channelVelFps: 0,
          });
          const tiny = H.tr55TimeOfConcentration({
            sheetLenFt: 5, sheetSlope: 0.1, sheetN: 0.011, p2In: 6,
            shallowLenFt: 0, shallowSlope: 0.1, shallowPaved: false,
            channelLenFt: 0, channelVelFps: 0,
          });
          return capped.sheetLenFt === 100 && Math.abs(capped.sheetMin - tc.sheetMin) < 1e-9 &&
            tiny.totalMin === 5;
        })());
    }

    // ---- SCS curve-number runoff (NEH-4 hand math) --------------------------
    // CN=75 → S=3.333, Ia=0.667; P=6 → Q=(5.333)^2/(6+2.667)=3.281 in.
    check('[71] SCS runoff: CN 75 / P 6 in gives Q = 3.28 in; P ≤ Ia gives 0',
      Math.abs(H.scsRunoffIn(6, 75) - 3.281) < 0.005 &&
      H.scsRunoffIn(0.5, 75) === 0);
    check('[71] SCS cumulative fraction: 0 at 0 hr, 1 at 24 hr, Type II jumps at hour 12',
      H.scsCumulativeFraction('II', 0) === 0 && H.scsCumulativeFraction('II', 24) === 1 &&
      H.scsCumulativeFraction('II', 12) - H.scsCumulativeFraction('II', 11) > 0.3 &&
      H.scsCumulativeFraction('III', 12) === 0.5);

    // ---- SCS storm hydrograph: mass balance + peak sanity -------------------
    {
      const hyd = H.scsStormHydrograph(
        { areaAcres: 40, cn: 85, rain24In: 6, stormType: 'II', tcMin: 20 }, 6);
      const runoffCf = H.scsRunoffIn(6, 85) / 12 * 40 * 43560;
      check('[71] SCS hydrograph conserves the runoff volume (±2%)',
        Math.abs(hyd.volumeCf - runoffCf) < 0.02 * runoffCf,
        `${Math.round(hyd.volumeCf)} vs ${Math.round(runoffCf)} CF`);
      check('[71] SCS hydrograph peaks near hour 12 for a Type II storm',
        hyd.peakAtMin > 11.5 * 60 && hyd.peakAtMin < 14 * 60 && hyd.peakCfs > 0);
      check('[71] SCS hydrograph: longer Tc lowers and delays the peak',
        ((): boolean => {
          const slow = H.scsStormHydrograph(
            { areaAcres: 40, cn: 85, rain24In: 6, stormType: 'II', tcMin: 120 }, 6);
          return slow.peakCfs < hyd.peakCfs && slow.peakAtMin >= hyd.peakAtMin;
        })());
      check('[71] SCS hydrograph is deterministic',
        JSON.stringify(H.scsStormHydrograph(
          { areaAcres: 40, cn: 85, rain24In: 6, stormType: 'II', tcMin: 20 }, 6)) === JSON.stringify(hyd));
    }

    // ---- Basin storage + outlet rating hand math ---------------------------
    {
      // bw=50, z=3, h=2: S = 2500·2 + 2·50·3·4 + (4/3)·9·8 = 5000+1200+96 = 6296.
      check('[71] prismoid storage matches the exact integral hand math',
        Math.abs(H.basinStorageCf({ bottomWFt: 50, sideSlopeH: 3, depthFt: 4 }, 2) - 6296) < 0.5);
      // 12" orifice, Cd 0.6, stage 4 ft: head = 3.5, Q = 0.6·(π/4)·sqrt(2·32.2·3.5).
      const qHand = 0.6 * (Math.PI / 4) * Math.sqrt(2 * 32.2 * 3.5);
      const outlet = { orificeDiaIn: 12, orificeCd: 0.6, weirCrestFt: 10, weirLengthFt: 10, weirCw: 3 };
      check('[71] orifice rating matches the hand math above full submergence',
        Math.abs(H.outletDischargeCfs(outlet, 4) - qHand) < 1e-6);
      check('[71] orifice rating is continuous and monotone through the submergence transition',
        ((): boolean => {
          const o30 = { orificeDiaIn: 30, orificeCd: 0.6, weirCrestFt: 99, weirLengthFt: 10, weirCw: 3 };
          let prev = 0;
          for (let h = 0.05; h <= 6; h += 0.05) {
            const q = H.outletDischargeCfs(o30, h);
            if (q < prev - 1e-9) return false;
            prev = q;
          }
          const d = 2.5;
          return Math.abs(H.outletDischargeCfs(o30, d - 1e-6) - H.outletDischargeCfs(o30, d + 1e-6)) < 1e-3;
        })());
      check('[71] weir engages above the crest: Q += Cw L Hw^1.5',
        ((): boolean => {
          const o2 = { ...outlet, weirCrestFt: 3 };
          const extra = H.outletDischargeCfs(o2, 4) - H.outletDischargeCfs(outlet, 4);
          return Math.abs(extra - 3 * 10 * 1) < 1e-6; // Hw = 1 ft
        })());
    }

    // ---- Level-pool routing: physics invariants ------------------------------
    {
      const inflow = H.scsStormHydrograph(
        { areaAcres: 40, cn: 85, rain24In: 6, stormType: 'II', tcMin: 20 }, 6);
      const geo = { bottomWFt: 350, sideSlopeH: 3, depthFt: 8 };
      const out = { orificeDiaIn: 12, orificeCd: 0.6, weirCrestFt: 6, weirLengthFt: 10, weirCw: 3 };
      const r = H.routeLevelPool(inflow, geo, out);
      check('[71] routing attenuates: peak out < peak in, max stage within the basin',
        r.peakOutflowCfs < r.peakInflowCfs && r.peakOutflowCfs > 0 &&
        r.maxStageFt > 0 && r.maxStageFt <= geo.depthFt && !r.overtopped);
      check('[71] routing: peak outflow never exceeds the rating at max stage',
        r.peakOutflowCfs <= H.outletDischargeCfs(out, r.maxStageFt) * (1 + 1e-6));
      check('[71] routing: max storage equals the prismoid storage at max stage',
        Math.abs(r.maxStorageCf - H.basinStorageCf(geo, r.maxStageFt)) < 1);
      check('[71] routing mass balance: outflow volume ≈ inflow volume (±3%)',
        ((): boolean => {
          const dtSec = inflow.dtMin * 60;
          let outV = 0;
          for (const q of r.outflow) outV += q * dtSec;
          const residual = H.basinStorageCf(geo, r.stage[r.stage.length - 1]);
          return Math.abs(outV + residual - inflow.volumeCf) < 0.03 * inflow.volumeCf;
        })());
      check('[71] routing is deterministic', JSON.stringify(H.routeLevelPool(inflow, geo, out)) === JSON.stringify(r));
      // Tiny pond with a huge inflow must overtop.
      check('[71] routing flags overtopping on an undersized pond',
        H.routeLevelPool(inflow, { bottomWFt: 10, sideSlopeH: 3, depthFt: 2 },
          { ...out, orificeDiaIn: 4, weirCrestFt: 1.5 }).overtopped);
      // Outlet auto-sizing meets the allowable release.
      const est = H.estimateRequiredStorageCf(inflow, inflow.peakCfs * 0.3);
      check('[71] storage estimate positive and below the total runoff volume',
        est > 0 && est < inflow.volumeCf);
      const des = H.designDetentionOutlet(inflow, inflow.peakCfs * 0.3, geo, 1);
      check('[71] outlet auto-sizing: routed peak ≤ allowable, crest reserves freeboard, orifice on the ladder',
        des.meetsRelease && des.routing.peakOutflowCfs <= inflow.peakCfs * 0.3 * (1 + 1e-6) &&
        H.ORIFICE_DIA_LADDER_IN.includes(des.outlet.orificeDiaIn) &&
        des.outlet.weirCrestFt <= des.geo.depthFt - 1 + 1e-9);
    }

    // ---- HDS-5 outlet control ------------------------------------------------
    {
      const dc = H.circularCriticalDepthFt(10, 2);
      // Verify Q^2 T = g A^3 at the returned depth (section factor balance).
      const r0 = 1, th = 2 * Math.acos(1 - dc / r0);
      const a = (r0 * r0 / 2) * (th - Math.sin(th));
      const t = 2 * Math.sqrt(dc * (2 - dc));
      check('[71] circular critical depth satisfies Q²T = gA³',
        dc > 0 && dc < 2 && Math.abs(10 * 10 * t - 32.2 * a * a * a) < 0.5);
      const oc = H.culvertOutletControl({ qCfs: 10, diaIn: 24, lengthFt: 40, slopeFtFt: 0.005, tailwaterFt: 0 });
      // Hand math: A=π, V=10/π, hv=V²/2g; H=(1+0.5+29·0.012²·40/0.5^{4/3})·hv.
      const v = 10 / Math.PI;
      const hv = v * v / (2 * 32.2);
      const lossHand = (1 + 0.5 + (29 * 0.012 * 0.012 * 40) / Math.pow(0.5, 4 / 3)) * hv;
      check('[71] outlet-control losses match the HDS-5 full-flow hand math',
        Math.abs(oc.lossesFt - lossHand) < 1e-6 &&
        Math.abs(oc.hwFt - (Math.max(0, (oc.criticalDepthFt + 2) / 2) + lossHand - 0.005 * 40)) < 1e-6);
      check('[71] outlet control: higher tailwater raises the headwater',
        H.culvertOutletControl({ qCfs: 10, diaIn: 24, lengthFt: 40, slopeFtFt: 0.005, tailwaterFt: 3 }).hwFt > oc.hwFt);
    }

    // ---- Model-level fixture (same ramp as [70]) ------------------------------
    const origin71 = { lat: 29.35, lon: -99.15 };
    const ftPerLon71 = 364000 * Math.cos((origin71.lat * Math.PI) / 180);
    const rect71 = { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };
    const bounds71 = {
      west: origin71.lon + rect71.minX / ftPerLon71,
      east: origin71.lon + rect71.maxX / ftPerLon71,
      south: origin71.lat + rect71.minY / 364000,
      north: origin71.lat + rect71.maxY / 364000,
    };
    const n71 = 64;
    const valuesFt71: number[] = [];
    for (let r = 0; r < n71; r++) {
      for (let c = 0; c < n71; c++) valuesFt71.push(250 - 0.01 * (rect71.minX + (c + 0.5) * ((rect71.maxX - rect71.minX) / n71)));
    }
    const grid71 = { width: n71, height: n71, bounds: bounds71, valuesFt: valuesFt71, source: 'synthetic', resolutionM: 10, noDataCount: 0 };
    const fence71 = [{ x: 100, y: 100 }, { x: 900, y: 100 }, { x: 900, y: 900 }, { x: 100, y: 900 }];
    const fg71 = G.buildFgSurface(grid71, rect71, fence71,
      { padSlopePct: 1, slopeDirDeg: 90, shrinkPct: 0, topsoilStripIn: 0 })!;
    const surfaces71: import('../client/src/lib/nextera/drainage').DrainageSurfaces = {
      pads: [{ x: 400, y: 500, length: 200, width: 100, rotation: 0 }],
      roads: [{ x: 500, y: 200, length: 1100, width: 30, rotation: 0 }],
      gravel: [{ outer: fence71, holes: [] }],
      parcel: [{ x: 0, y: 0 }, { x: 1000, y: 0 }, { x: 1000, y: 1000 }, { x: 0, y: 1000 }],
    };

    // ---- Additive identity: all new inputs default off ------------------------
    const base71 = D.buildDrainageModel(grid71, rect71, fg71, {})!;
    check('[71] new inputs present in the sanitizer with design-grade features OFF by default',
      ((): boolean => {
        const s = D.sanitizeDrainageInputs({});
        return s.tr55Tc === false && s.scsMode === false && s.routedDetention === false &&
          s.culvertOutlet === false && s.sheetFlowN === 0.15 && s.sheetFlowLenFt === 100 &&
          s.p2In === 3.5 && s.tcOverrideMin === 0 && s.curveNumber === 85 && s.preDevCn === 70 &&
          s.stormType === 'II' && s.rain24In === 6 && s.tailwaterFt === 0;
      })());
    check('[71] features off: model JSON has no tc55/scs/routing/outlet keys',
      !JSON.stringify(base71).includes('"tc55"') && !JSON.stringify(base71).includes('"scs"') &&
      !JSON.stringify(base71).includes('"routing"') && !JSON.stringify(base71).includes('"outlet"'));
    check('[71] sanitizer clamps the new inputs to their ranges',
      ((): boolean => {
        const s = D.sanitizeDrainageInputs({
          sheetFlowN: 99, sheetFlowLenFt: -5, p2In: 100, tcOverrideMin: 1e6,
          curveNumber: 5, preDevCn: 200, rain24In: -1, tailwaterFt: 99, stormType: 'X',
        });
        return s.sheetFlowN <= 0.8 && s.sheetFlowLenFt >= 0 && s.p2In <= 10 &&
          s.tcOverrideMin <= 180 && s.curveNumber >= 40 && s.preDevCn <= 95 &&
          s.rain24In >= 0.5 && s.tailwaterFt <= 8 && s.stormType === 'II';
      })());

    // ---- TR-55 in the model -----------------------------------------------------
    const m55 = D.buildDrainageModel(grid71, rect71, fg71,
      { tr55Tc: true }, undefined, { surfaces: surfaces71 })!;
    check('[71] TR-55 on: every discharge carries the segment breakdown that sums to Tc',
      m55.discharges.every(d => d.tc55 !== undefined &&
        Math.abs(Math.max(5, d.tc55.sheetMin + d.tc55.shallowMin + d.tc55.channelMin) - d.tcMin) < 1e-6));
    check('[71] TR-55 on: swale sections re-sized at the recomputed Q',
      m55.swales.every(s => Math.abs(s.section.capacityCfs - m55.discharges[s.dischargeIdx].qCfs) < 1e-6));
    check('[71] Tc override pins every discharge Tc and flags it',
      ((): boolean => {
        const m = D.buildDrainageModel(grid71, rect71, fg71,
          { tr55Tc: true, tcOverrideMin: 42 }, undefined, { surfaces: surfaces71 })!;
        return m.discharges.every(d => d.tcMin === 42 && d.tc55?.overridden === true);
      })());
    check('[71] TR-55 model is deterministic',
      JSON.stringify(D.buildDrainageModel(grid71, rect71, fg71,
        { tr55Tc: true }, undefined, { surfaces: surfaces71 })) === JSON.stringify(m55));

    // ---- SCS + routing in the model ----------------------------------------------
    const mScs = D.buildDrainageModel(grid71, rect71, fg71,
      { scsMode: true, routedDetention: true, curveNumber: 85, preDevCn: 70, rain24In: 6 },
      undefined, { surfaces: surfaces71 })!;
    check('[71] SCS on: model.scs present with per-DP hydrograph summaries',
      mScs.scs !== undefined && mScs.scs.sitePeakCfs > 0 &&
      mScs.scs.prePeakCfs < mScs.scs.sitePeakCfs &&
      mScs.discharges.every(d => d.scs !== undefined && d.scs.peakCfs > 0));
    check('[71] SCS site hydrograph peak ≥ any single DP peak and ≤ their sum',
      ((): boolean => {
        const peaks = mScs.discharges.map(d => d.scs!.peakCfs);
        const sum = peaks.reduce((s, v) => s + v, 0);
        return mScs.scs!.sitePeakCfs >= Math.max(...peaks) - 1e-9 &&
          mScs.scs!.sitePeakCfs <= sum + 1e-9;
      })());
    check('[71] routed detention: routed peak ≤ allowable (pre-dev peak), stage-storage table monotone',
      mScs.routing !== undefined && mScs.routing.meetsRelease &&
      mScs.routing.peakOutflowCfs <= mScs.routing.allowableCfs * (1 + 1e-6) &&
      mScs.routing.stageStorage.length === 9 &&
      mScs.routing.stageStorage.every((row, i, a) => i === 0 ||
        (row.storageCf > a[i - 1].storageCf && row.outflowCfs >= a[i - 1].outflowCfs)));
    check('[71] routed detention basin holds the routed storage at max stage',
      ((): boolean => {
        const r = mScs.routing!;
        const geo = { bottomWFt: r.bottomWFt, sideSlopeH: r.sideSlopeH, depthFt: r.depthFt };
        return Math.abs(H.basinStorageCf(geo, r.maxStageFt) - r.maxStorageCf) < 1;
      })());
    check('[71] SCS+routing model is deterministic',
      JSON.stringify(D.buildDrainageModel(grid71, rect71, fg71,
        { scsMode: true, routedDetention: true, curveNumber: 85, preDevCn: 70, rain24In: 6 },
        undefined, { surfaces: surfaces71 })) === JSON.stringify(mScs));

    // ---- Culvert outlet control in the model ---------------------------------------
    const mCul = D.buildDrainageModel(grid71, rect71, fg71,
      { culvertOutlet: true, tailwaterFt: 2 }, undefined, { surfaces: surfaces71 })!;
    check('[71] culvert outlet check: every culvert carries the inlet-vs-outlet comparison',
      (mCul.culverts?.length ?? 0) > 0 && mCul.culverts!.every(c =>
        c.outlet !== undefined &&
        (c.outlet.controlling === 'outlet') === (c.outlet.hwOutletFt > c.outlet.hwInletFt) &&
        c.outlet.tailwaterFt === 2));
    check('[71] culvert outlet check off: culverts have no outlet key',
      ((): boolean => {
        const m = D.buildDrainageModel(grid71, rect71, fg71, {}, undefined, { surfaces: surfaces71 })!;
        return (m.culverts ?? []).every(c => !('outlet' in c));
      })());

    // ---- DR-2 sheet: DXF/PDF twin -----------------------------------------------
    {
      const full71 = D.buildDrainageModel(grid71, rect71, fg71,
        { tr55Tc: true, scsMode: true, routedDetention: true, culvertOutlet: true, detention: true },
        undefined, { surfaces: surfaces71 })!;
      const DS2 = await import('../client/src/lib/nextera/drainageDetailSheet');
      const P = await import('../client/src/lib/nextera/pdfPlot');
      const tb71 = { projectName: 'HONDO BESS', location: 'Hondo, TX', drafter: 'QA', revision: 'A', date: '01/01/2026' } as any;
      const dxf71 = DS2.buildDrainageDetailSheetDxfString(design, 'Hondo_Test', fg71, full71, config, tb71);
      check('[71] DR-2 DXF ends with EOF, no NaN coordinates',
        dxf71.trimEnd().endsWith('EOF') && !dxf71.includes('NaN'));
      check('[71] DR-2 DXF declares the DR layers, sheet label and title',
        dxf71.includes('DR - DETAIL') && dxf71.includes('DR - WATER') &&
        dxf71.includes('SHEET DR-2') && dxf71.includes('DRAINAGE DETAILS & ROUTING'));
      check('[71] DR-2 DXF carries the TR-55 / NRCS / routing / stage-storage / culvert tables',
        dxf71.includes('TR-55 TIME OF CONCENTRATION') &&
        dxf71.includes('NRCS HYDROLOGY') &&
        dxf71.includes('LEVEL-POOL ROUTING') &&
        dxf71.includes('STAGE - STORAGE - DISCHARGE') &&
        dxf71.includes('CULVERTS (INLET VS OUTLET CONTROL)'));
      check('[71] DR-2 DXF draws the three detail panels',
        dxf71.includes('CHANNEL TYPICAL SECTION') &&
        dxf71.includes('POND OUTLET STRUCTURE') &&
        dxf71.includes('CULVERT PROFILE'));
      check('[71] DR-2 DXF draws the routed pond hydrograph chart (inflow/outflow/stage)',
        dxf71.includes('ROUTED POND HYDROGRAPHS') &&
        dxf71.includes('TIME (HR)') && dxf71.includes('Q (CFS)') &&
        dxf71.includes('INFLOW QP=') && dxf71.includes('OUTFLOW QP=') &&
        dxf71.includes('STAGE (MAX'));
      check('[71] routing model carries the hydrograph ordinates for the chart',
        ((): boolean => {
          const r = full71.routing!;
          const hyd = full71.scs!.hydrograph;
          if (!r.outflowCfs.length || !r.stageTraceFt.length) return false;
          if (r.outflowCfs.length !== r.stageTraceFt.length) return false;
          if (r.outflowCfs.length < hyd.ordinatesCfs.length) return false;
          const maxO = Math.max(...r.outflowCfs);
          const maxS = Math.max(...r.stageTraceFt);
          return maxO <= r.peakOutflowCfs + 1e-9 && maxO > 0.5 * r.peakOutflowCfs &&
            maxS <= r.maxStageFt + 1e-9 && maxS > 0.9 * r.maxStageFt;
        })());
      check('[71] DR-2 DXF is byte-deterministic',
        DS2.buildDrainageDetailSheetDxfString(design, 'Hondo_Test', fg71, full71, config, tb71) === dxf71);
      const pdf71 = P.buildDrainageDetailSheetPdfString(
        { design, projectName: 'Hondo_Test', config, meta: tb71 }, fg71, full71);
      const normalizePdf71 = (s: string) => s
        .replace(/\/CreationDate \([^)]*\)/g, '/CreationDate (X)')
        .replace(/\/ID \[[^\]]*\]/g, '/ID [X]');
      check('[71] DR-2 PDF twin renders and is byte-deterministic (normalized)',
        pdf71.startsWith('%PDF') &&
        normalizePdf71(P.buildDrainageDetailSheetPdfString(
          { design, projectName: 'Hondo_Test', config, meta: tb71 }, fg71, full71)) === normalizePdf71(pdf71));
      // Without the design-grade features the sheet still renders (fallback tables).
      const m0 = D.buildDrainageModel(grid71, rect71, fg71, {}, undefined, { surfaces: surfaces71 })!;
      const dxf0 = DS2.buildDrainageDetailSheetDxfString(design, 'Hondo_Test', fg71, m0, config, tb71);
      check('[71] DR-2 renders with features off (Kirpich fallback table, no routing boxes)',
        dxf0.trimEnd().endsWith('EOF') &&
        dxf0.includes('TIME OF CONCENTRATION (KIRPICH SCREENING)') &&
        !dxf0.includes('LEVEL-POOL ROUTING') &&
        !dxf0.includes('ROUTED POND HYDROGRAPHS'));
    }

    // ---- Additive guards -----------------------------------------------------------
    check('[71] dxfExport / drawing-package registry never import the new modules',
      ((): boolean => {
        const a = readFileSync('client/src/lib/nextera/dxfExport.ts', 'utf8');
        const b = readFileSync('client/src/lib/nextera/dxfSheets.ts', 'utf8');
        return !a.includes('hydrology') && !a.includes('drainageDetailSheet') &&
          !b.includes('hydrology') && !b.includes('drainageDetailSheet');
      })());
    check('[71] default design DXF is byte-identical with the design-grade package present',
      buildDesignDxfString(design, 'Hondo_Test') === dxf);

    // ---- Panel wiring source scans ---------------------------------------------------
    {
      const panelSrc71 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
      check('[71] panel: every design-grade input has a control',
        /<DrainageNumField\s+field="sheetFlowN"/.test(panelSrc71) &&
        /<DrainageNumField\s+field="sheetFlowLenFt"/.test(panelSrc71) &&
        /<DrainageNumField\s+field="p2In"/.test(panelSrc71) &&
        /<DrainageNumField\s+field="tcOverrideMin"/.test(panelSrc71) &&
        /<DrainageNumField\s+field="curveNumber"/.test(panelSrc71) &&
        /<DrainageNumField\s+field="preDevCn"/.test(panelSrc71) &&
        /<DrainageNumField\s+field="rain24In"/.test(panelSrc71) &&
        /<DrainageNumField\s+field="tailwaterFt"/.test(panelSrc71) &&
        panelSrc71.includes('tr55Tc: e.target.checked') &&
        panelSrc71.includes('scsMode: e.target.checked') &&
        panelSrc71.includes('routedDetention: e.target.checked') &&
        panelSrc71.includes('culvertOutlet: e.target.checked') &&
        panelSrc71.includes("stormType: e.target.value === 'III' ? 'III' : 'II'"));
      check('[71] panel: DR-2 DXF/PDF export handlers wired to the detail-sheet builders',
        panelSrc71.includes('buildDrainageDetailSheetDxfString(design, exportName, fgSurface, drainageModel') &&
        panelSrc71.includes('buildDrainageDetailSheetPdf(') &&
        /_Drainage_Details_\$\{new Date\(\)\.toISOString\(\)\.slice\(0, 10\)\}\.dxf/.test(panelSrc71));
    }
  }

  // ---------------------------------------------------------------
  // [72] Per-browser preferences must never leak into shared project files.
  // Two layers of defense: a source scan proving projectFromState never
  // mentions any per-browser preference key, and a behavioral deep-compare
  // proving that toggling each preference leaves exportProjectJson unchanged
  // (savedAt excluded) — the section [69]/[70] pattern generalized to the
  // whole class of local-only preferences.
  console.log('\n[72] Per-browser preference leak guard (project JSON purity)');
  {
    // Every state key that is deliberately per-browser only (localStorage,
    // never project JSON). Add new local-only prefs here so the guard covers
    // them automatically.
    const PER_BROWSER_KEYS = [
      'scEnabled', 'scInputs',
      'protectionEnabled', 'protectionInputs',
      'exportContoursDxf', 'exportGroundingDxf', 'exportCutFillShading',
      'showGradingLimits', 'gradingSlopeRatio',
      'showContours', 'contourIntervalFt',
      'labelDistanceScaling',
      'drainageIdf',
    ];

    // ---- Source scan: projectFromState body mentions none of the keys ------
    const storeSrc71 = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
    const pfsStart = storeSrc71.indexOf('const projectFromState');
    const pfsEnd = storeSrc71.indexOf('\n};', pfsStart);
    const pfsBody = storeSrc71.slice(pfsStart, pfsEnd);
    check('[72] source scan found the projectFromState body',
      pfsStart > 0 && pfsEnd > pfsStart);
    for (const key of PER_BROWSER_KEYS) {
      check(`[72] projectFromState never mentions ${key}`, !pfsBody.includes(key));
    }

    // ---- Behavioral: toggling each pref leaves the exported JSON unchanged --
    const { useDesignStore } = await import('../client/src/lib/stores/useDesignStore');
    useDesignStore.getState().clearSite();
    useDesignStore.setState({ boundary: hondo, targetMW: 100, targetMWh: 400 });
    useDesignStore.getState().regenerate();
    check('[72] baseline design regenerated for the leak probe',
      (useDesignStore.getState().design?.blocksPlaced ?? 0) > 0);

    const exportNormalized = (): string => {
      const raw = useDesignStore.getState().exportProjectJson();
      if (!raw) return '';
      const obj = JSON.parse(raw);
      delete obj.savedAt;
      return JSON.stringify(obj);
    };
    const baseline = exportNormalized();
    check('[72] baseline project JSON exported', baseline.length > 0);

    // For each preference, a pair of values guaranteed to differ from each
    // other so the toggle is a real state change regardless of defaults.
    const st0 = useDesignStore.getState() as any;
    const PROBES: Record<string, [unknown, unknown]> = {
      scEnabled: [true, false],
      scInputs: [{ ...st0.scInputs, utilityFaultMVA: st0.scInputs.utilityFaultMVA + 123 }, st0.scInputs],
      protectionEnabled: [true, false],
      protectionInputs: [{ ...st0.protectionInputs, dutyMarginPct: st0.protectionInputs.dutyMarginPct + 5 }, st0.protectionInputs],
      exportContoursDxf: [true, false],
      exportGroundingDxf: [true, false],
      exportCutFillShading: [true, false],
      showGradingLimits: [true, false],
      gradingSlopeRatio: [2, 4],
      showContours: [true, false],
      contourIntervalFt: [5, 0],
      labelDistanceScaling: [true, false],
      drainageIdf: [
        { source: 'test', lat: 29.3, lon: -99.1, durationsMin: [5, 10, 15, 30, 60], ariYears: [2, 5, 10, 25, 50, 100, 200], intensities: [[1, 2, 3, 4, 5, 6, 7]] },
        null,
      ],
    };
    check('[72] probe table covers exactly the guarded key list',
      JSON.stringify(Object.keys(PROBES).sort()) === JSON.stringify([...PER_BROWSER_KEYS].sort()));

    for (const key of PER_BROWSER_KEYS) {
      const [a, b] = PROBES[key];
      const original = (useDesignStore.getState() as any)[key];
      useDesignStore.setState({ [key]: a } as any);
      const withA = exportNormalized();
      useDesignStore.setState({ [key]: b } as any);
      const withB = exportNormalized();
      useDesignStore.setState({ [key]: original } as any);
      check(`[72] toggling ${key} leaves the exported project JSON unchanged`,
        withA === baseline && withB === baseline);
    }
  }

  // ---------------------------------------------------------------
  // [73] Traced-Tc hydrology, flexible detention (aspect + riser), and the
  // protection / interrupting-duty / arc-flash study. All three features
  // are opt-in: defaults must stay byte-identical with the flags off.
  console.log('\n[73] Traced Tc, flexible detention, protection & arc-flash study');
  {
    const G73 = await import('../client/src/lib/nextera/gradingSurface');
    const D73 = await import('../client/src/lib/nextera/drainage');
    const H73 = await import('../client/src/lib/nextera/hydrology');
    const P73 = await import('../client/src/lib/nextera/protection');

    // ---- Synthetic ramp site (the [65] fixture) -------------------------
    const origin73 = { lat: 29.35, lon: -99.15 };
    const ftPerLon73 = 364000 * Math.cos((origin73.lat * Math.PI) / 180);
    const rect73 = { minX: 0, maxX: 1000, minY: 0, maxY: 1000 };
    const n73 = 64;
    const bounds73 = {
      west: origin73.lon + rect73.minX / ftPerLon73,
      east: origin73.lon + rect73.maxX / ftPerLon73,
      south: origin73.lat + rect73.minY / 364000,
      north: origin73.lat + rect73.maxY / 364000,
    };
    const values73: number[] = [];
    for (let r = 0; r < n73; r++) {
      for (let c = 0; c < n73; c++) {
        const x = rect73.minX + (c + 0.5) * ((rect73.maxX - rect73.minX) / n73);
        values73.push(250 - 0.01 * x); // east-falling ramp
      }
    }
    const grid73 = { width: n73, height: n73, bounds: bounds73, valuesFt: values73, source: 'synthetic', resolutionM: 10, noDataCount: 0 } as any;
    const fence73 = [
      { x: 100, y: 100 }, { x: 900, y: 100 }, { x: 900, y: 900 }, { x: 100, y: 900 },
    ];
    const fg73 = G73.buildFgSurface(grid73, rect73, fence73,
      { padSlopePct: 1, slopeDirDeg: 90, benchMode: true, maxBenchHeightFt: 4 })!;
    check('[73] FG surface builds on the ramp fixture', fg73 !== null);

    // ---- Traced flow-path Tc --------------------------------------------
    const drBase = D73.buildDrainageModel(grid73, rect73, fg73, { tr55Tc: true })!;
    const drTraced = D73.buildDrainageModel(grid73, rect73, fg73, { tr55Tc: true, tracedTc: true })!;
    check('[73] traced Tc: every discharge point carries a finite traced path',
      drTraced.discharges.length > 0 &&
      drTraced.discharges.every(dp => Number.isFinite(dp.tracedPathFt ?? NaN) && (dp.tracedPathFt ?? 0) > 0));
    check('[73] traced Tc: traced path is never shorter than the cell size',
      drTraced.discharges.every(dp => (dp.tracedPathFt ?? 0) >= (rect73.maxX - rect73.minX) / n73 - 1e-9));
    check('[73] traced Tc: tr55Tc without tracedTc never sets tracedPathFt',
      drBase.discharges.every(dp => dp.tracedPathFt === undefined));
    check('[73] traced Tc: tcMin stays finite and within rational bounds',
      drTraced.discharges.every(dp => Number.isFinite(dp.tcMin) && dp.tcMin >= 5 && dp.tcMin <= 120));
    check('[73] traced Tc is deterministic (identical JSON on re-run)',
      JSON.stringify(drTraced) ===
      JSON.stringify(D73.buildDrainageModel(grid73, rect73, fg73, { tr55Tc: true, tracedTc: true })));
    check('[73] traced Tc default OFF: flag off is byte-identical to flag absent',
      JSON.stringify(drBase) ===
      JSON.stringify(D73.buildDrainageModel(grid73, rect73, fg73, { tr55Tc: true, tracedTc: false })));

    // ---- Flexible detention: rectangular prismoid + riser ---------------
    // Hand math: S(h) = a·bw²·h + (1+a)·bw·z·h² + (4/3)·z²·h³  (aspect a, side z=3)
    const bw = 40, a = 2, z = 3, h = 4;
    const geoR = { bottomWFt: bw, sideSlopeH: z, depthFt: 6, aspect: a };
    const handS = a * bw * bw * h + (1 + a) * bw * z * h * h + (4 / 3) * z * z * h * h * h;
    check('[73] basinStorageCf matches the rectangular prismoid hand formula',
      Math.abs(H73.basinStorageCf(geoR, h) - handS) < 1e-6,
      `got ${H73.basinStorageCf(geoR, h)}, want ${handS}`);
    check('[73] aspect 1 (and absent) reduce to the square-basin formula',
      Math.abs(H73.basinStorageCf({ ...geoR, aspect: 1 }, h) -
        (bw * bw * h + 2 * bw * z * h * h + (4 / 3) * z * z * h * h * h)) < 1e-6 &&
      H73.basinStorageCf({ bottomWFt: bw, sideSlopeH: z, depthFt: 6 }, h) ===
      H73.basinStorageCf({ ...geoR, aspect: 1 }, h));
    // Riser: above the crest the outlet discharges more than orifice alone.
    const outNoRiser = { orificeDiaIn: 12, orificeCd: 0.6, weirCrestFt: 5, weirLengthFt: 10, weirCw: 3.0 };
    const outRiser = { ...outNoRiser, riserDiaIn: 8, riserCrestFt: 1.5 };
    check('[73] riser adds discharge only above its crest',
      Math.abs(H73.outletDischargeCfs(outRiser, 1.0) - H73.outletDischargeCfs(outNoRiser, 1.0)) < 1e-9 &&
      H73.outletDischargeCfs(outRiser, 3.0) > H73.outletDischargeCfs(outNoRiser, 3.0));
    const stages73 = [0.5, 1, 1.5, 2, 2.5, 3, 3.5, 4, 4.5, 5, 5.5];
    check('[73] riser outlet rating stays monotone in stage',
      stages73.every((s, i) => i === 0 ||
        H73.outletDischargeCfs(outRiser, s) >= H73.outletDischargeCfs(outRiser, stages73[i - 1]) - 1e-9));
    // Model wiring: aspect + riser inputs surface on the routed detention.
    const drDet = D73.buildDrainageModel(grid73, rect73, fg73,
      { scsMode: true, routedDetention: true, basinAspect: 2, riserDiaIn: 8, riserCrestFt: 1.5 })!;
    check('[73] routed detention actually runs on the fixture (SCS mode enabled)', !!drDet.routing);
    if (drDet.routing) {
      const rt = drDet.routing as any;
      check('[73] routing model carries the aspect (rect plan) and riser inputs',
        rt.aspectRatio === 2 &&
        rt.bottomLFt === rt.bottomWFt * 2 &&
        rt.riserDiaIn === 8 && rt.riserCrestFt === 1.5);
    } else {
      check('[73] routing model carries the aspect and riser inputs (no routing produced on fixture — skipped)', true);
    }
    check('[73] detention defaults OFF: aspect/riser defaults are byte-identical to absent',
      JSON.stringify(D73.buildDrainageModel(grid73, rect73, fg73, { routedDetention: true })) ===
      JSON.stringify(D73.buildDrainageModel(grid73, rect73, fg73,
        { routedDetention: true, basinAspect: 1, riserDiaIn: 0, riserCrestFt: 0 })));

    // ---- Protection module hand anchors ----------------------------------
    // Sanitizer: garbage snaps to defaults, valid values pass through.
    const sanP = P73.sanitizeProtectionInputs({ dutyMarginPct: 999, ctiRequiredS: 0.4, feederPickupPu: 'x' });
    check('[73] protection sanitizer snaps garbage to defaults, keeps valid fields',
      sanP.dutyMarginPct === P73.DEFAULT_PROTECTION_INPUTS.dutyMarginPct &&
      sanP.ctiRequiredS === 0.4 &&
      sanP.feederPickupPu === P73.DEFAULT_PROTECTION_INPUTS.feederPickupPu);
    check('[73] protection sanitizer on non-object returns pure defaults',
      JSON.stringify(P73.sanitizeProtectionInputs(null)) === JSON.stringify(P73.DEFAULT_PROTECTION_INPUTS));
    // IEEE C37.112 very inverse: t = TD·(19.61/(M²−1) + 0.491).
    check('[73] very-inverse trip time matches the C37.112 hand formula',
      Math.abs(P73.veryInverseTripS(5, 2) - 2 * (19.61 / 24 + 0.491)) < 1e-9);
    check('[73] very-inverse never operates at/below pickup',
      P73.veryInverseTripS(1, 1) === Infinity && P73.veryInverseTripS(0.5, 1) === Infinity);
    // PPE thresholds (NFPA 70E): 1.2 / 4 / 8 / 25 / 40.
    check('[73] PPE category thresholds',
      P73.ppeCategory(1.0) === 0 && P73.ppeCategory(3) === 1 && P73.ppeCategory(7) === 2 &&
      P73.ppeCategory(20) === 3 && P73.ppeCategory(39) === 4 && P73.ppeCategory(41) === 5);
    // Lee method hand math: E = 2.142e6·V·Ibf·t/D², D = 36 in = 914.4 mm.
    const lee = P73.leeIncident(20, 34.5, 0.5, 36);
    const leeHand = (2.142e6 * 34.5 * 20 * 0.5) / (914.4 * 914.4) / 4.184;
    check('[73] Lee incident energy matches the hand formula',
      Math.abs(lee.calCm2 - leeHand) < 1e-9, `got ${lee.calCm2}, want ${leeHand}`);
    check('[73] Lee boundary is where energy falls to 1.2 cal/cm²',
      Math.abs(P73.leeIncident(20, 34.5, 0.5, lee.boundaryIn).calCm2 - 1.2) < 1e-6);
    // IEEE 1584 LV: energy scales linearly with time, decays with distance.
    const lv1 = P73.ieee1584LvIncident(30, 0.48, 0.2, 18);
    const lv2 = P73.ieee1584LvIncident(30, 0.48, 0.4, 18);
    const lvFar = P73.ieee1584LvIncident(30, 0.48, 0.2, 36);
    check('[73] IEEE 1584 LV: energy is linear in clearing time',
      Math.abs(lv2.calCm2 - 2 * lv1.calCm2) < 1e-9);
    check('[73] IEEE 1584 LV: energy decays with working distance, arcing < bolted',
      lvFar.calCm2 < lv1.calCm2 && lv1.arcingKA < 30 && lv1.arcingKA > 0);

    // ---- Full study over a real SC study ---------------------------------
    const { buildShortCircuitStudy, DEFAULT_SC_INPUTS } = await import('../client/src/lib/nextera/shortCircuit');
    const cfg73 = getConfiguration('ge-aux-400');
    const d73 = generateSiteDesign(hondo, cfg73, 100, 400, { hotClimate: true });
    const inv73 = d73.equipment.filter(e => e.kind === 'inverter');
    const xs73 = d73.equipment.map(e => e.x);
    const ys73 = d73.equipment.map(e => e.y);
    const sub73: Pt = { x: (Math.min(...xs73) + Math.max(...xs73)) / 2, y: Math.min(...ys73) - 400 };
    const feeders73 = generateFeeders(d73, sub73, cfg73.blockMW);
    const sc73 = buildShortCircuitStudy(
      feeders73, inv73.length, inverterAmps(cfg73.blockMW), DEFAULT_SC_INPUTS, { hasAux: true });
    const prot73 = P73.buildProtectionStudy(sc73, feeders73, P73.DEFAULT_PROTECTION_INPUTS);
    check('[73] study covers every SC bus with a duty row',
      prot73.duty.length === sc73.buses.length);
    check('[73] duty: recommended device is the smallest adequate ladder step',
      prot73.duty.every(r => {
        const ladder = r.kind === 'aux' ? P73.LV_BREAKER_KA_LADDER : P73.MV_BREAKER_KA_LADDER;
        const want = ladder.find(k => k >= r.symKA * 1.2) ?? null;
        return r.recommendedKA === want && r.adequate === (want !== null);
      }));
    check('[73] coordination: one pair per feeder, CTI = main − feeder trip',
      prot73.coordination.length === feeders73.length &&
      prot73.coordination.every(c => Math.abs(c.ctiS - (c.mainTripS - c.feederTripS)) < 1e-12));
    const kindOf73 = new Map(prot73.duty.map(r => [r.busId, r.kind]));
    check('[73] arc flash: MV buses use Lee, the aux bus uses IEEE 1584, no PCS rows',
      prot73.arcFlash.every(r => r.method === (kindOf73.get(r.busId) === 'aux' ? 'IEEE 1584-2002' : 'Lee')) &&
      prot73.arcFlash.every(r => Number.isFinite(r.incidentCalCm2) && r.incidentCalCm2 > 0) &&
      prot73.duty.filter(r => r.kind !== 'pcs').length === prot73.arcFlash.length);
    check('[73] summary counters agree with the rows',
      prot73.inadequateDutyCount === prot73.duty.filter(r => !r.adequate).length &&
      prot73.uncoordinatedCount === prot73.coordination.filter(c => !c.coordinated).length &&
      Math.abs(prot73.worstIncidentCalCm2 - Math.max(...prot73.arcFlash.map(r => r.incidentCalCm2))) < 1e-12);
    check('[73] protection study is deterministic (identical JSON on re-run)',
      JSON.stringify(prot73) ===
      JSON.stringify(P73.buildProtectionStudy(sc73, feeders73, P73.DEFAULT_PROTECTION_INPUTS)));

    // ---- POI data sheet: section only when the study is passed -----------
    const { buildPoiDataSheetModel, poiSections } = await import('../client/src/lib/nextera/poiDataSheet');
    const now73 = new Date('2026-01-01T00:00:00Z');
    const poiOff = buildPoiDataSheetModel(d73, cfg73, { feeders: feeders73, now: now73 });
    const poiOffAgain = buildPoiDataSheetModel(d73, cfg73, { feeders: feeders73, now: now73, protectionStudy: null });
    const poiOn = buildPoiDataSheetModel(d73, cfg73, { feeders: feeders73, now: now73, protectionStudy: prot73 });
    check('[73] POI model: null study is byte-identical to absent (additive guard)',
      JSON.stringify(poiOff) === JSON.stringify(poiOffAgain));
    const protSection = (m: any) =>
      poiSections(m).find((s: any) => /Protection, Interrupting Duty & Arc Flash/.test(s.title));
    check('[73] POI sheet: protection section appears only when the study is passed',
      !protSection(poiOff) && !!protSection(poiOn));
    check('[73] POI protection section carries duty, coordination, arc-flash and the disclaimer',
      (() => {
        const s = protSection(poiOn);
        const txt = JSON.stringify(s);
        return txt.includes('kA') && /COORDINATED|REVIEW/.test(txt) &&
          /cal\/cm2/.test(txt) && txt.includes('SCREENING STUDY');
      })());

    // ---- Panel + store wiring source scans (the [61]/[62] pattern) -------
    const panelSrc73 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
    check('[73] panel builds the study from the SC study and gates on both toggles',
      panelSrc73.includes('buildProtectionStudy(scStudy, feeders, protectionInputs)') &&
      /if \(!protectionEnabled \|\| !scStudy \|\| !feeders\.length\) return null;/.test(panelSrc73));
    check('[73] panel passes the study into the POI export',
      /buildPoiDataSheetModel\([^)]*protectionStudy/.test(panelSrc73.replace(/\n/g, ' ')));
    const storeSrc73 = readFileSync('client/src/lib/stores/useDesignStore.ts', 'utf8');
    check('[73] store persists the protection prefs per-browser via the sanitizer',
      storeSrc73.includes("localStorage.getItem('nextera-protection-inputs')") &&
      storeSrc73.includes("localStorage.setItem('nextera-protection-enabled'") &&
      /sanitizeProtectionInputs\(\{ \.\.\.get\(\)\.protectionInputs, \.\.\.patch \}\)/.test(storeSrc73));
    // Discipline grouping (T004): collapsible PanelSection wraps the steps,
    // collapse state per-browser only, children stay mounted when collapsed.
    check('[73] panel steps are wrapped in collapsible PanelSection groups',
      (panelSrc73.match(/<PanelSection\b/g) ?? []).length >= 7 &&
      panelSrc73.includes("const PANEL_OPEN_KEY = 'nextera-panel-open'"));
    check('[73] collapsed sections keep children mounted (CSS hidden, not unmount)',
      /className=\{open \? undefined : 'hidden'\}>\{children\}<\/div>/.test(panelSrc73));
    check('[73] collapse state never touches the design store (per-browser only)',
      !storeSrc73.includes('nextera-panel-open'));
  }

  // ---------------------------------------------------------------
  // [74] Design-grade drainage input bounds: the panel's number fields and
  // the sanitizer must share one clamp table (DRAINAGE_NUM_LIMITS), or a
  // typed value silently changes on export.
  console.log('\n[74] Drainage panel min/max match sanitizer clamp bounds');
  {
    const D74 = await import('../client/src/lib/nextera/drainage');
    const panelSrc74 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');

    // The limits table covers exactly the numeric keys of DrainageInputs.
    const numericKeys = Object.entries(D74.DEFAULT_DRAINAGE_INPUTS)
      .filter(([, v]) => typeof v === 'number')
      .map(([k]) => k)
      .sort();
    const limitKeys = Object.keys(D74.DRAINAGE_NUM_LIMITS).sort();
    check('[74] DRAINAGE_NUM_LIMITS covers exactly the numeric input keys',
      JSON.stringify(numericKeys) === JSON.stringify(limitKeys));

    // Behavioral: for every numeric key, the sanitizer clamps to exactly the
    // published min/max (so a UI reading the table can never disagree).
    for (const key of limitKeys) {
      const { min, max } = (D74.DRAINAGE_NUM_LIMITS as any)[key];
      const below = (D74.sanitizeDrainageInputs({ [key]: min - 1000 }) as any)[key];
      const above = (D74.sanitizeDrainageInputs({ [key]: max + 1000 }) as any)[key];
      const atMin = (D74.sanitizeDrainageInputs({ [key]: min }) as any)[key];
      const atMax = (D74.sanitizeDrainageInputs({ [key]: max }) as any)[key];
      check(`[74] sanitizer clamps ${key} to DRAINAGE_NUM_LIMITS (${min}–${max})`,
        below === min && above === max && atMin === min && atMax === max);
      check(`[74] default ${key} is inside its own limits`,
        (D74.DEFAULT_DRAINAGE_INPUTS as any)[key] >= min &&
        (D74.DEFAULT_DRAINAGE_INPUTS as any)[key] <= max);
    }

    // Every drainage numeric field rendered in the panel goes through the
    // shared DrainageNumField (which reads min/max from DRAINAGE_NUM_LIMITS,
    // shows out-of-range feedback and clamps on blur) — never a raw input.
    const PANEL_KEYS = [
      'runoffC', 'rainfallIntensityInHr', 'manningN', 'swaleSideSlopeH',
      'swaleGradePct', 'bottomWidthFt', 'freeboardFt',
      'preDevC', 'basinDepthFt',
      'sheetFlowN', 'sheetFlowLenFt', 'p2In', 'tcOverrideMin',
      'curveNumber', 'preDevCn', 'rain24In', 'tailwaterFt',
    ];
    for (const key of PANEL_KEYS) {
      check(`[74] panel renders ${key} via DrainageNumField`,
        new RegExp(`<DrainageNumField\\s+field="${key}"`).test(panelSrc74));
    }
    check('[74] composite-C fields render via the mapped DrainageNumField',
      /\[\s*\['cPad', 'Pads'\], \['cRoad', 'Roads'\], \['cGravel', 'Gravel'\], \['cUndisturbed', 'Undist\.'\],\s*\] as const\)\.map\(\[\key, label\]\)? =>/.test(panelSrc74.replace(/\n/g, ' ')) ||
      (panelSrc74.includes("['cPad', 'Pads'], ['cRoad', 'Roads'], ['cGravel', 'Gravel'], ['cUndisturbed', 'Undist.'],") &&
        /map\(\(\[key, label\]\) => \(\s*<DrainageNumField key=\{key\} field=\{key\}/.test(panelSrc74)));
    check('[74] no raw drainageInputs number input remains in the panel',
      !/value=\{drainageInputs\.(runoffC|rainfallIntensityInHr|manningN|swaleSideSlopeH|swaleGradePct|bottomWidthFt|freeboardFt|cPad|cRoad|cGravel|cUndisturbed|preDevC|basinDepthFt|sheetFlowN|sheetFlowLenFt|p2In|tcOverrideMin|curveNumber|preDevCn|rain24In|tailwaterFt)\}/.test(panelSrc74));
    check('[74] DrainageNumField reads its bounds from DRAINAGE_NUM_LIMITS and clamps on commit',
      panelSrc74.includes('DRAINAGE_NUM_LIMITS[field]') &&
      /const clamped = Math\.min\(max, Math\.max\(min, v\)\);/.test(panelSrc74) &&
      panelSrc74.includes('border-red-500') &&
      panelSrc74.includes('will clamp'));
    check('[74] DrainageNumField Escape cancels the edit (guard flag skips the blur commit)',
      /if \(e\.key === 'Escape'\) \{ cancelledRef\.current = true;/.test(panelSrc74) &&
      /if \(cancelledRef\.current\) \{\s*\n\s*cancelledRef\.current = false;\s*\n\s*setDraft\(String\(value\)\);\s*\n\s*setNote\(null\);\s*\n\s*return;/.test(panelSrc74));
  }

  // ---------------------------------------------------------------
  // [75] Study input bounds (IEEE-80 / short-circuit / protection / energy
  // sim): the panel's number fields and each study's sanitizer must share one
  // limits table, or a typed value silently changes when the study runs.
  console.log('\n[75] Study panels min/max match sanitizer bounds');
  {
    const panelSrc75 = readFileSync('client/src/components/DesignControlPanel.tsx', 'utf8');
    const I75 = await import('../client/src/lib/nextera/ieee80');
    const S75 = await import('../client/src/lib/nextera/shortCircuit');
    const P75 = await import('../client/src/lib/nextera/protection');
    const E75 = await import('../client/src/lib/nextera/energySim');

    // Each limits table covers exactly the numeric keys of its inputs
    // (bodyWeightKg is an enum; equipmentRatingKA is nullable with its own
    // SC_RATING_LIMITS entry).
    const numKeys = (defaults: Record<string, unknown>, exclude: string[] = []) =>
      Object.entries(defaults)
        .filter(([k, v]) => typeof v === 'number' && !exclude.includes(k))
        .map(([k]) => k)
        .sort();
    check('[75] IEEE80_NUM_LIMITS covers exactly the numeric input keys',
      JSON.stringify(numKeys(I75.DEFAULT_IEEE80_INPUTS as any, ['bodyWeightKg'])) ===
      JSON.stringify(Object.keys(I75.IEEE80_NUM_LIMITS).sort()));
    check('[75] SC_NUM_LIMITS covers exactly the numeric input keys',
      JSON.stringify(numKeys(S75.DEFAULT_SC_INPUTS as any)) ===
      JSON.stringify(Object.keys(S75.SC_NUM_LIMITS).sort()));
    check('[75] PROTECTION_NUM_LIMITS covers exactly the numeric input keys',
      JSON.stringify(numKeys(P75.DEFAULT_PROTECTION_INPUTS as any)) ===
      JSON.stringify(Object.keys(P75.PROTECTION_NUM_LIMITS).sort()));
    check('[75] ENERGY_SIM_NUM_LIMITS covers exactly the numeric input keys',
      JSON.stringify(numKeys(E75.DEFAULT_ENERGY_SIM_INPUTS as any)) ===
      JSON.stringify(Object.keys(E75.ENERGY_SIM_NUM_LIMITS).sort()));

    // Behavioral: at min/max the sanitizer passes the value through; outside
    // it applies its policy (snap-to-default or clamp) — either way, the
    // published bounds are exactly the range the sanitizer accepts verbatim.
    type Lim = { min: number; max: number };
    const checkStudy = (
      name: string,
      limits: Record<string, Lim>,
      defaults: Record<string, number>,
      sanitize: (v: unknown) => Record<string, number>,
    ) => {
      for (const [key, { min, max }] of Object.entries(limits)) {
        const atMin = sanitize({ [key]: min })[key];
        const atMax = sanitize({ [key]: max })[key];
        const below = sanitize({ [key]: min - 1000 })[key];
        const above = sanitize({ [key]: max + 1000 })[key];
        check(`[75] ${name} sanitizer bounds for ${key} equal the limits table (${min}\u2013${max})`,
          atMin === min && atMax === max &&
          (below === min || below === defaults[key]) &&
          (above === max || above === defaults[key]));
        check(`[75] ${name} default ${key} is inside its own limits`,
          defaults[key] >= min && defaults[key] <= max);
      }
    };
    checkStudy('IEEE-80', I75.IEEE80_NUM_LIMITS as any, I75.DEFAULT_IEEE80_INPUTS as any,
      v => I75.sanitizeIeee80Inputs(v) as any);
    checkStudy('short-circuit', S75.SC_NUM_LIMITS as any, S75.DEFAULT_SC_INPUTS as any,
      v => S75.sanitizeScInputs(v) as any);
    checkStudy('protection', P75.PROTECTION_NUM_LIMITS as any, P75.DEFAULT_PROTECTION_INPUTS as any,
      v => P75.sanitizeProtectionInputs(v) as any);
    checkStudy('energy-sim', E75.ENERGY_SIM_NUM_LIMITS as any, E75.DEFAULT_ENERGY_SIM_INPUTS as any,
      v => E75.sanitizeEnergySimInputs(v) as any);

    // Nullable SC gear rating: blank stays null, in-range passes, garbage → null.
    check('[75] SC gear rating honors SC_RATING_LIMITS (null / in-range / out-of-range)',
      S75.sanitizeScInputs({ equipmentRatingKA: null }).equipmentRatingKA === null &&
      S75.sanitizeScInputs({ equipmentRatingKA: S75.SC_RATING_LIMITS.min }).equipmentRatingKA === S75.SC_RATING_LIMITS.min &&
      S75.sanitizeScInputs({ equipmentRatingKA: S75.SC_RATING_LIMITS.max }).equipmentRatingKA === S75.SC_RATING_LIMITS.max &&
      S75.sanitizeScInputs({ equipmentRatingKA: S75.SC_RATING_LIMITS.max + 1 }).equipmentRatingKA === null);

    // Source scan: every study field renders via the shared StudyNumField
    // whose bounds are read from the study's limits table.
    const FIELD_REFS = [
      // IEEE-80 (metric fields shown in in/ft go through displayBounds)
      'IEEE80_NUM_LIMITS.soilRhoOhmM.min', 'IEEE80_NUM_LIMITS.surfaceRhoOhmM.min',
      'displayBounds(IEEE80_NUM_LIMITS.surfaceThicknessM, 0.0254, 1)',
      'IEEE80_NUM_LIMITS.faultCurrentA.min', 'IEEE80_NUM_LIMITS.faultDurationS.min',
      'IEEE80_NUM_LIMITS.splitFactorSf.min', 'IEEE80_NUM_LIMITS.xOverR.min',
      'displayBounds(IEEE80_NUM_LIMITS.burialDepthM, 0.0254, 0)',
      'displayBounds(IEEE80_NUM_LIMITS.rodLengthM, FT_TO_M, 1)',
      'IEEE80_NUM_LIMITS.conductorKcmil.min',
      // short-circuit
      'SC_NUM_LIMITS.utilityFaultMVA.min', 'SC_NUM_LIMITS.utilityXOverR.min',
      'SC_NUM_LIMITS.inverterK.min', 'SC_RATING_LIMITS.min',
      'SC_NUM_LIMITS.auxKVA.min', 'SC_NUM_LIMITS.auxPctZ.min', 'SC_NUM_LIMITS.auxXOverR.min',
      // protection
      'PROTECTION_NUM_LIMITS.dutyMarginPct.min', 'PROTECTION_NUM_LIMITS.ctiRequiredS.min',
      'PROTECTION_NUM_LIMITS.feederPickupPu.min', 'PROTECTION_NUM_LIMITS.mainPickupPu.min',
      'PROTECTION_NUM_LIMITS.feederTimeDial.min', 'PROTECTION_NUM_LIMITS.mainTimeDial.min',
      'PROTECTION_NUM_LIMITS.mvWorkingDistIn.min', 'PROTECTION_NUM_LIMITS.lvWorkingDistIn.min',
      // energy sim (RTE percent fields scale the 0-1 model bounds by 100)
      'ENERGY_SIM_NUM_LIMITS.cyclesPerDay.min', 'ENERGY_SIM_NUM_LIMITS.dodPct.min',
      'ENERGY_SIM_NUM_LIMITS.avgAmbientC.min', 'ENERGY_SIM_NUM_LIMITS.projectLifeYears.min',
      'ENERGY_SIM_NUM_LIMITS.contractMWh.min', 'ENERGY_SIM_NUM_LIMITS.auxKwPerContainer.min',
      'ENERGY_SIM_NUM_LIMITS.batteryRteDc.min * 100', 'ENERGY_SIM_NUM_LIMITS.pcsEff.min * 100',
    ];
    for (const ref of FIELD_REFS) {
      check(`[75] panel binds bounds from ${ref}`, panelSrc75.includes(ref));
    }
    // No raw study-input number input remains in the panel (bodyWeightKg is
    // an enum <select>, not a numeric range field).
    check('[75] no raw study-input number input remains in the panel',
      !/value=\{(ieee80Inputs|scInputs|protectionInputs|energySimInputs)\.(?!bodyWeightKg)/.test(
        panelSrc75.replace(/<StudyNumField[\s\S]*?\/>/g, '')));
    // StudyNumField mirrors the DrainageNumField pattern: red-border feedback,
    // clamp on commit, Escape cancel.
    const studyFieldSrc = panelSrc75.slice(
      panelSrc75.indexOf('function StudyNumField'),
      panelSrc75.indexOf('function displayBounds'));
    check('[75] StudyNumField clamps on commit with out-of-range feedback',
      /const clamped = Math\.min\(max, Math\.max\(min, v\)\);/.test(studyFieldSrc) &&
      studyFieldSrc.includes('border-red-500') &&
      studyFieldSrc.includes('will clamp') &&
      studyFieldSrc.includes('Adjusted to'));
    // Integer sanitizers (projectLifeYears rounds after clamping) must be
    // mirrored in the field: `integer` mode rounds on commit and surfaces the
    // rounding in the "Adjusted to" note, and the live onChange path never
    // commits a decimal draft the sanitizer would change.
    check('[75] StudyNumField integer mode rounds on commit and surfaces it',
      /const final = integer \? Math\.round\(clamped\)/.test(studyFieldSrc) &&
      /onCommit\(final\);/.test(studyFieldSrc) &&
      /setDraft\(String\(final\)\);/.test(studyFieldSrc) &&
      /final !== v/.test(studyFieldSrc) &&
      /\(!integer \|\| Number\.isInteger\(v\)\)/.test(studyFieldSrc));
    check('[75] Project life field uses integer mode (sanitizer Math.round parity)',
      /label="Project life \(yr\)"[\s\S]{0,200}?\binteger\b[\s\S]{0,200}?ENERGY_SIM_NUM_LIMITS\.projectLifeYears\.min/.test(panelSrc75));
    // Sanitizer behavior anchor: decimals round to nearest whole year after
    // clamping (20.5 → 21, 0.4 → clamp to 1, 40.6 → clamp to 40).
    {
      const s = (v: number) => E75.sanitizeEnergySimInputs({ ...E75.DEFAULT_ENERGY_SIM_INPUTS, projectLifeYears: v }).projectLifeYears;
      check('[75] energy-sim sanitizer rounds projectLifeYears decimals (20.5 → 21)',
        s(20.5) === 21 && s(20.4) === 20 && s(0.4) === 1 && s(40.6) === 40);
    }
    check('[75] StudyNumField Escape cancels the edit',
      /if \(e\.key === 'Escape'\) \{ cancelledRef\.current = true;/.test(studyFieldSrc));
    // displayBounds keeps converted display ranges inside the model range
    // (min rounds up, max rounds down, at the field's display precision).
    check('[75] displayBounds rounds min up and max down at display precision',
      panelSrc75.includes('function displayBounds(lim: { min: number; max: number }, perUnit: number, decimals = 2)') &&
      panelSrc75.includes('Math.ceil((lim.min / perUnit) * f) / f') &&
      panelSrc75.includes('Math.floor((lim.max / perUnit) * f) / f'));
    // Unit-converted IEEE-80 fields (inches/ft → metric): the display value
    // is rounded (0.1 in rock depth, whole-inch burial, 0.1 ft rod), so the
    // field must round the typed value to that same precision on commit and
    // surface it — otherwise the metric round-trip silently redisplays a
    // different number than what was typed (e.g. burial 17.7 in → stored
    // 0.44958 m → redisplayed as 18 with no note).
    check('[75] StudyNumField displayDecimals rounds on commit and surfaces it',
      /displayDecimals !== undefined \? roundToDecimals\(clamped, displayDecimals\)/.test(studyFieldSrc) &&
      /nearest/.test(studyFieldSrc) &&
      /\(displayDecimals === undefined \|\| roundToDecimals\(v, displayDecimals\) === v\)/.test(studyFieldSrc));
    // Each unit-converted field pairs displayDecimals with the same-precision
    // display rounding of its value prop AND same-precision displayBounds.
    check('[75] Rock depth field: displayDecimals 1 + 0.1-in display rounding',
      /displayBounds\(IEEE80_NUM_LIMITS\.surfaceThicknessM, 0\.0254, 1\)[\s\S]{0,200}?displayDecimals=\{1\}[\s\S]{0,200}?surfaceThicknessM \/ 0\.0254 \* 10\) \/ 10/.test(panelSrc75));
    check('[75] Burial field: displayDecimals 0 + whole-inch display rounding',
      /displayBounds\(IEEE80_NUM_LIMITS\.burialDepthM, 0\.0254, 0\)[\s\S]{0,200}?displayDecimals=\{0\}[\s\S]{0,200}?Math\.round\(ieee80Inputs\.burialDepthM \/ 0\.0254\)/.test(panelSrc75));
    check('[75] Rod length field: displayDecimals 1 + 0.1-ft display rounding',
      /displayBounds\(IEEE80_NUM_LIMITS\.rodLengthM, FT_TO_M, 1\)[\s\S]{0,200}?displayDecimals=\{1\}[\s\S]{0,200}?rodLengthM \/ FT_TO_M \* 10\) \/ 10/.test(panelSrc75));
    // Behavioral anchor: clamp-then-round at display precision stays inside
    // the sanitizer range for all three fields (bounds sit on the display
    // grid, so rounding a clamped value can never step back outside), and the
    // metric round-trip of a rounded display value redisplays identically.
    {
      const FT_TO_M75 = 0.3048;
      const db = (lim: { min: number; max: number }, perUnit: number, decimals: number) => {
        const f = 10 ** decimals;
        return { min: Math.ceil((lim.min / perUnit) * f) / f, max: Math.floor((lim.max / perUnit) * f) / f };
      };
      const roundTo = (x: number, d: number) => { const f = 10 ** d; return Math.round(x * f) / f; };
      const cases: Array<{ lim: { min: number; max: number }; perUnit: number; decimals: number }> = [
        { lim: I75.IEEE80_NUM_LIMITS.surfaceThicknessM, perUnit: 0.0254, decimals: 1 },
        { lim: I75.IEEE80_NUM_LIMITS.burialDepthM, perUnit: 0.0254, decimals: 0 },
        { lim: I75.IEEE80_NUM_LIMITS.rodLengthM, perUnit: FT_TO_M75, decimals: 1 },
      ];
      let allOk = true;
      for (const { lim, perUnit, decimals } of cases) {
        const b = db(lim, perUnit, decimals);
        // Sweep typed values across and beyond the display range.
        for (let i = 0; i <= 200; i++) {
          const typed = b.min - 1 + (b.max - b.min + 2) * (i / 200);
          const clamped = Math.min(b.max, Math.max(b.min, typed));
          const final = roundTo(clamped, decimals);
          const metric = final * perUnit;
          // stored metric stays inside the sanitizer range (tiny float slack)
          if (metric < lim.min - 1e-9 || metric > lim.max + 1e-9) { allOk = false; break; }
          // redisplaying the stored metric reproduces the committed value
          if (roundTo(metric / perUnit, decimals) !== final) { allOk = false; break; }
        }
      }
      check('[75] inch/ft fields: clamp+round stays in sanitizer range and round-trips exactly', allOk);
    }
    // Percent-entered efficiency fields (Battery DC RTE / PCS eff): displayed
    // as ×100 percents rounded to 0.1, stored as 0-1 fractions. The fields
    // must use displayDecimals={1} with grid-snapped ×100 bounds so a typed
    // percent can never commit a fraction that redisplays differently.
    check('[75] RTE percent field: displayDecimals 1 + grid-snapped ×100 bounds + 0.1% display rounding',
      /roundToDecimals\(ENERGY_SIM_NUM_LIMITS\.batteryRteDc\.min \* 100, 1\)[\s\S]{0,220}?displayDecimals=\{1\}[\s\S]{0,220}?Math\.round\(energySimInputs\.batteryRteDc \* 1000\) \/ 10/.test(panelSrc75));
    check('[75] PCS eff percent field: displayDecimals 1 + grid-snapped ×100 bounds + 0.1% display rounding',
      /roundToDecimals\(ENERGY_SIM_NUM_LIMITS\.pcsEff\.min \* 100, 1\)[\s\S]{0,220}?displayDecimals=\{1\}[\s\S]{0,220}?Math\.round\(energySimInputs\.pcsEff \* 1000\) \/ 10/.test(panelSrc75));
    // Behavioral sweep: for every typed value across and beyond the percent
    // range, clamp+round to the 0.1% grid, store fraction = v/100, run the
    // real sanitizer, and assert (a) the sanitizer doesn't move the stored
    // fraction and (b) the redisplayed percent equals the committed value.
    {
      const roundTo = (x: number, d: number) => { const f = 10 ** d; return Math.round(x * f) / f; };
      const pctCases: Array<{ key: 'batteryRteDc' | 'pcsEff' }> = [{ key: 'batteryRteDc' }, { key: 'pcsEff' }];
      let allOk = true;
      for (const { key } of pctCases) {
        const lim = E75.ENERGY_SIM_NUM_LIMITS[key];
        const bMin = roundTo(lim.min * 100, 1);
        const bMax = roundTo(lim.max * 100, 1);
        // every 0.01% step across [min-1, max+1] — includes all committable
        // 0.1-grid values plus off-grid typed values that get rounded
        const steps = Math.round((bMax - bMin + 2) * 100);
        for (let i = 0; i <= steps; i++) {
          const typed = roundTo(bMin - 1 + i / 100, 2);
          const clamped = Math.min(bMax, Math.max(bMin, typed));
          const committed = roundTo(clamped, 1);
          const stored = committed / 100;
          const sanitized = E75.sanitizeEnergySimInputs({ ...E75.DEFAULT_ENERGY_SIM_INPUTS, [key]: stored })[key];
          if (sanitized !== stored) { allOk = false; break; }
          if (Math.round(sanitized * 1000) / 10 !== committed) { allOk = false; break; }
        }
        if (!allOk) break;
      }
      check('[75] percent fields: stored fraction survives sanitizer and redisplays the committed percent exactly', allOk);
    }
  }

  // ---------------------------------------------------------------
  // [76] Camera pose NaN guard: a non-finite requestCameraPose must be
  // rejected. A NaN pose poisons the camera view matrix, WebGLClipping then
  // projects the ground clipping planes to NaN, and three.js's uniform
  // flatten() throws "firstElem.toArray is not a function" on EVERY frame —
  // a permanently blank canvas (task: 3D view crash when zooming close).
  {
    const { useDesignStore } = await import('../client/src/lib/stores/useDesignStore');
    const before = useDesignStore.getState().cameraPoseRequest;
    useDesignStore.getState().requestCameraPose([NaN, 10, 20], [0, 0, 0]);
    check('[76] requestCameraPose rejects NaN position',
      useDesignStore.getState().cameraPoseRequest === before);
    useDesignStore.getState().requestCameraPose([0, 10, 20], [0, Infinity, 0]);
    check('[76] requestCameraPose rejects non-finite target',
      useDesignStore.getState().cameraPoseRequest === before);
    useDesignStore.getState().requestCameraPose([1, 2, 3], [4, 5, 6]);
    const after = useDesignStore.getState().cameraPoseRequest;
    check('[76] requestCameraPose accepts a finite pose',
      !!after && after !== before && after.pos[0] === 1 && after.target[2] === 6);
    useDesignStore.setState({ cameraPoseRequest: before });
  }

