      const dxfPeEci = buildDesignDxfString(dPe586, 'Hondo_586pe', cfgPe586, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, { eciLegend: true });
      check('[586] PE config also swaps to ECI symbols', dxfPeEci !== dxfPeDefault);
      // Source: the swap maps PCS row per config, keeps rows without an ECI
