      const sheetOff = buildSheetDxfString(SHEET_REGISTRY[siteIdx], ctx586, siteIdx);
      const sheetEci = buildSheetDxfString(SHEET_REGISTRY[siteIdx], { ...ctx586, eciLegend: true }, siteIdx);
      check('[586] package site-plan sheet honors the flag', sheetEci !== sheetOff);
      // Package PDF path mirrors the DXF package (composeSheetDisplay).
