      const pdfSheetOff = composeSheetDisplay(SHEET_REGISTRY[siteIdx], ctx586, siteIdx);
      const pdfSheetEci = composeSheetDisplay(SHEET_REGISTRY[siteIdx], { ...ctx586, eciLegend: true }, siteIdx);
