      const disp586 = composeDesignDisplay({ design: d, projectName: 'Hondo_586', config: cfg581, eciLegend: true } as any);
      const disp586Off = composeDesignDisplay({ design: d, projectName: 'Hondo_586', config: cfg581 } as any);
      check('[586] PDF/CAD display list honors the flag', disp586.ops.length !== disp586Off.ops.length);
      check('[586] display list gains hatch ops under the flag',
        disp586.ops.filter(o => (o as any).kind === 'hatch').length > disp586Off.ops.filter(o => (o as any).kind === 'hatch').length);

      // Project persistence: boolean-validated, written only when true.
      const { validateProjectFile } = await import('../client/src/lib/stores/useDesignStore');
      const { useDesignStore: store586 } = await import('../client/src/lib/stores/useDesignStore');
      store586.setState({ boundary: hondo });
