    const va = eciSymbolForEquipment({ ...bessProto, rotation: Math.PI / 2, doorEnd: 1, epanel: 'left' } as any, cfgGe, 'eci')?.glyphKey;
    const vc = eciSymbolForEquipment({ ...bessProto, rotation: Math.PI / 2, doorEnd: 1, epanel: 'right' } as any, cfgGe, 'eci')?.glyphKey;
    check("[594] rotated container: epanel left = 'A', right = 'C'", va === 'lgLinkA' && vc === 'lgLinkC');
    // Aux gear mapping + kinds without a delivered symbol keep legacy rects.
