    const [ccx, ccy] = p594.toYard((bx0 + bx1) / 2, (by0 + by1) / 2);
    check('[594] glyph body center lands on the equipment center',
      Math.abs(ccx - bessProto.x) < 1e-6 && Math.abs(ccy - bessProto.y) < 1e-6);

    // DXF yard swap: symbol fills land in the yard (not just the legend
