    const meta594 = { projectName: 'ECI594', location: 'Hondo, TX', drafter: 'QA', revision: 'A', date: '01/01/2026' };
    const wOn = new DxfWriter();
    composeDesignDxf(wOn, d594, 'ECI594', cfgGe, meta594, undefined, undefined, undefined, undefined, undefined, undefined, undefined, { eciLegend: true });
    const wOff = new DxfWriter();
    composeDesignDxf(wOff, d594, 'ECI594', cfgGe, meta594);
    const grayHatches = (wOn.ops as any[]).filter(o => o.kind === 'hatch' && o.layer === 'SYM-GRAY');
    const nearBess = grayHatches.some(o => o.loops.some((r: number[][]) =>
      r.some(([x, y]) => Math.hypot(x - bessProto.x, y - bessProto.y) < bessProto.length)));
    check('[594] symbol fills render in the yard at equipment positions',
      grayHatches.length > d594.equipment.length && nearBess);
    const neutralFallbacks = (w: any) => (w.ops as any[]).filter(o =>
      o.kind === 'poly' && o.closed && o.layer === LAYERS.SYM_DARK &&
      o.provenance?.role === 'neutral-equipment-outline' &&
      o.provenance?.symbolResolution === 'neutral-fallback').length;
    // Kinds without delivered artwork remain visible as intentional neutral
