    const labelTexts = (w: any) => (w.ops as any[]).filter(o => o.kind === 'text' && /Labels/.test(o.layer)).length;
    check('[594] equipment labels unchanged in ECI mode', labelTexts(wOn) === labelTexts(wOff));
    // [786] The default library (delivered GLB traces) draws symbols too, so
