    // still fall back to the ECI library rather than losing their symbol.
    const defaultDark = (wOff.ops as any[]).filter(o => o.kind === 'hatch' && o.layer === 'SYM-DARK');
    check('[786] default compose draws delivered symbols in the yard',
      defaultDark.length > d594.equipment.length &&
      defaultDark.some(o => o.loops.some((r: number[][]) =>
        r.some(([x, y]) => Math.hypot(x - bessProto.x, y - bessProto.y) < bessProto.length))));
    check('[786] default SYM-GRAY only from the ECI-fallback kinds',
      (wOff.ops as any[]).filter(o => o.layer === 'SYM-GRAY').length <
        (wOn.ops as any[]).filter(o => o.layer === 'SYM-GRAY').length);

    // Package sheets route the flag into drawEquipment.
    const sheetsSrc594 = readFileSync('client/src/lib/nextera/dxfSheets.ts', 'utf8');
    check('[594] all plan sheets pass eciLegend into drawEquipment',
      (sheetsSrc594.match(/drawEquipment\(dxf, ctx\.design, ctx\.config, !!ctx\.eciLegend(?:, true)?\)/g) || []).length === 3);
    // Cover overlays intentionally keep the halo rectangles (aerial linework).
    check('[594] cover overlay keeps legacy rects',
      /drawEquipment\(ov, ctx\.design, ctx\.config\);/.test(sheetsSrc594));

    // Scene: 2D replaces boxes with flat symbols, 3D decals ride box tops,
    // legacy compartment markers suppressed while symbols show.
    const sceneSrc594 = readFileSync('client/src/components/DesignScene.tsx', 'utf8');
    check('[594] scene overlay shares the DXF placement math',
      /eciSymbolForEquipment/.test(sceneSrc594) && /EciSymbolOverlay/.test(sceneSrc594));
    check('[594] 2D hides boxes for symbol kinds; 3D keeps boxes under decals',
      /: !is3D \? symbolKinds/.test(sceneSrc594) &&
      /eq\.height \+ 0\.\d+ : 0\.\d+/.test(sceneSrc594));
    check('[913] generated compartment meshes absent in every scene mode',
      !/CompartmentMarker|PcsCompartmentMarkers|hideCompartmentMarkers/.test(sceneSrc594) &&
      !/parts\.(corners|dc|mv)/.test(sceneSrc594));
    const annotationsSrc913 = readFileSync('client/src/components/SheetAnnotations2D.tsx', 'utf8');
    check('[913] 2D annotations no longer advertise removed compartment boxes',
      !/pcsdc|pcsaux|cablecomp|Cable Compartment|Connection Box|Cable-Compartment Corner/.test(annotationsSrc913));
    check('[594] realistic near-LOD keeps GLB detail (no decals over models)',
      /!\(realistic && !realisticFarEff\) && \(\s*<EciSymbolOverlay/.test(sceneSrc594));
    // Highlighted equipment must not fall back to legacy geometry in 2D: the
