    const rect821 = (cx: number, cy: number, l: number, w: number, deg: number): number[] => {
      const r = (deg * Math.PI) / 180, c = Math.cos(r), s = Math.sin(r);
      const out: number[] = [];
      for (const [dx, dy] of [[-l / 2, -w / 2], [l / 2, -w / 2], [l / 2, w / 2], [-l / 2, w / 2]] as const) {
        out.push(cx + c * dx - s * dy, cy + s * dx + c * dy);
      }
      return out;
    };

