    check('[821] "PCS-3" classifies as inverter', (classifyTraceName('PCS-3') as any)?.equip === 'inverter');
    check('[821] "DC-4" is a boundary layer, never equipment', classifyTraceName('DC-4')?.kind === 'boundary');
    check('[821] "Backup Generator" classifies as generator placeholder', (classifyTraceName('Backup Generator') as any)?.equip === 'generator');
    check('[821] "SUBSTATION" recognized as substation outline', classifyTraceName('SUBSTATION')?.kind === 'substation');
    check('[821] unknown name returns null (goes to the tagging prompt)', classifyTraceName('THING 9') === null);

