    check('[821] rotated rect pose recovers rotation and dims',
      !!pose821 && Math.abs(pose821.rotationDeg - 30) < 0.1 && Math.abs(pose821.lengthFt - 23.525) < 0.05 && Math.abs(pose821.widthFt - 8.433) < 0.05,
      pose821 ? `${pose821.rotationDeg.toFixed(2)}° ${pose821.lengthFt.toFixed(2)}x${pose821.widthFt.toFixed(2)}` : 'null pose');
